package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** What gets sorted: shells by color on the Beach, gravel, sand and bricks on the Building Site. */
internal enum class SortTheme { SHELLS, MATERIALS }

/**
 * One kind of thing in the pile and the bin it goes in: its [name] ("pink", "gravel"), what one is called in a
 * sentence ([thing]), the [bin]'s name, and its colors ([light], [color], [shade]).
 */
internal class SortKind(val name: String, val thing: String, val bin: String, val light: Color, val color: Color, val shade: Color)

/**
 * The look of Sort in one arena: the [theme], the three [kinds], the ground ([groundLight] to [ground], [groundShade]),
 * the patch the pile lies on ([patch]), the band along the top ([band], [bandLight]), the bins' [binBody] colors,
 * and what the line under the game says.
 */
internal class SortLook(
    val arena: Arena,
    val theme: SortTheme,
    val kinds: List<SortKind>,
    val groundLight: Color,
    val ground: Color,
    val groundShade: Color,
    val patch: Color,
    val band: Color,
    val bandLight: Color,
    val binLight: Color,
    val binBody: Color,
    val binDark: Color,
    val start: String,
    val done: String,
) {
    /** The name of one item in the pile, as a screen reader reads it. */
    fun nameOf(item: SortItem): String {
        val k = kinds[item.kind]
        return when (theme) {
            SortTheme.SHELLS -> "${k.name} ${shellShapes[item.shape]}"
            SortTheme.MATERIALS -> when (item.kind) {
                0 -> listOf("round gravel stone", "flat gravel stone", "pointy gravel stone")[item.shape]
                1 -> listOf("sack of sand", "leaning sack of sand", "small sack of sand")[item.shape]
                else -> listOf("brick", "pair of bricks", "half brick")[item.shape]
            }
        }
    }

    companion object {
        private val shellShapes = listOf("scallop shell", "spiral shell", "clam shell")

        /** [arena]'s look, its colors through [g]. Arenas without a Sort game get the Beach's. */
        fun of(arena: Arena, g: SceneGrade): SortLook = when (arena) {
            Arena.BUILDING_SITE -> SortLook(
                Arena.BUILDING_SITE, SortTheme.MATERIALS,
                listOf(
                    SortKind("gravel", "gravel", "gravel bin", g(0xFFC9CDD2), g(0xFF9AA0A8), g(0xFF6C727B)),
                    SortKind("sand", "sand sack", "sand bin", g(0xFFF0DCAE), g(0xFFD9B97A), g(0xFFA9854C)),
                    SortKind("bricks", "brick", "brick bin", g(0xFFEB8F68), g(0xFFC9583A), g(0xFF8E3424)),
                ),
                g(0xFFE3D6BE), g(0xFFC9B898), g(0xFF9C8E76), g(0xFFB09C7A),
                g(0xFFFFC21F), g(0xFF3B3F46),
                g(0xFF7FC4F0), g(0xFF2F7FC0), g(0xFF1D4F80),
                "Drag each one to its bin!",
                "All sorted! The bins hop for joy!",
            )
            else -> SortLook(
                Arena.BEACH, SortTheme.SHELLS,
                listOf(
                    SortKind("pink", "pink shell", "pink basket", g(0xFFFFD0DC), g(0xFFF48FAA), g(0xFFC85C7C)),
                    SortKind("yellow", "yellow shell", "yellow basket", g(0xFFFFF0A8), g(0xFFF5C842), g(0xFFC2901C)),
                    SortKind("blue", "blue shell", "blue basket", g(0xFFCDE6FF), g(0xFF6FA8EC), g(0xFF3A6CB8)),
                ),
                g(0xFFFFF5DC), g(0xFFF3DFB2), g(0xFFD8BC86), g(0xFFE6CC98),
                g(0xFF2FA8D0), g(0xFFBFF0F5),
                g(0xFFF2D7A0), g(0xFFD9AE6A), g(0xFF9C7440),
                "Sort each shell by its color!",
                "All sorted! The baskets hop for joy!",
            )
        }
    }
}

/**
 * Where Sort sits in a [width] x [height] area (in dp, like the item and bin boxes over the canvas): the [pile]
 * area in the middle, the three [bins] along the bottom, and the [item] size.
 */
internal class SortLayout(val width: Float, val height: Float) {
    private val gap = minOf(width, height) * 0.03f
    val binHeight: Float = minOf(height * 0.25f, (width - gap * 4) / 3 * 0.95f)
    val binWidth: Float = minOf((width - gap * 4) / 3, binHeight * 1.3f)
    val bins: List<Rect> = List(3) { i ->
        val total = binWidth * 3 + gap * 2
        val left = (width - total) / 2 + i * (binWidth + gap)
        Rect(Offset(left, height - gap - binHeight), Size(binWidth, binHeight))
    }
    val item: Float = (minOf(width, height - binHeight - gap * 3) * 0.235f).coerceAtMost(104f)
    val pile: Rect = Rect(item * 0.5f + gap, item * 0.5f + gap * 1.5f, width - item * 0.5f - gap, height - binHeight - gap * 2 - item * 0.45f)

    /** The center of an item lying at ([x], [y]) in the pile's 0 to 1 coordinates. */
    fun at(x: Float, y: Float): Offset = Offset(pile.left + x * pile.width, pile.top + y * pile.height)

    /** Where things drop into bin [i]. */
    fun mouth(i: Int): Offset = Offset(bins[i].center.x, bins[i].top + binHeight * 0.18f)

    /** The bin under [p], if any (a little generous around each). */
    fun binAt(p: Offset): Int? = bins.indexOfFirst {
        p.x in it.left - 6f..it.right + 6f && p.y in it.top - binHeight * 0.35f..it.bottom + 6f
    }.takeIf { it >= 0 }
}
