/**
 * Sunny and Mo, small, hanging out in [arena] while the player sorts: Sunny on the left and Mo on the right,
 * standing on the bottom edge of this strip (the top of the controls), clear of the board. Mo peeks out of a hole
 * where there is ground to dig in. When [cheering] (the level is solved), both hop for joy.
 */
@Composable
fun StoryCameos(arena: Arena, cheering: Boolean, modifier: Modifier = Modifier, spread: Dp = 94.dp, height: Dp = 52.dp) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val clock = rememberSceneClock()
    val joy by animateFloatAsState(if (cheering) 1f else 0f, tween(400))
    Canvas(modifier.clearAndSetSemantics { }) {
        val t = clock.value
        val h = height.toPx()
        val ground = size.height + 2.dp.toPx()
        val left = size.width / 2 - spread.toPx()
        val right = size.width / 2 + spread.toPx()
        val look = cameoLook(arena)
        val cheer = joy > 0.5f
        val hopS = if (cheer) abs(swing(t, 80)) * 18f else 0f
        val hopM = if (cheer) abs(swing(t, 80, 0.25f)) * 18f else 0f
        // Sunny glances around now and then.
        val glance = Offset(swing(t, 6) * 2f, 0f)
        val float = if (look.floating) swing(t, 20) * 3.dp.toPx() else 0f
        sunny(
            left, ground - float, h, grade, t,
            pose = if (cheer) Pose.CHEER else look.sunny,
            hat = look.hat,
            hop = hopS,
            look = glance,
        )
        if (look.hole && !cheer) {
            // Mo ducks back into the hole now and then, and pops up again.
            val d = drift(t, 9, 0.4f)
            val rise = if (d < 0.1f) abs(d - 0.05f) / 0.05f * 0.7f + 0.3f else 1f
            mo(right, ground - 3.dp.toPx(), h * 1.25f, grade, t, Pose.PEEK, hat = look.hat, rise = rise, soil = grade(look.soil))
        } else {
            mo(
                right, ground - float * 0.8f, h * 0.92f, grade, t,
                pose = if (cheer) Pose.CHEER else look.mo,
                hat = look.hat,
                hop = hopM,
                shovel = !cheer && look.mo == Pose.STAND,
                flip = true,
            )
        }
    }
}

/** How the cameos look in an arena. */
private class CameoLook(val sunny: Pose, val mo: Pose, val hat: Hat, val hole: Boolean, val soil: Color, val floating: Boolean = false)

private fun cameoLook(arena: Arena): CameoLook = when (arena) {
    Arena.PLAYGROUND -> CameoLook(Pose.SIT, Pose.PEEK, Hat.NONE, hole = true, soil = soilOf(Setting.SANDBOX))
    Arena.BEACH -> CameoLook(Pose.SIT, Pose.STAND, Hat.NONE, hole = false, soil = soilOf(Setting.BEACH))
    Arena.SEA_FLOOR -> CameoLook(Pose.STAND, Pose.SIT, Hat.SPACE_HELMET, hole = false, soil = soilOf(Setting.UNDERWATER), floating = true)
    Arena.DESERT -> CameoLook(Pose.SIT, Pose.PEEK, Hat.NONE, hole = true, soil = soilOf(Setting.DESERT))
    Arena.BUILDING_SITE -> CameoLook(Pose.SIT, Pose.STAND, Hat.HARD_HAT, hole = false, soil = soilOf(Setting.BACKYARD))
    Arena.MARS -> CameoLook(Pose.STAND, Pose.PEEK, Hat.SPACE_HELMET, hole = true, soil = soilOf(Setting.MARS))
}

/** The map's small storybook button that replays an arena's story: [label] is read by screen readers. */
@Composable
fun StoryButton(label: String, onClick: () -> Unit, face: Color, modifier: Modifier = Modifier) {
    GameButton(onClick, ButtonStyle(face, Color.White), modifier.size(36.dp, 39.dp), shape = androidx.compose.foundation.shape.CircleShape, lip = 3.dp, label = label) {
        Canvas(Modifier.size(22.dp)) {
            val u = size.minDimension / 24f
            val white = Color.White
            // An open book: two pages curving up from the spine.
            val leftPage = Path().apply {
                moveTo(12f * u, 7f * u)
                quadraticTo(8f * u, 4.5f * u, 3f * u, 5f * u)
                lineTo(3f * u, 18f * u)
                quadraticTo(8f * u, 17.5f * u, 12f * u, 20f * u)
                close()
            }
            val rightPage = Path().apply {
                moveTo(12f * u, 7f * u)
                quadraticTo(16f * u, 4.5f * u, 21f * u, 5f * u)
                lineTo(21f * u, 18f * u)
                quadraticTo(16f * u, 17.5f * u, 12f * u, 20f * u)
                close()
            }
            drawPath(leftPage, white)
            drawPath(rightPage, white.copy(alpha = 0.85f))
            val line = Stroke(1.2f * u, cap = StrokeCap.Round)
            val ink = face.copy(alpha = 0.55f)
            for (k in 0..2) {
                val y = 9f + k * 3f
                drawLine(ink, Offset(5f * u, y * u), Offset(10f * u, (y + 0.8f) * u), line.width, StrokeCap.Round)
                drawLine(ink, Offset(14f * u, (y + 0.8f) * u), Offset(19f * u, y * u), line.width, StrokeCap.Round)
            }
            // A little paw print on the cover corner.
            drawCircle(Color(0xFFFFC93A), 2.2f * u, Offset(18.5f * u, 20.5f * u))
        }
    }
}
