package io.colorsand.ui.minigame

import io.colorsand.core.Arena
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.atan2
import kotlin.math.cos
import kotlin.math.hypot
import kotlin.math.sin
import kotlin.random.Random

/** A point in a [SandToss] field: [x] across (0 to 1), [y] up from the ground, both in field widths. */
data class TossPoint(val x: Float, val y: Float)

/**
 * What stands to be hit: a stack to knock over ([knock]: toy blocks, traffic cones) or something to land in or on
 * (a sand bucket, a pallet), [halfWidth] to each side of its middle and [height] tall, in field widths.
 */
enum class TossTargetKind(val knock: Boolean, val halfWidth: Float, val height: Float) {
    BLOCKS(true, 0.062f, 0.19f),
    BUCKET(false, 0.07f, 0.1f),
    CONES(true, 0.066f, 0.2f),
    PALLET(false, 0.09f, 0.05f),
}

/** One target standing in spot [lane] (0 nearest) at [x] since [appearedAt] seconds; [hitAt] is when it was knocked over or landed in. */
data class TossTarget(val id: Int, val kind: TossTargetKind, val lane: Int, val x: Float, val appearedAt: Float, val hitAt: Float? = null) {
    val left: Float get() = x - kind.halfWidth
    val right: Float get() = x + kind.halfWidth
    val top: Float get() = kind.height
}

/**
 * The ball (a sandball, a sandbag) in the air: where it is, how fast it goes, how often it bounced, and the
 * second it was thrown. [knocked] is set once it knocked something over and bounces back from it.
 */
data class TossBall(
    val x: Float,
    val y: Float,
    val vx: Float,
    val vy: Float,
    val thrownAt: Float,
    val bounces: Int = 0,
    val knocked: Boolean = false,
)

/** What one [SandToss.step] did, for sounds, puffs and buzzes. */
enum class TossEvent { THROWN, BOUNCED, KNOCKED, LANDED_IN, SPLAT, MISSED, APPEARED, DONE }

/** How the whole arc from the current aim comes down next to the nearest standing target. */
enum class AimHint { SHORT, ON, LONG }

/**
 * A round of the gentle toss, in a field 1 wide with the ground at y = 0: a launcher at the bottom left throws a ball
 * on a gravity arc at [angle] degrees with [power] (0 to 1). [TARGETS] targets stand at three distances, [STANDING]
 * at a time (a new one pops up in a free spot after each hit); a stack is knocked over by a ball running into it, a
 * bucket or pallet is hit by a ball dropping in or onto it. Balls bounce softly on the ground and splat. Throws are
 * unlimited, and the [preview] of the arc gets longer after each miss in a row as a helping hand. [arena] picks the
 * targets (toy blocks and buckets, or traffic cones and pallets), [seed] where they stand.
 */
class SandToss(val arena: Arena, seed: Int) {
    private val random = Random(seed)

    /** Seconds since the round began. */
    var time: Float = 0f
        private set

    /** The aim, in degrees above the ground. */
    var angle: Float = 45f
        private set

    /** How hard the next throw goes, [MIN_POWER] to 1. */
    var power: Float = 0.55f
        private set

    /** The ball in the air, or null between throws. */
    var ball: TossBall? = null
        private set

    /** The targets standing, and those just hit while they topple and fade. */
    val targets: List<TossTarget> get() = standing

    /** How many targets were hit. */
    var hits: Int = 0
        private set

    /** Throws so far. */
    var throws: Int = 0
        private set

    /** Misses since the last hit: each one makes the [preview] longer. */
    var missesInARow: Int = 0
        private set

    /** Where the last ball splatted on the ground, and when, for its puff. */
    var splat: Pair<TossPoint, Float>? = null
        private set

    /** When the last target was hit, or null. */
    var doneAt: Float? = null
        private set

    val isDone: Boolean get() = hits >= TARGETS

    /** Whether a throw can go now: no ball in the air and targets left. */
    val canThrow: Boolean get() = ball == null && !isDone

    private val kinds: List<TossTargetKind> = if (arena == Arena.BUILDING_SITE) {
        listOf(TossTargetKind.CONES, TossTargetKind.PALLET)
    } else {
        listOf(TossTargetKind.BLOCKS, TossTargetKind.BUCKET)
    }
    private val standing = mutableListOf<TossTarget>()
    private var nextId = 0
    private var shown = 0
    private val pending = mutableListOf<Pair<Int, Float>>()
    private var throwHit = false
    private var thrownNow = false

    init {
        // One of each kind and a third either way, in a shuffled order across the three distances.
        val first = (kinds + kinds[random.nextInt(2)]).shuffled(random)
        for (lane in 0 until STANDING) place(lane, first[lane], 0f)
    }

    /** Aims at [degrees] and [strength], kept within the launcher's reach. */
    fun aim(degrees: Float, strength: Float) {
        angle = degrees.coerceIn(MIN_ANGLE, MAX_ANGLE)
        power = strength.coerceIn(MIN_POWER, 1f)
    }

    /** Aims a step higher (+1) or lower (-1), as an arrow key or a screen reader action does. */
    fun nudgeAngle(direction: Int) = aim(angle + direction * ANGLE_STEP, power)

    /** Throws a step harder (+1) or softer (-1). */
    fun nudgePower(direction: Int) = aim(angle, power + direction * POWER_STEP)

    /**
     * Aims from a drag that pulled the sling back by ([dx], [dy]) field widths (y up), from where it was pressed:
     * the ball goes the opposite way, and the further the pull, the harder. Returns whether the pull is long enough
     * to throw ([MIN_PULL]); a shorter one keeps the aim as it was.
     */
    fun pull(dx: Float, dy: Float): Boolean {
        val length = hypot(dx, dy)
        if (length < MIN_PULL) return false
        var degrees = atan2(-dy, -dx) * 180f / PI.toFloat()
        // Pulled forward instead of back: point as near as the launcher allows.
        if (degrees > 90f || degrees < -90f) degrees = if (degrees > 0f) MAX_ANGLE else MIN_ANGLE
        aim(degrees, length / MAX_PULL)
        return true
    }

    /** The ball's speed at launch for [power], in field widths a second. */
    fun speed(power: Float = this.power): Float = MAX_SPEED * power

    /** Throws the ball from the launcher as aimed, if [canThrow]. */
    fun throwBall(): Boolean {
        if (!canThrow) return false
        val a = angle * PI.toFloat() / 180f
        val v = speed()
        ball = TossBall(LAUNCH_X, LAUNCH_Y, cos(a) * v, sin(a) * v, time)
        throws++
        throwHit = false
        thrownNow = true
        return true
    }

    /** How many seconds of the arc the [preview] shows now: more after every miss in a row, the whole arc after four. */
    val previewSeconds: Float
        get() = if (missesInARow >= FULL_AFTER) FULL_PREVIEW else BASE_PREVIEW + missesInARow * PREVIEW_STEP

    /** The dotted arc from the launcher as aimed, [previewSeconds] long, ending where it would first touch something. */
    fun preview(seconds: Float = previewSeconds): List<TossPoint> {
        val a = angle * PI.toFloat() / 180f
        val v = speed()
        var x = LAUNCH_X
        var y = LAUNCH_Y
        var vx = cos(a) * v
        var vy = sin(a) * v
        val out = mutableListOf(TossPoint(x, y))
        var t = 0f
        while (t < seconds) {
            val d = minOf(PREVIEW_DT, seconds - t)
            val py = y
            vy -= GRAVITY * d
            x += vx * d
            y += vy * d
            t += d
            val touch = standing.firstOrNull { it.hitAt == null && touches(it, x, y, py, vy) }
            if (y - RADIUS <= 0f || touch != null || x > 1.1f) {
                out += TossPoint(x, y.coerceAtLeast(RADIUS))
                return out
            }
            out += TossPoint(x, y)
        }
        return out
    }

    /** Where the whole arc as aimed comes down next to the nearest standing target, or null once none stands. */
    fun aimHint(): Pair<TossTarget, AimHint>? {
        val end = preview(FULL_PREVIEW).last()
        val target = standing.filter { it.hitAt == null }.minByOrNull { abs(it.x - end.x) } ?: return null
        val hint = when {
            end.x < target.left - RADIUS -> AimHint.SHORT
            end.x > target.right + RADIUS -> AimHint.LONG
            else -> AimHint.ON
        }
        return target to hint
    }

    /** Runs the round on by [dt] seconds (at most [MAX_FRAME]) in small steps; returns what happened. */
    fun step(dt: Float): List<TossEvent> {
        val events = mutableListOf<TossEvent>()
        if (thrownNow) {
            events += TossEvent.THROWN
            thrownNow = false
        }
        var left = dt.coerceIn(0f, MAX_FRAME)
        while (left > 0f) {
            val d = minOf(left, MAX_STEP)
            advance(d, events)
            left -= d
        }
        return events
    }

    private fun advance(d: Float, events: MutableList<TossEvent>) {
        time += d
        // Targets that were hit fade out, and a new one pops up in their place a moment later.
        standing.removeAll { it.hitAt != null && time - it.hitAt > CLEAR_S }
        val due = pending.filter { time >= it.second }
        for ((lane, _) in due) {
            pending.removeAll { it.first == lane }
            if (shown < TARGETS) {
                place(lane, nextKind(), time)
                events += TossEvent.APPEARED
            }
        }
        val b = ball ?: return
        var vx = b.vx
        var vy = b.vy - GRAVITY * d
        var x = b.x + vx * d
        var y = b.y + vy * d
        var bounces = b.bounces
        var knocked = b.knocked
        for (target in standing) {
            if (target.hitAt != null || !touches(target, x, y, b.y, vy)) continue
            if (target.kind.knock && !knocked) {
                hit(target, events, TossEvent.KNOCKED)
                // The ball bounces softly back off the stack and drops.
                knocked = true
                vx = -abs(vx) * 0.25f
                vy = minOf(vy, 0.2f)
            } else if (!target.kind.knock && b.y - RADIUS >= target.top && vy < 0f) {
                hit(target, events, TossEvent.LANDED_IN)
                ball = null
                endThrow(events)
                return
            } else if (!target.kind.knock) {
                // A glancing knock on the side of a bucket or pallet: it bounces off.
                vx = if (x < target.x) -abs(vx) * 0.4f else abs(vx) * 0.4f
                x = if (x < target.x) target.left - RADIUS else target.right + RADIUS
            }
        }
        if (y - RADIUS <= 0f && vy < 0f) {
            y = RADIUS
            if (bounces < MAX_BOUNCES && -vy > SETTLE_SPEED) {
                vy = -vy * BOUNCE
                vx *= ROLL
                bounces++
                events += TossEvent.BOUNCED
            } else {
                splat = TossPoint(x, 0f) to time
                ball = null
                events += TossEvent.SPLAT
                endThrow(events)
                return
            }
        }
        if (x > 1.12f || x < -0.12f || time - b.thrownAt > MAX_FLIGHT_S) {
            ball = null
            endThrow(events)
            return
        }
        ball = TossBall(x, y, vx, vy, b.thrownAt, bounces, knocked)
    }

    /** Whether a ball at ([x], [y]), [prevY] a moment ago and falling at [vy], touches [target]. */
    private fun touches(target: TossTarget, x: Float, y: Float, prevY: Float, vy: Float): Boolean {
        if (x < target.left - RADIUS || x > target.right + RADIUS) return false
        if (target.kind.knock) return y - RADIUS < target.top
        // A bucket or pallet: dropping in through its top, or running into its side.
        val dropsIn = vy < 0f && prevY - RADIUS >= target.top && y - RADIUS < target.top
        return dropsIn || y - RADIUS < target.top
    }

    private fun hit(target: TossTarget, events: MutableList<TossEvent>, event: TossEvent) {
        val i = standing.indexOf(target)
        standing[i] = target.copy(hitAt = time)
        hits++
        throwHit = true
        events += event
        if (isDone) {
            doneAt = time
            events += TossEvent.DONE
        } else {
            pending += target.lane to time + RESPAWN_S
        }
    }

    private fun endThrow(events: MutableList<TossEvent>) {
        if (throwHit) {
            missesInARow = 0
        } else {
            missesInARow++
            events += TossEvent.MISSED
        }
    }

    private fun place(lane: Int, kind: TossTargetKind, at: Float) {
        // A little closer or further each time, so no two throws are quite the same.
        val x = LANES[lane] + (random.nextFloat() * 2f - 1f) * LANE_JITTER
        standing += TossTarget(nextId++, kind, lane, x, at)
        shown++
    }

    /** A kind for the next target: the one fewer of them stands now, so both kinds keep coming. */
    private fun nextKind(): TossTargetKind {
        val counts = kinds.map { k -> standing.count { it.kind == k && it.hitAt == null } }
        return if (counts[0] == counts[1]) kinds[random.nextInt(2)] else kinds[if (counts[0] < counts[1]) 0 else 1]
    }

    companion object {
        /** Targets to hit in a round. */
        const val TARGETS = 5

        /** Targets standing at once. */
        const val STANDING = 3

        /** The middles of the three spots targets stand in: near, middle and far. */
        val LANES = listOf(0.42f, 0.63f, 0.85f)

        /** How far a target stands from its spot's middle, at most. */
        const val LANE_JITTER = 0.025f

        /** Where the ball leaves the launcher. */
        const val LAUNCH_X = 0.13f
        const val LAUNCH_Y = 0.15f

        /** The ball's radius. */
        const val RADIUS = 0.026f

        /** Gravity, in field widths a second squared: a slow, floaty arc. */
        const val GRAVITY = 0.95f

        /** The launch speed at full power. */
        const val MAX_SPEED = 0.95f

        const val MIN_ANGLE = 12f
        const val MAX_ANGLE = 78f
        const val MIN_POWER = 0.2f
        const val ANGLE_STEP = 3f
        const val POWER_STEP = 0.04f

        /** The pull, in field widths, for full power, and the shortest that throws. */
        const val MAX_PULL = 0.26f
        const val MIN_PULL = 0.03f

        /** The preview arc at first, how much longer each miss in a row makes it, and the whole arc after [FULL_AFTER]. */
        const val BASE_PREVIEW = 0.4f
        const val PREVIEW_STEP = 0.25f
        const val FULL_AFTER = 4
        const val FULL_PREVIEW = 5f

        /** How much of its speed a ball keeps bouncing up off the ground, and rolling along it. */
        private const val BOUNCE = 0.36f
        private const val ROLL = 0.55f
        private const val MAX_BOUNCES = 2
        private const val SETTLE_SPEED = 0.22f

        /** How long a hit target stays while it topples or fills, and when a new one pops up. */
        const val CLEAR_S = 1.4f
        const val RESPAWN_S = 1.6f

        private const val MAX_FLIGHT_S = 6f
        private const val PREVIEW_DT = 1f / 60f
        private const val MAX_STEP = 1f / 240f

        /** The longest frame the round runs on by. */
        const val MAX_FRAME = 0.25f
    }
}
