package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.lerp
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade
import kotlin.math.floor
import kotlin.math.sin

/** How a [DigLook]'s patch of sand is framed: a wooden sandbox, a driftwood box, or a riveted metal tray. */
internal enum class DigFrame { WOOD, DRIFTWOOD, METAL }

/**
 * The look of a Treasure dig in one arena: its sand ([light], [sand], [shade]), the inside of a hole ([hole] down to
 * [deep]), the [flecks] in the grains, the [frame] around the patch in [wood] colors, the little shovel's [blade]
 * and [handle], and the three [finds] buried there.
 */
internal class DigLook(
    val light: Color,
    val sand: Color,
    val shade: Color,
    val hole: Color,
    val deep: Color,
    val flecks: List<Color>,
    val frame: DigFrame,
    val wood: Color,
    val woodLight: Color,
    val woodDark: Color,
    val blade: Color,
    val handle: Color,
    val finds: List<DigFind>,
) {
    companion object {
        /** [arena]'s dig, its colors through [g]. Arenas without a Treasure dig get the Playground's. */
        fun of(arena: Arena, g: SceneGrade): DigLook = when (arena) {
            Arena.BEACH -> DigLook(
                g(0xFFFFF5DC), g(0xFFF3DFB2), g(0xFFD8BC86), g(0xFFC6A473), g(0xFF8E6E46),
                listOf(g(0xFFF2A9A0), g(0xFFFFFFFF), g(0xFFC9AE80)),
                DigFrame.DRIFTWOOD, g(0xFFC2AE92), g(0xFFE0D2BA), g(0xFF8C7963),
                g(0xFF2FA8E0), g(0xFFFFE07A), beachFinds,
            )
            Arena.MARS -> DigLook(
                g(0xFFEA9A6C), g(0xFFD27145), g(0xFFA9512F), g(0xFF84381F), g(0xFF4E1E12),
                listOf(g(0xFF4A3A36), g(0xFF6A4E44), g(0xFFFFC28A)),
                DigFrame.METAL, g(0xFF9AA3AE), g(0xFFD3D9E0), g(0xFF5E6670),
                g(0xFFC9D0D8), g(0xFFEDEFF2), marsFinds,
            )
            else -> DigLook(
                g(0xFFF2D6A2), g(0xFFE1B97C), g(0xFFC0945A), g(0xFF9C7142), g(0xFF5E3F22),
                listOf(g(0xFFB98E5A), g(0xFF9C9488), g(0xFFFFEBC2)),
                DigFrame.WOOD, g(0xFFC98A4B), g(0xFFE5AC6B), g(0xFF8E5A2E),
                g(0xFFE8574A), g(0xFFFFD04A), sandboxToys,
            )
        }
    }
}

/**
 * Where a [columns] x [rows] dig sits in a [width] x [height] area, in pixels: the patch's top-left [origin], the
 * size of a [cell], and the [rim] of the frame around it. Centered, as big as fits.
 */
internal class DigLayout(width: Float, height: Float, val columns: Int, val rows: Int) {
    val cell: Float = minOf(width / (columns + 2 * RIM), height / (rows + 2 * RIM))
    val rim: Float = cell * RIM
    val origin: Offset = Offset((width - cell * columns) / 2, (height - cell * rows) / 2)

    /** The patch of sand, without the frame. */
    val patch: Rect get() = Rect(origin, Size(cell * columns, cell * rows))

    fun center(index: Int): Offset = origin + Offset((index % columns + 0.5f) * cell, (index / columns + 0.5f) * cell)

    /** The cell at [point], or null off the patch. */
    fun cellAt(point: Offset): Int? {
        val x = floor((point.x - origin.x) / cell).toInt()
        val y = floor((point.y - origin.y) / cell).toInt()
        return if (x in 0 until columns && y in 0 until rows) y * columns + x else null
    }

    private companion object {
        /** The frame's width, in cells. */
        const val RIM = 0.42f
    }
}

/** The frame around the patch: planks with grain and nails, bleached driftwood with knots, or riveted steel. */
internal fun DrawScope.drawDigFrame(look: DigLook, layout: DigLayout) {
    val inner = layout.patch
    val rim = layout.rim
    val outer = Rect(inner.left - rim, inner.top - rim, inner.right + rim, inner.bottom + rim)
    val corner = CornerRadius(rim * if (look.frame == DigFrame.METAL) 0.7f else 0.5f)
    // A soft shadow on the scenery, then the frame's dark side and its lit face.
    drawRoundRect(Color.Black.copy(alpha = 0.22f), outer.topLeft + Offset(0f, rim * 0.45f), outer.size, corner)
    drawRoundRect(look.woodDark, outer.topLeft + Offset(0f, rim * 0.22f), outer.size, corner)
    drawRoundRect(Brush.verticalGradient(listOf(look.woodLight, look.wood), outer.top, outer.bottom), outer.topLeft, outer.size, corner)
    when (look.frame) {
        DigFrame.WOOD, DigFrame.DRIFTWOOD -> {
            val grain = look.woodDark.copy(alpha = if (look.frame == DigFrame.WOOD) 0.32f else 0.22f)
            val w = rim * 0.06f
            // Grain lines along each side, and the mitred joints at the corners.
            for (k in 1..2) {
                val d = rim * k / 3f
                drawLine(grain, Offset(inner.left + rim * 0.3f, outer.top + d), Offset(inner.right - rim * 0.3f, outer.top + d), w)
                drawLine(grain, Offset(inner.left + rim * 0.3f, inner.bottom + d), Offset(inner.right - rim * 0.3f, inner.bottom + d), w)
                drawLine(grain, Offset(outer.left + d, inner.top + rim * 0.3f), Offset(outer.left + d, inner.bottom - rim * 0.3f), w)
                drawLine(grain, Offset(inner.right + d, inner.top + rim * 0.3f), Offset(inner.right + d, inner.bottom - rim * 0.3f), w)
            }
            val joint = look.woodDark.copy(alpha = 0.5f)
            drawLine(joint, outer.topLeft + Offset(rim * 0.2f, rim * 0.2f), inner.topLeft, w * 1.5f)
            drawLine(joint, Offset(outer.right - rim * 0.2f, outer.top + rim * 0.2f), Offset(inner.right, inner.top), w * 1.5f)
            drawLine(joint, Offset(outer.left + rim * 0.2f, outer.bottom - rim * 0.2f), Offset(inner.left, inner.bottom), w * 1.5f)
            drawLine(joint, Offset(outer.right - rim * 0.2f, outer.bottom - rim * 0.2f), Offset(inner.right, inner.bottom), w * 1.5f)
            if (look.frame == DigFrame.WOOD) {
                for (c in listOf(outer.topLeft, Offset(outer.right, outer.top), Offset(outer.left, outer.bottom), outer.bottomRight)) {
                    val p = Offset(if (c.x < inner.left) c.x + rim * 0.5f else c.x - rim * 0.5f, if (c.y < inner.top) c.y + rim * 0.5f else c.y - rim * 0.5f)
                    drawCircle(look.woodDark, rim * 0.1f, p)
                    drawCircle(look.woodLight, rim * 0.045f, p - Offset(rim * 0.03f, rim * 0.03f))
                }
            } else {
                // A few knots in the bleached wood.
                val knots = listOf(
                    Offset(inner.left + inner.width * 0.3f, outer.top + rim * 0.5f),
                    Offset(inner.left + inner.width * 0.72f, inner.bottom + rim * 0.5f),
                    Offset(outer.left + rim * 0.5f, inner.top + inner.height * 0.6f),
                )
                for (p in knots) {
                    drawOval(look.woodDark.copy(alpha = 0.4f), p - Offset(rim * 0.22f, rim * 0.12f), Size(rim * 0.44f, rim * 0.24f), style = Stroke(w * 1.4f))
                }
            }
        }
        DigFrame.METAL -> {
            drawRoundRect(Color.White.copy(alpha = 0.35f), outer.topLeft + Offset(rim * 0.2f, rim * 0.12f), Size(outer.width - rim * 0.4f, rim * 0.16f), CornerRadius(rim * 0.08f))
            val step = layout.cell
            fun rivet(p: Offset) {
                drawCircle(look.woodDark, rim * 0.11f, p + Offset(0f, rim * 0.03f))
                drawCircle(look.woodLight, rim * 0.09f, p)
                drawCircle(Color.White.copy(alpha = 0.8f), rim * 0.035f, p - Offset(rim * 0.03f, rim * 0.03f))
            }
            for (i in 0..layout.columns) {
                rivet(Offset(inner.left + i * step, outer.top + rim * 0.5f))
                rivet(Offset(inner.left + i * step, inner.bottom + rim * 0.5f))
            }
            for (j in 1 until layout.rows) {
                rivet(Offset(outer.left + rim * 0.5f, inner.top + j * step))
                rivet(Offset(inner.right + rim * 0.5f, inner.top + j * step))
            }
        }
    }
    // The bed under the sand squares shows in the gaps between them.
    drawRoundRect(look.hole, inner.topLeft, inner.size, CornerRadius(rim * 0.25f))
    drawRoundRect(Color.Black.copy(alpha = 0.18f), inner.topLeft, inner.size, CornerRadius(rim * 0.25f), style = Stroke(rim * 0.12f))
}

/**
 * One square of untouched sand at [center], a soft mound with a lit top, a shaded lip and a few grains and pebbles
 * in it. [press] (0 to 1) squashes it as the shovel goes in; [seed] varies its grains.
 */
internal fun DrawScope.drawSandSquare(look: DigLook, center: Offset, cell: Float, seed: Int, press: Float = 0f) {
    val inset = cell * 0.045f
    val w = cell - 2 * inset
    val h = w * (1f - 0.08f * press)
    val top = center.y + w / 2 - h
    val left = center.x - w / 2
    val corner = CornerRadius(cell * 0.2f)
    val tint = noise(seed) * 0.18f
    drawRoundRect(look.shade, Offset(left, top + cell * 0.06f), Size(w, h), corner)
    drawRoundRect(
        Brush.verticalGradient(listOf(lerp(look.light, Color.White, tint * 0.4f), lerp(look.sand, look.light, tint)), top, top + h),
        Offset(left, top),
        Size(w, h - cell * 0.04f),
        corner,
    )
    // A soft highlight across the top of the mound.
    drawRoundRect(Color.White.copy(alpha = 0.22f), Offset(left + w * 0.14f, top + h * 0.08f), Size(w * 0.5f, h * 0.14f), CornerRadius(h * 0.07f))
    for (k in 0 until 5) {
        val color = look.flecks[(seed + k) % look.flecks.size]
        val p = Offset(left + w * (0.15f + 0.7f * noise(seed * 7 + k)), top + h * (0.3f + 0.6f * noise(seed * 13 + k + 50)))
        drawCircle(color.copy(alpha = 0.75f), cell * (0.018f + 0.022f * noise(seed + k * 31)), p)
    }
}

/** A pseudo-random number in 0..1 for [seed], always the same for the same seed. */
internal fun noise(seed: Int): Float {
    val x = sin(seed * 12.9898f + 1.7f) * 43758.547f
    return x - floor(x)
}
