/** A bit of sand knocked loose by the finger, tumbling down for a moment. */
internal class Crumb(var x: Float, var y: Float, var vx: Float, var vy: Float, val color: Int, var age: Float = 0f)

/** How long a crumb tumbles, in seconds. */
internal const val CRUMB_S = 0.45f

/**
 * The whole Sand flow at this frame: the rim and the sand with its strata, sky over a dune, rocks, carved channels,
 * the water with its shimmer, the target filling ([shownFill], 0 to 1) with the duck or palm, and the pipe or spring.
 * [time] is in seconds; [done] is how far along the finish is, 0 to 1, or null before it.
 */
internal fun DrawScope.drawSandFlow(
    look: FlowLook,
    grade: SceneGrade,
    layout: FlowLayout,
    round: SandFlow,
    shownFill: Float,
    time: Float,
    done: Float?,
    crumbs: List<Crumb>,
) {
    val grid = layout.grid
    val s = layout.cell
    val corner = CornerRadius(s * 0.42f)
    val rim = layout.rim
    val outer = Rect(grid.left - rim, grid.top - rim, grid.right + rim, grid.bottom + rim)
    // The rim: a soft shadow on the scenery, its dark side, then its lit face.
    drawRoundRect(Color.Black.copy(alpha = 0.2f), outer.topLeft + Offset(0f, rim * 0.6f), outer.size, CornerRadius(s * 0.6f))
    drawRoundRect(look.rimDark, outer.topLeft + Offset(0f, rim * 0.25f), outer.size, CornerRadius(s * 0.6f))
    drawRoundRect(Brush.verticalGradient(listOf(look.rimLight, look.rim), outer.top, outer.bottom), outer.topLeft, outer.size, CornerRadius(s * 0.6f))
    val clip = Path().apply { addRoundRect(androidx.compose.ui.geometry.RoundRect(grid, corner)) }
    clipPath(clip) {
        drawSand(look, layout, round)
        drawTarget(look, grade, layout, round, shownFill, time, done)
        drawBlobs(layout, round, look.rockShade, inset = 0.05f, lift = 0.07f) { round.cell(it) == FlowCell.ROCK }
        drawBlobs(layout, round, look.rock, inset = 0.07f) { round.cell(it) == FlowCell.ROCK }
        drawRockShine(look, layout, round)
        drawBlobs(layout, round, look.tunnelDeep, inset = 0f) { round.cell(it) == FlowCell.OPEN }
        drawBlobs(layout, round, look.tunnel, inset = 0.0f, lift = 0.12f) { round.cell(it) == FlowCell.OPEN }
        drawWater(look, layout, round, time)
        drawPours(look, layout, round, shownFill, time)
        for (c in crumbs) {
            val k = (c.age / CRUMB_S).coerceIn(0f, 1f)
            drawCircle(look.flecks[c.color % look.flecks.size].copy(alpha = 1f - k), s * 0.07f * (1f - 0.4f * k), Offset(c.x, c.y))
        }
        // A soft inner shadow round the edge, as if looking into the ground.
        drawRoundRect(Color.Black.copy(alpha = 0.16f), grid.topLeft, grid.size, corner, style = Stroke(s * 0.12f))
    }
    drawTargetKeepsake(look, grade, layout, round, shownFill, time, done)
    drawSource(look, grade, layout, round, time)
}

/** The sand: deeper colors further down, wavy strata and flecks; on a dune, the sky over its slope. */
private fun DrawScope.drawSand(look: FlowLook, layout: FlowLayout, round: SandFlow) {
    val grid = layout.grid
    val s = layout.cell
    if (look.isDune) drawRect(Brush.verticalGradient(listOf(look.skyTop, look.skyBottom), grid.top, grid.bottom), grid.topLeft, grid.size)
    // The ground line: under the sky in each column, smoothed from column to column.
    val ground = FloatArray(round.columns) { x ->
        var y = 0
        while (y < round.rows && round.cell(x, y) == FlowCell.AIR) y++
        grid.top + y * s
    }
    val surface = Path().apply {
        moveTo(grid.left, grid.bottom)
        lineTo(grid.left, ground[0])
        for (x in 0 until round.columns) {
            val mid = grid.left + (x + 0.5f) * s
            val next = if (x + 1 < round.columns) ground[x + 1] else ground[x]
            quadraticBezierTo(mid, ground[x], grid.left + (x + 1) * s, (ground[x] + next) / 2)
        }
        lineTo(grid.right, grid.bottom)
        close()
    }
    clipPath(surface) {
        drawRect(Brush.verticalGradient(listOf(look.light, look.sand, look.deep), grid.top, grid.bottom), grid.topLeft, grid.size)
        // Wavy layers of sand, a little darker each.
        for (k in 1..5) {
            val y0 = grid.top + grid.height * k / 6f
            val band = Path().apply {
                moveTo(grid.left, y0)
                var x = grid.left
                while (x <= grid.right + s) {
                    lineTo(x, y0 + sin(x / s * 0.9f + k * 1.7f) * s * 0.18f)
                    x += s * 0.5f
                }
            }
            drawPath(band, look.strata.copy(alpha = 0.35f), style = Stroke(s * 0.1f))
        }
        for (i in 0 until round.size) {
            if (round.cell(i) != FlowCell.SAND) continue
            val tl = layout.topLeft(i % round.columns, i / round.columns)
            for (k in 0 until 3) {
                val p = tl + Offset(s * (0.15f + 0.7f * noise(i * 7 + k)), s * (0.15f + 0.7f * noise(i * 13 + k + 50)))
                drawCircle(look.flecks[(i + k) % look.flecks.size].copy(alpha = 0.7f), s * (0.03f + 0.03f * noise(i + k * 31)), p)
            }
        }
    }
    if (look.isDune) drawPath(surface, Color.White.copy(alpha = 0.35f), style = Stroke(s * 0.08f))
}

/**
 * Cells where [where] holds as one rounded shape: each a rounded square, joined to its neighbors by bars, so
 * channels and rock groups read as smooth blobs. [inset] (in cells) shrinks it; [lift] shifts its bottom up.
 */
private inline fun DrawScope.drawBlobs(layout: FlowLayout, round: SandFlow, color: Color, inset: Float, lift: Float = 0f, where: (Int) -> Boolean) {
    val s = layout.cell
    val pad = s * inset
    val r = CornerRadius(s * 0.36f)
    val dy = s * lift
    for (i in 0 until round.size) {
        if (!where(i)) continue
        val x = i % round.columns
        val y = i / round.columns
        val tl = layout.topLeft(x, y)
        drawRoundRect(color, tl + Offset(pad, pad), Size(s - 2 * pad, s - 2 * pad - dy), r)
        val right = x + 1 < round.columns && where(i + 1)
        val down = y + 1 < round.rows && where(i + round.columns)
        if (right) drawRect(color, tl + Offset(s / 2, pad), Size(s, s - 2 * pad - dy))
        if (down) drawRect(color, tl + Offset(pad, s / 2), Size(s - 2 * pad, s))
        if (right && down && where(i + round.columns + 1)) drawRect(color, tl + Offset(s / 2, s / 2), Size(s, s))
    }
}

/** A glossy highlight on each rock's top-left. */
private fun DrawScope.drawRockShine(look: FlowLook, layout: FlowLayout, round: SandFlow) {
    val s = layout.cell
    for (i in 0 until round.size) {
        if (round.cell(i) != FlowCell.ROCK) continue
        val x = i % round.columns
        val y = i / round.columns
        val above = y > 0 && round.cell(i - round.columns) == FlowCell.ROCK
        if (above) continue
        val tl = layout.topLeft(x, y)
        drawRoundRect(look.rockLight, tl + Offset(s * 0.2f, s * 0.16f), Size(s * 0.6f, s * 0.2f), CornerRadius(s * 0.1f))
        drawCircle(look.rockShade.copy(alpha = 0.5f), s * 0.06f, tl + Offset(s * (0.3f + 0.4f * noise(i)), s * 0.62f))
    }
}

/** The water: one blue shape over the wet cells, a bright line where its top meets the air, and a moving shimmer. */
private fun DrawScope.drawWater(look: FlowLook, layout: FlowLayout, round: SandFlow, time: Float) {
    val s = layout.cell
    drawBlobs(layout, round, look.waterDeep, inset = 0.04f) { round.isWet(it) }
    drawBlobs(layout, round, look.water, inset = 0.08f, lift = 0.08f) { round.isWet(it) }
    for (i in 0 until round.size) {
        if (!round.isWet(i)) continue
        val x = i % round.columns
        val y = i / round.columns
        val tl = layout.topLeft(x, y)
        val top = y == 0 || !round.isWet(i - round.columns)
        if (top) drawRoundRect(look.waterLight.copy(alpha = 0.85f), tl + Offset(s * 0.12f, s * 0.12f), Size(s * 0.76f, s * 0.12f), CornerRadius(s * 0.06f))
        // A glint that drifts through the water.
        val wave = sin(time * 3.2f - x * 0.9f + y * 0.6f)
        if (wave > 0.3f) {
            val a = (wave - 0.3f) / 0.7f
            val p = tl + Offset(s * (0.3f + 0.35f * noise(i * 3 + (time * 0.5f).toInt())), s * (0.4f + 0.25f * noise(i * 5)))
            drawRoundRect(Color.White.copy(alpha = 0.55f * a), p, Size(s * 0.26f, s * 0.07f), CornerRadius(s * 0.04f))
        }
    }
}

/** The bounds of the target cells. */
internal fun FlowLayout.targetRect(round: SandFlow): Rect {
    val cells = (0 until round.size).filter { round.cell(it) == FlowCell.TARGET }
    val xs = cells.map { it % round.columns }
    val ys = cells.map { it / round.columns }
    return Rect(topLeft(xs.min(), ys.min()), topLeft(xs.max() + 1, ys.max() + 1))
}

/** The basin the water fills, as a fraction of the target rect from the left, top, right and bottom. */
private fun basin(look: FlowLook, r: Rect, s: Float): Rect =
    if (look.isDune) Rect(r.left + s * 0.15f, r.top + s * 0.55f, r.right - s * 0.15f, r.bottom - s * 0.2f)
    else Rect(r.left + s * 0.3f, r.top + s * 1.0f, r.right - s * 0.3f, r.bottom - s * 0.22f)

/** The top of the water in the basin at [fill]. */
private fun waterTop(b: Rect, fill: Float): Float = b.bottom - (b.height - b.height * 0.08f) * fill

/**
 * The target's room: a cozy hollow with a tub in it for the duck, or the oasis pool in the dune's hollow, its
 * water rising with [fill].
 */
private fun DrawScope.drawTarget(look: FlowLook, grade: SceneGrade, layout: FlowLayout, round: SandFlow, fill: Float, time: Float, done: Float?) {
    val s = layout.cell
    val r = layout.targetRect(round)
    val b = basin(look, r, s)
    if (look.isDune) {
        val bowl = Path().apply {
            moveTo(b.left, b.top)
            cubicTo(b.left + b.width * 0.08f, b.bottom + s * 0.1f, b.right - b.width * 0.08f, b.bottom + s * 0.1f, b.right, b.top)
            close()
        }
        drawPath(bowl, lerp(look.tunnel, look.deep, 0.4f))
        clipPath(bowl) {
            val top = waterTop(b, fill)
            drawRect(Brush.verticalGradient(listOf(look.water, look.waterDeep), top, b.bottom), Offset(b.left, top), Size(b.width, b.bottom - top + s))
            if (fill > 0.02f) {
                drawRect(look.waterLight.copy(alpha = 0.8f), Offset(b.left, top), Size(b.width, s * 0.09f))
                for (k in 0 until 3) {
                    val x = b.left + b.width * ((k * 0.33f + time * 0.07f) % 1f)
                    drawRoundRect(Color.White.copy(alpha = 0.4f), Offset(x, top + s * 0.2f + k * s * 0.12f), Size(s * 0.5f, s * 0.06f), CornerRadius(s * 0.03f))
                }
            }
            // Dry, cracked mud at the bottom until the water covers it.
            if (fill < 0.4f) {
                val crack = look.tunnelDeep.copy(alpha = 0.5f * (1f - fill / 0.4f))
                drawLine(crack, Offset(b.center.x - s * 0.8f, b.bottom - s * 0.25f), Offset(b.center.x - s * 0.2f, b.bottom - s * 0.1f), s * 0.05f)
                drawLine(crack, Offset(b.center.x - s * 0.2f, b.bottom - s * 0.1f), Offset(b.center.x + s * 0.6f, b.bottom - s * 0.3f), s * 0.05f)
            }
        }
        drawPath(bowl, look.rimDark.copy(alpha = 0.4f), style = Stroke(s * 0.06f))
        // Tufts of grass on the banks, greener as the water comes.
        val grass = lerp(grade(0xFFB59A5A), grade(0xFF4C9A44), fill)
        for (k in 0 until 4) {
            val x = if (k < 2) r.left + s * (0.1f + 0.15f * k) else r.right - s * (0.1f + 0.15f * (k - 2))
            drawLine(grass, Offset(x, b.top + s * 0.05f), Offset(x + (if (k < 2) -1 else 1) * s * 0.06f, b.top - s * (0.25f + 0.2f * fill)), s * 0.06f)
        }
    } else {
        // A cozy hollow under the sandbox with a tub in it, seen cut in half.
        drawRoundRect(Brush.verticalGradient(listOf(look.tunnelDeep, look.tunnel), r.top, r.bottom), r.topLeft, r.size, CornerRadius(s * 0.4f))
        drawRoundRect(Color.Black.copy(alpha = 0.12f), r.topLeft, r.size, CornerRadius(s * 0.4f), style = Stroke(s * 0.1f))
        val inside = grade(0xFFE6F2F8)
        val tub = Path().apply {
            moveTo(b.left, b.top)
            lineTo(b.right, b.top)
            lineTo(b.right, b.bottom - s * 0.5f)
            quadraticBezierTo(b.right, b.bottom, b.right - s * 0.5f, b.bottom)
            lineTo(b.left + s * 0.5f, b.bottom)
            quadraticBezierTo(b.left, b.bottom, b.left, b.bottom - s * 0.5f)
            close()
        }
        drawPath(tub, inside)
        clipPath(tub) {
            val top = waterTop(b, fill)
            drawRect(Brush.verticalGradient(listOf(look.water.copy(alpha = 0.9f), look.waterDeep), top, b.bottom), Offset(b.left, top), Size(b.width, b.bottom - top))
            if (fill > 0.02f) drawRect(look.waterLight, Offset(b.left, top), Size(b.width, s * 0.08f))
            // Bubbles on the bath.
            if (fill > 0.3f) {
                for (k in 0 until 5) {
                    val x = b.left + b.width * (0.1f + 0.2f * k)
                    drawCircle(Color.White.copy(alpha = 0.75f), s * (0.1f + 0.05f * noise(k)), Offset(x, top - s * 0.02f + sin(time * 2f + k) * s * 0.03f))
                }
            }
        }
        // The tub's walls, rim and little feet, in a glossy enamel.
        val enamel = grade(0xFFFFFFFF)
        val enamelShade = grade(0xFFC9D6E0)
        drawPath(tub, enamelShade, style = Stroke(s * 0.2f))
        drawPath(tub, enamel, style = Stroke(s * 0.11f))
        drawRoundRect(enamel, Offset(b.left - s * 0.18f, b.top - s * 0.1f), Size(b.width + s * 0.36f, s * 0.2f), CornerRadius(s * 0.1f))
        for (fx in floatArrayOf(b.left + s * 0.45f, b.right - s * 0.45f)) {
            drawCircle(grade(0xFFFFC94A), s * 0.13f, Offset(fx, b.bottom + s * 0.12f))
        }
    }
    if (done != null && done < 1f) drawGlow(r.center, s * (1.2f + 2f * done), Color(0xFFFFF2B0).copy(alpha = 0.7f * (1f - done)))
}

/** The duck floating on the bath, or the oasis palm on its bank, perking up green as the pool fills. */
private fun DrawScope.drawTargetKeepsake(look: FlowLook, grade: SceneGrade, layout: FlowLayout, round: SandFlow, fill: Float, time: Float, done: Float?) {
    val s = layout.cell
    val r = layout.targetRect(round)
    val b = basin(look, r, s)
    val t = time / 30f
    if (look.isDune) {
        // The palm stands on the far bank, wilted and pale until the water comes.
        val size = s * 3.9f
        val unit = size / 100f
        val baseX = b.center.x + s * 0.2f
        val baseY = b.top + s * 0.1f
        val perk = fill
        drawIntoCanvas { canvas ->
            val paint = Paint().apply { colorFilter = ColorFilter.colorMatrix(ColorMatrix().apply { setToSaturation(0.2f + 0.8f * perk) }) }
            canvas.saveLayer(Rect(baseX - size, baseY - size * 1.3f, baseX + size, baseY + size * 0.2f), paint)
            translate(baseX, baseY) {
                rotate(-14f * (1f - perk), Offset.Zero) {
                    scale(unit, unit * (0.86f + 0.14f * perk), Offset.Zero) {
                        // Without the art's own little pond: the pool here is the oasis.
                        translate(-52f, -86f) { clipRect(-40f, -40f, 140f, 86f) { drawKeepsake(Arena.DESERT, 1, t, grade) } }
                    }
                }
            }
            canvas.restore()
        }
        if (done != null) sparkles(Offset(baseX + s * 0.4f, baseY - size * 0.6f), s, done, time)
    } else {
        // The duck rides on the water, a little above it once the tub is full.
        val size = s * 2.2f
        val unit = size / 100f
        val top = waterTop(b, fill)
        val bob = if (fill > 0.05f) sin(time * 2.4f) * s * 0.05f else 0f
        val lift = if (done != null) s * 0.25f * kotlin.math.min(1f, done * 3f) else 0f
        val baseY = minOf(b.bottom - s * 0.05f, top + s * 0.3f) + bob - lift
        val cx = b.center.x
        translate(cx - 52f * unit, baseY - 92f * unit) {
            scale(unit, unit, Offset.Zero) { drawKeepsake(Arena.PLAYGROUND, 2, t, grade) }
        }
        // The water in front of the duck's belly, so it sits in the bath and not on it.
        if (fill > 0.05f) {
            val front = waterTop(b, fill)
            clipRect(b.left, front, b.right, b.bottom) {
                drawRect(look.water.copy(alpha = 0.45f), Offset(b.left + s * 0.06f, front), Size(b.width - s * 0.12f, b.bottom - front - s * 0.06f))
            }
            drawRect(look.waterLight.copy(alpha = 0.7f), Offset(b.left + s * 0.06f, front), Size(b.width - s * 0.12f, s * 0.06f))
        }
        if (done != null) sparkles(Offset(cx, baseY - size * 0.5f), s, done, time)
    }
}

/** A ring of sparkles round [center] as the round finishes. */
private fun DrawScope.sparkles(center: Offset, s: Float, done: Float, time: Float) {
    val n = 7
    for (k in 0 until n) {
        val a = 2 * PI.toFloat() * k / n + time * 0.6f
        val d = s * (0.9f + 1.1f * done)
        val tw = 0.5f + 0.5f * sin(time * 6f + k * 1.3f)
        drawSparkle(center + Offset(cos(a) * d, sin(a) * d * 0.8f), s * (0.12f + 0.1f * tw), Color(0xFFFFF4B8).copy(alpha = (1f - done * 0.6f)))
    }
}

/** Water running into the target: a falling stream from where it entered down to the water's surface. */
private fun DrawScope.drawPours(look: FlowLook, layout: FlowLayout, round: SandFlow, fill: Float, time: Float) {
    val s = layout.cell
    val r = layout.targetRect(round)
    val b = basin(look, r, s)
    val top = waterTop(b, fill)
    for (i in 0 until round.size) {
        if (round.cell(i) != FlowCell.TARGET) continue
        val since = round.sincePour(i) ?: continue
        if (since > POUR_LINGER) continue
        val a = 1f - since / (POUR_LINGER + 1f)
        val tl = layout.topLeft(i % round.columns, i / round.columns)
        val x = (tl.x + s / 2).coerceIn(b.left + s * 0.3f, b.right - s * 0.3f)
        val from = tl.y
        if (top <= from) continue
        drawRoundRect(look.water.copy(alpha = 0.8f * a), Offset(x - s * 0.13f, from), Size(s * 0.26f, top - from), CornerRadius(s * 0.13f))
        drawRoundRect(look.waterLight.copy(alpha = 0.7f * a), Offset(x - s * 0.04f, from), Size(s * 0.07f, top - from), CornerRadius(s * 0.04f))
        // A little splash ring where it lands.
        val ring = (time * 3f + i * 0.37f) % 1f
        drawOval(Color.White.copy(alpha = 0.6f * a * (1f - ring)), Offset(x - s * (0.15f + 0.35f * ring), top - s * 0.06f), Size(s * (0.3f + 0.7f * ring), s * 0.14f), style = Stroke(s * 0.04f))
    }
}

/** Steps a pour stream shows after the last water ran in. */
private const val POUR_LINGER = 5

/** Over the source: a toy pipe coming down into the sandbox, or a spring welling up among stones. */
private fun DrawScope.drawSource(look: FlowLook, grade: SceneGrade, layout: FlowLayout, round: SandFlow, time: Float) {
    val s = layout.cell
    val c = layout.center(round.source)
    val top = layout.grid.top
    if (look.isDune) {
        val pool = Offset(c.x, top + s * 0.05f)
        // Stones round the spring.
        for ((dx, dy, rr) in listOf(Triple(-0.62f, 0.02f, 0.3f), Triple(0.64f, 0.0f, 0.32f), Triple(-0.25f, -0.22f, 0.22f), Triple(0.3f, -0.26f, 0.24f))) {
            val p = pool + Offset(dx * s, dy * s)
            drawCircle(look.rockShade, rr * s, p + Offset(0f, rr * s * 0.25f))
            drawCircle(look.rock, rr * s * 0.92f, p)
            drawCircle(look.rockLight, rr * s * 0.35f, p - Offset(rr * s * 0.3f, rr * s * 0.35f))
        }
        drawOval(look.waterDeep, pool - Offset(s * 0.42f, s * 0.14f), Size(s * 0.84f, s * 0.3f))
        drawOval(look.water, pool - Offset(s * 0.36f, s * 0.12f), Size(s * 0.72f, s * 0.22f))
        // Water welling up.
        val bub = (time * 1.4f) % 1f
        drawOval(look.waterLight.copy(alpha = 0.9f * (1f - bub)), pool - Offset(s * 0.1f + s * 0.2f * bub, s * 0.05f + s * 0.04f * bub), Size(s * (0.2f + 0.4f * bub), s * (0.1f + 0.08f * bub)), style = Stroke(s * 0.05f))
        drawCircle(Color.White.copy(alpha = 0.6f), s * 0.05f, pool + Offset(-s * 0.15f, -s * 0.02f))
    } else {
        // A red toy pipe from above with a collar where it meets the sand.
        val pipe = layout.cell * 0.62f
        val red = grade(0xFFE8574A)
        val redShade = grade(0xFFB8392F)
        val from = top - s * 1.25f
        drawRoundRect(redShade, Offset(c.x - pipe / 2, from), Size(pipe, top - from + s * 0.12f), CornerRadius(pipe * 0.25f))
        drawRoundRect(red, Offset(c.x - pipe / 2, from), Size(pipe * 0.8f, top - from + s * 0.08f), CornerRadius(pipe * 0.25f))
        drawRoundRect(Color.White.copy(alpha = 0.4f), Offset(c.x - pipe * 0.32f, from + s * 0.1f), Size(pipe * 0.14f, top - from - s * 0.3f), CornerRadius(pipe * 0.07f))
        // The collar and a little tap wheel.
        drawRoundRect(grade(0xFFFFD04A), Offset(c.x - pipe * 0.7f, top - s * 0.24f), Size(pipe * 1.4f, s * 0.26f), CornerRadius(s * 0.1f))
        drawRoundRect(Color.White.copy(alpha = 0.45f), Offset(c.x - pipe * 0.55f, top - s * 0.21f), Size(pipe * 0.8f, s * 0.07f), CornerRadius(s * 0.04f))
        val wheel = Offset(c.x + pipe * 0.9f, from + s * 0.45f)
        drawLine(grade(0xFF8A9099), Offset(c.x + pipe / 2, wheel.y), wheel, s * 0.08f)
        rotate(time * 40f, wheel) {
            drawCircle(grade(0xFF3FA7E0), s * 0.2f, wheel, style = Stroke(s * 0.07f))
            drawLine(grade(0xFF3FA7E0), wheel - Offset(s * 0.2f, 0f), wheel + Offset(s * 0.2f, 0f), s * 0.05f)
            drawLine(grade(0xFF3FA7E0), wheel - Offset(0f, s * 0.2f), wheel + Offset(0f, s * 0.2f), s * 0.05f)
        }
        drawCircle(Color.White, s * 0.05f, wheel)
    }
}
