/**
 * The card at the end of any keepsake game: a confetti shower, the keepsake star popping in on a slowly turning
 * sunburst, what the round earned ([outcome]) and buttons to play [keepsake]'s game again or go back to the puzzle.
 */
@Composable
internal fun MinigameResult(
    keepsake: KeepsakeGame,
    level: Int,
    outcome: MinigameOutcome,
    seed: Int,
    onAgain: () -> Unit,
    onDone: () -> Unit,
) {
    val palette = LocalPalette.current
    val card = remember(seed) { Animatable(0f) }
    val badge = remember(seed) { Animatable(0f) }
    val burst = remember(seed) { Animatable(0f) }
    LaunchedEffect(seed) {
        card.animateTo(1f, spring(dampingRatio = 0.55f, stiffness = Spring.StiffnessLow))
    }
    LaunchedEffect(seed) {
        delay(380)
        launch { burst.animateTo(1f, tween(900, easing = FastOutSlowInEasing)) }
        badge.animateTo(1f, spring(dampingRatio = 0.38f, stiffness = Spring.StiffnessMediumLow))
    }
    val turn = rememberInfiniteTransition(label = "sunburst").animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = infiniteRepeatable(tween(16_000, easing = LinearEasing)),
        label = "turn",
    )
    Box(
        Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.4f * card.value.coerceIn(0f, 1f))),
        contentAlignment = Alignment.Center,
    ) {
        Confetti(seed = seed, modifier = Modifier.fillMaxSize())
        Column(
            Modifier
                .padding(24.dp)
                .widthIn(max = 330.dp)
                .graphicsLayer {
                    val s = 0.6f + 0.4f * card.value
                    scaleX = s
                    scaleY = s
                    alpha = card.value.coerceIn(0f, 1f)
                    transformOrigin = TransformOrigin(0.5f, 0.6f)
                }
                .frosted(palette, RoundedCornerShape(30.dp), elevation = 12.dp)
                .background(palette.surface.copy(alpha = 0.7f), RoundedCornerShape(30.dp))
                .padding(start = 24.dp, end = 24.dp, top = 8.dp, bottom = 22.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Box(Modifier.size(150.dp), contentAlignment = Alignment.Center) {
                Box(
                    Modifier.fillMaxSize().drawWithCache {
                        val rays = sunburst(Offset(size.width / 2, size.height / 2), size.minDimension / 2)
                        onDrawBehind {
                            val b = badge.value.coerceIn(0f, 1f)
                            rotate(turn.value) { drawPath(rays, Color(0xFFFFD45A).copy(alpha = 0.35f * b)) }
                            val t = burst.value
                            if (t > 0f && t < 1f) {
                                val reach = size.minDimension * (0.28f + 0.26f * t)
                                for (k in 0 until 10) {
                                    val a = k * PI / 5 + 0.2
                                    val p = center + Offset((cos(a) * reach).toFloat(), (sin(a) * reach).toFloat())
                                    val color = if (k % 2 == 0) Color(0xFFFFE27A) else Color.White
                                    drawSparkle(p, size.minDimension * 0.05f * (1f - t * 0.5f), color.copy(alpha = 1f - t))
                                }
                            }
                        }
                    },
                )
                KeepsakeBadge(
                    keepsake.arena,
                    keepsake.stage,
                    earned = true,
                    modifier = Modifier.size(96.dp).graphicsLayer {
                        val v = badge.value
                        scaleX = v
                        scaleY = v
                        rotationZ = (1f - v) * -25f
                    },
                )
            }
            Text(
                if (outcome == MinigameOutcome.NEW_STAR) "Keepsake star earned!" else "Lovely play!",
                color = palette.accent,
                fontSize = 25.sp,
                lineHeight = 29.sp,
                fontWeight = FontWeight.Black,
                textAlign = TextAlign.Center,
                style = LocalTextStyle.current.withTitleShadow(palette),
            )
            Spacer(Modifier.height(6.dp))
            Text(
                when (outcome) {
                    MinigameOutcome.NEW_STAR -> "The ${keepsake.keepsake} gives level $level a fourth star."
                    MinigameOutcome.REPLAY -> "Level $level already has the ${keepsake.keepsake}'s star. Play any time!"
                    MinigameOutcome.NOT_CLEARED -> "Clear level $level to keep the ${keepsake.keepsake}'s star."
                },
                color = palette.dimText,
                fontSize = 15.sp,
                lineHeight = 19.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
            )
            Spacer(Modifier.height(18.dp))
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                CardButton("Again", onAgain, ButtonStyle.accent(palette), Modifier.weight(1f))
                CardButton("Done", onDone, ButtonStyle.go(palette), Modifier.weight(1f))
            }
        }
    }
}

/** A pill button for two side by side on a card: give each a share of the row's width. */
@Composable
internal fun CardButton(text: String, onClick: () -> Unit, style: ButtonStyle, modifier: Modifier = Modifier) {
    GameButton(onClick, style, modifier.height(52.dp), lip = 5.dp) {
        Text(
            text,
            color = style.content,
            fontSize = 18.sp,
            fontWeight = FontWeight.ExtraBold,
            maxLines = 1,
            modifier = Modifier.padding(horizontal = 12.dp),
        )
    }
}

/** Twelve soft rays around [c], reaching [r]. */
private fun sunburst(c: Offset, r: Float): Path = Path().apply {
    for (k in 0 until 12) {
        val a = k * PI / 6
        val half = PI / 22
        moveTo(c.x, c.y)
        lineTo(c.x + (cos(a - half) * r).toFloat(), c.y + (sin(a - half) * r).toFloat())
        lineTo(c.x + (cos(a + half) * r).toFloat(), c.y + (sin(a + half) * r).toFloat())
        close()
    }
}
