package io.colorsand.ui.minigame

import kotlin.math.abs
import kotlin.math.max
import kotlin.random.Random

/** How close a dug hole is to the nearest find still hidden: right next to one, two squares off, or further. */
enum class Warmth { HOT, WARM, COLD }

/**
 * A round of Treasure dig: a [columns] x [rows] patch of sand with [finds] hidden under some of its squares (cell
 * numbers, row by row). Each dig opens one square; the holes glow warmer the closer they are to a find still hidden.
 * There is no way to lose: after [LUCK] empty digs in a row, the next one turns up the nearest find, so a round
 * never takes more than [LUCK] digs per find. The state is immutable; [dig] returns the next one.
 */
data class TreasureDig(
    val columns: Int,
    val rows: Int,
    val finds: List<Int>,
    val dug: Set<Int> = emptySet(),
    /** The finds dug up so far, as indices into [finds], in the order they were found. */
    val found: List<Int> = emptyList(),
    /** Empty digs since the last find. */
    val misses: Int = 0,
) {
    val cells: Int get() = columns * rows

    val isDone: Boolean get() = found.size == finds.size

    /** The find buried at [cell], dug up or not, or null. */
    fun findAt(cell: Int): Int? = finds.indexOf(cell).takeIf { it >= 0 }

    /** This round after digging [cell]. Digging a hole again, off the patch or after the last find does nothing. */
    fun dig(cell: Int): TreasureDig {
        if (isDone || cell !in 0 until cells || cell in dug) return this
        val here = findAt(cell)
        if (here != null) return copy(dug = dug + cell, found = found + here, misses = 0)
        if (misses + 1 < LUCK) return copy(dug = dug + cell, misses = misses + 1)
        // Lucky: the nearest find still hidden was right here after all.
        val lucky = hidden().minBy { distance(finds[it], cell) }
        return copy(finds = finds.toMutableList().also { it[lucky] = cell }, dug = dug + cell, found = found + lucky, misses = 0)
    }

    /** How warm [cell] is: its distance to the nearest find still hidden. Null once everything is found. */
    fun warmth(cell: Int): Warmth? {
        val nearest = hidden().minOfOrNull { distance(finds[it], cell) } ?: return null
        return when {
            nearest <= 1 -> Warmth.HOT
            nearest == 2 -> Warmth.WARM
            else -> Warmth.COLD
        }
    }

    /** The finds not dug up yet. */
    private fun hidden(): List<Int> = finds.indices.filter { it !in found }

    /** Squares between cells [a] and [b], diagonal steps counting as one. */
    fun distance(a: Int, b: Int): Int = max(abs(a % columns - b % columns), abs(a / columns - b / columns))

    companion object {
        /** The most empty digs in a row before the next dig is sure to find something. */
        const val LUCK = 6

        /**
         * A new round with [count] finds hidden on a [columns] x [rows] patch, the same for the same [seed]. The finds
         * lie at least three squares apart, so each hot hole points at one find.
         */
        fun start(seed: Int, columns: Int = 6, rows: Int = 7, count: Int = 3): TreasureDig {
            val random = Random(seed)
            val empty = TreasureDig(columns, rows, emptyList())
            val finds = mutableListOf<Int>()
            while (finds.size < count) {
                val cell = random.nextInt(columns * rows)
                if (finds.all { empty.distance(it, cell) >= 3 }) finds += cell
            }
            return TreasureDig(columns, rows, finds)
        }
    }
}
