/**
 * Rocket path: [arena]'s keepsake (the kite, the sea turtle, the rocket) flies up a gentle course that scrolls by
 * on its own for about a minute, through rings (or gaps in the reef), collecting sparkles; bumping into a balloon,
 * jellyfish or asteroid just pushes it aside. Drag or hold anywhere to steer; Left and Right steer from the keyboard,
 * and Enter, Space or a screen reader's tap turns on Auto-steer, which follows the sparkles by itself. At the end it
 * glides into the goal (a cloud with the sun, a reef cave, the two moons) and the round calls [onFinished].
 */
@Composable
fun RocketPathGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { PathLook.of(arena, grade) }
    val round = remember(seed) { RocketPath(seed) }
    val pops = remember(seed) { mutableListOf<PathPop>() }
    var frame by remember(seed) { mutableStateOf(0) }
    var collected by remember(seed) { mutableStateOf(0) }
    var rings by remember(seed) { mutableStateOf(0) }
    var auto by remember(seed) { mutableStateOf(false) }
    var arrived by remember(seed) { mutableStateOf(false) }
    var finished by remember(seed) { mutableStateOf(false) }
    var bumped by remember(seed) { mutableStateOf(false) }
    val sceneClock = rememberSceneClock()
    val focus = remember { FocusRequester() }
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }

    LaunchedEffect(round) {
        var last = -1L
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else (now - last) / 1_000_000_000f
                last = now
                round.auto = auto
                for (event in round.step(dt)) {
                    when (event) {
                        PathEvent.SPARKLE -> {
                            round.sparkles.filter { it.collectedAt != null }.maxByOrNull { it.collectedAt!! }?.let {
                                pops += PathPop(it.x, it.d, round.time, big = false)
                            }
                            collected = round.collected
                            feedback.play(Sounds.click)
                            feedback.tick()
                        }
                        PathEvent.RING -> {
                            round.gates.filter { it.passedAt != null }.maxByOrNull { it.passedAt!! }?.let {
                                pops += PathPop(it.x, it.d, round.time, big = true)
                            }
                            rings = round.ringsPassed
                            feedback.play(Sounds.chime((rings % 4) + 1))
                        }
                        PathEvent.BUMP -> {
                            bumped = true
                            feedback.play(Sounds.land)
                            feedback.tick()
                        }
                        PathEvent.ARRIVED -> {
                            arrived = true
                            feedback.confirm()
                        }
                        PathEvent.FINISHED -> finished = true
                    }
                }
                auto = round.auto
                pops.removeAll { round.time - it.at > PATH_POP_S }
                frame++
            }
        }
    }
    LaunchedEffect(finished) {
        if (finished) {
            delay(700)
            onFinished()
        }
    }

    fun toggleAuto() {
        if (arrived) return
        auto = !auto
        round.auto = auto
        feedback.play(Sounds.click)
    }

    val status = when {
        arrived -> look.arrived
        auto -> "Auto-steer on"
        bumped && collected < 6 -> "Boing! It just drifts aside."
        collected >= 24 -> "Nearly there!"
        collected >= 12 -> "Lovely flying! Keep going."
        collected >= 3 -> "Collect the ${look.sparkles}!"
        else -> look.start
    }
    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .clip(RoundedCornerShape(28.dp))
                .semantics {
                    contentDescription = "The ${look.keepsake} flying up toward ${look.goal}, through rings and past ${look.sparkles}"
                    stateDescription = "$collected ${look.sparkles} collected, $rings of ${round.gates.size} rings" +
                        if (auto) ", auto-steer on" else ""
                    onClick(label = if (auto) "Stop auto-steer" else "Auto-steer") { toggleAuto(); true }
                    customActions = listOf(
                        CustomAccessibilityAction(if (auto) "Stop auto-steer" else "Auto-steer") { toggleAuto(); true },
                        CustomAccessibilityAction("Steer left") { round.nudge(-1); auto = false; true },
                        CustomAccessibilityAction("Steer right") { round.nudge(1); auto = false; true },
                    )
                }
                .onKeyEvent { event ->
                    val dir = when (event.key) {
                        Key.DirectionLeft -> -1
                        Key.DirectionRight -> 1
                        else -> 0
                    }
                    when {
                        dir != 0 && event.type == KeyEventType.KeyDown -> { round.hold(dir); auto = false; true }
                        dir != 0 && event.type == KeyEventType.KeyUp -> { round.hold(0); true }
                        (event.key == Key.Enter || event.key == Key.Spacebar) && event.type == KeyEventType.KeyUp -> { toggleAuto(); true }
                        else -> false
                    }
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(round) {
                    // Wherever a finger presses or drags, the keepsake steers over to it.
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        // The press is the game's alone, so keys keep coming here after a tap or a drag.
                        down.consume()
                        runCatching { focus.requestFocus() }
                        val width = size.width.toFloat()
                        round.steerTo(down.position.x / width)
                        auto = false
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            change.consume()
                            if (!change.pressed) break
                            round.steerTo(change.position.x / width)
                        }
                    }
                },
        ) {
            if (frame < 0) return@Canvas
            val layout = PathLayout(size.width, size.height, round.travel)
            val t = round.time
            drawPathBackdrop(look, layout, round, t)
            drawPathGoal(look, layout, round, t)
            drawGatesBehind(look, layout, round, t)
            drawPathSparkles(look, layout, round, t)
            drawPathObstacles(look, layout, round, t)
            drawPathKeepsake(look, layout, round, grade, t, sceneClock.value)
            drawGatesFront(look, layout, round)
            drawPathPops(look, layout, pops, t)
            drawPathProgress(look, layout, round)
        }
        Spacer(Modifier.height(12.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status,
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text(
                "$collected/${round.sparkles.size}",
                color = palette.accent,
                fontSize = 16.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
            )
        }
    }
}
