package io.colorsand.ui.minigame

import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.hypot
import kotlin.math.min
import kotlin.math.sin
import kotlin.random.Random

/** The little treasures a bubble can carry. */
enum class BubbleTreasure(val title: String) { PEARL("pearl"), SHELL("shell"), STARFISH("starfish") }

/**
 * One rising bubble, born at [born] seconds on the sea floor above [x0], [r] wide (field widths, at full size). It
 * rises [speed] field widths a second and sways [wobble] to each side [wobbleRate] times a second from [phase]
 * (0 to 1). Some carry a [treasure].
 */
data class Bubble(
    val id: Int,
    val x0: Float,
    val r: Float,
    val speed: Float,
    val wobble: Float,
    val wobbleRate: Float,
    val phase: Float,
    val born: Float,
    val treasure: BubbleTreasure?,
)

/** A bubble popped at ([x], [y]) at [at] seconds, as it was then. */
data class PoppedBubble(val bubble: Bubble, val x: Float, val y: Float, val at: Float)

/**
 * A round of Bubble pop, in a field 1 wide and [height] high, y measured up from the sea floor. Bubbles of
 * different sizes are born on the floor, swell to full size over [GROW_S] seconds, and rise slowly with a gentle
 * sway; some carry a treasure. A tap pops the bubble under it ([popAt]); [popLowest] pops the one nearest the
 * floor, for keyboards and screen readers. Bubbles that float off the top are simply gone, with no penalty. The round
 * is done after [goal] pops or [treasureGoal] treasures, whichever comes first, and bubbles keep coming until then.
 * The round starts [warm] seconds in, with bubbles already on their way up. The same [seed] makes the same round
 * every time; [step] moves it on.
 */
class BubblePop(seed: Int, val goal: Int = GOAL, val treasureGoal: Int = TREASURE_GOAL, warm: Float = WARM_S) {
    private val random = Random(seed)

    /** Seconds since the round began. */
    var time: Float = 0f
        private set

    /** How high the water is above the floor, in field widths; the game sets it from its size. */
    var height: Float = 1.4f
        set(value) { field = value.coerceAtLeast(MIN_HEIGHT) }

    private val live = mutableListOf<Bubble>()

    /** The bubbles in the water, oldest first. */
    val bubbles: List<Bubble> get() = live

    /** Every pop so far, in order. */
    val pops = mutableListOf<PoppedBubble>()

    /** The treasures collected, in order. */
    val treasures: List<BubbleTreasure> get() = pops.mapNotNull { it.bubble.treasure }

    val popped: Int get() = pops.size

    val isDone: Boolean get() = popped >= goal || treasures.size >= treasureGoal

    private var nextId = 0
    private var nextSpawn = 0.2f
    private var sinceTreasure = 0
    private var lastTreasure: BubbleTreasure? = null
    private var lastX = 0.5f

    init {
        while (time < warm) step(0.1f)
    }

    /** How far [b] has swelled, 0 to 1. */
    fun grown(b: Bubble): Float = ((time - b.born) / GROW_S).coerceIn(0f, 1f)

    /** [b]'s radius now. */
    fun radius(b: Bubble): Float = b.r * (0.3f + 0.7f * grown(b))

    /** [b]'s middle across now. */
    fun x(b: Bubble): Float = b.x0 + b.wobble * grown(b) * sin(2 * PI.toFloat() * (b.phase + (time - b.born) * b.wobbleRate))

    /** [b]'s middle above the floor now: resting on the floor as it swells, then rising. */
    fun y(b: Bubble): Float = radius(b) + b.speed * (time - b.born - GROW_S * 0.5f).coerceAtLeast(0f)

    /** Moves the round on by [dt] seconds: bubbles rise, the ones off the top are gone, new ones are born. */
    fun step(dt: Float) {
        time += dt
        live.removeAll { y(it) - radius(it) > height }
        if (!isDone && (time >= nextSpawn || live.isEmpty()) && live.size < MAX_BUBBLES) {
            spawn()
            // Quicker while the water is nearly empty, so there is always something to pop.
            val pace = if (live.size < FEW) 0.35f else 1f
            nextSpawn = time + pace * SPAWN_EVERY * (0.75f + 0.5f * random.nextFloat())
        }
    }

    private fun spawn() {
        val treasure = if (sinceTreasure >= TREASURE_EVERY - 1 || random.nextFloat() < TREASURE_CHANCE) {
            sinceTreasure = 0
            BubbleTreasure.entries.filter { it != lastTreasure }.random(random).also { lastTreasure = it }
        } else {
            sinceTreasure++
            null
        }
        val r = if (treasure != null) 0.08f + 0.02f * random.nextFloat() else 0.045f + 0.05f * random.nextFloat()
        // Clear of the sides even at the far end of a sway, and not right where the last one came up.
        val edge = r + 0.045f
        var x = 0.5f
        for (tries in 0 until 6) {
            x = edge + (1f - 2 * edge) * random.nextFloat()
            if (abs(x - lastX) > 0.18f) break
        }
        lastX = x
        live += Bubble(
            id = nextId++,
            x0 = x,
            r = r,
            // Small bubbles hurry, big ones take their time.
            speed = 0.15f - 0.4f * (r - 0.045f) + 0.02f * random.nextFloat(),
            wobble = 0.012f + 0.02f * random.nextFloat(),
            wobbleRate = 0.35f + 0.3f * random.nextFloat(),
            phase = random.nextFloat(),
            born = time,
            treasure = treasure,
        )
    }

    /**
     * The bubble under ([x], [y]), with [slack] to spare around its edge so small bubbles are easy to hit: the one
     * whose middle is closest, or null.
     */
    fun bubbleAt(x: Float, y: Float, slack: Float = SLACK): Bubble? =
        live.map { it to hypot(x(it) - x, y(it) - y) }
            .filter { (b, d) -> d <= radius(b) + slack }
            .minByOrNull { (b, d) -> d / radius(b) }?.first

    /** The bubble nearest the floor, or null. */
    fun lowest(): Bubble? = live.minByOrNull { y(it) }

    /** Pops [b] if it is still in the water and the round isn't done; returns the pop, or null. */
    fun pop(b: Bubble): PoppedBubble? {
        if (isDone || !live.remove(b)) return null
        return PoppedBubble(b, x(b), y(b), time).also { pops += it }
    }

    /** Pops the bubble under ([x], [y]), if any. */
    fun popAt(x: Float, y: Float): PoppedBubble? = bubbleAt(x, y)?.let(::pop)

    /** Pops the bubble nearest the floor, if any. */
    fun popLowest(): PoppedBubble? = lowest()?.let(::pop)

    /** How far the round is, 0 to 1: by pops or treasures, whichever is further along. */
    val progress: Float get() = min(1f, maxOf(popped / goal.toFloat(), treasures.size / treasureGoal.toFloat()))

    companion object {
        /** Pops that finish a round. */
        const val GOAL = 25

        /** Treasures that finish a round. */
        const val TREASURE_GOAL = 5

        /** The most bubbles in the water at once. */
        const val MAX_BUBBLES = 9

        /** Fewer bubbles than this in the water and new ones come quicker. */
        const val FEW = 4

        /** Seconds between new bubbles, give or take a quarter. */
        const val SPAWN_EVERY = 1f

        /** Seconds a new bubble takes to swell to full size. */
        const val GROW_S = 0.6f

        /** The chance a bubble carries a treasure... */
        const val TREASURE_CHANCE = 0.15f

        /** ...and at least one in this many does. */
        const val TREASURE_EVERY = 6

        /** How far outside a bubble a tap still pops it, in field widths. */
        const val SLACK = 0.035f

        /** How many seconds in a round starts, so the water is full of bubbles from the first look. */
        const val WARM_S = 6f

        /** The lowest the water can be, so bubbles always have room to rise. */
        const val MIN_HEIGHT = 0.6f
    }
}
