        SeekProp("the bench", Rect(2f, 60f, 38f, 90f), Offset(20f, 89f), Rustle.WOBBLE),
        SeekProp("the sandbox", Rect(28f, 84f, 80f, 108f), Offset(54f, 106f), Rustle.WOBBLE),
