    // Grass tufts and flowers scattered over the lawn, the same every time, in stage units well past its sides.
    private val tufts = SceneRandom(11).let { r -> List(46) { Offset(r.next(-80f, 180f), r.next(horizonY + 6f, 140f)) } }
    private val flowers = SceneRandom(19).let { r -> List(22) { Offset(r.next(-80f, 180f), r.next(horizonY + 8f, 130f)) } }
    private val farTrees = SceneRandom(23).let { r -> List(14) { Offset(r.next(-80f, 180f), r.next(2.2f, 3.6f)) } }
    private val farRidge = Ridge(260f, horizonY - 1f, 6f, 2.6f, 0.15f)
    private val nearRidge = Ridge(260f, horizonY + 1f, 3.5f, 3.4f, 0.6f)

    override fun DrawScope.drawScenery(view: Rect, t: Float) {
        // Sky down to the hills.
        drawRect(
            Brush.verticalGradient(
                0f to skyTop, 0.45f to skyMid, 0.8f to skyLow, 1f to skyHorizon,
                startY = minOf(view.top, -10f), endY = horizonY,
            ),
            Offset(view.left, view.top), androidx.compose.ui.geometry.Size(view.width, horizonY + 2f - view.top),
        )
        val sun = Offset(view.right - 13f, view.top + 13f)
        drawGlow(sun, 26f, sunGlow.copy(alpha = 0.55f))
        dot(sunCore, sun.x, sun.y, 7f)
        for ((i, cloud) in clouds.withIndex()) {
            val span = view.width + 50f
            val x = view.left - 25f + span * drift(t, 1 + i % 2, i * 0.37f)
            val y = view.top * 0.6f + 6f + i * 9f
            translate(x, y + 1.2f) { drawPath(cloud, cloudShade.copy(alpha = 0.7f)) }
            translate(x, y) { drawPath(cloud, cloudWhite.copy(alpha = 0.9f)) }
        }
        // A few birds gliding across, flapping now and then.
        for (k in 0 until 3) {
            val x = view.left - 10f + (view.width + 20f) * drift(t, 2, k * 0.08f)
            val y = view.top * 0.45f + 10f + k * 2.6f + swing(t, 20, k * 0.2f) * 1.2f
            val flap = 0.4f + 0.6f * kotlin.math.abs(swing(t, 300, k * 0.3f))
            val bird = Path().apply {
                moveTo(x - 2.6f - k * 1.5f, y - 1.6f * flap)
                quadraticTo(x - 1.2f - k * 1.5f, y - 1.2f, x - k * 1.5f, y)
                quadraticTo(x + 1.2f - k * 1.5f, y - 1.2f, x + 2.6f - k * 1.5f, y - 1.6f * flap)
            }
            drawPath(bird, birdColor, style = Stroke(0.55f, cap = StrokeCap.Round))
        }
        // Hills and far trees on the horizon, the ridges laid from well past the left edge.
        translate(-80f, 0f) {
            drawPath(farRidge.fill(horizonY + 6f), farHillColor)
            for (tree in farTrees) {
                val x = tree.x + 80f
                dot(farTree, x, farRidge.y(x) + 1f, tree.y)
            }
            drawPath(nearRidge.fill(horizonY + 8f), nearHillColor)
        }
        // A picket fence along the back of the lawn.
        val fenceTop = horizonY - 6f
        box(fenceShade, view.left, fenceTop + 2.5f, view.right, fenceTop + 4.2f)
        box(fenceShade, view.left, fenceTop + 6.5f, view.right, fenceTop + 8.2f)
        var x = view.left - (view.left % 5f) - 5f
        while (x < view.right + 5f) {
            fencePicket(x, fenceTop)
            x += 5f
        }
        // The lawn, paler far off.
        drawRect(
            Brush.verticalGradient(0f to grassFar, 1f to grassNear, startY = horizonY + 2f, endY = 125f),
            Offset(view.left, horizonY + 3f), androidx.compose.ui.geometry.Size(view.width, view.bottom - horizonY - 3f),
        )
        oval(Color.White.copy(alpha = 0.12f), 50f, horizonY + 8f, 90f, 4f)
        for ((i, p) in tufts.withIndex()) {
            if (p.x < view.left - 4f || p.x > view.right + 4f || p.y > view.bottom + 4f) continue
            val s = 0.6f + (p.y - horizonY) / 90f
            tuft(p, s, swing(t, 10, i * 0.13f), if (i % 3 == 0) tuftLight else tuftColor)
        }
        for ((i, p) in flowers.withIndex()) {
            if (p.x < view.left - 4f || p.x > view.right + 4f || p.y > view.bottom + 4f) continue
            val s = 0.6f + (p.y - horizonY) / 110f
            val color = flowerColors[i % flowerColors.size]
            for (k in 0 until 5) {
                val a = k * 72f * DEG + i
                dot(color, p.x + kotlin.math.cos(a) * 1.1f * s, p.y + kotlin.math.sin(a) * 1.1f * s, 0.85f * s)
            }
            dot(flowerHeart, p.x, p.y, 0.6f * s)
        }
    }

    private fun DrawScope.fencePicket(x: Float, top: Float) {
        val picket = polygon(x - 1.3f, top + 1.2f, x, top, x + 1.3f, top + 1.2f, x + 1.3f, top + 10f, x - 1.3f, top + 10f)
        translate(0.5f, 0.4f) { drawPath(picket, fenceShade) }
        drawPath(picket, fenceColor)
    }

    /** A little tuft of grass blades at [p], [s] times the usual size, bent by [bend]. */
    private fun DrawScope.tuft(p: Offset, s: Float, bend: Float, color: Color) {
        val path = Path()
        for (b in -1..1) {
            val bx = p.x + b * 0.8f * s
            val h = (2.2f + 0.8f * (1 - kotlin.math.abs(b))) * s
            val lean = (b * 0.7f + bend * 0.4f) * s
            path.moveTo(bx - 0.45f * s, p.y)
            path.quadraticTo(bx + lean * 0.3f, p.y - h * 0.6f, bx + lean, p.y - h)
            path.quadraticTo(bx + lean * 0.3f + 0.4f * s, p.y - h * 0.5f, bx + 0.45f * s, p.y)
            path.close()
        }
        drawPath(path, color)
    }

    override fun DrawScope.drawBack(prop: Int, t: Float) {
        when (prop) {
            0 -> treeBack()
            1 -> slideBack()
            4 -> benchBack()
            5 -> sandboxBack()
            6 -> toyBoxBack()
            7 -> grassBlades(t, front = false)
