            2 -> bush(36f, 67f, 30f, 19f, t)
            3 -> bush(90f, 81f, 23f, 15f, t + 0.3f)
            4 -> benchFront(t)
            5 -> sandboxFront()
            6 -> toyBoxFront()
            7 -> grassBlades(t, front = true)
        }
    }

