        val path = Path().apply {
            moveTo(70f, 26f)
            cubicTo(80f, 30f, 82f, 52f, 97f, 58f)
        }
        stick(rail, 86f, 47f, 86f, 62f, 2f)
        drawPath(path, chuteDark, style = Stroke(8f, cap = StrokeCap.Round))
        drawPath(path, chute, style = Stroke(6.2f, cap = StrokeCap.Round))
        translate(-0.9f, -1.2f) { drawPath(path, chuteLight, style = Stroke(1.4f, cap = StrokeCap.Round)) }
        // The deck and its handrail.
