        stick(rail, 70.5f, 24f, 70.5f, 16f, 1.6f)
        stick(railLight, 56f, 16f, 70.5f, 16f, 1.6f)
        // The ladder over whatever hides behind it.
        stick(rail, 56f, 26f, 56f, 62.5f, 2.4f)
        stick(rail, 68f, 26f, 68f, 62.5f, 2.4f)
        for (k in 0 until 6) {
            val y = 31f + k * 5.8f
            stick(chuteDark, 56f, y + 0.4f, 68f, y + 0.4f, 1.7f)
