        stick(railLight, 55.5f, 28f, 55.5f, 60f, 0.7f)
        stick(railLight, 67.5f, 28f, 67.5f, 60f, 0.7f)
    }

    /** A round bush [w] wide and [h] tall standing at ([cx], [base]), with a few berries. */
    private fun DrawScope.bush(cx: Float, base: Float, w: Float, h: Float, t: Float) {
        oval(Color.Black.copy(alpha = 0.16f), cx, base, w * 0.52f, 2f)
        val r = h * 0.42f
        oval(leafDark, cx, base - r * 0.9f, w * 0.5f, r * 0.95f)
        dot(leafDark, cx - w * 0.28f, base - r * 1.2f, r * 0.95f)
        dot(leafDark, cx + w * 0.27f, base - r * 1.15f, r * 0.9f)
        dot(leafDark, cx, base - h + r, r * 1.1f)
        dot(leaf, cx - w * 0.29f, base - r * 1.35f, r * 0.8f)
        dot(leaf, cx + w * 0.25f, base - r * 1.3f, r * 0.78f)
        dot(leaf, cx - w * 0.02f, base - h + r * 0.9f, r * 0.95f)
        oval(leaf, cx, base - r * 0.8f, w * 0.42f, r * 0.6f)
        dot(leafLight, cx - w * 0.08f, base - h + r * 0.55f, r * 0.42f)
        dot(leafLight, cx - w * 0.33f, base - r * 1.6f, r * 0.32f)
        dot(leafLight, cx + w * 0.2f, base - r * 1.55f, r * 0.3f)
        for (k in 0 until 4) {
            val bx = cx + w * (-0.3f + k * 0.2f)
            val by = base - r * (0.7f + (k % 2) * 0.9f)
            dot(g(0xFFD93D55), bx, by, 0.95f)
            dot(Color.White.copy(alpha = 0.6f), bx - 0.3f, by - 0.3f, 0.3f)
        }
    }

