    /** The tall grass at the front: tall bending blades, the back row darker. */
    private fun DrawScope.grassBlades(t: Float, front: Boolean) {
        val path = Path()
        val count = if (front) 7 else 6
        for (b in 0 until count) {
            val x = if (front) 2.5f + b * 3.6f else 4f + b * 3.5f
            val h = if (front) 8f + (b * 5 % 4) * 1.6f else 13f + (b * 3 % 4) * 1.3f
            val lean = (b - count / 2f) * 0.8f + swing(t, 10, b * 0.1f + if (front) 0.2f else 0f) * 1.2f
            path.moveTo(x - 0.9f, 117f)
            path.quadraticTo(x + lean * 0.3f, 117f - h * 0.6f, x + lean, 117f - h)
            path.quadraticTo(x + lean * 0.3f + 0.7f, 117f - h * 0.5f, x + 0.9f, 117f)
            path.close()
        }
        drawPath(path, if (front) tuftLight else tuftColor)
        if (front) {
            for ((i, x) in floatArrayOf(5f, 19f).withIndex()) {
                val y = 105f + i * 2f
                stick(tuftColor, x, 117f, x + 0.6f, y, 0.6f)
                for (k in 0 until 5) {
                    val a = k * 72f * DEG
                    dot(flowerColors[(i + 1) % 3], x + 0.6f + kotlin.math.cos(a) * 1.3f, y + kotlin.math.sin(a) * 1.3f, 1f)
                }
                dot(flowerHeart, x + 0.6f, y, 0.7f)
            }
        }
    }
}

/** Radians in a degree. */
internal const val DEG = (kotlin.math.PI / 180).toFloat()
