package io.colorsand.ui.minigame

import kotlin.math.abs
import kotlin.random.Random

/** A swap of the gems at cells [a] and [b]. */
data class GemMove(val a: Int, val b: Int)

/** After a fall, the gem now at [cell] came down from row [fromRow] of its column; a negative row is above the board. */
data class GemFall(val cell: Int, val fromRow: Int)

/**
 * One wave of a turn: the [matched] cells burst, the gems above fell into the gaps and new ones dropped in from the
 * top ([falls]), leaving [board].
 */
data class GemCascade(val matched: Set<Int>, val board: GemBoard, val falls: List<GemFall>)

/**
 * A square board of [size] x [size] gems of [kinds] kinds (0 until [kinds]), cell by cell in reading order; [EMPTY]
 * marks a gap. Lines of three or more of a kind across or down are matches. Immutable: every change returns a new
 * board.
 */
data class GemBoard(val size: Int, val kinds: Int, val gems: List<Int>) {
    init {
        require(gems.size == size * size) { "A $size x $size board needs ${size * size} gems, not ${gems.size}" }
    }

    val cells: Int get() = gems.size

    fun row(cell: Int): Int = cell / size

    fun column(cell: Int): Int = cell % size

    fun cell(row: Int, column: Int): Int = row * size + column

    operator fun get(cell: Int): Int = gems[cell]

    /** Whether [a] and [b] are side by side or one above the other. */
    fun adjacent(a: Int, b: Int): Boolean {
        if (a !in 0 until cells || b !in 0 until cells) return false
        return (row(a) == row(b) && abs(column(a) - column(b)) == 1) || (column(a) == column(b) && abs(row(a) - row(b)) == 1)
    }

    /** The neighbor of [cell] one step [dRow], [dColumn] away, or null off the edge. */
    fun neighbor(cell: Int, dRow: Int, dColumn: Int): Int? {
        val r = row(cell) + dRow
        val c = column(cell) + dColumn
        return if (r in 0 until size && c in 0 until size) cell(r, c) else null
    }

    /** This board with the gems at [a] and [b] swapped. */
    fun swapped(a: Int, b: Int): GemBoard = copy(gems = gems.toMutableList().also { it[a] = gems[b]; it[b] = gems[a] })

    /** Every cell in a line of three or more of the same kind, across or down. */
    fun matches(): Set<Int> {
        val found = mutableSetOf<Int>()
        fun scan(line: List<Int>) {
            var start = 0
            while (start < line.size) {
                var end = start + 1
                while (end < line.size && gems[line[end]] == gems[line[start]]) end++
                if (gems[line[start]] != EMPTY && end - start >= 3) for (i in start until end) found += line[i]
                start = end
            }
        }
        for (r in 0 until size) scan(List(size) { cell(r, it) })
        for (c in 0 until size) scan(List(size) { cell(it, c) })
        return found
    }

    /** Whether swapping [a] and [b] makes a match. */
    fun isMatchingSwap(a: Int, b: Int): Boolean = adjacent(a, b) && swapped(a, b).matches().isNotEmpty()

    /** Every swap that makes a match, in reading order. */
    fun moves(): List<GemMove> = buildList {
        for (a in 0 until cells) {
            for (b in listOfNotNull(neighbor(a, 0, 1), neighbor(a, 1, 0))) if (isMatchingSwap(a, b)) add(GemMove(a, b))
        }
    }

    fun hasMove(): Boolean = moves().isNotEmpty()

    /** This board with [cells] emptied. */
    fun cleared(cells: Set<Int>): GemBoard = copy(gems = gems.mapIndexed { i, k -> if (i in cells) EMPTY else k })

    /**
     * The gems settle: in each column they fall down into the gaps below them, and new gems of kinds from [random]
     * drop in from above to fill the column. Returns the full board and how every gem that moved got there.
     */
    fun collapse(random: Random): Pair<GemBoard, List<GemFall>> {
        val next = gems.toMutableList()
        val falls = mutableListOf<GemFall>()
        for (c in 0 until size) {
            var to = size - 1
            for (r in size - 1 downTo 0) {
                val k = gems[cell(r, c)]
                if (k == EMPTY) continue
                next[cell(to, c)] = k
                if (to != r) falls += GemFall(cell(to, c), r)
                to--
            }
            val fresh = to + 1
            for (r in to downTo 0) {
                next[cell(r, c)] = random.nextInt(kinds)
                falls += GemFall(cell(r, c), r - fresh)
            }
        }
        return copy(gems = next) to falls
    }

    /** The same gems rearranged by [random] so there is no match and at least one move, or a [fresh] board. */
    fun shuffled(random: Random): GemBoard {
        repeat(200) {
            val b = copy(gems = gems.shuffled(random))
            if (b.matches().isEmpty() && b.hasMove()) return b
        }
        return fresh(size, kinds, random)
    }

    companion object {
        /** A gap where a gem burst. */
        const val EMPTY = -1

        /** A full board with no match on it and at least one move, from [random]. */
        fun fresh(size: Int, kinds: Int, random: Random): GemBoard {
            require(kinds >= 3) { "Needs at least three kinds of gem" }
            while (true) {
                val gems = MutableList(size * size) { EMPTY }
                for (i in gems.indices) {
                    val r = i / size
                    val c = i % size
                    val banned = mutableSetOf<Int>()
                    if (c >= 2 && gems[i - 1] == gems[i - 2]) banned += gems[i - 1]
                    if (r >= 2 && gems[i - size] == gems[i - 2 * size]) banned += gems[i - size]
                    val allowed = (0 until kinds).filter { it !in banned }
                    gems[i] = allowed[random.nextInt(allowed.size)]
                }
                val board = GemBoard(size, kinds, gems)
                if (board.hasMove()) return board
            }
        }
    }
}

/**
 * The outcome of one swap: the [move], each wave of bursting and falling gems in order ([cascades]), the board it was
 * [reshuffled] to when no move was left (or null), and the round [after] it.
 */
data class GemTurn(val move: GemMove, val cascades: List<GemCascade>, val reshuffled: GemBoard?, val after: GemMatch) {
    /** How many gems burst in this turn. */
    val cleared: Int get() = cascades.sumOf { it.matched.size }
}

/**
 * A round of Sand gem match: swap two neighboring gems to line up three or more of a kind; they burst, the gems
 * above fall, new ones drop in and may match again in cascades. No move limit and nothing to lose: the round is done
 * once [cleared] reaches [goal]. When no move is left the board is gently reshuffled. [seed] and [draws] (how many
 * times new gems have been drawn so far) make every refill the same each time.
 */
data class GemMatch(val board: GemBoard, val cleared: Int = 0, val goal: Int = GOAL, val seed: Int = 0, val draws: Int = 0) {
    val isDone: Boolean get() = cleared >= goal

    /** How full the meter is, 0 to 1. */
    val progress: Float get() = (cleared.toFloat() / goal).coerceIn(0f, 1f)

    /** A swap that makes a match, for a helper or a screen reader; null once done. */
    fun anyMove(): GemMove? = if (isDone) null else board.moves().let { m -> m.getOrNull(m.size / 2) }

    /** The turn swapping [a] and [b], or null if they aren't neighbors, it makes no match, or the round is done. */
    fun swap(a: Int, b: Int): GemTurn? {
        if (isDone || !board.isMatchingSwap(a, b)) return null
        var current = board.swapped(a, b)
        var draw = draws
        var total = cleared
        val cascades = mutableListOf<GemCascade>()
        while (true) {
            val matched = current.matches()
            if (matched.isEmpty()) break
            val (next, falls) = current.cleared(matched).collapse(random(draw++))
            cascades += GemCascade(matched, next, falls)
            total += matched.size
            current = next
            // A safety net: a board can't keep matching forever, but never loop more than this.
            if (cascades.size >= MAX_CASCADES) break
        }
        val reshuffled = if (current.matches().isEmpty() && current.hasMove()) null else current.shuffled(random(draw++))
        val after = copy(board = reshuffled ?: current, cleared = total, draws = draw)
        return GemTurn(GemMove(a, b), cascades, reshuffled, after)
    }

    private fun random(draw: Int) = Random(seed * 7919 + draw * 104_729 + 17)

    companion object {
        /** Gems to burst to fill the meter. */
        const val GOAL = 40

        const val SIZE = 7

        const val KINDS = 5

        private const val MAX_CASCADES = 30

        /** A new round, the same for the same [seed]. */
        fun start(seed: Int, goal: Int = GOAL): GemMatch =
            GemMatch(GemBoard.fresh(SIZE, KINDS, Random(seed * 31 + 5)), goal = goal, seed = seed)
    }
}
