/**
 * Color mixer: a target color on a card, and pots of red, yellow, blue and white by a mixing vessel (the octopus's
 * shell bowl on the Sea Floor, the cement mixer's turning drum on the Building Site). Each tap on a pot tosses a
 * scoop in and the mix changes color; a meter shows how close it is. A close enough mix celebrates and brings the
 * next color; the third calls [onFinished]. Scoops are unlimited, the bowl can be emptied any time, and after a few
 * scoops a hint lights the pot to try next (see [ColorMixer]). [seed] picks the three colors.
 */
@Composable
fun ColorMixerGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { MixerLook.of(arena, grade) }
    var round by remember(seed) { mutableStateOf(ColorMixer.start(arena, seed)) }
    // From a match until the next color is up: the pots rest and the vessel shows off.
    var celebrating by remember(seed) { mutableStateOf(false) }
    var finished by remember(seed) { mutableStateOf(false) }
    // The player emptied the bowl (rather than a match pouring it off).
    var emptied by remember(seed) { mutableStateOf(false) }
    val drops = remember(seed) { mutableStateListOf<MixerDrop>() }
    val burst = remember(seed) { Animatable(0f) }
    val stir = remember(seed) { Animatable(0f) }
    val turns = remember(seed) { Animatable(0f) }
    val tip = remember(seed) { Animatable(0f) }
    val clock = rememberInfiniteTransition(label = "mixer").animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(MIXER_LOOP_MS, easing = LinearEasing)),
        label = "clock",
    )
    val scope = rememberCoroutineScope()
    val inkColors = remember(grade) { Ink.entries.map { grade(it.color.argb) } }

    // The mix as it shows: the color eases over once a scoop lands, the level rises with the scoops.
    val bowlColor = round.bowl.color?.let { grade(it.argb) }
    var shownColor by remember(seed) { mutableStateOf(Color.White) }
    if (bowlColor != null) shownColor = bowlColor
    val mixColor by animateColorAsState(shownColor, tween(MIX_MS, delayMillis = (DROP_MS * DROP_LANDS).toInt()), label = "mix")
    val level = if (round.bowl.isEmpty) 0f else (0.45f + 0.09f * round.bowl.total).coerceAtMost(1f)
    val fill by animateFloatAsState(level, spring(dampingRatio = 0.7f, stiffness = Spring.StiffnessLow), label = "fill")
    val closeness by animateFloatAsState(round.closeness, tween(MIX_MS, delayMillis = (DROP_MS * DROP_LANDS).toInt()), label = "near")

    fun add(ink: Ink) {
        if (celebrating || finished || round.isDone) return
        val next = round.add(ink)
        round = next
        emptied = false
        feedback.play(Sounds.pick)
        feedback.tick()
        val fall = Animatable(0f)
        val drop = MixerDrop(inkColors[ink.ordinal], ink.ordinal) { fall.value }
        drops += drop
        scope.launch {
            fall.animateTo(1f, tween(DROP_MS, easing = LinearEasing))
            drops -= drop
        }
        scope.launch {
            delay((DROP_MS * DROP_LANDS).toLong())
            feedback.play(Sounds.land)
            launch { turns.animateTo(turns.value + 1f, tween(900, easing = FastOutSlowInEasing)) }
            stir.snapTo(1f)
            stir.animateTo(0f, tween(1400))
        }
        if (next.isMatch) {
            celebrating = true
            val last = next.done == next.targets.lastIndex
            scope.launch {
                delay((DROP_MS * DROP_LANDS).toLong() + MIX_MS / 2)
                feedback.play(Sounds.chime(next.done * 2 + 2))
                feedback.confirm()
                burst.snapTo(0f)
                burst.animateTo(1f, tween(1300, easing = LinearEasing))
                if (last) {
                    delay(FINISH_DELAY_MS / 2)
                    finished = true
                    onFinished()
                } else {
                    delay(NEXT_DELAY_MS)
                    // Poured off; on to the next color.
                    feedback.play(Sounds.pour)
                    launch { tip.animateTo(1f, tween(260)); tip.animateTo(0f, spring(dampingRatio = 0.5f)) }
                    round = round.next()
                    celebrating = false
                }
            }
        }
    }
    fun empty() {
        if (celebrating || finished || round.bowl.isEmpty) return
        round = round.empty()
        emptied = true
        feedback.play(Sounds.pour)
        feedback.tick()
        scope.launch {
            tip.animateTo(1f, tween(260))
            tip.animateTo(0f, spring(dampingRatio = 0.5f, stiffness = Spring.StiffnessLow))
        }
    }

    val target = round.target
    val helping = !celebrating && !round.isMatch && round.scoops >= ColorMixer.HINT_AFTER
    val hint = if (helping) round.hint() else null
    val suggestEmpty = helping && hint == null
    val mixed = round.done + if (celebrating) 1 else 0
    val pulse = 0.5f + 0.5f * sin(clock.value * 2f * PI.toFloat() * 80f)

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        if (target != null) TargetCard(look, grade, round, target, mixed)
        Spacer(Modifier.height(8.dp))
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .semantics {
                    contentDescription = "The ${if (look.vessel == MixerVessel.SHELL) "octopus's shell bowl" else "cement mixer's drum"}: " +
                        round.bowl.describe()
                },
        ) {
            drawMixer(look, grade, mixColor, fill, stir.value, turns.value, tip.value, burst.value, drops, clock.value)
        }
        Spacer(Modifier.height(6.dp))
        ClosenessMeter(look, if (round.bowl.isEmpty) 0f else closeness, target?.let { grade(it.color.argb) } ?: mixColor, celebrating)
        Spacer(Modifier.height(10.dp))
        Text(
            statusText(look, round, celebrating, emptied, hint, suggestEmpty),
            color = palette.text,
            fontSize = 15.sp,
            lineHeight = 19.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 2,
            modifier = Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(22.dp), elevation = 4.dp)
                .padding(horizontal = 16.dp, vertical = 7.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        )
        Spacer(Modifier.height(12.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.Bottom) {
            Ink.entries.forEach { ink ->
                PotButton(look, ink, inkColors[ink.ordinal], glow = if (hint == ink) pulse else null, enabled = !celebrating) { add(ink) }
            }
        }
        Spacer(Modifier.height(10.dp))
        val emptyStyle = ButtonStyle.accent(palette)
        GameButton(
            onClick = ::empty,
            style = emptyStyle,
            enabled = !round.bowl.isEmpty && !celebrating,
            lip = 4.dp,
            label = "Empty the ${if (look.vessel == MixerVessel.SHELL) "bowl" else "drum"}",
            modifier = Modifier
                .size(width = 150.dp, height = 46.dp)
                .drawBehind {
                    if (suggestEmpty) drawGlow(center, size.width * 0.75f, palette.highlight.copy(alpha = 0.35f + 0.4f * pulse))
                },
        ) {
            Text(
                "Empty",
                color = emptyStyle.content,
                fontSize = 17.sp,
                fontWeight = FontWeight.ExtraBold,
                modifier = Modifier.clearAndSetSemantics { },
            )
        }
    }
}

/** The color to mix, its name, and three slots for the round's colors, ticked as they are mixed. */
@Composable
private fun TargetCard(look: MixerLook, grade: SceneGrade, round: ColorMixer, target: MixTarget, mixed: Int) {
    val palette = LocalPalette.current
    Row(
        Modifier
            .widthIn(max = 460.dp)
            .fillMaxWidth()
            .frosted(palette, RoundedCornerShape(22.dp), elevation = 5.dp)
            .padding(horizontal = 12.dp, vertical = 8.dp)
            .semantics(mergeDescendants = true) { contentDescription = "Mix ${target.name}. $mixed of ${round.targets.size} mixed." },
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Canvas(Modifier.size(58.dp)) {
            val unit = size.minDimension / 100f
            scale(unit, unit, Offset.Zero) { drawSwatch(look, grade(target.color.argb)) }
        }
        Spacer(Modifier.width(12.dp))
        Column(Modifier.weight(1f)) {
            Text("Mix this color", color = palette.dimText, fontSize = 13.sp, fontWeight = FontWeight.Bold, maxLines = 1)
            Text(target.name, color = palette.text, fontSize = 21.sp, fontWeight = FontWeight.Black, maxLines = 1)
        }
        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
            round.targets.forEachIndexed { i, t ->
                val c = grade(t.color.argb)
                Canvas(Modifier.size(24.dp)) {
                    val r = size.minDimension / 2
                    when {
                        i < mixed -> {
                            drawCircle(lerp(c, Color.Black, 0.2f), r)
                            drawCircle(c, r * 0.86f, center - Offset(0f, r * 0.06f))
                            val unit = size.minDimension / 100f
                            scale(unit, unit, Offset.Zero) { drawTick(Color.White) }
                        }
                        i == mixed -> {
                            drawCircle(c, r * 0.9f, style = Stroke(r * 0.22f))
                            drawCircle(c.copy(alpha = 0.35f), r * 0.55f)
                        }
                        else -> drawCircle(palette.dimText.copy(alpha = 0.25f), r * 0.7f)
                    }
                }
            }
        }
    }
}

/**
 * How near the mix is: a rounded bar filling toward the target color, with a twinkle at the end where it counts as a
 * match. On the Sea Floor it fills with bubbles, on the Building Site it has hazard stripes.
 */
@Composable
private fun ClosenessMeter(look: MixerLook, closeness: Float, color: Color, matched: Boolean) {
    val palette = LocalPalette.current
    val percent = (closeness * 100).roundToInt()
    Row(
        Modifier
            .widthIn(max = 460.dp)
            .fillMaxWidth()
            .frosted(palette, RoundedCornerShape(50), elevation = 3.dp)
            .padding(horizontal = 14.dp, vertical = 6.dp)
            .semantics(mergeDescendants = true) { contentDescription = "Closeness $percent percent" },
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text("Close", color = palette.dimText, fontSize = 13.sp, fontWeight = FontWeight.Bold, modifier = Modifier.clearAndSetSemantics { })
        Spacer(Modifier.width(10.dp))
        Canvas(Modifier.weight(1f).height(18.dp)) {
            val h = size.height
            val r = CornerRadius(h / 2)
            drawRoundRect(Color.Black.copy(alpha = 0.16f), size = size, cornerRadius = r)
            val w = (size.width * closeness).coerceAtLeast(if (closeness > 0f) h else 0f)
            if (w > 0f) {
                drawRoundRect(
                    Brush.horizontalGradient(listOf(lerp(color, Color.Gray, 0.6f), color), 0f, size.width),
                    size = Size(w, h),
                    cornerRadius = r,
                )
                when (look.vessel) {
                    MixerVessel.SHELL -> {
                        var x = h * 0.6f
                        while (x < w - h * 0.4f) {
                            drawCircle(Color.White.copy(alpha = 0.45f), h * 0.18f, Offset(x, h * 0.5f), style = Stroke(h * 0.07f))
                            x += h * 0.9f
                        }
                    }
                    MixerVessel.DRUM -> {
                        var x = -h
                        while (x < w) {
                            val band = Path().apply {
                                moveTo(x, h); lineTo(x + h * 0.5f, h); lineTo(x + h, 0f); lineTo(x + h * 0.5f, 0f); close()
                            }
                            clipRect(0f, 0f, w, h) { drawPath(band, Color.Black.copy(alpha = 0.12f)) }
                            x += h
                        }
                    }
                }
                drawRoundRect(Color.White.copy(alpha = 0.35f), Offset(h * 0.3f, h * 0.14f), Size((w - h * 0.6f).coerceAtLeast(0f), h * 0.22f), CornerRadius(h * 0.11f))
            }
            val goal = Offset(size.width - h / 2, h / 2)
            goalStar(goal, h * (if (matched) 0.7f else 0.45f), if (matched) Color(0xFFFFE27A) else Color.White.copy(alpha = 0.9f))
        }
        Spacer(Modifier.width(10.dp))
        Text(
            "$percent%",
            color = palette.text,
            fontSize = 14.sp,
            fontWeight = FontWeight.Black,
            textAlign = TextAlign.End,
            modifier = Modifier.width(40.dp).clearAndSetSemantics { },
        )
    }
}

/** One pot by the vessel, a button that adds a scoop of [ink]; [glow] (0 to 1) lights it when it is the hint. */
@Composable
private fun PotButton(look: MixerLook, ink: Ink, color: Color, glow: Float?, enabled: Boolean, onClick: () -> Unit) {
    val palette = LocalPalette.current
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        GameButton(
            onClick = onClick,
            style = ButtonStyle(lerp(palette.surface, Color.White, if (palette.isLight) 0.4f else 0.12f)),
            shape = RoundedCornerShape(22.dp),
            lip = 5.dp,
            label = "Add a scoop of ${ink.title} ${look.scoop}",
            modifier = Modifier
                .size(width = 70.dp, height = 76.dp)
                .drawBehind { if (glow != null) drawGlow(center, size.width * 0.95f, palette.highlight.copy(alpha = 0.35f + 0.45f * glow)) }
                .drawWithContent {
                    drawContent()
                    // The hint: a ring that breathes around the pot to try next.
                    if (glow != null) {
                        val grow = 3.dp.toPx() * glow
                        drawRoundRect(
                            palette.highlight.copy(alpha = 0.6f + 0.4f * glow),
                            Offset(-grow, -grow),
                            Size(size.width + 2 * grow, size.height + 2 * grow),
                            CornerRadius(22.dp.toPx() + grow),
                            style = Stroke(3.dp.toPx()),
                        )
                    }
                },
        ) {
            Canvas(Modifier.fillMaxSize().padding(3.dp)) {
                val unit = size.minDimension / 100f
                scale(unit, unit, Offset.Zero) { drawPot(look, color, if (glow != null) glow else 0f) }
            }
        }
        Spacer(Modifier.height(3.dp))
        Text(
            ink.title.replaceFirstChar { it.uppercase() },
            color = if (enabled) palette.text else palette.dimText,
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.clearAndSetSemantics { },
        )
    }
}

/**
 * What the line under the meter says: how close the mix is, a tip once it has been a while, or the cheer of a match.
 * It is a polite live region, so screen readers hear the closeness after every scoop.
 */
private fun statusText(look: MixerLook, round: ColorMixer, celebrating: Boolean, emptied: Boolean, hint: Ink?, suggestEmpty: Boolean): String {
    val name = round.target?.name ?: ""
    val percent = (round.closeness * 100).roundToInt()
    if (celebrating) {
        return if (round.done == round.targets.lastIndex) {
            if (look.vessel == MixerVessel.SHELL) "$name! All three inks mixed. The octopus is delighted!"
            else "$name! All three colors mixed. Great building!"
        } else {
            "$name! A perfect match!"
        }
    }
    val words = when (round.nearness) {
        Nearness.EMPTY -> return when {
            emptied -> "Empty. Tap a pot to start mixing $name again."
            round.done > 0 -> "Next up: $name! Tap a pot to start."
            look.vessel == MixerVessel.SHELL -> "Tap the ink pots to mix $name in the shell."
            else -> "Tap the sand buckets to mix $name in the drum."
        }
        Nearness.FAR -> "Far off."
        Nearness.WARMER -> "Getting warmer…"
        Nearness.CLOSE -> "Close!"
        Nearness.VERY_CLOSE -> "So close!"
        Nearness.MATCH -> "Spot on!"
    }
    val tip = when {
        hint != null -> " Try a scoop of ${hint.title}."
        suggestEmpty -> " Empty it and start fresh."
        else -> ""
    }
    return "$percent% · $words$tip"
}

/** One loop of the mixer's clock, in milliseconds: the scenes' two minutes, so the keepsake moves as it does there. */
private const val MIXER_LOOP_MS = 120_000

/** A scoop's flight into the vessel, in milliseconds. */
private const val DROP_MS = 620

/** How long the mix takes to change color once a scoop lands, in milliseconds. */
private const val MIX_MS = 450

/** How long a match shows off before the next color comes up, in milliseconds. */
private const val NEXT_DELAY_MS = 900L
