/**
 * "Play with the dump truck": the level-complete card's way into [keepsake]'s game, with the keepsake bobbing on
 * it. It pops in once the keepsake itself has popped into the scenery.
 */
@Composable
fun PlayKeepsakeButton(level: Int, keepsake: KeepsakeGame, onClick: () -> Unit) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val appear = remember(level) { Animatable(0f) }
    LaunchedEffect(level) {
        delay(APPEAR_DELAY_MS)
        appear.animateTo(1f, spring(dampingRatio = 0.5f, stiffness = Spring.StiffnessMediumLow))
    }
    val bob = rememberInfiniteTransition(label = "bob").animateFloat(
        initialValue = -1f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(900, easing = FastOutSlowInEasing), RepeatMode.Reverse),
        label = "bob",
    )
    val style = ButtonStyle.bright(palette)
    GameButton(
        onClick = onClick,
        style = style,
        lip = 5.dp,
        modifier = Modifier.heightIn(min = 54.dp).graphicsLayer {
            val v = appear.value
            scaleX = 0.5f + 0.5f * v
            scaleY = 0.5f + 0.5f * v
            alpha = v.coerceIn(0f, 1f)
            transformOrigin = TransformOrigin(0.5f, 0f)
        },
    ) {
        Row(Modifier.padding(start = 10.dp, end = 18.dp, top = 6.dp, bottom = 6.dp), verticalAlignment = Alignment.CenterVertically) {
            Canvas(Modifier.size(38.dp).graphicsLayer { rotationZ = 6f * bob.value; translationY = -2.dp.toPx() * bob.value }) {
                val unit = size.minDimension / 100f
                scale(unit, unit, Offset.Zero) { drawKeepsake(keepsake.arena, keepsake.stage, 0f, grade) }
            }
            Spacer(Modifier.width(6.dp))
            Text(
                "Play with the ${keepsake.keepsake.replace(' ', '\u00A0')}",
                color = style.content,
                fontSize = 16.sp,
                lineHeight = 19.sp,
                fontWeight = FontWeight.ExtraBold,
                textAlign = TextAlign.Center,
                maxLines = 2,
            )
        }
    }
}

/** How long after the card comes up the button pops in: just after the keepsake (see Keepsakes.kt). */
private const val APPEAR_DELAY_MS = 2000L
