package io.colorsand.ui.minigame

import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.hypot
import kotlin.math.sign
import kotlin.math.sin
import kotlin.random.Random

/** A ring (or a gap) on the course at [x] across, [d] along it; [passedAt] is when the keepsake went through. */
data class PathGate(val id: Int, val x: Float, val d: Float, val passedAt: Float? = null)

/** A sparkle to collect (a star, a bubble, stardust) at [x], [d]; [collectedAt] is when it was. */
data class PathSparkle(val id: Int, val x: Float, val d: Float, val collectedAt: Float? = null)

/**
 * Something drifting on the course (a balloon, a jellyfish, a little asteroid) at [x0] + [offset] across and [d]
 * along it, [radius] round. A bump sends it gliding aside at [drift], turning at [spin]; [bumpedAt] is the last bump.
 */
data class PathObstacle(
    val id: Int,
    val x0: Float,
    val d: Float,
    val radius: Float,
    val offset: Float = 0f,
    val drift: Float = 0f,
    val spin: Float = 0f,
    val bumpedAt: Float? = null,
) {
    val x: Float get() = x0 + offset
}

/** What one [RocketPath.step] did, for sounds and sparkles. */
enum class PathEvent { SPARKLE, RING, BUMP, ARRIVED, FINISHED }

/**
 * A round of Rocket path: a gentle course that scrolls by on its own, [LENGTH] field widths long (x across 0 to 1,
 * d along it, both in field widths), carrying the keepsake up it at [SPEED]. The keepsake steers left and right
 * ([steerTo] a finger, [hold] a key, or [auto] by itself) through rings, past sparkles to collect and drifting
 * things that a bump just pushes gently aside. Nothing is lost by missing anything. At the end of the course the
 * scrolling stops and the keepsake glides into the goal; [FINISHED] comes once, [FINALE_S] seconds later.
 * [seed] shapes the course.
 */
class RocketPath(seed: Int) {
    private val random = Random(seed)
    private val phase1 = random.nextFloat() * TAU
    private val phase2 = random.nextFloat() * TAU

    /** Seconds since the round began. */
    var time: Float = 0f
        private set

    /** How far up the course the view is (the keepsake's place on it until the finale). */
    var travel: Float = 0f
        private set

    /** The keepsake's place across, 0 to 1. */
    var x: Float = 0.5f
        private set

    /** How fast it moves across just now, in field widths a second (for banking). */
    var vx: Float = 0f
        private set

    /** Steers by itself toward the next ring or sparkle. */
    var auto: Boolean = false

    /** When the course ran out and the finale began, or null. */
    var arrivedAt: Float? = null
        private set

    /** When the keepsake reached the goal, or null. */
    var finishedAt: Float? = null
        private set

    val gates: List<PathGate> get() = gateList
    val sparkles: List<PathSparkle> get() = sparkleList
    val obstacles: List<PathObstacle> get() = obstacleList

    val collected: Int get() = sparkleList.count { it.collectedAt != null }
    val ringsPassed: Int get() = gateList.count { it.passedAt != null }

    /** How far along the course the view is, 0 to 1. */
    val progress: Float get() = (travel / LENGTH).coerceIn(0f, 1f)

    /** How far into the finale, 0 to 1 (0 before it). */
    val finale: Float get() = arrivedAt?.let { ((time - it) / FINALE_S).coerceIn(0f, 1f) } ?: 0f

    /** The keepsake's place along the course: at the view until the finale, then gliding up into the goal. */
    val shipD: Float get() = travel + ease(finale) * GOAL_AHEAD

    private val gateList = mutableListOf<PathGate>()
    private val sparkleList = mutableListOf<PathSparkle>()
    private val obstacleList = mutableListOf<PathObstacle>()
    private var target: Float? = null
    private var held = 0
    private var nextId = 0

    init {
        // Sparkles lead up to the first ring, then every ring has three after it, all along the breeze line.
        for (d in listOf(0.9f, 1.3f, 1.7f)) sparkleList += PathSparkle(nextId++, line(d), d)
        var d = FIRST_GATE
        var k = 0
        while (d < LENGTH - 1.2f) {
            gateList += PathGate(nextId++, line(d), d)
            for (s in 1..3) {
                val sd = d + s * GATE_GAP / 4f
                if (sd < LENGTH - 0.6f) sparkleList += PathSparkle(nextId++, line(sd), sd)
            }
            // Something drifting off to the side of the line, now and then a little closer to it.
            val od = d + GATE_GAP * 0.5f + (random.nextFloat() - 0.5f) * 0.25f
            if (od < LENGTH - 0.8f) {
                val lx = line(od)
                val side = if (lx < 0.5f) 1f else -1f
                val away = if (k % 3 == 2) 0.22f else 0.3f + random.nextFloat() * 0.06f
                val radius = 0.05f + random.nextFloat() * 0.02f
                obstacleList += PathObstacle(nextId++, (lx + side * away).coerceIn(0.08f, 0.92f), od, radius)
            }
            d += GATE_GAP
            k++
        }
    }

    /** The breeze line the rings and sparkles follow, across at [d]. */
    fun line(d: Float): Float =
        (0.5f + 0.27f * sin(0.62f * d + phase1) + 0.08f * sin(1.5f * d + phase2)).coerceIn(0.14f, 0.86f)

    /** Steers toward [x] across (a finger's place), or stops steering when null. Turns the helper off. */
    fun steerTo(x: Float?) {
        target = x?.coerceIn(MARGIN, 1f - MARGIN)
        if (x != null) auto = false
    }

    /** Steers left (-1) or right (+1) while a key is held, 0 to let go. Turns the helper off. */
    fun hold(direction: Int) {
        held = direction.sign
        if (held != 0) {
            target = null
            auto = false
        }
    }

    /** Steers a step left (-1) or right (+1), as a screen reader action does. */
    fun nudge(direction: Int) {
        target = (x + direction * NUDGE).coerceIn(MARGIN, 1f - MARGIN)
        auto = false
    }

    /** Where the helper steers now: along the breeze line the rings and sparkles sit on, a little ahead. */
    fun autoTarget(): Float = line(travel + AUTO_LEAD)

    /** Runs the round on by [dt] seconds (at most [MAX_FRAME]) in small steps; returns what happened. */
    fun step(dt: Float): List<PathEvent> {
        val events = mutableListOf<PathEvent>()
        var left = dt.coerceIn(0f, MAX_FRAME)
        while (left > 0f) {
            val d = minOf(left, MAX_STEP)
            advance(d, events)
            left -= d
        }
        return events
    }

    private fun advance(dt: Float, events: MutableList<PathEvent>) {
        time += dt
        val before = travel
        if (arrivedAt == null) {
            // A moment on the ground, easing in, then a steady glide.
            travel = (travel + SPEED * dt * ((time - START_S) / EASE_IN_S).coerceIn(0f, 1f)).coerceAtMost(LENGTH)
            if (travel >= LENGTH) {
                arrivedAt = time
                events += PathEvent.ARRIVED
            }
        }
        // Steering.
        val oldX = x
        val goal = when {
            arrivedAt != null -> 0.5f
            auto -> autoTarget()
            else -> target
        }
        if (held != 0 && arrivedAt == null) {
            x += held * STEER_SPEED * dt
        } else if (goal != null) {
            val gap = goal - x
            // Quick at a distance, settling softly as it gets there.
            val speed = minOf(STEER_SPEED, abs(gap) * 6f + 0.05f)
            x += gap.coerceIn(-speed * dt, speed * dt)
        }
        x = x.coerceIn(MARGIN, 1f - MARGIN)
        vx = (x - oldX) / dt
        val now = shipD
        if (arrivedAt == null) {
            for (i in gateList.indices) {
                val g = gateList[i]
                if (g.passedAt == null && before < g.d && travel >= g.d && abs(x - g.x) <= GATE_HALF_WIDTH) {
                    gateList[i] = g.copy(passedAt = time)
                    events += PathEvent.RING
                }
            }
        }
        for (i in sparkleList.indices) {
            val s = sparkleList[i]
            if (s.collectedAt == null && abs(s.d - now) <= REACH && abs(s.x - x) <= REACH) {
                sparkleList[i] = s.copy(collectedAt = time)
                events += PathEvent.SPARKLE
            }
        }
        for (i in obstacleList.indices) {
            var o = obstacleList[i]
            val dx = o.x - x
            val touching = hypot(dx, o.d - now) < o.radius + SHIP_RADIUS
            if (touching && (o.bumpedAt == null || time - o.bumpedAt > 0.5f)) {
                // A gentle push out of the way, to whichever side it was on.
                val way = if (abs(dx) < 0.005f) (if (o.x < 0.5f) -1f else 1f) else sign(dx)
                o = o.copy(drift = way * BUMP_SPEED, spin = way * 1.5f, bumpedAt = time)
                events += PathEvent.BUMP
            }
            if (o.drift != 0f) {
                val damp = 1f - DRIFT_DAMPING * dt
                o = o.copy(
                    offset = (o.offset + o.drift * dt).coerceIn(-0.6f, 0.6f),
                    drift = if (abs(o.drift) < 0.002f) 0f else o.drift * damp,
                    spin = o.spin * damp,
                )
            }
            obstacleList[i] = o
        }
        if (arrivedAt != null && finishedAt == null && finale >= 1f) {
            finishedAt = time
            events += PathEvent.FINISHED
        }
    }

    private fun ease(p: Float): Float = p * p * (3f - 2f * p)

    companion object {
        /** The course's length, in field widths. */
        const val LENGTH = 18f

        /** How fast the course scrolls by, in field widths a second: about 53 seconds from start to goal. */
        const val SPEED = 0.34f

        /** Where the first ring is, and the distance between rings. */
        const val FIRST_GATE = 2.2f
        const val GATE_GAP = 1.6f

        /** How far to each side of a ring's middle still counts as going through. */
        const val GATE_HALF_WIDTH = 0.12f

        /** The keepsake's size for bumping into things, and how near a sparkle it collects it. */
        const val SHIP_RADIUS = 0.07f
        const val REACH = 0.09f

        /** How fast the keepsake moves across at most, in field widths a second, and a screen reader's step. */
        const val STEER_SPEED = 0.85f
        const val NUDGE = 0.12f

        /** How near the edges the keepsake goes. */
        const val MARGIN = 0.08f

        /** How fast a bump sends something aside, and how quickly it slows down again. */
        const val BUMP_SPEED = 0.45f
        const val DRIFT_DAMPING = 1.6f

        /** How far beyond the course's end the goal is, and how long the glide into it takes. */
        const val GOAL_AHEAD = 0.7f
        const val FINALE_S = 2.6f

        /** How far ahead on the line the helper steers for. */
        private const val AUTO_LEAD = 0.1f

        /** How long the keepsake waits at the start before the course begins to move, and eases in after. */
        private const val START_S = 1.2f
        private const val EASE_IN_S = 1.5f
        private const val TAU = (2 * PI).toFloat()
        private const val MAX_STEP = 1f / 120f

        /** The longest frame the round runs on by. */
        const val MAX_FRAME = 0.25f
    }
}
