// The heads-up display around the board: the header on top, the notice line and the controls below.
// Every piece sits on a frosted panel so it reads over any scenery.

/**
 * The top bar: the levels button, a plaque with the arena badge, its stage and the level number, and the colors
 * button; under it a pill with the moves made and the stars they still earn against the level's par.
 */
@Composable
internal fun Header(game: GameController, onColors: () -> Unit, onLevels: () -> Unit) = WithHudLook {
    Column(Modifier.widthIn(max = 520.dp).fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) {
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            LevelsButton(onLevels)
            Spacer(Modifier.weight(1f).widthIn(min = 8.dp))
            LevelPlaque(game.levelNumber)
            Spacer(Modifier.weight(1f).widthIn(min = 8.dp))
            PaletteButton(onColors)
        }
        MovesPill(game.levelNumber, game.moveCount, Modifier.offset(y = (-4).dp))
    }
}

@Composable
private fun LevelPlaque(level: Int) {
    val palette = LocalPalette.current
    val arena = Arena.of(level)
    val shape = RoundedCornerShape(20.dp)
    Row(
        Modifier
            .height(56.dp)
            .widthIn(min = 168.dp)
            .frosted(palette, shape)
            .padding(start = 6.dp, end = 12.dp)
            .semantics(mergeDescendants = true) {},
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Box(Modifier.size(width = 46.dp, height = 52.dp)) {
            ArenaBadge(arena, Modifier.size(42.dp).align(Alignment.TopCenter).padding(top = 1.dp))
            // The stage in the arena, as a small ribbon across the badge's foot.
            Text(
                "${Arena.stage(level)}/${Arena.LEVELS}",
                color = Color.White,
                fontSize = 10.sp,
                fontWeight = FontWeight.ExtraBold,
                lineHeight = 12.sp,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .border(1.dp, Color.White, RoundedCornerShape(50))
                    .background(arenaColors(arena).deep, RoundedCornerShape(50))
                    .padding(horizontal = 6.dp, vertical = 1.dp)
                    .semantics { contentDescription = "stage ${Arena.stage(level)} of ${Arena.LEVELS}" },
            )
        }
        Spacer(Modifier.width(8.dp))
        Column {
            Text(
                arena.title.uppercase(),
                color = palette.dimText,
                fontSize = 11.sp,
                fontWeight = FontWeight.ExtraBold,
                letterSpacing = 0.8.sp,
                maxLines = 1,
                lineHeight = 13.sp,
            )
            Text(
                "Level $level",
                color = palette.accent,
                fontSize = 24.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
                lineHeight = 26.sp,
                style = LocalTextStyle.current.withTitleShadow(palette),
            )
        }
    }
}

/** Moves so far, and the stars they would earn now: all three while the player stays at or under par. */
@Composable
private fun MovesPill(level: Int, moves: Int, modifier: Modifier) {
    val palette = LocalPalette.current
    // The solver's par; cached per level, and the solver finds a solution quickly.
    val par = remember(level) { Stars.par(level) }
    val stars = Stars.earned(moves, par)
    Row(
        modifier
            .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
            .padding(horizontal = 14.dp, vertical = 5.dp)
            .semantics(mergeDescendants = true) {},
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text("MOVES", color = palette.dimText, fontSize = 10.sp, fontWeight = FontWeight.ExtraBold, letterSpacing = 0.6.sp)
        Spacer(Modifier.width(5.dp))
        Text("$moves", color = palette.text, fontSize = 16.sp, fontWeight = FontWeight.Black, lineHeight = 18.sp)
        Box(Modifier.padding(horizontal = 10.dp).size(width = 1.dp, height = 16.dp).background(palette.dimText.copy(alpha = 0.3f)))
        StarRow(
            stars,
            emptyColor = palette.dimText,
            size = 15.dp,
            modifier = Modifier.clearAndSetSemantics { contentDescription = "$stars stars so far" },
        )
        if (par != null) {
            Spacer(Modifier.width(6.dp))
            Text("Par $par", color = palette.dimText, fontSize = 12.sp, fontWeight = FontWeight.Bold)
        }
    }
}

/** A toast-style pill above the controls for hints and dead ends; it pops in and fades out. */
@Composable
internal fun NoticeLine(game: GameController) = WithHudLook {
    val text = when {
        game.isSolved -> null
        game.isStuck -> "No moves left. Undo or restart."
        game.notice == Notice.DEAD_END -> "Can't be solved from here. Undo or restart."
        game.notice == Notice.NO_HINT -> "No hint found. Try a few moves."
        game.hint != null -> "Pour the raised tube into the glowing one."
        else -> null
    }
    // Keep the last text while the toast fades out.
    var shown by remember { mutableStateOf("") }
    if (text != null) shown = text
    val palette = LocalPalette.current
    Box(Modifier.heightIn(min = 44.dp), contentAlignment = Alignment.Center) {
        AnimatedVisibility(text != null, enter = fadeIn() + scaleIn(initialScale = 0.8f), exit = fadeOut() + scaleOut(targetScale = 0.9f)) {
            Row(
                Modifier
                    .padding(horizontal = 8.dp)
                    .frosted(palette, RoundedCornerShape(20.dp), elevation = 4.dp)
                    .padding(start = 10.dp, end = 14.dp, top = 7.dp, bottom = 7.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                // The hint bulb on a small badge of the hint button's color.
                Box(Modifier.size(24.dp).background(palette.highlight, CircleShape), contentAlignment = Alignment.Center) {
                    Image(
                        rememberVectorPainter(HudIcons.Hint),
                        contentDescription = null,
                        colorFilter = ColorFilter.tint(readableOn(palette.highlight)),
                        modifier = Modifier.size(16.dp),
                    )
                }
                Spacer(Modifier.width(8.dp))
                Text(shown, color = palette.text, textAlign = TextAlign.Center, fontSize = 13.sp, fontWeight = FontWeight.Bold, lineHeight = 16.sp)
            }
        }
    }
}

/** Undo, restart and hint as round game buttons with captions, on a frosted strip: a row, or a [vertical] column. */
@Composable
internal fun Controls(game: GameController, vertical: Boolean = false) = WithHudLook {
    val palette = LocalPalette.current
    val playing = !game.isSolved
    val buttons = @Composable {
        val style = ButtonStyle.accent(palette)
        RoundIconButton(HudIcons.Undo, "Undo", game::undo, style, enabled = game.canUndo && playing, caption = true)
        RoundIconButton(HudIcons.Restart, "Restart", game::restart, style, enabled = game.canUndo && playing, caption = true)
        RoundIconButton(HudIcons.Hint, "Hint", game::showHint, ButtonStyle.bright(palette), enabled = playing && !game.isStuck, caption = true)
    }
    val strip = Modifier.frosted(palette, RoundedCornerShape(28.dp))
    if (vertical) {
        Column(strip.padding(horizontal = 12.dp, vertical = 12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { buttons() }
    } else {
        Row(strip.padding(horizontal = 20.dp, vertical = 8.dp), horizontalArrangement = Arrangement.spacedBy(22.dp)) { buttons() }
    }
}
