package io.colorsand.ui.story

import io.colorsand.core.Arena

/** Whether a story beat starts an arena (when the player arrives there) or closes it (once its last level is cleared). */
enum class Beat { OPENING, CLOSING }

/** One beat of Sunny and Mo's story: [arena]'s opening or closing, a few illustrated panels long. */
data class StoryBeat(val arena: Arena, val beat: Beat) {
    /** How the beat is kept in a [StoryBook]: "playground-open", "mars-close", ... */
    val key: String get() = arena.name.lowercase() + if (beat == Beat.OPENING) "-open" else "-close"

    companion object {
        fun opening(arena: Arena) = StoryBeat(arena, Beat.OPENING)
        fun closing(arena: Arena) = StoryBeat(arena, Beat.CLOSING)
    }
}

/**
 * What the story overlay plays: the [beats] in order, or, with no beats, the single "The next day..." panel that
 * starts a new loop through the arenas on [day] (2 for levels 31-60, ...). A [replay] was asked for from the map.
 * With [nextLevel] the game goes on to the next level once the show ends (a closing played from Next level).
 */
data class StoryShow(val beats: List<StoryBeat>, val day: Int = 0, val replay: Boolean = false, val nextLevel: Boolean = false) {
    /** The keys this show marks as seen in a [StoryBook]. */
    val keys: List<String> get() = if (beats.isEmpty()) listOf(StoryBook.dayKey(day)) else beats.map { it.key }

    /** This show as text, so a show in progress survives the screen being rebuilt: "rn|0|beach-close". */
    fun encode(): String = (if (replay) "r" else "") + (if (nextLevel) "n" else "") + "|$day|" + beats.joinToString(",") { it.key }

    companion object {
        private val byKey: Map<String, StoryBeat> =
            Arena.entries.flatMap { listOf(StoryBeat.opening(it), StoryBeat.closing(it)) }.associateBy { it.key }

        /** The show [text] encodes, or null if it can't be read. */
        fun decode(text: String?): StoryShow? {
            val parts = text?.split('|') ?: return null
            if (parts.size != 3) return null
            val day = parts[1].toIntOrNull() ?: return null
            val beats = parts[2].split(',').filter { it.isNotEmpty() }.map { byKey[it] ?: return null }
            if (beats.isEmpty() && day < 2) return null
            return StoryShow(beats, day, replay = 'r' in parts[0], nextLevel = 'n' in parts[0])
        }
    }
}

/**
 * The story beats (and later days) already played, so each plays by itself only once. Stored as text like
 * "beach-close,playground-open,day2". Unknown entries are skipped.
 */
data class StoryBook(val seen: Set<String> = emptySet()) {
    operator fun contains(beat: StoryBeat): Boolean = beat.key in seen

    /** Whether the "next day" panel for [day] has played. */
    fun hasSeenDay(day: Int): Boolean = dayKey(day) in seen

    /** This book with everything [show] plays marked as seen. */
    fun record(show: StoryShow): StoryBook = if (seen.containsAll(show.keys)) this else StoryBook(seen + show.keys)

    fun encode(): String = seen.sorted().joinToString(",")

    companion object {
        private val beatKeys: Set<String> =
            Arena.entries.flatMap { listOf(StoryBeat.opening(it).key, StoryBeat.closing(it).key) }.toSet()

        internal fun dayKey(day: Int) = "day$day"

        fun decode(text: String?): StoryBook = StoryBook(
            text.orEmpty().split(',').map { it.trim() }.filterTo(LinkedHashSet()) { key ->
                key in beatKeys || (key.startsWith("day") && (key.removePrefix("day").toIntOrNull() ?: 0) >= 2)
            },
        )
    }
}

/** When the story plays by itself. */
object StoryPlan {
    /** The levels of one trip through all the arenas, after which they repeat. */
    val LOOP_LEVELS = Arena.LEVELS * Arena.entries.size

    /** Which trip through the arenas [level] is on: 1 for levels 1-30, 2 for 31-60, ... */
    fun day(level: Int): Int = (level - 1) / LOOP_LEVELS + 1

    /**
     * What plays when the player arrives in an arena at [level] (see ArenaArrival), given what [book] has seen:
     * on the first trip, the arena's opening, once. On later trips the openings don't play again, but arriving at
     * the start of a new trip shows the "next day" panel once.
     *
     * Arriving at an arena's first level with the level before it [clearedBefore] also catches up on the arena
     * before's closing, if it hasn't played: say the game was closed on the last level's success card, before Next.
     */
    fun onArrival(level: Int, book: StoryBook, clearedBefore: Boolean = false): StoryShow? {
        if (level < 1) return null
        val day = day(level)
        val arena = Arena.of(level)
        if (day == 1) {
            val missed = if (level > 1 && Arena.isFirst(level) && clearedBefore) {
                StoryBeat.closing(Arena.of(level - 1)).takeIf { it !in book }
            } else {
                null
            }
            val opening = StoryBeat.opening(arena).takeIf { it !in book }
            val beats = listOfNotNull(missed, opening)
            return if (beats.isEmpty()) null else StoryShow(beats)
        }
        val startsTrip = (level - 1) % LOOP_LEVELS == 0
        return if (startsTrip && !book.hasSeenDay(day)) StoryShow(emptyList(), day) else null
    }

    /** What plays after [level] is solved and the player goes on: the arena's closing, after its last level, once. */
    fun afterClear(level: Int, book: StoryBook): StoryShow? {
        if (level < 1 || day(level) != 1 || !Arena.isLast(level)) return null
        val closing = StoryBeat.closing(Arena.of(level))
        return if (closing in book) null else StoryShow(listOf(closing), nextLevel = true)
    }

    /** Replaying [arena]'s story from the map: its opening, and its closing once that has been seen. */
    fun replay(arena: Arena, book: StoryBook): StoryShow {
        val closing = StoryBeat.closing(arena)
        return StoryShow(listOfNotNull(StoryBeat.opening(arena), closing.takeIf { it in book }), replay = true)
    }
}
