package io.colorsand.ui.minigame

import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.sin
import kotlin.math.sqrt
import kotlin.random.Random

/**
 * One thing in the pile: which bin it belongs in ([kind]), which of its looks it has ([shape]), where it lies in
 * the pile ([x], [y], 0 to 1 across and down the pile's area) and how it is turned ([tilt], in degrees).
 */
data class SortItem(val kind: Int, val shape: Int, val x: Float, val y: Float, val tilt: Float)

/** What became of an attempt to sort an item into a bin. */
enum class SortResult { RIGHT, WRONG, IGNORED }

/**
 * A round of Sort: a pile of [items], each belonging in one of [bins] bins, and the ones [sorted] so far (item
 * index to bin). The pile is drawn in item order, so a later item lies on top of an earlier one. A right bin takes
 * an item; a wrong one doesn't, and the item simply goes back to the pile, so there is no way to fail. Done when the
 * pile is empty. Immutable; [sort] returns the next state.
 */
data class SortRound(val items: List<SortItem>, val bins: Int = KINDS, val sorted: Map<Int, Int> = emptyMap()) {
    val isDone: Boolean get() = sorted.size == items.size

    /** The items still in the pile, bottom first. */
    val pile: List<Int> get() = items.indices.filter { it !in sorted }

    fun isSorted(item: Int): Boolean = item in sorted

    /** Whether [item] belongs in [bin]. */
    fun fits(item: Int, bin: Int): Boolean = items.getOrNull(item)?.kind == bin

    /** How many items are in [bin]. */
    fun countIn(bin: Int): Int = sorted.values.count { it == bin }

    /** What sorting [item] into [bin] would do. */
    fun resultOf(item: Int, bin: Int): SortResult = when {
        item !in items.indices || bin !in 0 until bins || item in sorted -> SortResult.IGNORED
        fits(item, bin) -> SortResult.RIGHT
        else -> SortResult.WRONG
    }

    /** This round after sorting [item] into [bin]: in it goes if it belongs there, otherwise nothing changes. */
    fun sort(item: Int, bin: Int): SortRound =
        if (resultOf(item, bin) == SortResult.RIGHT) copy(sorted = sorted + (item to bin)) else this

    /**
     * The topmost item still in the pile under the point ([x], [y]) in the pile's 0 to 1 coordinates, where an item
     * covers an ellipse [rx] by [ry] around its place; null if there is none.
     */
    fun itemAt(x: Float, y: Float, rx: Float, ry: Float): Int? = pile.lastOrNull { i ->
        val dx = (x - items[i].x) / rx
        val dy = (y - items[i].y) / ry
        dx * dx + dy * dy <= 1f
    }

    companion object {
        /** Bins, and kinds of things in the pile. */
        const val KINDS = 3

        /** Things of each kind in the pile. */
        const val PER_KIND = 5

        /** Looks each kind comes in. */
        const val SHAPES = 3

        /** The least distance between two things in the pile, in its 0 to 1 coordinates. */
        const val SPACING = 0.19f

        /**
         * A new pile of [perKind] things of each of [kinds] kinds, the same for the same [seed]: mixed up, in
         * different shapes and turns, scattered over an oval so each one shows at least partly.
         */
        fun start(seed: Int, kinds: Int = KINDS, perKind: Int = PER_KIND): SortRound {
            val random = Random(seed)
            val kindsInPile = List(kinds * perKind) { it % kinds }.shuffled(random)
            val places = scatter(random, kindsInPile.size)
            val items = kindsInPile.mapIndexed { i, kind ->
                val (x, y) = places[i]
                SortItem(kind, random.nextInt(SHAPES), x, y, random.nextFloat() * 50f - 25f)
            }
            return SortRound(items, kinds)
        }

        /** [count] places in an oval in the middle of the 0 to 1 square, kept [SPACING] apart where they fit. */
        private fun scatter(random: Random, count: Int): List<Pair<Float, Float>> {
            var spacing = SPACING
            while (true) {
                val places = mutableListOf<Pair<Float, Float>>()
                var tries = 0
                while (places.size < count && tries < 4000) {
                    tries++
                    val a = random.nextFloat() * 2 * PI.toFloat()
                    val r = sqrt(random.nextFloat())
                    val x = 0.5f + cos(a) * r * 0.4f
                    val y = 0.5f + sin(a) * r * 0.38f
                    if (places.all { (px, py) -> (px - x) * (px - x) + (py - y) * (py - y) >= spacing * spacing }) places += x to y
                }
                if (places.size == count) return places
                spacing *= 0.92f
            }
        }
    }
}
