// Bubble pop's drawing: the water and sea floor, the glossy bubbles and their treasures, the pops, the clownfish
// and the collection shell. Sizes follow the field's width, so the art scales with the play area.

/**
 * Where things are in a play area [width] x [height] (pixels): the sea floor is a band along the bottom, and the
 * round's field (1 wide, y up from the floor) maps onto the water above it.
 */
internal class BubbleField(val width: Float, val height: Float) {
    /** How tall the sand is. */
    val floor: Float = min(height * 0.16f, width * 0.3f)

    /** The line on the sand where bubbles are born. */
    val floorLine: Float = height - floor * 0.72f

    /** The water's height in field widths, for [BubblePop.height]. */
    val water: Float get() = floorLine / width

    /** The point on screen for field point ([x], [y]). */
    fun at(x: Float, y: Float): Offset = Offset(x * width, floorLine - y * width)

    /** The field point under screen point [p]. */
    fun field(p: Offset): Offset = Offset(p.x / width, (floorLine - p.y) / width)

    /** The collection shell's hinge, on the sand in the middle. */
    val shell: Offset get() = Offset(width / 2f, height - floor * 0.3f)

    /** The shell's size: its half width. */
    val shellSize: Float get() = min(width * 0.15f, floor * 1.25f)

    /** Where the [i]th treasure (0 until 5) settles in the shell. */
    fun slot(i: Int): Offset {
        val s = shellSize
        return shell + Offset((i - 2) * s * 0.34f, -s * 0.2f - (if (i % 2 == 0) 0f else s * 0.08f))
    }

    /** How big a treasure sitting in the shell is: its radius. */
    val slotSize: Float get() = shellSize * 0.25f
}

/** The water from the light surface down to the deep, light rays swaying through it, and marine snow drifting. */
internal fun DrawScope.drawBubbleWater(field: BubbleField, g: SceneGrade, t: Float) {
    val w = size.width
    val h = size.height
    drawRect(Brush.verticalGradient(listOf(g(0xFF8EDDEA), g(0xFF3FA6C9), g(0xFF1F6E9C)), 0f, field.floorLine))
    // Rays of light from the surface, leaning and swaying.
    for (k in 0 until 4) {
        val sway = sin(t * 0.25f + k * 1.7f) * w * 0.04f
        val x = w * (0.12f + k * 0.26f) + sway
        val ray = Path().apply {
            moveTo(x - w * 0.05f, 0f)
            lineTo(x + w * 0.04f, 0f)
            lineTo(x + w * 0.2f, h * 0.8f)
            lineTo(x + w * 0.06f, h * 0.8f)
            close()
        }
        val glow = 0.1f + 0.05f * sin(t * 0.4f + k * 2.1f)
        drawPath(ray, Brush.verticalGradient(listOf(Color.White.copy(alpha = glow), Color.White.copy(alpha = 0f)), 0f, h * 0.8f))
    }
    // Far-off reef humps, faded into the blue.
    val reef = g(0xFF2A84AE).copy(alpha = 0.55f)
    oval(reef, w * 0.12f, field.floorLine, w * 0.22f, w * 0.12f)
    oval(reef, w * 0.32f, field.floorLine, w * 0.12f, w * 0.06f)
    oval(reef, w * 0.86f, field.floorLine, w * 0.26f, w * 0.15f)
    for (k in 0 until 3) {
        val x = w * (0.78f + k * 0.07f)
        drawLine(reef, Offset(x, field.floorLine - w * 0.1f), Offset(x + sin(t * 0.5f + k) * w * 0.012f, field.floorLine - w * (0.2f + 0.04f * k)), w * 0.025f, StrokeCap.Round)
    }
    // Marine snow drifting down.
    for (k in 0 until 22) {
        val x0 = ((k * 0.618f) % 1f) * w
        val fall = ((t * (0.008f + 0.004f * (k % 3)) + k * 0.137f) % 1f)
        val y = fall * field.floorLine
        val x = x0 + sin(t * 0.6f + k) * w * 0.01f
        drawCircle(Color.White.copy(alpha = 0.25f * sin(fall * PI.toFloat())), w * (0.003f + 0.002f * (k % 2)), Offset(x, y))
    }
}

/** The sandy floor with ripples, pebbles and swaying sea grass, in front of the water. */
internal fun DrawScope.drawBubbleFloor(field: BubbleField, g: SceneGrade, t: Float) {
    val w = size.width
    val h = size.height
    val top = field.height - field.floor
    val sand = Path().apply {
        moveTo(0f, top + field.floor * 0.12f)
        val steps = 24
        for (i in 0..steps) {
            val x = w * i / steps
            lineTo(x, top + field.floor * (0.12f + 0.1f * sin(i / steps.toFloat() * TAU * 1.5f + 0.6f)))
        }
        lineTo(w, h)
        lineTo(0f, h)
        close()
    }
    drawPath(sand, Brush.verticalGradient(listOf(g(0xFFF4E2B2), g(0xFFDDBD82)), top, h))
    // Ripples in the sand.
    val ripple = g(0xFFC9A66A).copy(alpha = 0.45f)
    for (k in 0 until 5) {
        val y = top + field.floor * (0.4f + 0.12f * k)
        val x = w * ((k * 0.37f) % 1f)
        drawArc(ripple, 200f, 140f, false, Offset(x - w * 0.1f, y - field.floor * 0.08f), Size(w * 0.2f, field.floor * 0.16f), style = Stroke(w * 0.006f, cap = StrokeCap.Round))
    }
    // Pebbles.
    val pebbles = listOf(0.08f to 0.62f, 0.2f to 0.78f, 0.74f to 0.7f, 0.9f to 0.58f, 0.33f to 0.55f, 0.63f to 0.86f)
    pebbles.forEachIndexed { k, (px, py) ->
        val c = Offset(w * px, top + field.floor * py)
        val r = w * (0.012f + 0.006f * (k % 3))
        oval(g(0xFFA89A8A), c.x, c.y, r * 1.3f, r)
        oval(g(0xFFCFC3B4), c.x - r * 0.2f, c.y - r * 0.25f, r * 0.8f, r * 0.55f)
    }
    // Sea grass at both sides.
    for ((x0, n) in listOf(w * 0.05f to 4, w * 0.95f to 5, w * 0.27f to 2)) {
        for (k in 0 until n) {
            val x = x0 + (k - n / 2f) * w * 0.018f
            val base = Offset(x, top + field.floor * 0.3f)
            val tall = w * (0.13f + 0.04f * ((k * 7) % 3))
            val bend = sin(t * 0.8f + k * 0.9f + x0) * w * 0.03f
            val blade = Path().apply {
                moveTo(base.x - w * 0.009f, base.y)
                quadraticTo(base.x + bend * 0.5f - w * 0.012f, base.y - tall * 0.55f, base.x + bend, base.y - tall)
                quadraticTo(base.x + bend * 0.5f + w * 0.012f, base.y - tall * 0.5f, base.x + w * 0.009f, base.y)
                close()
            }
            drawPath(blade, if (k % 2 == 0) g(0xFF3FA65A) else g(0xFF5CC06C))
        }
    }
}

/**
 * A glossy bubble of radius [r] around [c]: a clear body with an iridescent rim turning with [spin] (0 to 1), a
 * bright highlight, and its [treasure] floating inside. [squish] stretches it a little as it wobbles.
 */
internal fun DrawScope.drawBubble(c: Offset, r: Float, spin: Float, squish: Float, treasure: BubbleTreasure?, g: SceneGrade) {
    scale(1f + squish, 1f - squish, c) {
        drawCircle(
            Brush.radialGradient(
                0f to Color.White.copy(alpha = 0.04f),
                0.72f to Color(0xFFC8F2FF).copy(alpha = 0.12f),
                1f to Color(0xFFEFFCFF).copy(alpha = 0.45f),
                center = c,
                radius = r,
            ),
            r,
            c,
        )
        if (treasure != null) {
            drawGlow(c, r * 0.8f, Color(0xFFFFF4C8).copy(alpha = 0.35f))
            rotate(sin(spin * TAU * 3f) * 12f, c) { drawTreasure(treasure, c + Offset(0f, r * 0.04f), r * 0.52f, g) }
        }
        rotate(spin * 360f, c) {
            // A soft film of rainbow inside the rim...
            drawCircle(
                Brush.sweepGradient(
                    listOf(
                        Color(0xFF8ADCFF), Color(0xFFFFA8D2), Color(0xFFFFE9A0), Color(0xFFA6F7CF),
                        Color(0xFFB9A8FF), Color(0xFF8ADCFF),
                    ),
                    c,
                ),
                r * 0.8f,
                c,
                alpha = 0.22f,
                style = Stroke(r * 0.26f),
            )
            // ...and a bright one on it.
            drawCircle(
                Brush.sweepGradient(
                    listOf(
                        Color(0xFFFF9EC8), Color(0xFFFFE28A), Color(0xFF9CF5C4), Color(0xFF8ADCFF),
                        Color(0xFFC6A2FF), Color(0xFFFF9EC8),
                    ),
                    c,
                ),
                r * 0.95f,
                c,
                alpha = 0.75f,
                style = Stroke(r * 0.085f),
            )
        }
        drawCircle(Color.White.copy(alpha = 0.6f), r, c, style = Stroke(maxOf(1f, r * 0.03f)))
        // The window highlight, up and to the left, and a little one opposite.
        rotate(-38f, c) {
            drawOval(Color.White.copy(alpha = 0.85f), Offset(c.x - r * 0.3f, c.y - r * 0.78f), Size(r * 0.5f, r * 0.2f))
        }
        drawCircle(Color.White.copy(alpha = 0.9f), r * 0.07f, c + Offset(-r * 0.62f, -r * 0.2f))
        drawCircle(Color.White.copy(alpha = 0.4f), r * 0.09f, c + Offset(r * 0.48f, r * 0.45f))
    }
}

/** A [treasure] of radius [s] around [c]. */
internal fun DrawScope.drawTreasure(treasure: BubbleTreasure, c: Offset, s: Float, g: SceneGrade) {
    when (treasure) {
        BubbleTreasure.PEARL -> {
            drawCircle(Color.Black.copy(alpha = 0.12f), s * 0.8f, c + Offset(s * 0.06f, s * 0.1f))
            drawCircle(
                Brush.radialGradient(
                    0f to Color.White,
                    0.45f to g(0xFFF6EEF4),
                    1f to g(0xFFC4B2D2),
                    center = c + Offset(-s * 0.3f, -s * 0.3f),
                    radius = s * 1.1f,
                ),
                s * 0.78f,
                c,
            )
            drawCircle(g(0xFFFFD6E8).copy(alpha = 0.5f), s * 0.7f, c, style = Stroke(s * 0.08f))
            drawCircle(Color.White, s * 0.16f, c + Offset(-s * 0.28f, -s * 0.3f))
        }
        BubbleTreasure.SHELL -> {
            val hinge = c + Offset(0f, s * 0.75f)
            val fan = Path().apply {
                moveTo(hinge.x, hinge.y)
                for (k in 0..10) {
                    val a = (200f + k * 14f) / 360f * TAU
                    val bump = if (k % 2 == 0) 1f else 0.9f
                    lineTo(hinge.x + cos(a) * s * 1.05f * bump, hinge.y + sin(a) * s * 1.35f * bump)
                }
                close()
            }
            drawPath(fan, g(0xFFE88370))
            scale(0.88f, 0.88f, hinge) { drawPath(fan, g(0xFFFFB49C)) }
            for (k in 1..9 step 2) {
                val a = (200f + k * 14f) / 360f * TAU
                drawLine(g(0xFFE88370), hinge, hinge + Offset(cos(a) * s, sin(a) * s * 1.25f), s * 0.07f, StrokeCap.Round)
            }
            drawRoundRect(g(0xFFE88370), Offset(hinge.x - s * 0.3f, hinge.y - s * 0.18f), Size(s * 0.6f, s * 0.26f), androidx.compose.ui.geometry.CornerRadius(s * 0.1f))
            drawCircle(Color.White.copy(alpha = 0.6f), s * 0.12f, c + Offset(-s * 0.3f, -s * 0.15f))
        }
        BubbleTreasure.STARFISH -> {
            val star = starPath(0.48f)
            translate(c.x, c.y) {
                rotate(-8f, Offset.Zero) {
                    scale(s * 1.02f, s * 1.02f, Offset.Zero) { drawPath(star, g(0xFFE0612E)) }
                    scale(s * 0.86f, s * 0.86f, Offset.Zero) { drawPath(star, g(0xFFFF9150)) }
                    for (k in 0 until 5) {
                        val a = -TAU / 4 + k * TAU / 5
                        drawCircle(g(0xFFFFD08A), s * 0.07f, Offset(cos(a) * s * 0.5f, sin(a) * s * 0.5f))
                    }
                    drawCircle(g(0xFFFFC27A), s * 0.12f, Offset.Zero)
                }
            }
        }
    }
}

/** A bubble bursting: a ring flying out and fading, a flash, and droplets thrown out and falling, [p] from 0 to 1. */
internal fun DrawScope.drawPopBurst(c: Offset, r: Float, p: Float, seed: Int) {
    if (p <= 0f || p >= 1f) return
    val e = 1f - (1f - p) * (1f - p)
    if (p < 0.45f) drawGlow(c, r * (1f + 0.6f * e), Color.White.copy(alpha = 0.55f * (1f - p / 0.45f)))
    drawCircle(
        Brush.sweepGradient(listOf(Color(0xFFFFB8DA), Color(0xFFFFF0A8), Color(0xFFB4FFD8), Color(0xFFA8E8FF), Color(0xFFFFB8DA)), c),
        r * (1f + 0.75f * e),
        c,
        alpha = 0.9f * (1f - p),
        style = Stroke(r * 0.14f * (1f - p) + 0.5f),
    )
    for (k in 0 until 9) {
        val a = (k / 9f + seed * 0.173f) * TAU
        val reach = r * (1.05f + (0.9f + 0.4f * ((k * 5 + seed) % 3)) * e)
        val d = c + Offset(cos(a) * reach, sin(a) * reach + r * 0.9f * p * p)
        drawCircle(Color(0xFFE8FBFF).copy(alpha = 0.95f * (1f - p)), r * 0.085f * (1f - 0.5f * p), d)
        drawCircle(Color.White.copy(alpha = 1f - p), r * 0.03f, d + Offset(-r * 0.025f, -r * 0.025f))
    }
    if (p < 0.6f) drawSparkle(c + Offset(r * 0.5f, -r * 0.5f), r * 0.35f * (1f - p), Color.White, 1f - p / 0.6f)
}

/**
 * The clownfish keepsake swimming at [c], [length] long, facing right when [facing] is 1 and left when -1, its
 * tail wagging at [wag] (radians, it keeps turning).
 */
internal fun DrawScope.drawSwimmingClownfish(c: Offset, length: Float, facing: Float, wag: Float, g: SceneGrade) {
    val unit = length / 52f
    translate(c.x - 50f * unit, c.y - 60f * unit) {
        scale(unit, unit, Offset.Zero) {
            scale(facing, 1f, Offset(50f, 60f)) {
                val orange = g(0xFFFF8A1E)
                val dark = g(0xFF2A2328)
                rotate(sin(wag) * 12f, Offset(32f, 60f)) {
                    drawPath(fishTail, dark)
                    scale(0.8f, 0.8f, Offset(32f, 60f)) { drawPath(fishTail, orange) }
                }
                oval(dark, 52f, 49f, 9f, 5f)
                oval(orange, 52f, 50f, 8f, 4f)
                oval(dark, 50f, 60f, 21f, 13f)
                clipPath(fishBody) {
                    drawPath(fishBody, orange)
                    for (sx in floatArrayOf(40f, 54f, 66f)) {
                        oval(dark, sx, 60f, 4.4f, 14f)
                        oval(Color.White, sx, 60f, 3f, 14f)
                    }
                    oval(g(0xFFD9620C), 50f, 70f, 22f, 4f)
                    oval(Color.White.copy(alpha = 0.35f), 46f, 52f, 12f, 3f)
                }
                rotate(sin(wag * 0.7f) * 20f, Offset(53f, 66f)) { oval(orange, 53f, 70f, 5f, 3f) }
                drawCircle(Color.White, 3.3f, Offset(63f, 57f))
                eye(63.6f, 57.2f, 2f)
            }
        }
    }
}

private val fishBody = Path().apply { addOval(Rect(30f, 48f, 70f, 72f)) }
private val fishTail = polygon(34f, 60f, 20f, 49f, 22f, 60f, 20f, 71f)

/** The back half of the open collection shell: its lid tipped up behind, and the pearly hollow inside. */
internal fun DrawScope.drawShellBack(field: BubbleField, g: SceneGrade, glow: Float) {
    val c = field.shell
    val s = field.shellSize
    oval(Color.Black.copy(alpha = 0.16f), c.x, c.y + s * 0.2f, s * 1.1f, s * 0.16f)
    if (glow > 0f) drawGlow(c - Offset(0f, s * 0.35f), s * 1.6f, Color(0xFFFFF1B8).copy(alpha = 0.6f * glow))
    val hinge = c + Offset(0f, -s * 0.12f)
    val lid = scallop(hinge, s, s * 0.95f, up = true)
    drawPath(lid, g(0xFFE58FA6))
    scale(0.9f, 0.9f, hinge) { drawPath(lid, g(0xFFFFC2CF)) }
    for (k in 1..11 step 2) {
        val a = (180f + k * 15f) / 360f * TAU
        drawLine(g(0xFFF0A3B6), hinge, hinge + Offset(cos(a) * s * 0.85f, sin(a) * s * 0.8f), s * 0.035f, StrokeCap.Round)
    }
    // The hollow, pearly pink.
    drawOval(
        Brush.radialGradient(listOf(g(0xFFFFF0F4), g(0xFFE7A9BE)), center = c + Offset(0f, -s * 0.2f), radius = s * 0.9f),
        Offset(c.x - s * 0.88f, c.y - s * 0.38f),
        Size(s * 1.76f, s * 0.4f),
    )
}

/** The front half of the collection shell: the lower lip, in front of the treasures sitting in it. */
internal fun DrawScope.drawShellFront(field: BubbleField, g: SceneGrade) {
    val c = field.shell
    val s = field.shellSize
    val lip = Path().apply {
        moveTo(c.x - s * 0.95f, c.y - s * 0.18f)
        cubicTo(c.x - s * 0.8f, c.y + s * 0.28f, c.x + s * 0.8f, c.y + s * 0.28f, c.x + s * 0.95f, c.y - s * 0.18f)
        cubicTo(c.x + s * 0.6f, c.y - s * 0.06f, c.x - s * 0.6f, c.y - s * 0.06f, c.x - s * 0.95f, c.y - s * 0.18f)
        close()
    }
    drawPath(lip, g(0xFFE58FA6))
    clipPath(lip) {
        for (k in -4..4) {
            val x = c.x + k * s * 0.21f
            drawLine(g(0xFFFFC2CF), Offset(x, c.y - s * 0.12f), Offset(c.x + k * s * 0.14f, c.y + s * 0.3f), s * 0.07f, StrokeCap.Round)
        }
    }
    drawCircle(Color.White.copy(alpha = 0.55f), s * 0.05f, Offset(c.x - s * 0.55f, c.y - s * 0.05f))
}

/** A scallop's fan around [hinge], [rx] by [ry], opening up or down. */
private fun scallop(hinge: Offset, rx: Float, ry: Float, up: Boolean): Path = Path().apply {
    moveTo(hinge.x, hinge.y)
    for (k in 0..12) {
        val a = (180f + k * 15f) / 360f * TAU
        val bump = if (k % 2 == 0) 1f else 0.93f
        val y = sin(a) * ry * bump
        lineTo(hinge.x + cos(a) * rx * bump, hinge.y + if (up) y else -y)
    }
    close()
}
