/**
 * Snowball toss, gently: a sling at the bottom left of [arena]'s ground throws sandballs at toy blocks and sand
 * buckets (Playground) or sandbags at stacks of traffic cones and pallets (Building Site). Pull back from anywhere
 * to aim and set the power, with a dotted arc showing the start of the throw, and let go to toss. Throws are
 * unlimited and the arc grows after misses; five hits end the round and call [onFinished]. Up and Down aim, Left and
 * Right set the power, Enter or Space throws, and screen readers get the same as actions plus where the arc lands.
 */
@Composable
fun SandTossGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { TossLook.of(arena, grade) }
    val round = remember(seed, arena) { SandToss(arena, seed) }
    val puffs = remember(seed) { mutableListOf<TossPuff>() }
    var frame by remember(seed) { mutableStateOf(0) }
    var status by remember(seed) { mutableStateOf(look.start) }
    var hits by remember(seed) { mutableStateOf(0) }
    var done by remember(seed) { mutableStateOf(false) }
    // The aim as screen readers hear it, refreshed when it changes.
    var aim by remember(seed) { mutableStateOf(round.angle to round.power) }
    val sceneClock = rememberSceneClock()
    val focus = remember { FocusRequester() }
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }

    LaunchedEffect(round) {
        var last = -1L
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else (now - last) / 1_000_000_000f
                last = now
                val before = round.ball
                for (event in round.step(dt)) {
                    when (event) {
                        TossEvent.THROWN -> feedback.play(Sounds.pick)
                        TossEvent.BOUNCED -> {
                            round.ball?.let { puffs += TossPuff(it.x, 0f, round.time, 0.6f) }
                            feedback.tick()
                        }
                        TossEvent.KNOCKED, TossEvent.LANDED_IN -> {
                            val target = round.targets.filter { it.hitAt != null }.maxByOrNull { it.hitAt!! }
                            if (target != null) {
                                puffs += TossPuff(target.x, target.top, round.time, 1.2f)
                                status = look.cheer(target.kind)
                            }
                            hits = round.hits
                            feedback.play(Sounds.chime(round.hits))
                            feedback.confirm()
                        }
                        TossEvent.SPLAT -> {
                            round.splat?.let { puffs += TossPuff(it.first.x, 0.01f, round.time, 1f) }
                            feedback.play(Sounds.land)
                        }
                        TossEvent.MISSED -> status = when {
                            round.missesInARow >= SandToss.FULL_AFTER -> "Now the dots show the whole way!"
                            round.missesInARow >= 2 -> "The dots reach further now. Follow them!"
                            else -> "So close! Try again."
                        }
                        TossEvent.APPEARED -> feedback.play(Sounds.click)
                        TossEvent.DONE -> {
                            status = look.done
                            done = true
                        }
                    }
                }
                if (before != null && round.ball == null && round.canThrow) aim = round.angle to round.power
                puffs.removeAll { round.time - it.at > PUFF_S }
                frame++
            }
        }
    }
    LaunchedEffect(done) {
        if (done) {
            delay(1800)
            onFinished()
        }
    }

    fun toss() {
        if (round.throwBall()) status = "Whee!"
    }
    fun aimBy(angle: Int, power: Int) {
        if (angle != 0) round.nudgeAngle(angle)
        if (power != 0) round.nudgePower(power)
        aim = round.angle to round.power
        feedback.tick()
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .clip(RoundedCornerShape(28.dp))
                .semantics {
                    contentDescription = "A ${look.launcher} at the bottom left, ${targetsLine(look, round)}"
                    stateDescription = aimLine(look, round, aim, hits)
                    onClick(label = "Throw") { toss(); true }
                    customActions = listOf(
                        CustomAccessibilityAction("Aim higher") { aimBy(1, 0); true },
                        CustomAccessibilityAction("Aim lower") { aimBy(-1, 0); true },
                        CustomAccessibilityAction("More power") { aimBy(0, 1); true },
                        CustomAccessibilityAction("Less power") { aimBy(0, -1); true },
                        CustomAccessibilityAction("Throw") { toss(); true },
                    )
                }
                .onKeyEvent { event ->
                    val down = event.type == KeyEventType.KeyDown
                    when (event.key) {
                        Key.DirectionUp -> { if (down) aimBy(1, 0); true }
                        Key.DirectionDown -> { if (down) aimBy(-1, 0); true }
                        Key.DirectionRight -> { if (down) aimBy(0, 1); true }
                        Key.DirectionLeft -> { if (down) aimBy(0, -1); true }
                        Key.Enter, Key.Spacebar -> { if (event.type == KeyEventType.KeyUp) toss(); true }
                        else -> false
                    }
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(round) {
                    // Press anywhere and pull back: the ball flies the other way, harder the further the pull.
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        // The press is the game's alone, so keys keep coming here after a drag.
                        down.consume()
                        runCatching { focus.requestFocus() }
                        val width = size.width.toFloat()
                        var pulled = false
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            change.consume()
                            if (!change.pressed) break
                            val d = change.position - down.position
                            // Pulled back to where it started, the throw is called off.
                            val now = round.pull(d.x / width, -d.y / width)
                            if (now && !pulled) feedback.tick()
                            pulled = now
                        }
                        if (pulled) {
                            aim = round.angle to round.power
                            toss()
                        }
                    }
                },
        ) {
            if (frame < 0) return@Canvas
            val layout = TossLayout(size.width, size.height)
            drawTossScenery(look, layout, round.time)
            drawTossForeground(look, layout, grade, sceneClock.value)
            drawTossSplat(look, layout, round)
            drawLauncherBack(look, layout, round)
            drawTossTargets(look, layout, round, grade)
            drawTossPreview(layout, round, Color.White)
            drawTossBall(look, layout, round)
            drawLauncherFront(look, layout, round, round.time)
            drawTossPuffs(look, layout, puffs, round.time)
        }
        Spacer(Modifier.height(12.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status,
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text(
                "$hits/${SandToss.TARGETS}",
                color = palette.accent,
                fontSize = 16.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
            )
        }
    }
}

/** What stands to be hit, nearest first, for screen readers. */
private fun targetsLine(look: TossLook, round: SandToss): String {
    val standing = round.targets.filter { it.hitAt == null }.sortedBy { it.x }
    if (standing.isEmpty()) return "nothing left standing"
    return standing.joinToString(prefix = "aiming at ", separator = ", ") { "${look.name(it.kind)} ${distance(it.lane)}" }
}

private fun distance(lane: Int): String = when (lane) {
    0 -> "near"
    1 -> "in the middle"
    else -> "far"
}

/** The aim as screen readers hear it: angle, power, where the throw comes down, and the hits so far. */
private fun aimLine(look: TossLook, round: SandToss, aim: Pair<Float, Float>, hits: Int): String {
    val (angle, power) = aim
    val lands = round.aimHint()?.let { (target, hint) ->
        val name = look.name(target.kind)
        when (hint) {
            AimHint.SHORT -> "comes down short of the $name"
            AimHint.ON -> "comes down on the $name"
            AimHint.LONG -> "goes past the $name"
        }
    } ?: "nothing left to hit"
    return "Aim ${angle.roundToInt()} degrees, power ${(power * 100).roundToInt()} percent, $lands. $hits of ${SandToss.TARGETS} hit"
}
