// Sunny the kitten and Mo the mole, painted in code in the keepsakes' soft two-tone style (a shade under a lit
// color, a gloss, no outlines). Each stands on (x, ground) and is drawn [height] tall: inside, they are painted
// in a box 100 units tall standing on y = 0, x = 0 in the middle, y growing downward.

/** What a character is doing. */
internal enum class Pose {
    STAND, WAVE, CHEER, SIT, SLEEP, POINT,

    /** Both paws held out in front, around whatever the caller draws as the prop. */
    HOLD,

    /** Mo only: popping out of a hole (see [mo]'s rise and soil). Sunny treats it like [STAND]. */
    PEEK,
}

/** The look on a character's face. Open eyes blink now and then by themselves. */
internal enum class Mood { OPEN, HAPPY, CLOSED, WIDE }

/** What a character wears on its head. */
internal enum class Hat { NONE, HARD_HAT, SPACE_HELMET }

private val Ink = Color(0xFF2E2329)

/**
 * Sunny, a little orange kitten with a cream muzzle and belly and one white paw tip (the paw the player pours
 * with), standing at ([x], [ground]) [height] tall. [t] is the scene clock (blinks, the tail's sway, a wave);
 * [hop] lifts Sunny off the ground (in the 100-unit box), [look] nudges the eyes. With [flip] Sunny faces the
 * other way. A [prop] is drawn in Sunny's own units after the body and before the arms, so with [Pose.HOLD] the
 * paws hold it (they meet around (0, -26)).
 */
internal fun DrawScope.sunny(
    x: Float,
    ground: Float,
    height: Float,
    g: SceneGrade,
    t: Float,
    pose: Pose = Pose.STAND,
    mood: Mood = Mood.OPEN,
    hat: Hat = Hat.NONE,
    flip: Boolean = false,
    hop: Float = 0f,
    look: Offset = Offset.Zero,
    prop: (DrawScope.() -> Unit)? = null,
) = place(x, ground, height, flip) {
    val c = SunnyColors(g)
    if (pose != Pose.SLEEP) shadow(18f, hop)
    translate(0f, -hop - idleBob(pose, t, 0f)) {
        when (pose) {
            Pose.SLEEP -> {
                // Curled up on its tummy, the tail wrapped round the front.
                oval(c.shade, 6f, -13f, 30f, 13f)
                oval(c.fur, 5f, -14f, 28.5f, 11.5f)
                oval(c.light.copy(alpha = 0.5f), -2f, -20f, 12f, 3f)
                oval(c.cream, -10f, -4f, 8f, 4f)
                prop?.invoke(this)
                val tail = Path().apply {
                    moveTo(32f, -8f)
                    cubicTo(36f, 4f, 0f, 4f, -18f, -1f)
                }
                drawPath(tail, c.fur, style = Stroke(7f, cap = StrokeCap.Round))
                dot(c.tip, -18f, -1f, 4f)
                translate(-20f, -26f) { rotate(-14f, Offset.Zero) { sunnyHead(c, t, Mood.CLOSED, hat, look) } }
            }
            else -> {
                val sitting = pose == Pose.SIT
                val headY = if (sitting) -55f else -66f
                val shoulderY = if (sitting) -30f else -38f
                // The tail, behind, swaying.
                rotate(swing(t, 40, 0.1f) * 9f, Offset(13f, -12f)) {
                    val tail = Path().apply {
                        moveTo(12f, -11f)
                        cubicTo(30f, -8f, 36f, -28f, 28f, -42f)
                    }
                    drawPath(tail, c.shade, style = Stroke(7.5f, cap = StrokeCap.Round))
                    drawPath(tail, c.fur, style = Stroke(5.5f, cap = StrokeCap.Round))
                    dot(c.tip, 28f, -42f, 4f)
                }
                if (sitting) {
                    oval(c.shade, 0f, -21f, 22f, 21f)
                    oval(c.fur, -1f, -22f, 20.5f, 19.5f)
                    oval(c.cream, 0f, -18f, 12f, 12.5f)
                } else {
                    // Feet under the body, a little apart; a jump tucks them in.
                    val spread = if (hop > 2f) 7f else 9f
                    oval(c.creamShade, -spread, -3.5f, 8f, 5f)
                    oval(c.creamShade, spread, -3.5f, 8f, 5f)
                    oval(c.shade, 0f, -27f, 20f, 25f)
                    oval(c.fur, -1f, -28f, 18.5f, 23.5f)
                    oval(c.cream, 0f, -22f, 11f, 14f)
                    oval(c.cream, -spread, -4.5f, 7.5f, 4f)
                    oval(c.cream, spread, -4.5f, 7.5f, 4f)
                }
                oval(c.light.copy(alpha = 0.35f), -9f, shoulderY + 2f, 4f, 7f)
                prop?.invoke(this)
                val (left, right) = armAngles(pose, t)
                // Arms raised up beside the head are drawn after it, so they show.
                if (left >= RAISED) sunnyArm(c, -14f, shoulderY, left, c.cream)
                if (right >= RAISED) sunnyArm(c, 14f, shoulderY, right, c.tip)
                if (sitting) {
                    // Hind paws poking out in front.
                    oval(c.creamShade, -10f, -3f, 8f, 4.5f)
                    oval(c.creamShade, 10f, -3f, 8f, 4.5f)
                    oval(c.cream, -10f, -4f, 7f, 3.5f)
                    oval(c.cream, 10f, -4f, 7f, 3.5f)
                }
                val tilt = when (pose) {
                    Pose.CHEER -> swing(t, 120) * 4f
                    Pose.POINT -> -6f
                    else -> swing(t, 16, 0.3f) * 3f
                }
                val face = when {
                    mood != Mood.OPEN -> mood
                    pose == Pose.CHEER -> Mood.HAPPY
                    else -> mood
                }
                translate(0f, headY) { rotate(tilt, Offset(0f, 18f)) { sunnyHead(c, t, face, hat, look, open = pose == Pose.CHEER) } }
                val reach = if (pose == Pose.POINT) 22f else 17f
                if (left < RAISED) sunnyArm(c, -14f, shoulderY, left, c.cream, reach)
                if (right < RAISED) sunnyArm(c, 14f, shoulderY, right, c.tip, reach)
            }
        }
    }
}

private class SunnyColors(g: SceneGrade) {
    val fur = g(0xFFF4A04C)
    val shade = g(0xFFD8782E)
    val light = g(0xFFFFC98A)
    val stripe = g(0xFFD0702A)
    val cream = g(0xFFFFEBD0)
    val creamShade = g(0xFFEBCDA6)
    val tip = g(0xFFFFFFFF)
    val pink = g(0xFFF58FA0)
    val inner = g(0xFFF7B2B9)
}

/** The arm angles (degrees, 0 to the right, 90 down) for [pose]: left arm, right arm. */
private fun armAngles(pose: Pose, t: Float): Pair<Float, Float> = when (pose) {
    Pose.WAVE -> 112f to -40f + swing(t, 110) * 18f
    Pose.CHEER -> -145f + swing(t, 120) * 6f to -35f - swing(t, 120) * 6f
    Pose.SIT -> 84f to 96f
    Pose.POINT -> 110f to -18f
    Pose.HOLD -> 58f to 122f
    else -> 106f to 74f
}

/** Arms pointing higher than this (degrees, -90 is straight up) are raised beside the head. */
private const val RAISED = -10f

private fun DrawScope.sunnyArm(c: SunnyColors, sx: Float, sy: Float, degrees: Float, hand: Color, length: Float = 14f) {
    val a = degrees * TAU / 360f
    val hx = sx + cos(a) * length
    val hy = sy + sin(a) * length
    stick(c.shade, sx, sy, hx, hy, 9f)
    stick(c.fur, sx, sy, hx, hy, 7.5f)
    dot(c.creamShade, hx, hy + 0.6f, 4.8f)
    dot(hand, hx, hy, 4.4f)
}

/** Sunny's head, centered on (0, 0): big round eyes, tufted ears, whiskers, a striped forehead. */
private fun DrawScope.sunnyHead(c: SunnyColors, t: Float, mood: Mood, hat: Hat, look: Offset, open: Boolean = false) {
    // Ears, twitching now and then.
    val twitch = if (drift(t, 30, 0.2f) < 0.03f) 8f else 0f
    rotate(-twitch, Offset(-14f, -14f)) { ear(c, -1f) }
    ear(c, 1f)
    oval(c.shade, 0f, 1.5f, 28.5f, 25f)
    oval(c.fur, -1f, 0f, 27f, 23.5f)
    stick(c.stripe, 0f, -22f, 0f, -16f, 3f)
    stick(c.stripe, -7.5f, -20.5f, -6f, -15.5f, 2.6f)
    stick(c.stripe, 7.5f, -20.5f, 6f, -15.5f, 2.6f)
    oval(Color.White.copy(alpha = 0.35f), -11f, -13f, 7f, 3f)
    // Muzzle and chin.
    oval(c.cream, -6.5f, 10.5f, 8.5f, 6.5f)
    oval(c.cream, 6.5f, 10.5f, 8.5f, 6.5f)
    oval(c.cream, 0f, 14f, 6f, 4f)
    oval(c.pink.copy(alpha = 0.45f), -18.5f, 6.5f, 4.5f, 2.6f)
    oval(c.pink.copy(alpha = 0.45f), 18.5f, 6.5f, 4.5f, 2.6f)
    eyes(mood, t, -10.5f, 10.5f, -1f, 5.2f, 6.6f, look, 0.37f)
    oval(c.pink, 0f, 6f, 3.4f, 2.4f)
    oval(Color.White.copy(alpha = 0.6f), -0.8f, 5.2f, 1.2f, 0.7f)
    if (open || mood == Mood.WIDE) {
        oval(Color(0xFF8A3A4A), 0f, 11.5f, 3.4f, if (open) 3.4f else 2.2f)
        if (open) oval(c.pink, 0f, 13.5f, 2.2f, 1.3f)
    } else {
        val mouth = Path().apply {
            moveTo(-4.5f, 9.5f)
            quadraticTo(-2.2f, 12.6f, 0f, 10f)
            quadraticTo(2.2f, 12.6f, 4.5f, 9.5f)
        }
        drawPath(mouth, Ink, style = Stroke(1.4f, cap = StrokeCap.Round))
    }
    val whisker = c.shade.copy(alpha = 0.8f)
    for (s in floatArrayOf(-1f, 1f)) {
        stick(whisker, s * 15f, 9f, s * 29f, 6f, 0.9f)
        stick(whisker, s * 15f, 12f, s * 28f, 14.5f, 0.9f)
    }
    hat(hat, 0f, 0f, 1f)
}

private fun DrawScope.ear(c: SunnyColors, side: Float) {
    val outer = Path().apply {
        moveTo(side * 26f, -5f)
        quadraticTo(side * 29f, -30f, side * 22f, -36f)
        quadraticTo(side * 13f, -31f, side * 5f, -21f)
        close()
    }
    val inner = Path().apply {
        moveTo(side * 21.5f, -11f)
        quadraticTo(side * 24f, -27f, side * 20.5f, -30f)
        quadraticTo(side * 14f, -26f, side * 10f, -20f)
        close()
    }
    drawPath(outer, c.shade)
    drawPath(inner, c.inner)
}

/**
 * Mo, a round, velvety gray-brown mole with a pink nose, little round glasses and big pink digging paws, standing at
 * ([x], [ground]) [height] tall. See [sunny] for the shared parameters. With [Pose.PEEK] Mo is in a hole at
 * ([x], [ground]) edged with [soil], [rise] of the way out (0 under the ground, 1 out to the waist). With [shovel]
 * Mo holds a little shovel in the right paw.
 */
internal fun DrawScope.mo(
    x: Float,
    ground: Float,
    height: Float,
    g: SceneGrade,
    t: Float,
    pose: Pose = Pose.STAND,
    mood: Mood = Mood.OPEN,
    hat: Hat = Hat.NONE,
    flip: Boolean = false,
    hop: Float = 0f,
    look: Offset = Offset.Zero,
    shovel: Boolean = false,
    rise: Float = 1f,
    soil: Color = Color(0xFFD9B77E),
    prop: (DrawScope.() -> Unit)? = null,
) = place(x, ground, height, flip) {
    val c = MoColors(g)
    when (pose) {
        Pose.PEEK -> {
            // The hole, Mo rising out of it (clipped at the rim), then the rim of thrown-up soil in front.
            oval(darker(soil, 0.55f), 0f, 0f, 30f, 8f)
            val sink = 50f * (1f - rise.coerceIn(0f, 1f)) + 34f
            clipRect(-80f, -200f, 80f, 1.5f) {
                translate(0f, sink) { moBody(c, t, Pose.STAND, mood, hat, look, shovel = false, peek = true) }
            }
            clipRect(-80f, 0.5f, 80f, 40f) {
                oval(darker(soil, 0.85f), 0f, 1.5f, 33f, 9f)
                oval(soil, 0f, 0.5f, 32f, 8f)
            }
            dot(soil, -31f, 1f, 6f)
            dot(soil, 31f, 1f, 6.5f)
            dot(darker(soil, 0.92f), -38f, 3f, 3.5f)
            dot(darker(soil, 0.92f), 39f, 2.5f, 3f)
            // Paws on the rim once Mo is out.
            if (rise > 0.55f) {
                moPaw(c, -22f, -1f, -110f)
                moPaw(c, 22f, -1f, -70f)
            }
        }
        else -> {
            if (pose != Pose.SLEEP) shadow(21f, hop)
            translate(0f, -hop - idleBob(pose, t, 0.4f)) { moBody(c, t, pose, mood, hat, look, shovel, peek = false, prop = prop) }
        }
    }
}

private class MoColors(g: SceneGrade) {
    val fur = g(0xFF5E4F4B)
    val shade = g(0xFF433733)
    val light = g(0xFF8A7972)
    val belly = g(0xFF7A6A64)
    val pink = g(0xFFF6A2AE)
    val pinkShade = g(0xFFD97B8C)
    val nose = g(0xFFFF7F96)
    val rim = g(0xFFF0C46A)
}

private fun DrawScope.moBody(
    c: MoColors,
    t: Float,
    pose: Pose,
    mood: Mood,
    hat: Hat,
    look: Offset,
    shovel: Boolean,
    peek: Boolean,
    prop: (DrawScope.() -> Unit)? = null,
) {
    if (pose == Pose.SLEEP) {
        oval(c.shade, 0f, -15f, 33f, 15.5f)
        oval(c.fur, -1f, -16f, 31f, 14f)
        oval(c.light.copy(alpha = 0.45f), -8f, -24f, 14f, 3f)
        oval(c.pink, -26f, -3f, 7f, 3.5f)
        prop?.invoke(this)
        translate(20f, -24f) { rotate(12f, Offset.Zero) { moFace(c, t, Mood.CLOSED, hat, look, crown = false) } }
        return
    }
    val sitting = pose == Pose.SIT
    val top = if (sitting) -62f else -78f
    val faceY = if (sitting) -38f else -52f
    if (!sitting && !peek) {
        oval(c.pinkShade, -11f, -3f, 9f, 4.5f)
        oval(c.pinkShade, 11f, -3f, 9f, 4.5f)
        oval(c.pink, -11f, -4f, 8f, 3.5f)
        oval(c.pink, 11f, -4f, 8f, 3.5f)
    }
    if (sitting) {
        oval(c.shade, 0f, -31f, 29f, 31f)
        oval(c.fur, -1.5f, -32f, 27f, 29.5f)
        oval(c.belly, 0f, -18f, 16f, 14f)
    } else {
        oval(c.shade, 0f, -40f, 27f, 38f)
        oval(c.fur, -1.5f, -41f, 25f, 36.5f)
        oval(c.belly, 0f, -24f, 15f, 16f)
    }
    // A velvety sheen on the upper left.
    oval(c.light.copy(alpha = 0.45f), -11f, top + 22f, 7f, 12f)
    oval(Color.White.copy(alpha = 0.18f), -12f, top + 16f, 3.5f, 6f)
    // A little tuft on top.
    stick(c.shade, -2f, top + 1f, -5f, top - 5f, 2f)
    stick(c.shade, 0.5f, top, 0.5f, top - 7f, 2f)
    stick(c.shade, 3f, top + 1f, 6f, top - 4.5f, 2f)
    prop?.invoke(this)
    val shoulderY = if (sitting) -26f else -36f
    val (left, right) = when (pose) {
        Pose.WAVE -> 118f to -58f + swing(t, 110, 0.3f) * 20f
        Pose.CHEER -> -125f + swing(t, 120, 0.2f) * 8f to -55f - swing(t, 120, 0.2f) * 8f
        Pose.SIT -> 70f to 110f
        Pose.POINT -> 118f to -40f
        Pose.HOLD -> 50f to 130f
        else -> if (shovel) 122f to 80f else 122f to 58f
    }
    if (sitting) {
        oval(c.pinkShade, -13f, -3f, 9.5f, 5f)
        oval(c.pinkShade, 13f, -3f, 9.5f, 5f)
        oval(c.pink, -13f, -4f, 8.5f, 4f)
        oval(c.pink, 13f, -4f, 8.5f, 4f)
    }
    translate(0f, faceY) { moFace(c, t, if (pose == Pose.CHEER && mood == Mood.OPEN) Mood.HAPPY else mood, Hat.NONE, look, open = pose == Pose.CHEER) }
    if (!peek) {
        moArm(c, -21f, shoulderY, left, 12f)
        if (shovel) shovelIn(c, 21f, shoulderY, right)
        moArm(c, 21f, shoulderY, right, 12f)
    }
    hat(hat, 0f, top + 22f, 1.08f)
}

private fun DrawScope.moArm(c: MoColors, sx: Float, sy: Float, degrees: Float, length: Float) {
    val a = degrees * TAU / 360f
    val hx = sx + cos(a) * length
    val hy = sy + sin(a) * length
    stick(c.shade, sx, sy, hx, hy, 10f)
    stick(c.fur, sx, sy, hx, hy, 8f)
    moPaw(c, hx, hy, degrees)
}

/** A big pink digging paw at ([x], [y]), its claws pointing at [degrees]. */
private fun DrawScope.moPaw(c: MoColors, x: Float, y: Float, degrees: Float) {
    translate(x, y) {
        rotate(degrees, Offset.Zero) {
            oval(c.pinkShade, 1f, 0.8f, 8.5f, 7.5f)
            oval(c.pink, 0.5f, 0f, 8f, 7f)
            for (k in -1..2) {
                val fy = -5.5f + k * 3.7f + 1.8f
                oval(c.pinkShade, 8.4f, fy + 0.4f, 3.4f, 2f)
                oval(c.pink, 8f, fy, 3.2f, 1.8f)
            }
            oval(Color.White.copy(alpha = 0.4f), -1.5f, -3f, 3f, 1.6f)
        }
    }
}

private fun DrawScope.shovelIn(c: MoColors, sx: Float, sy: Float, degrees: Float) {
    val a = degrees * TAU / 360f
    val hx = sx + cos(a) * 12f
    val hy = sy + sin(a) * 12f
    stick(Color(0xFF9A6A3C), hx - 4f, hy - 20f, hx + 5f, hy + 16f, 3f)
    box(Color(0xFF9A6A3C), hx - 8f, hy - 24f, hx, hy - 20f, 2f)
    val blade = Path().apply {
        moveTo(hx + 0f, hy + 14f)
        lineTo(hx + 11f, hy + 12f)
        quadraticTo(hx + 12f, hy + 26f, hx + 7f, hy + 30f)
        quadraticTo(hx + 0f, hy + 26f, hx + 0f, hy + 14f)
        close()
    }
    drawPath(blade, Color(0xFF3FA7D6))
    oval(Color.White.copy(alpha = 0.4f), hx + 4f, hy + 18f, 2f, 3.5f)
}

/** Mo's face, centered on the snout's root: glasses over small bright eyes, a big pink nose, a shy smile. */
private fun DrawScope.moFace(c: MoColors, t: Float, mood: Mood, hat: Hat, look: Offset, open: Boolean = false, crown: Boolean = true) {
    if (!crown) {
        // Asleep on its side: draw the head's round end so the face sits on something.
        oval(c.fur, 0f, -2f, 14f, 13f)
    }
    oval(c.pink.copy(alpha = 0.4f), -16f, 3.5f, 4.2f, 2.4f)
    oval(c.pink.copy(alpha = 0.4f), 16f, 3.5f, 4.2f, 2.4f)
    eyes(mood, t + 0.37f, -8.5f, 8.5f, -6f, 3.4f, 3.8f, look, 0.42f, glint = 1.4f)
    // Little round glasses.
    val glass = Stroke(1.6f)
    for (s in floatArrayOf(-8.5f, 8.5f)) {
        drawCircle(Color.White.copy(alpha = 0.14f), 7.2f, Offset(s, -6f))
        drawCircle(c.rim, 7.2f, Offset(s, -6f), style = glass)
    }
    stick(c.rim, -1.6f, -7f, 1.6f, -7f, 1.6f)
    oval(Color.White.copy(alpha = 0.55f), -11f, -9.5f, 1.8f, 1.1f)
    oval(Color.White.copy(alpha = 0.55f), 6f, -9.5f, 1.8f, 1.1f)
    // Snout and nose.
    oval(c.pinkShade, 0f, 5f, 7f, 5f)
    oval(c.pink, 0f, 4.4f, 6.5f, 4.4f)
    oval(c.nose, 0f, 2f, 4.4f, 3.2f)
    oval(Color.White.copy(alpha = 0.6f), -1.4f, 1f, 1.5f, 0.9f)
    for (s in floatArrayOf(-1f, 1f)) {
        dot(c.light, s * 9f, 4f, 0.7f)
        dot(c.light, s * 10.5f, 6.5f, 0.7f)
        dot(c.light, s * 8.5f, 8.5f, 0.7f)
    }
    if (open) {
        oval(Color(0xFF8A3A4A), 0f, 11.5f, 3f, 2.8f)
    } else {
        val smile = Path().apply {
            moveTo(-3.2f, 10.2f)
            quadraticTo(0f, 13f, 3.2f, 10.2f)
        }
        drawPath(smile, Ink, style = Stroke(1.3f, cap = StrokeCap.Round))
    }
    hat(hat, 0f, -18f, 1f)
}

/**
 * A pair of eyes at [lx] and [rx] on height [y], [w] x [h] each: open (blinking now and then, the blink keyed to
 * [blinkPhase]), happy arcs, closed sleepy arcs or wide.
 */
private fun DrawScope.eyes(
    mood: Mood,
    t: Float,
    lx: Float,
    rx: Float,
    y: Float,
    w: Float,
    h: Float,
    look: Offset,
    blinkPhase: Float,
    glint: Float = 2.2f,
) {
    val blinking = mood == Mood.OPEN && drift(t, 34, blinkPhase) < 0.025f
    for (cx in floatArrayOf(lx, rx)) {
        when {
            mood == Mood.HAPPY -> {
                val arc = Path().apply {
                    moveTo(cx - w, y + h * 0.3f)
                    quadraticTo(cx, y - h * 1.1f, cx + w, y + h * 0.3f)
                }
                drawPath(arc, Ink, style = Stroke(w * 0.42f, cap = StrokeCap.Round))
            }
            mood == Mood.CLOSED || blinking -> {
                val arc = Path().apply {
                    moveTo(cx - w, y)
                    quadraticTo(cx, y + h * 0.8f, cx + w, y)
                }
                drawPath(arc, Ink, style = Stroke(w * 0.38f, cap = StrokeCap.Round))
            }
            else -> {
                val s = if (mood == Mood.WIDE) 1.18f else 1f
                val ex = cx + look.x
                val ey = y + look.y
                oval(Ink, ex, ey, w * s, h * s)
                dot(Color.White, ex - w * 0.32f, ey - h * 0.36f, glint * s)
                dot(Color.White.copy(alpha = 0.85f), ex + w * 0.36f, ey + h * 0.36f, glint * 0.45f * s)
            }
        }
    }
}

/** [hat] on a head whose crown is around ([cx], [cy]), [s] times the kitten's size. */
private fun DrawScope.hat(hat: Hat, cx: Float, cy: Float, s: Float) {
    when (hat) {
        Hat.NONE -> Unit
        Hat.HARD_HAT -> translate(cx, cy) {
            scale(s, s, Offset.Zero) {
                val dome = Path().apply {
                    moveTo(-22f, -13f)
                    cubicTo(-23f, -40f, 23f, -40f, 22f, -13f)
                    close()
                }
                drawPath(dome, Color(0xFFE0A21C))
                translate(-1f, -1f) { drawPath(dome, Color(0xFFFFC93A)) }
                stick(Color(0xFFFFE07A), 0f, -32f, 0f, -15f, 4f)
                box(Color(0xFFD08E12), -29f, -15f, 29f, -9f, 3f)
                box(Color(0xFFF2B526), -29f, -16f, 29f, -11f, 3f)
                oval(Color.White.copy(alpha = 0.45f), -10f, -27f, 5f, 2.5f)
            }
        }
        Hat.SPACE_HELMET -> translate(cx, cy) {
            scale(s, s, Offset.Zero) {
                drawCircle(Color(0x33DFF3FF), 36f, Offset(0f, 2f))
                drawCircle(Color.White.copy(alpha = 0.85f), 36f, Offset(0f, 2f), style = Stroke(2.4f))
                rotate(-35f, Offset(-17f, -17f)) { oval(Color.White.copy(alpha = 0.6f), -17f, -17f, 9f, 3.2f) }
                dot(Color.White.copy(alpha = 0.6f), 22f, -16f, 2f)
                box(Color(0xFFC9D0DA), -20f, 33f, 20f, 40f, 3.5f)
                box(Color(0xFFE9EDF2), -20f, 33f, 20f, 37f, 3.5f)
            }
        }
    }
}

/** A gentle breathing bob while standing or sitting, in units. */
private fun idleBob(pose: Pose, t: Float, phase: Float): Float =
    if (pose == Pose.SLEEP || pose == Pose.CHEER) 0f else (0.5f + 0.5f * swing(t, 45, phase)) * 1.6f

/** The soft contact shadow under a character [width] wide, shrinking as it [hop]s up. */
private fun DrawScope.shadow(width: Float, hop: Float) {
    val k = (1f - hop / 60f).coerceIn(0.4f, 1f)
    oval(Color.Black.copy(alpha = 0.18f * k), 0f, 0f, width * k, 3.6f * k)
}

/** [color] darkened to [k] of its brightness. */
internal fun darker(color: Color, k: Float) = Color(color.red * k, color.green * k, color.blue * k, color.alpha)

/** Runs [art] in a character's 100-unit box, standing at ([x], [ground]) and [height] tall, mirrored with [flip]. */
private inline fun DrawScope.place(x: Float, ground: Float, height: Float, flip: Boolean, art: DrawScope.() -> Unit) {
    val s = height / 100f
    translate(x, ground) { scale(if (flip) -s else s, s, Offset.Zero) { art() } }
}
