package io.colorsand

import androidx.compose.ui.ExperimentalComposeUiApi
import androidx.compose.ui.window.ComposeViewport
import io.colorsand.ui.App
import io.colorsand.ui.InMemoryProgressStore
import io.colorsand.ui.ProgressStore
import kotlinx.browser.document
import kotlinx.browser.localStorage
import org.jetbrains.skiko.wasm.onWasmReady

/** Progress in the browser's localStorage, falling back to memory where storage is blocked. */
private object BrowserProgressStore : ProgressStore {
    private const val KEY = "colorsand.level"
    private const val PALETTE_KEY = "colorsand.palette"
    private const val CUSTOM_KEY = "colorsand.customColors"
    private const val PAW_KEY = "colorsand.paw"
    private const val STARS_KEY = "colorsand.stars"
    private const val KEEPSAKE_STARS_KEY = "colorsand.keepsakeStars"
    private const val STORY_KEY = "colorsand.story"
    private const val SOUND_KEY = "colorsand.sound"
    private const val HAPTICS_KEY = "colorsand.haptics"
    private val fallback = InMemoryProgressStore()

    override var level: Int
        get() = runCatching { localStorage.getItem(KEY)?.toIntOrNull() }.getOrNull() ?: fallback.level
        set(value) {
            fallback.level = value
            runCatching { localStorage.setItem(KEY, value.toString()) }
        }

    override var palette: String
        get() = runCatching { localStorage.getItem(PALETTE_KEY) }.getOrNull() ?: fallback.palette
        set(value) {
            fallback.palette = value
            runCatching { localStorage.setItem(PALETTE_KEY, value) }
        }

    override var customColors: String
        get() = runCatching { localStorage.getItem(CUSTOM_KEY) }.getOrNull() ?: fallback.customColors
        set(value) {
            fallback.customColors = value
            runCatching { localStorage.setItem(CUSTOM_KEY, value) }
        }

    override var paw: String
        get() = runCatching { localStorage.getItem(PAW_KEY) }.getOrNull() ?: fallback.paw
        set(value) {
            fallback.paw = value
            runCatching { localStorage.setItem(PAW_KEY, value) }
        }

    override var stars: String
        get() = runCatching { localStorage.getItem(STARS_KEY) }.getOrNull() ?: fallback.stars
        set(value) {
            fallback.stars = value
            runCatching { localStorage.setItem(STARS_KEY, value) }
        }

    override var keepsakeStars: String
        get() = runCatching { localStorage.getItem(KEEPSAKE_STARS_KEY) }.getOrNull() ?: fallback.keepsakeStars
        set(value) {
            fallback.keepsakeStars = value
            runCatching { localStorage.setItem(KEEPSAKE_STARS_KEY, value) }
        }

    override var story: String
        get() = runCatching { localStorage.getItem(STORY_KEY) }.getOrNull() ?: fallback.story
        set(value) {
            fallback.story = value
            runCatching { localStorage.setItem(STORY_KEY, value) }
        }

    override var sound: Boolean
        get() = runCatching { localStorage.getItem(SOUND_KEY)?.toBooleanStrictOrNull() }.getOrNull() ?: fallback.sound
        set(value) {
            fallback.sound = value
            runCatching { localStorage.setItem(SOUND_KEY, value.toString()) }
        }

    override var haptics: Boolean
        get() = runCatching { localStorage.getItem(HAPTICS_KEY)?.toBooleanStrictOrNull() }.getOrNull() ?: fallback.haptics
        set(value) {
            fallback.haptics = value
            runCatching { localStorage.setItem(HAPTICS_KEY, value.toString()) }
        }
}

@OptIn(ExperimentalComposeUiApi::class)
fun main() {
    onWasmReady {
        val root = document.getElementById("root") ?: document.body!!
        root.innerHTML = ""
        ComposeViewport(root) { App(BrowserProgressStore) }
    }
}
