package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** What catches the grains: a see-through beach bucket, a camel's netted saddle bag, or a glass jar. */
internal enum class Catcher(val noun: String) { BUCKET("bucket"), SADDLE_BAG("saddle bag"), JAR("jar") }

/** The scenery behind the falling sand: a beach with the sea, desert dunes with sand blowing off a crest, or Mars. */
internal enum class CatchScene { BEACH, DESERT, MARS }

/**
 * The look of Catch the grains in one arena: the [scene] behind it, its sky ([skyTop] to [skyBottom]), the [far]
 * band (the sea, far dunes, red hills) and its [farLight] edge, the sand underfoot ([groundLight], [ground],
 * [groundShade]), the [catcher] and its colors ([body], [bodyLight], [bodyDark], [accent]), the keepsake standing
 * by ([arena]'s [stage]) and what the line under the game says ([start], [full]).
 */
internal class CatchLook(
    val arena: Arena,
    val stage: Int,
    val scene: CatchScene,
    val skyTop: Color,
    val skyBottom: Color,
    val far: Color,
    val farLight: Color,
    val groundLight: Color,
    val ground: Color,
    val groundShade: Color,
    val catcher: Catcher,
    val body: Color,
    val bodyLight: Color,
    val bodyDark: Color,
    val accent: Color,
    val start: String,
    val full: String,
) {
    companion object {
        /** [arena]'s look, its colors through [g]. Arenas without a Catch the grains get the Beach's. */
        fun of(arena: Arena, g: SceneGrade): CatchLook = when (arena) {
            Arena.DESERT -> CatchLook(
                Arena.DESERT, 3, CatchScene.DESERT,
                g(0xFFFFD9A8), g(0xFFFFF0D2), g(0xFFE9B572), g(0xFFF7D29A),
                g(0xFFF8DDA6), g(0xFFEBC07E), g(0xFFC9955A),
                Catcher.SADDLE_BAG, g(0xFFB3322E), g(0xFFD9524A), g(0xFF6E3A1E), g(0xFFF2C14A),
                "Slide the saddle bag under the sand!",
                "The saddle bag is full!",
            )
            Arena.MARS -> CatchLook(
                Arena.MARS, 3, CatchScene.MARS,
                g(0xFF3A1F3D), g(0xFFC9714E), g(0xFFA9512F), g(0xFFD27145),
                g(0xFFEA9A6C), g(0xFFD27145), g(0xFF9C4A2A),
                Catcher.JAR, g(0xFFDDEFF6), g(0xFFFFFFFF), g(0xFF8FA6B4), g(0xFFB9C2CC),
                "Catch the floating dust in the jar!",
                "The jar is full of red dust!",
            )
            else -> CatchLook(
                Arena.BEACH, 4, CatchScene.BEACH,
                g(0xFF7FCBF2), g(0xFFDDF3FC), g(0xFF2FA8D0), g(0xFFBFF0F5),
                g(0xFFFFF5DC), g(0xFFF3DFB2), g(0xFFD8BC86),
                Catcher.BUCKET, g(0xFF2F8FE0), g(0xFF7FC4FF), g(0xFF1D5FA8), g(0xFFFFD04A),
                "Drag the bucket to catch the sand!",
                "The bucket is full!",
            )
        }
    }
}

/**
 * Where Catch the grains sits in a [width] x [height] canvas, in pixels: the [field] the round's 0 to 1
 * coordinates map onto, and a [unit] for sizes (a hundredth of its smaller side).
 */
internal class CatchLayout(width: Float, height: Float) {
    val field: Rect = Rect(0f, 0f, width, height)
    val unit: Float = minOf(width, height) / 100f

    fun x(x: Float): Float = field.left + x * field.width
    fun y(y: Float): Float = field.top + y * field.height
    fun at(x: Float, y: Float): Offset = Offset(x(x), y(y))

    /** The field's 0 to 1 across at pixel [px]. */
    fun fieldX(px: Float): Float = (px - field.left) / field.width

    /** The container standing with its middle at [bin]: mouth on top, base on the ground. */
    fun container(bin: Float): Rect = Rect(
        x(bin - GrainCatch.HALF_WIDTH),
        y(GrainCatch.MOUTH),
        x(bin + GrainCatch.HALF_WIDTH),
        y(GrainCatch.GROUND),
    )
}
