// The Building Site's machines and Mars's explorers, in the order they are earned. See KeepsakeArt.kt for the box.

internal fun DrawScope.siteKeepsake(stage: Int, t: Float, g: SceneGrade) = when (stage) {
    1 -> trafficCone(g)
    2 -> wheelbarrow(t, g)
    3 -> worker(t, g)
    4 -> cementMixer(t, g)
    else -> excavator(t, g)
}

internal fun DrawScope.marsKeepsake(stage: Int, t: Float, g: SceneGrade) = when (stage) {
    1 -> pawFlag(t, g)
    2 -> alien(t, g)
    3 -> astronaut(t, g)
    4 -> rover(t, g)
    else -> rocket(t, g)
}

/** An orange traffic cone with white reflective bands. */
private fun DrawScope.trafficCone(g: SceneGrade) {
    groundShadow(50f, 52f)
    box(g(0xFFD9561A), 24f, 88f, 76f, 95f, 2.5f)
    drawPath(cone, g(0xFFFF7A1A))
    clipPath(cone) {
        box(g(0xFFF7F4EE), 0f, 38f, 100f, 48f)
        box(g(0xFFF7F4EE), 0f, 62f, 100f, 72f)
        drawPath(coneShade, Color.Black.copy(alpha = 0.16f))
        box(Color.White.copy(alpha = 0.35f), 41f, 20f, 44f, 88f)
    }
}

private val cone = Path().apply {
    moveTo(45f, 18f)
    quadraticBezierTo(50f, 14f, 55f, 18f)
    lineTo(70f, 89f)
    lineTo(30f, 89f)
    close()
}
private val coneShade = polygon(53f, 14f, 60f, 14f, 76f, 92f, 58f, 92f)

/** A green wheelbarrow heaped with building sand. */
private fun DrawScope.wheelbarrow(t: Float, g: SceneGrade) {
    groundShadow(50f, 76f)
    val frame = g(0xFF55606E)
    stick(frame, 32f, 74f, 30f, 94f, 2.5f)
    stick(frame, 28f, 66f, 6f, 58f, 3f)
    stick(frame, 34f, 72f, 78f, 82f, 2.5f)
    oval(g(0xFFB9A88A), 48f, 54f, 27f, 9f)
    oval(g(0xFFD3C3A2), 46f, 52f, 22f, 6.5f)
    for (k in 0..3) dot(g(0xFF8E8676), 34f + k * 9f, 53f + (k % 2) * 2f, 1.3f)
    drawPath(tray, g(0xFF23804A))
    drawPath(trayLit, g(0xFF2F9E5A))
    box(g(0xFF46B873), 18f, 54f, 80f, 57f, 1.5f)
    dot(g(0xFF2E333B), 79f, 83f, 11f)
    dot(g(0xFF9AA3AE), 79f, 83f, 4.5f)
    rotate(t * 360f * 30f, Offset(79f, 83f)) { stick(g(0xFF5A626C), 75f, 83f, 83f, 83f, 1.2f) }
    stick(g(0xFF2E333B), 4f, 57f, 9f, 59f, 4f)
}

private val tray = polygon(18f, 55f, 80f, 55f, 70f, 78f, 30f, 78f)
private val trayLit = polygon(20f, 57f, 64f, 57f, 58f, 74f, 30f, 74f)

/** A builder in a yellow hard hat and hi-vis vest, waving hello. */
private fun DrawScope.worker(t: Float, g: SceneGrade) {
    groundShadow(50f, 40f)
    val skin = g(0xFFE6B48A)
    val shirt = g(0xFF4E7FC0)
    box(g(0xFF3B3F46), 38f, 90f, 49f, 96f, 2f)
    box(g(0xFF3B3F46), 51f, 90f, 62f, 96f, 2f)
    box(g(0xFF2F4F86), 40f, 66f, 49.5f, 92f, 2f)
    box(g(0xFF3B5C99), 50.5f, 66f, 60f, 92f, 2f)
    arm(39f, 46f, 20f, 100f, 6.5f, shirt, skin)
    arm(61f, 46f, 18f, -60f + swing(t, 50) * 22f, 6.5f, shirt, skin)
    box(shirt, 37f, 40f, 63f, 70f, 7f)
    box(g(0xFFFF8A1F), 38f, 41f, 62f, 70f, 6f)
    box(g(0xFF4E7FC0), 47f, 41f, 53f, 54f)
    box(g(0xFFF2F2C8), 38f, 59f, 62f, 63f)
    box(g(0xFFF2F2C8), 41f, 41f, 44f, 70f)
    box(g(0xFFF2F2C8), 56f, 41f, 59f, 70f)
    dot(skin, 50f, 30f, 9.5f)
    eye(46.5f, 30f, 1.4f)
    eye(53.5f, 30f, 1.4f)
    drawArc(g(0xFF7A3E2A), 20f, 140f, false, Offset(46f, 31f), Size(8f, 5f), style = Stroke(1.2f))
    drawArc(g(0xFFE0A91C), 180f, 180f, true, Offset(39f, 14f), Size(22f, 20f))
    drawArc(g(0xFFFFCB2E), 180f, 180f, true, Offset(40f, 15f), Size(19f, 17f))
    box(g(0xFFE0A91C), 36f, 22.5f, 64f, 26f, 1.7f)
    box(g(0xFFFFDE6A), 49f, 15f, 51f, 23f)
}

/** A cement mixer, its striped drum turning. */
private fun DrawScope.cementMixer(t: Float, g: SceneGrade) {
    groundShadow(52f, 66f)
    val frame = g(0xFF55606E)
    stick(frame, 40f, 66f, 32f, 94f, 3f)
    stick(frame, 62f, 66f, 66f, 86f, 3f)
    box(g(0xFF2F8A55), 22f, 64f, 46f, 80f, 3f)
    box(g(0xFF3BA566), 22f, 64f, 43f, 77f, 3f)
    dot(g(0xFF2E333B), 66f, 87f, 8f)
    dot(g(0xFF9AA3AE), 66f, 87f, 3f)
    rotate(-24f, Offset(52f, 50f)) {
        oval(g(0xFF6A2E10), 75f, 50f, 5f, 10f)
        clipPath(drum) {
            drawPath(drum, g(0xFFFF8C2A))
            // Stripes sliding across the drum make it turn.
            val shift = drift(t, 40) * 16f
            val blue = g(0xFF2F5FA8)
            for (k in -1..4) {
                val x = 24f + k * 16f + shift
                stick(blue, x, 34f, x + 10f, 68f, 4.5f)
            }
            box(Color.Black.copy(alpha = 0.15f), 0f, 58f, 100f, 70f)
            box(Color.White.copy(alpha = 0.3f), 30f, 38f, 70f, 41f, 1.5f)
        }
        oval(g(0xFF3A1A08), 75f, 50f, 3f, 7f)
    }
}

private val drum = Path().apply {
    moveTo(28f, 40f)
    quadraticBezierTo(30f, 34f, 46f, 34f)
    lineTo(66f, 38f)
    quadraticBezierTo(76f, 40f, 76f, 50f)
    quadraticBezierTo(76f, 60f, 66f, 62f)
    lineTo(46f, 66f)
    quadraticBezierTo(30f, 66f, 28f, 60f)
    close()
}

/** A yellow excavator on tracks, its arm dipping the bucket up and down. */
private fun DrawScope.excavator(t: Float, g: SceneGrade) {
    groundShadow(46f, 90f)
    val yellow = g(0xFFF5B92B)
    val yellowDark = g(0xFFD6961A)
    val dark = g(0xFF2E333B)
    box(dark, 8f, 80f, 64f, 95f, 7.5f)
    for (x in floatArrayOf(16f, 28f, 40f, 52f)) {
        dot(g(0xFF6B7380), x, 87.5f, 4.2f)
        dot(g(0xFF9AA3AE), x, 87.5f, 1.6f)
    }
    box(yellowDark, 10f, 60f, 56f, 81f, 4f)
    box(yellow, 10f, 60f, 54f, 78f, 4f)
    box(yellowDark, 8f, 62f, 18f, 78f, 3f)
    box(dark, 22f, 52f, 25f, 61f)
    box(yellowDark, 32f, 36f, 56f, 62f, 4f)
    box(yellow, 32f, 36f, 54f, 60f, 4f)
    box(g(0xFF9FD6F2), 36f, 40f, 51f, 54f, 2.5f)
    box(Color.White.copy(alpha = 0.45f), 38f, 42f, 42f, 52f, 2f)
    // Boom up to the elbow, then the stick down to the bucket, which swings with the dig.
    val dig = swing(t, 20) * 10f
    val elbowX = 76f
    val elbowY = 24f
    val a = (70f + dig) * TAU / 360f
    val bx = elbowX + cos(a) * 34f
    val by = elbowY + sin(a) * 34f
    stick(g(0xFF9AA3AE), 52f, 66f, 70f, 34f, 2f)
    stick(yellowDark, 52f, 62f, elbowX, elbowY, 8f)
    stick(yellow, 51f, 60f, elbowX - 1f, elbowY - 1f, 5f)
    stick(yellowDark, elbowX, elbowY, bx, by, 6f)
    stick(yellow, elbowX - 1f, elbowY, bx - 1f, by, 3.5f)
    dot(dark, elbowX, elbowY, 2.4f)
    translate(bx, by) {
        rotate(dig * 1.5f, Offset.Zero) {
            drawPath(bucket, dark)
            for (k in 0..2) stick(g(0xFF9AA3AE), -6f + k * 5f, 10f, -7f + k * 5f, 13f, 1.5f)
        }
    }
}

private val bucket = polygon(-4f, -3f, 6f, -2f, 6f, 6f, 3f, 10f, -9f, 11f, -8f, 4f)

/** A teal flag with a paw print, planted on a little red rock and rippling in the thin wind. */
private fun DrawScope.pawFlag(t: Float, g: SceneGrade) {
    groundShadow(36f, 34f)
    oval(g(0xFF9A3E22), 36f, 93f, 16f, 5f)
    oval(g(0xFFC0582E), 34f, 91.5f, 12f, 3.5f)
    stick(g(0xFFC9D0DA), 34f, 14f, 34f, 92f, 2.4f)
    dot(g(0xFFF2C14A), 34f, 12f, 2.6f)
    val teal = g(0xFF2BB3A3)
    val tealDark = g(0xFF1F8C80)
    // The cloth in narrow strips, each lifted by the wave passing along it.
    val strips = 8
    for (k in 0 until strips) {
        val x = 35f + k * 5f
        val w = swing(t, 60, -k * 0.07f) * (1f + k * 0.35f)
        val shade = if (swing(t, 60, -k * 0.07f + 0.25f) > 0f) teal else tealDark
        box(shade, x - 0.2f, 16f + w, x + 5.2f, 40f + w)
    }
    val mid = swing(t, 60, -0.28f) * 2.4f
    val paw = g(0xFFF8F6F0)
    oval(paw, 56f, 31f + mid, 5f, 4f)
    dot(paw, 50.5f, 25.5f + mid, 2f)
    dot(paw, 54.5f, 22.5f + mid, 2f)
    dot(paw, 58.5f, 22.5f + mid, 2f)
    dot(paw, 62f, 25.5f + mid, 2f)
}

/** A little green alien with antennae, hopping and blinking. */
private fun DrawScope.alien(t: Float, g: SceneGrade) {
    val hop = swing(t, 36).let { if (it > 0f) it * 4f else 0f }
    groundShadow(50f, 36f - hop)
    val green = g(0xFF7ED957)
    val dark = g(0xFF55B034)
    translate(0f, -hop) {
        oval(dark, 42f, 92f, 6f, 3.5f)
        oval(dark, 58f, 92f, 6f, 3.5f)
        oval(dark, 50f, 75f, 15f, 17f)
        oval(green, 49f, 74f, 13.5f, 15.5f)
        oval(g(0xFFB4F08E), 50f, 78f, 7f, 8f)
        oval(dark, 34f, 72f, 4f, 8f)
        oval(dark, 66f, 72f, 4f, 8f)
        val wob = swing(t, 50) * 3f
        stick(dark, 43f, 36f, 36f + wob, 18f, 2f)
        stick(dark, 57f, 36f, 64f + wob, 18f, 2f)
        dot(g(0xFFFF7FB0), 36f + wob, 17f, 3.4f)
        dot(g(0xFFFF7FB0), 64f + wob, 17f, 3.4f)
        oval(dark, 50f, 48f, 19f, 15f)
        oval(green, 49f, 47f, 18f, 14f)
        if (swing(t, 24) > 0.96f) {
            stick(g(0xFF26222B), 39f, 47f, 47f, 47f, 1.6f)
            stick(g(0xFF26222B), 53f, 47f, 61f, 47f, 1.6f)
        } else {
            oval(g(0xFF26222B), 43f, 46f, 5f, 6.5f)
            oval(g(0xFF26222B), 57f, 46f, 5f, 6.5f)
            dot(Color.White, 41.5f, 43.5f, 1.8f)
            dot(Color.White, 55.5f, 43.5f, 1.8f)
        }
        drawArc(g(0xFF2E6B1E), 20f, 140f, false, Offset(46f, 51f), Size(8f, 5f), style = Stroke(1.4f))
    }
}

/** An astronaut in a white suit and gold visor, waving. */
private fun DrawScope.astronaut(t: Float, g: SceneGrade) {
    groundShadow(50f, 44f)
    val suit = g(0xFFF4F6F8)
    val shade = g(0xFFC9D0DA)
    box(g(0xFFA8B1BE), 33f, 40f, 67f, 70f, 6f)
    box(shade, 38f, 68f, 49f, 92f, 4f)
    box(suit, 51f, 68f, 62f, 92f, 4f)
    box(g(0xFF8E97A4), 37f, 88f, 50f, 96f, 2.5f)
    box(g(0xFF8E97A4), 50f, 88f, 63f, 96f, 2.5f)
    arm(38f, 48f, 20f, 105f, 8f, shade, g(0xFFE0E4EA))
    arm(62f, 48f, 18f, -55f + swing(t, 44) * 22f, 8f, suit, g(0xFFE0E4EA))
    box(shade, 36f, 42f, 64f, 74f, 8f)
    box(suit, 36f, 42f, 62f, 72f, 8f)
    box(g(0xFFDDE2E8), 43f, 52f, 57f, 62f, 2f)
    dot(g(0xFFE8494E), 47f, 57f, 1.8f)
    dot(g(0xFF3E8EE0), 53f, 57f, 1.8f)
    box(g(0xFFFF8A1F), 36f, 66f, 62f, 68f)
    dot(shade, 50f, 30f, 15.5f)
    dot(suit, 49.5f, 29f, 14.5f)
    oval(g(0xFFB97A1E), 51f, 31f, 10.5f, 8.5f)
    oval(g(0xFFE8A93A), 51f, 30f, 9.5f, 7.5f)
    oval(Color.White.copy(alpha = 0.6f), 47f, 27f, 3.5f, 2f)
    val blink = 0.5f + 0.5f * swing(t, 60)
    dot(g(0xFFFF5A5A).copy(alpha = blink), 63f, 22f, 1.6f)
}

/** A six-wheeled rover with a solar deck, its camera mast looking around. */
private fun DrawScope.rover(t: Float, g: SceneGrade) {
    groundShadow(50f, 80f)
    val dark = g(0xFF4A4F57)
    val metal = g(0xFF9AA3AE)
    stick(metal, 22f, 84f, 34f, 74f, 2.2f)
    stick(metal, 46f, 84f, 34f, 74f, 2.2f)
    stick(metal, 70f, 84f, 62f, 74f, 2.2f)
    box(g(0xFFC9CED6), 18f, 58f, 80f, 75f, 3f)
    box(g(0xFFE6E9ED), 18f, 58f, 78f, 72f, 3f)
    box(g(0xFFD9A53A), 24f, 62f, 44f, 70f, 1.5f)
    box(g(0xFF243F75), 12f, 52f, 84f, 58f, 1.5f)
    for (x in 1..5) stick(g(0xFF4A6AA8), 12f + x * 12f, 52.5f, 12f + x * 12f, 57.5f, 0.6f)
    stick(metal, 28f, 52f, 26f, 42f, 1.4f)
    drawArc(metal, 200f, 140f, true, Offset(19f, 36f), Size(14f, 10f))
    stick(metal, 68f, 52f, 68f, 30f, 2.2f)
    val pan = swing(t, 8) * 3f
    box(g(0xFFE6E9ED), 60f + pan, 23f, 76f + pan, 31f, 2f)
    dot(dark, 72f + pan * 1.3f, 27f, 2.4f)
    dot(g(0xFF6FD3FF), 72.3f + pan * 1.3f, 26.6f, 1f)
    for (x in floatArrayOf(22f, 46f, 70f)) {
        dot(dark, x, 86f, 8.5f)
        dot(metal, x, 86f, 3.4f)
        for (k in 0..5) {
            val a = k * TAU / 6
            dot(g(0xFF34383F), x + cos(a) * 7f, 86f + sin(a) * 7f, 1.2f)
        }
    }
}

/**
 * A landed rocket on its fins, a light blinking on its nose and a little dust puffing at its feet. In the air
 * ([flying]) it has no shadow on the ground and no dust.
 */
internal fun DrawScope.rocket(t: Float, g: SceneGrade, flying: Boolean = false) {
    if (!flying) groundShadow(50f, 70f)
    val red = g(0xFFE84B4B)
    val redDark = g(0xFFB8333A)
    stick(g(0xFF8E97A4), 36f, 70f, 22f, 94f, 2.2f)
    stick(g(0xFF8E97A4), 64f, 70f, 78f, 94f, 2.2f)
    box(g(0xFF55606E), 40f, 76f, 60f, 86f, 2f)
    drawPath(finLeft, redDark)
    drawPath(finRight, redDark)
    drawPath(rocketBody, g(0xFFF2F4F7))
    clipPath(rocketBody) {
        box(red, 0f, 0f, 100f, 25f)
        box(red, 0f, 66f, 100f, 72f)
        box(Color.Black.copy(alpha = 0.13f), 56f, 0f, 100f, 100f)
        box(Color.White.copy(alpha = 0.5f), 40f, 20f, 42.5f, 70f, 1f)
    }
    dot(g(0xFF8E97A4), 50f, 44f, 8f)
    dot(g(0xFF3E7FC4), 50f, 44f, 6f)
    oval(Color.White.copy(alpha = 0.6f), 48f, 42f, 2.2f, 1.6f)
    stick(redDark, 50f, 74f, 50f, 84f, 2.4f)
    val blink = swing(t, 60)
    if (blink > 0f) dot(g(0xFFFFE27A).copy(alpha = blink), 50f, 7f, 1.6f)
    if (!flying) for (k in 0..2) {
        val p = drift(t, 18, k / 3f)
        val side = if (k == 1) -1f else 1f
        dot(g(0xFFD07A4E).copy(alpha = 0.45f * (1f - p)), 50f + side * (8f + p * 20f), 92f - p * 6f, 3f + p * 4f)
    }
}

private val rocketBody = Path().apply {
    moveTo(50f, 4f)
    quadraticBezierTo(64f, 16f, 64f, 36f)
    lineTo(62f, 76f)
    lineTo(38f, 76f)
    lineTo(36f, 36f)
    quadraticBezierTo(36f, 16f, 50f, 4f)
    close()
}
private val finLeft = polygon(38f, 52f, 24f, 72f, 24f, 82f, 38f, 74f)
private val finRight = polygon(62f, 52f, 76f, 72f, 76f, 82f, 62f, 74f)
