package io.colorsand.ui.hud

import io.colorsand.core.Arena

/**
 * How the level selector's world map is laid out: one section per visit to an arena, [Arena.LEVELS] levels each,
 * in play order (Playground 1-5, Beach 6-10, Sea Floor 11-15, ..., Mars 26-30, Playground II 31-35, ...).
 */
object MapLayout {
    /** The section that level [number] belongs to, from 0. */
    fun section(number: Int): Int = (number - 1) / Arena.LEVELS

    /** The first level of [section]. */
    fun firstLevel(section: Int): Int = section * Arena.LEVELS + 1

    /** Sections to show while levels up to [unlocked] are open: through the one holding it, and the next as a peek. */
    fun sectionCount(unlocked: Int): Int = section(unlocked) + 2

    /** The section's name: the arena, with a Roman numeral from its second round on ("Beach II"). */
    fun title(section: Int): String {
        val arena = Arena.of(firstLevel(section))
        val round = section / Arena.entries.size + 1
        return if (round == 1) arena.title else "${arena.title} ${roman(round)}"
    }

    /** Where the node of [stage] (1..[Arena.LEVELS]) sits across the map, as a fraction of its width: a trail winding side to side. */
    fun nodeX(stage: Int): Float = NODE_X[(stage - 1) % NODE_X.size]

    /** [n] (at least 1) in Roman numerals. */
    fun roman(n: Int): String {
        require(n >= 1) { "No Roman numeral for $n" }
        var rest = n
        return buildString {
            for ((value, symbol) in NUMERALS) {
                while (rest >= value) {
                    append(symbol)
                    rest -= value
                }
            }
        }
    }

    private val NODE_X = listOf(0.64f, 0.34f, 0.66f, 0.36f, 0.62f)

    private val NUMERALS = listOf(
        1000 to "M", 900 to "CM", 500 to "D", 400 to "CD", 100 to "C", 90 to "XC",
        50 to "L", 40 to "XL", 10 to "X", 9 to "IX", 5 to "V", 4 to "IV", 1 to "I",
    )
}
