package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** The ground the toss is played on: a playground lawn by the sandbox, or a building site's gravel yard. */
internal enum class TossScene { PLAYGROUND, SITE }

/**
 * The look of the toss in one arena: the [scene], its sky ([skyTop] to [skyBottom]), the [far] hills or haze, the
 * ground ([groundLight], [ground], [groundShade]), the launcher's colors ([frame], [frameDark], [band]), the ball
 * ([ball], [ballLight], [ballDark]) and the keepsake standing by the launcher ([arena]'s [stage]). The nouns name the
 * launcher, the ball and both kinds of target for the line under the game and screen readers.
 */
internal class TossLook(
    val arena: Arena,
    val stage: Int,
    val scene: TossScene,
    val skyTop: Color,
    val skyBottom: Color,
    val far: Color,
    val farLight: Color,
    val groundLight: Color,
    val ground: Color,
    val groundShade: Color,
    val frame: Color,
    val frameDark: Color,
    val band: Color,
    val ball: Color,
    val ballLight: Color,
    val ballDark: Color,
    val launcher: String,
    val ballName: String,
    val start: String,
    val done: String,
) {
    /** What screen readers and the line under the game call [kind]. */
    fun name(kind: TossTargetKind): String = when (kind) {
        TossTargetKind.BLOCKS -> "toy blocks"
        TossTargetKind.BUCKET -> "bucket"
        TossTargetKind.CONES -> "cones"
        TossTargetKind.PALLET -> "pallet"
    }

    /** The cheer for hitting [kind]. */
    fun cheer(kind: TossTargetKind): String = when (kind) {
        TossTargetKind.BLOCKS -> "Bonk! The blocks tumble!"
        TossTargetKind.BUCKET -> "Plop! Right in the bucket!"
        TossTargetKind.CONES -> "Clonk! Cones down!"
        TossTargetKind.PALLET -> "Thud! On the pallet!"
    }

    companion object {
        /** [arena]'s look, its colors through [g]. Arenas without the toss get the Playground's. */
        fun of(arena: Arena, g: SceneGrade): TossLook = when (arena) {
            Arena.BUILDING_SITE -> TossLook(
                Arena.BUILDING_SITE, 1, TossScene.SITE,
                g(0xFF4F9EE0), g(0xFFDCEDF3), g(0xFFC9B8A0), g(0xFFE3D6C0),
                g(0xFFD3CCC0), g(0xFFB4ADA2), g(0xFF8C857B),
                g(0xFFFFB31F), g(0xFFC9861A), g(0xFF3B3A3E),
                g(0xFFC9A46A), g(0xFFE3C48C), g(0xFF8E6B3C),
                "sling", "sandbag",
                "Pull back the sling to toss a sandbag!",
                "Five hits! Great tossing!",
            )
            else -> TossLook(
                Arena.PLAYGROUND, 1, TossScene.PLAYGROUND,
                g(0xFF3A93DB), g(0xFFCDEBF8), g(0xFF7CC55B), g(0xFFA6DA84),
                g(0xFF7CCB5E), g(0xFF5DA746), g(0xFF3F8A35),
                g(0xFFDDA567), g(0xFF8E5A31), g(0xFFE6533F),
                g(0xFFF0CF8E), g(0xFFFFE6B3), g(0xFFC99A55),
                "sling", "sandball",
                "Pull back the sling to toss a sandball!",
                "Five hits! Great tossing!",
            )
        }
    }
}

/**
 * Where the toss sits in a [width] x [height] canvas, in pixels: the field is as wide as the canvas, its ground
 * a band up from the bottom (deeper on a tall screen, as a foreground) and the sky above it, at least 0.85 field
 * widths tall where the canvas allows. [unit] is a hundredth of the width.
 */
internal class TossLayout(val width: Float, val height: Float) {
    val unit: Float = width / 100f

    /** The ground line's y. */
    val groundY: Float = height - (height - width * 0.85f).coerceIn(width * 0.14f, maxOf(width * 0.14f, height * 0.3f))

    fun x(x: Float): Float = x * width
    fun y(y: Float): Float = groundY - y * width
    fun at(x: Float, y: Float): Offset = Offset(x(x), y(y))
    fun at(p: TossPoint): Offset = at(p.x, p.y)

    /** A distance of [d] field widths, in pixels. */
    fun len(d: Float): Float = d * width
}
