/** Rows of sky over the ground, and rows the chamber takes under it. */
internal const val DEEP_SKY = 2.4f
internal const val DEEP_CHAMBER = 2.6f

/**
 * Where a Dig deeper shaft of [columns] sits in a [width] x [height] area, in pixels: a framed window, a [cell] per
 * tile, that scrolls down with the camera (the world row at the window's top, see [rowAt] and [top]).
 */
internal class DeepLayout(width: Float, height: Float, val columns: Int) {
    val cell: Float = minOf(width / (columns + 2 * RIM), height / (MIN_ROWS + 2 * RIM))
    val rim: Float = cell * RIM
    val window: Rect = Rect(
        Offset((width - cell * columns) / 2, rim),
        Size(cell * columns, height - 2 * rim),
    )

    /** How many rows the window shows. */
    val rows: Float get() = window.height / cell

    /** The screen y of world row [row]'s top, with [camera] the row at the window's top. */
    fun top(row: Float, camera: Float): Float = window.top + (row - camera) * cell

    fun left(column: Int): Float = window.left + column * cell

    /** The world column and row at screen [point], with [camera] the row at the top. */
    fun cellAt(point: Offset, camera: Float): Pair<Int, Int> =
        floor((point.x - window.left) / cell).toInt() to floor((point.y - window.top) / cell + camera).toInt()

    /** The camera row that shows the digger at [y] a third of the way down, kept within the world. */
    fun cameraFor(y: Float, depth: Int): Float =
        (y - rows * 0.36f).coerceIn(-DEEP_SKY, (depth + DEEP_CHAMBER - rows).coerceAtLeast(-DEEP_SKY))

    private companion object {
        const val RIM = 0.26f
        const val MIN_ROWS = 7f
    }
}

/** A chip of ground knocked off by a tap. */
internal class Chip(var x: Float, var y: Float, var vx: Float, var vy: Float, val color: Color, var age: Float = 0f)

internal const val CHIP_S = 0.5f

/** A find popping out of its tile: which one, at which tile, and when (seconds). */
internal class Pop(val find: Int, val x: Int, val y: Int, val at: Float)

internal const val DIG_POP_S = 1.1f

/**
 * The whole dig at this frame: the frame, the sky with the arena's landmark, every tile in view with its cracks
 * and peeking finds, the dug tunnel, the chamber (hidden until [reveal] goes 0 to 1), the digger at ([diggerX],
 * [diggerY]) facing [facing] with its tool at [swing] (0 to 1), chips and finds popping out. [time] is in seconds.
 */
internal fun DrawScope.drawDigDeeper(
    look: DeepLook,
    grade: SceneGrade,
    layout: DeepLayout,
    round: DigDeeper,
    camera: Float,
    diggerX: Float,
    diggerY: Float,
    facing: Int,
    swing: Float,
    reveal: Float,
    time: Float,
    chips: List<Chip>,
    pops: List<Pop>,
) {
    val s = layout.cell
    val w = layout.window
    val rim = layout.rim
    val outer = Rect(w.left - rim, w.top - rim, w.right + rim, w.bottom + rim)
    drawRoundRect(Color.Black.copy(alpha = 0.2f), outer.topLeft + Offset(0f, rim * 0.7f), outer.size, CornerRadius(s * 0.5f))
    drawRoundRect(look.slabDark, outer.topLeft + Offset(0f, rim * 0.3f), outer.size, CornerRadius(s * 0.5f))
    drawRoundRect(Brush.verticalGradient(listOf(look.slabLight, look.slab), outer.top, outer.bottom), outer.topLeft, outer.size, CornerRadius(s * 0.5f))
    clipPath(Path().apply { addRoundRect(RoundRect(w, CornerRadius(s * 0.36f))) }) {
        drawSky(look, grade, layout, camera, time)
        val first = floor(camera).toInt().coerceAtLeast(0)
        val last = (camera + layout.rows).toInt().coerceAtMost(round.depth - 1)
        for (y in first..last) drawRowBand(look, layout, round, y, camera)
        for (y in first..last) for (x in 0 until round.columns) {
            if (!round.isDug(x, y)) drawTile(look, grade, layout, round, x, y, camera, time)
        }
        drawTunnel(look, layout, round, camera, first, last)
        drawChamber(look, grade, layout, round, camera, reveal, time)
        drawDigger(look, grade, layout, diggerX, diggerY, camera, facing, swing, time)
        for (c in chips) {
            val k = (c.age / CHIP_S).coerceIn(0f, 1f)
            drawRoundRect(c.color.copy(alpha = 1f - k * k), Offset(c.x, c.y), Size(s * 0.1f, s * 0.08f), CornerRadius(s * 0.03f))
        }
        for (p in pops) {
            val k = ((time - p.at) / DIG_POP_S).coerceIn(0f, 1f)
            val rise = sin(k * PI.toFloat() * 0.5f)
            val cx = layout.left(p.x) + s / 2
            val cy = layout.top(p.y.toFloat(), camera) + s / 2 - rise * s * 0.9f
            val size = s * (0.4f + 0.5f * rise)
            drawGlow(Offset(cx, cy), size * 0.9f, look.glow.copy(alpha = 0.7f * (1f - k)))
            drawFind(look.finds[p.find], grade, Offset(cx - size / 2, cy - size / 2), size)
            if (k < 0.8f) drawSparkle(Offset(cx + size * 0.4f, cy - size * 0.4f), s * 0.16f * (1f - k), Color.White)
        }
        drawRoundRect(Color.Black.copy(alpha = 0.16f), w.topLeft, w.size, CornerRadius(s * 0.36f), style = Stroke(s * 0.1f))
    }
}

/** The sky over the ground and the arena's landmark standing on it: the pyramid, or cones and a fence at the site. */
private fun DrawScope.drawSky(look: DeepLook, grade: SceneGrade, layout: DeepLayout, camera: Float, time: Float) {
    val s = layout.cell
    val w = layout.window
    val ground = layout.top(0f, camera)
    if (ground <= w.top) return
    val skyTop = layout.top(-DEEP_SKY, camera)
    drawRect(Brush.verticalGradient(listOf(look.skyTop, look.skyBottom), skyTop, ground), Offset(w.left, skyTop), Size(w.width, ground - skyTop))
    val t = time / 30f
    if (look.isSite) {
        // A fence along the back, and a cone off to the side.
        val fence = grade(0xFFF2A33A)
        for (k in 0..14) {
            val x = w.left + k * s * 0.5f
            drawRect(fence.copy(alpha = 0.55f), Offset(x, ground - s * 0.9f), Size(s * 0.06f, s * 0.9f))
        }
        drawRect(fence.copy(alpha = 0.7f), Offset(w.left, ground - s * 0.8f), Size(w.width, s * 0.08f))
        drawRect(fence.copy(alpha = 0.7f), Offset(w.left, ground - s * 0.4f), Size(w.width, s * 0.08f))
        val size = s * 1.1f
        translate(w.right - s * 1.25f, ground - size * 0.96f) { scale(size / 100f, size / 100f, Offset.Zero) { drawKeepsake(Arena.BUILDING_SITE, 1, t, grade) } }
    } else {
        val size = s * 2.3f
        translate(w.right - size * 0.95f, ground - size * 0.94f) { scale(size / 100f, size / 100f, Offset.Zero) { drawKeepsake(Arena.DESERT, 5, t, grade) } }
    }
    // The ground's top edge, a soft lit lip.
    val top = look.layers[0]
    drawRect(top.light, Offset(w.left, ground - s * 0.08f), Size(w.width, s * 0.12f))
}

/** The bed under one row's tiles, which shows in the gaps between them. */
private fun DrawScope.drawRowBand(look: DeepLook, layout: DeepLayout, round: DigDeeper, y: Int, camera: Float) {
    val layer = look.layers[round.tile(0, y).layer]
    val top = layout.top(y.toFloat(), camera)
    drawRect(lerp(layer.dark, layer.base, 0.35f), Offset(layout.window.left, top), Size(layout.window.width, layout.cell + 1f))
}

/** One tile of ground: a rounded block in its layer's colors and texture, a slab, cracks, and a find peeking out. */
private fun DrawScope.drawTile(look: DeepLook, grade: SceneGrade, layout: DeepLayout, round: DigDeeper, x: Int, y: Int, camera: Float, time: Float) {
    val s = layout.cell
    val tile = round.tile(x, y)
    val layer = look.layers[tile.layer]
    val l = layout.left(x)
    val t = layout.top(y.toFloat(), camera)
    val inset = s * 0.035f
    val seed = y * 31 + x * 7
    val corner = CornerRadius(s * 0.18f)
    if (tile.slab) {
        drawSlab(look, layout, round, x, y, l, t)
    } else {
        drawRoundRect(layer.dark, Offset(l + inset, t + inset + s * 0.05f), Size(s - 2 * inset, s - 2 * inset - s * 0.05f), corner)
        drawRoundRect(
            Brush.verticalGradient(listOf(layer.light, layer.base), t, t + s),
            Offset(l + inset, t + inset),
            Size(s - 2 * inset, s - 2 * inset - s * 0.07f),
            corner,
        )
        drawTexture(layer, l, t, s, seed)
        drawRoundRect(Color.White.copy(alpha = 0.18f), Offset(l + s * 0.16f, t + s * 0.1f), Size(s * 0.42f, s * 0.08f), CornerRadius(s * 0.04f))
    }
    tile.find?.let { find ->
        // A corner of the find shows through the ground, with a twinkle now and then.
        val size = s * 0.5f
        val p = Offset(l + s * (0.12f + 0.3f * noise(seed)), t + s * (0.14f + 0.26f * noise(seed + 5)))
        drawGlow(p + Offset(size / 2, size / 2), size * 0.7f, look.glow.copy(alpha = 0.35f))
        drawFind(look.finds[find], grade, p, size)
        val tw = sin(time * 2.4f + seed)
        if (tw > 0.2f) drawSparkle(p + Offset(size * 0.25f, size * 0.15f), s * 0.12f * tw, Color.White.copy(alpha = 0.9f * tw))
    }
    val crack = round.cracks(x, y)
    if (crack > 0f) drawCracks(l, t, s, crack, seed, layer.dark)
}

/** The texture of one tile of [layer]. */
private fun DrawScope.drawTexture(layer: DeepLayer, l: Float, t: Float, s: Float, seed: Int) {
    when (layer.texture) {
        DeepTexture.GRAINS -> for (k in 0 until 6) {
            val p = Offset(l + s * (0.15f + 0.7f * noise(seed * 7 + k)), t + s * (0.25f + 0.6f * noise(seed * 13 + k)))
            drawCircle((if (k % 2 == 0) layer.dark else layer.light).copy(alpha = 0.6f), s * 0.03f, p)
        }
        DeepTexture.STRATA -> for (k in 1..3) {
            val y = t + s * (0.2f + 0.22f * k)
            drawLine(layer.dark.copy(alpha = 0.35f), Offset(l + s * 0.1f, y + s * 0.03f * sin(seed + k.toFloat())), Offset(l + s * 0.9f, y - s * 0.03f * sin(seed + k.toFloat())), s * 0.035f)
        }
        DeepTexture.PEBBLES -> for (k in 0 until 4) {
            val p = Offset(l + s * (0.2f + 0.6f * noise(seed * 3 + k)), t + s * (0.28f + 0.5f * noise(seed * 5 + k)))
            val r = s * (0.07f + 0.05f * noise(seed + k * 11))
            drawOval(layer.dark.copy(alpha = 0.7f), p - Offset(r, r * 0.6f) + Offset(0f, r * 0.2f), Size(2 * r, 1.4f * r))
            drawOval(lerp(layer.light, Color.White, 0.2f), p - Offset(r, r * 0.7f), Size(2 * r * 0.9f, 1.3f * r))
        }
        DeepTexture.STREAKS -> for (k in 0 until 2) {
            val y = t + s * (0.35f + 0.3f * k + 0.08f * noise(seed + k))
            drawLine(layer.light.copy(alpha = 0.5f), Offset(l + s * 0.18f, y), Offset(l + s * (0.5f + 0.3f * noise(seed * 9 + k)), y + s * 0.04f), s * 0.05f)
        }
        DeepTexture.STONE -> {
            val c = Offset(l + s * (0.35f + 0.3f * noise(seed)), t + s * (0.4f + 0.2f * noise(seed + 3)))
            drawLine(layer.dark.copy(alpha = 0.45f), Offset(l + s * 0.1f, t + s * 0.3f), c, s * 0.03f)
            drawLine(layer.dark.copy(alpha = 0.45f), c, Offset(l + s * 0.85f, t + s * 0.55f), s * 0.03f)
            drawLine(layer.dark.copy(alpha = 0.45f), c, Offset(l + s * 0.45f, t + s * 0.88f), s * 0.03f)
            drawCircle(layer.light.copy(alpha = 0.5f), s * 0.05f, Offset(l + s * 0.7f, t + s * 0.3f))
        }
    }
}

/** A hard slab: a length of old rusty pipe at the site, a carved sandstone block in the desert. */
private fun DrawScope.drawSlab(look: DeepLook, layout: DeepLayout, round: DigDeeper, x: Int, y: Int, l: Float, t: Float) {
    val s = layout.cell
    val leftOpen = x == 0 || !round.tile(x - 1, y).slab
    val rightOpen = x == round.columns - 1 || !round.tile(x + 1, y).slab
    if (look.isSite) {
        val pipeTop = t + s * 0.22f
        val h = s * 0.56f
        drawRect(look.slabDark, Offset(l, pipeTop + s * 0.04f), Size(s, h))
        drawRect(Brush.verticalGradient(listOf(look.slabLight, look.slab, look.slabDark), pipeTop, pipeTop + h), Offset(l, pipeTop), Size(s, h - s * 0.04f))
        drawRect(Color(0xFFB0683A).copy(alpha = 0.45f), Offset(l + s * (0.2f + 0.4f * noise(x + y)), pipeTop + h * 0.5f), Size(s * 0.22f, h * 0.35f))
        // Flanges where the pipe's lengths join, and open ends.
        if (leftOpen) drawRoundRect(look.slabDark, Offset(l + s * 0.02f, pipeTop - s * 0.06f), Size(s * 0.16f, h + s * 0.12f), CornerRadius(s * 0.05f))
        if (rightOpen) drawRoundRect(look.slabDark, Offset(l + s * 0.82f, pipeTop - s * 0.06f), Size(s * 0.16f, h + s * 0.12f), CornerRadius(s * 0.05f))
        drawCircle(look.slabDark, s * 0.035f, Offset(l + s * 0.5f, pipeTop + h * 0.2f))
    } else {
        val inset = s * 0.035f
        drawRoundRect(look.slabDark, Offset(l + inset, t + inset + s * 0.05f), Size(s - 2 * inset, s - 2 * inset - s * 0.05f), CornerRadius(s * 0.08f))
        drawRoundRect(look.slab, Offset(l + inset, t + inset), Size(s - 2 * inset, s - 2 * inset - s * 0.07f), CornerRadius(s * 0.08f))
        // A carved eye-and-wave glyph.
        val c = Offset(l + s / 2, t + s * 0.45f)
        drawOval(look.slabDark.copy(alpha = 0.7f), c - Offset(s * 0.2f, s * 0.09f), Size(s * 0.4f, s * 0.18f), style = Stroke(s * 0.04f))
        drawCircle(look.slabDark.copy(alpha = 0.7f), s * 0.05f, c)
        drawLine(look.slabDark.copy(alpha = 0.6f), c + Offset(-s * 0.2f, s * 0.22f), c + Offset(s * 0.2f, s * 0.22f), s * 0.04f)
        drawRoundRect(Color.White.copy(alpha = 0.22f), Offset(l + s * 0.12f, t + s * 0.1f), Size(s * 0.5f, s * 0.07f), CornerRadius(s * 0.03f))
    }
}

/** Cracks spreading from the middle of a tile as it takes taps ([amount], 0 to 1). */
private fun DrawScope.drawCracks(l: Float, t: Float, s: Float, amount: Float, seed: Int, color: Color) {
    val c = Offset(l + s * 0.5f, t + s * 0.48f)
    val n = 3 + (amount * 4).toInt()
    for (k in 0 until n) {
        val a = 2 * PI.toFloat() * (k + noise(seed + k)) / n
        val len = s * (0.18f + 0.26f * amount) * (0.7f + 0.5f * noise(seed * 3 + k))
        val mid = c + Offset(cos(a) * len * 0.5f + s * 0.04f * sin(a * 3), sin(a) * len * 0.5f)
        val end = c + Offset(cos(a + 0.25f) * len, sin(a + 0.25f) * len)
        drawLine(Color.Black.copy(alpha = 0.55f), c, mid, s * 0.035f)
        drawLine(Color.Black.copy(alpha = 0.45f), mid, end, s * 0.028f)
        drawLine(color.copy(alpha = 0.3f), mid + Offset(s * 0.015f, s * 0.015f), end + Offset(s * 0.015f, s * 0.015f), s * 0.02f)
    }
}

/** The dug-out tunnel: one dark rounded shape over the dug tiles, deeper at the bottom, with a lit top lip. */
private fun DrawScope.drawTunnel(look: DeepLook, layout: DeepLayout, round: DigDeeper, camera: Float, first: Int, last: Int) {
    val s = layout.cell
    val r = CornerRadius(s * 0.3f)
    for (y in first..last) for (x in 0 until round.columns) {
        if (!round.isDug(x, y)) continue
        val layer = look.layers[round.tile(x, y).layer]
        val dark = lerp(layer.dark, Color.Black, 0.35f)
        val l = layout.left(x)
        val t = layout.top(y.toFloat(), camera)
        val pad = s * 0.02f
        val up = y == 0 || round.isDug(x, y - 1)
        drawRoundRect(dark, Offset(l + pad, t + pad), Size(s - 2 * pad, s - 2 * pad), r)
        // Shade under the roof where the tunnel is closed above.
        if (!up) drawRoundRect(Color.Black.copy(alpha = 0.22f), Offset(l + pad, t + pad), Size(s - 2 * pad, s * 0.22f), r)
        val right = x + 1 < round.columns && round.isDug(x + 1, y)
        val down = y + 1 < round.depth && round.isDug(x, y + 1)
        if (up) drawRect(dark, Offset(l + pad, t - s * 0.1f), Size(s - 2 * pad, s * 0.5f))
        if (right) drawRect(dark, Offset(l + s / 2, t + pad), Size(s, s - 2 * pad))
        if (down) drawRect(dark, Offset(l + pad, t + s / 2), Size(s - 2 * pad, s * 0.6f))
        // A little ledge of loose bits on the floor.
        if (!down) drawRoundRect(layer.base.copy(alpha = 0.55f), Offset(l + s * 0.12f, t + s * 0.82f), Size(s * 0.76f, s * 0.12f), CornerRadius(s * 0.06f))
    }
}

/**
 * The chamber under the last row: dark bedrock with a faint glow coming through until it opens, then a lit room
 * with the prize on a pedestal ([reveal] 0 to 1).
 */
private fun DrawScope.drawChamber(look: DeepLook, grade: SceneGrade, layout: DeepLayout, round: DigDeeper, camera: Float, reveal: Float, time: Float) {
    val s = layout.cell
    val w = layout.window
    val top = layout.top(round.depth.toFloat(), camera)
    if (top > w.bottom) return
    val height = DEEP_CHAMBER * s + s
    val bed = look.layers.last()
    drawRect(Brush.verticalGradient(listOf(bed.dark, lerp(bed.dark, Color.Black, 0.4f)), top, top + height), Offset(w.left, top), Size(w.width, height))
    val room = Rect(w.left + s * 0.6f, top + s * 0.15f, w.right - s * 0.6f, top + DEEP_CHAMBER * s - s * 0.1f)
    val pulse = 0.5f + 0.5f * sin(time * 2f)
    if (reveal <= 0f) {
        // A secret glow leaking through the cracks.
        drawGlow(room.center, s * (1.2f + 0.2f * pulse), look.glow.copy(alpha = 0.25f + 0.1f * pulse))
        return
    }
    val a = reveal.coerceIn(0f, 1f)
    val walls = Path().apply { addRoundRect(RoundRect(room, CornerRadius(s * 0.4f, s * 0.4f))) }
    clipPath(walls) {
        drawRect(Brush.verticalGradient(listOf(look.chamberDark, look.chamber), room.top, room.bottom), room.topLeft, room.size, alpha = a)
        // Blocks in the walls.
        val rows = 4
        for (r in 0 until rows) {
            val y = room.top + room.height * r / rows
            drawLine(look.chamberDark.copy(alpha = 0.6f * a), Offset(room.left, y), Offset(room.right, y), s * 0.03f)
            var x = room.left + (if (r % 2 == 0) s * 0.3f else s * 0.8f)
            while (x < room.right) {
                drawLine(look.chamberDark.copy(alpha = 0.5f * a), Offset(x, y), Offset(x, y + room.height / rows), s * 0.03f)
                x += s
            }
        }
        if (look.isSite) {
            // A hanging work lamp.
            val lamp = Offset(room.left + room.width * 0.2f, room.top + s * 0.55f)
            drawLine(grade(0xFF3E434A).copy(alpha = a), Offset(lamp.x, room.top), lamp, s * 0.03f)
            drawGlow(lamp, s * 0.9f, look.glow.copy(alpha = 0.6f * a))
            drawCircle(grade(0xFFFFF4C8).copy(alpha = a), s * 0.12f, lamp)
        } else {
            // Glyphs on the walls and two torches.
            for (k in 0 until 5) {
                val gx = room.left + room.width * (0.12f + 0.19f * k)
                val gy = room.top + s * 0.4f
                drawCircle(look.chamberDark.copy(alpha = 0.55f * a), s * 0.07f, Offset(gx, gy), style = Stroke(s * 0.03f))
                drawLine(look.chamberDark.copy(alpha = 0.55f * a), Offset(gx, gy + s * 0.1f), Offset(gx, gy + s * 0.32f), s * 0.03f)
            }
            for (tx in floatArrayOf(room.left + s * 0.4f, room.right - s * 0.4f)) {
                val flame = Offset(tx, room.top + room.height * 0.42f)
                drawGlow(flame, s * (0.7f + 0.08f * pulse), look.glow.copy(alpha = 0.7f * a))
                drawLine(grade(0xFF6E4728).copy(alpha = a), flame + Offset(0f, s * 0.1f), flame + Offset(0f, s * 0.45f), s * 0.07f)
                drawOval(grade(0xFFFF9A3D).copy(alpha = a), flame - Offset(s * 0.07f, s * 0.14f), Size(s * 0.14f, s * 0.22f))
                drawOval(grade(0xFFFFE27A).copy(alpha = a), flame - Offset(s * 0.04f, s * 0.08f), Size(s * 0.08f, s * 0.13f))
            }
        }
    }
    drawRoundRect(look.chamberDark.copy(alpha = a), room.topLeft, room.size, CornerRadius(s * 0.4f), style = Stroke(s * 0.08f))
    // The prize on its pedestal, rising a little and glowing.
    val pedestal = Rect(room.center.x - s * 0.55f, room.bottom - s * 0.5f, room.center.x + s * 0.55f, room.bottom)
    drawRoundRect(look.chamberDark.copy(alpha = a), pedestal.topLeft, pedestal.size, CornerRadius(s * 0.08f))
    drawRoundRect(look.chamber.copy(alpha = a), pedestal.topLeft, Size(pedestal.width, s * 0.12f), CornerRadius(s * 0.06f))
    val size = s * if (look.isSite) 1.75f else 1.3f
    val c = Offset(room.center.x, pedestal.top - size * 0.42f - s * 0.08f * sin(time * 2.2f))
    drawGlow(c, size * (0.9f + 0.1f * pulse), look.glow.copy(alpha = 0.8f * a))
    if (a > 0.05f) drawFind(look.prize, grade, c - Offset(size / 2, size / 2), size)
    for (k in 0 until 6) {
        val ang = 2 * PI.toFloat() * k / 6 + time * 0.7f
        val tw = 0.5f + 0.5f * sin(time * 5f + k * 1.7f)
        drawSparkle(c + Offset(cos(ang) * size * 0.75f, sin(ang) * size * 0.5f), s * 0.13f * tw * a, Color.White.copy(alpha = a))
    }
}

/**
 * The digger at world ([x], [y]) (y = -1 on the surface): a little explorer with a pith helmet, headlamp and pick
 * in the desert, the excavator itself at the site. It faces [facing] (-1 left, 1 right) and [swing]s its tool.
 */
private fun DrawScope.drawDigger(look: DeepLook, grade: SceneGrade, layout: DeepLayout, x: Float, y: Float, camera: Float, facing: Int, swing: Float, time: Float) {
    val s = layout.cell
    val size = s * if (look.isSite) 1.15f else 1.0f
    val cx = layout.window.left + (x + 0.5f) * s
    val bottom = layout.top(y + 1f, camera) - s * 0.04f
    val hit = sin(swing * PI.toFloat())
    translate(cx, bottom) {
        scale(facing.toFloat(), 1f, Offset.Zero) {
            if (look.isSite) {
                rotate(hit * 6f, Offset(0f, 0f)) {
                    scale(size / 100f, size / 100f, Offset.Zero) {
                        translate(-46f, -96f) { drawKeepsake(Arena.BUILDING_SITE, 5, time / 30f + hit * 0.02f, grade) }
                    }
                }
            } else {
                scale(size / 100f, size / 100f, Offset.Zero) { translate(-50f, -96f) { explorer(grade, hit, time) } }
            }
        }
    }
}

/** A little explorer in a 100 x 100 box, facing right, swinging a pick by [hit] (0 to 1). */
private fun DrawScope.explorer(g: SceneGrade, hit: Float, time: Float) {
    val khaki = g(0xFFD9B77A)
    val khakiDark = g(0xFFA9864C)
    val skin = g(0xFFF2C29A)
    // Boots and body.
    oval(g(0xFF5E3F22), 40f, 93f, 8f, 4f)
    oval(g(0xFF5E3F22), 58f, 93f, 8f, 4f)
    box(khakiDark, 32f, 56f, 68f, 92f, 12f)
    box(khaki, 32f, 54f, 66f, 89f, 12f)
    box(g(0xFF7A4E2A), 32f, 72f, 66f, 77f, 1f)
    dot(g(0xFFFFD04A), 49f, 74.5f, 2.4f)
    // The pick, swung down and forward by the hit.
    val hand = Offset(64f, 66f)
    rotate(-40f + hit * 75f, hand) {
        stick(g(0xFF8E5A2E), hand.x, hand.y, hand.x + 30f, hand.y, 4.5f)
        val head = Path().apply {
            moveTo(hand.x + 28f, hand.y - 14f)
            quadraticBezierTo(hand.x + 36f, hand.y, hand.x + 28f, hand.y + 14f)
            lineTo(hand.x + 31f, hand.y)
            close()
        }
        drawPath(head, g(0xFF8A9099))
        drawPath(head, g(0xFFC9D0D8), style = Stroke(1.5f))
    }
    dot(skin, hand.x, hand.y, 5f)
    // Head, helmet and headlamp.
    dot(skin, 50f, 40f, 15f)
    dot(g(0xFF2E2A28), 56f, 40f, 2.2f)
    oval(g(0xFFFF9B8A).copy(alpha = 0.6f), 58f, 46f, 3.5f, 2f)
    oval(khakiDark, 50f, 31f, 25f, 5f)
    oval(khaki, 50f, 30f, 24f, 4f)
    drawArc(khaki, 180f, 180f, true, Offset(32f, 12f), Size(36f, 36f))
    drawRect(khakiDark, Offset(32f, 26f), Size(36f, 3f))
    val lamp = Offset(62f, 22f)
    drawGlow(lamp + Offset(10f, 4f), 16f, g(0xFFFFF2B0).copy(alpha = 0.5f + 0.15f * sin(time * 3f)))
    dot(g(0xFF5E646C), lamp.x, lamp.y, 4.5f)
    dot(g(0xFFFFF4C8), lamp.x + 1f, lamp.y, 3f)
    oval(Color.White.copy(alpha = 0.45f), 42f, 18f, 6f, 2.5f)
}
