/**
 * The whole game, in layers from back to front: the arena's scenery and keepsakes, the HUD around the board (see Hud.kt),
 * then the level-complete card, the color picker and the level selector over them. The level selector floats on
 * the scenery, which then shows the arena in view on the map; so does a keepsake's game (see [MinigameOverlay]).
 */
@Composable
fun App(store: ProgressStore) {
    val game = rememberSaveable(saver = GameController.saver(store, OPEN_ALL_LEVELS)) { GameController(store, openAllLevels = OPEN_ALL_LEVELS) }
    val pours = rememberPourAnimation(game)
    val feedback = rememberGameFeedback(game, pours, store)
    var chosen by remember { mutableStateOf(storedPalette(store)) }
    var custom by remember { mutableStateOf(CustomScheme.decode(store.customColors)) }
    var paw by remember { mutableStateOf(PawKind.byName(store.paw)) }
    var picking by remember { mutableStateOf(false) }
    var showLevels by rememberSaveable { mutableStateOf(false) }
    // The arena whose part of the world map is in view, while the map is open.
    var mapArena by remember { mutableStateOf<Arena?>(null) }
    // The level whose keepsake game is being played, if one is.
    var keepsakeGame by remember { mutableStateOf<Int?>(null) }
    // Sunny and Mo's story: the beats played so far, and the show playing now. The show is kept as text so it
    // survives the screen being rebuilt; it counts as seen once it ends (played through or skipped).
    var storyBook by remember { mutableStateOf(StoryBook.decode(store.story)) }
    var playing by rememberSaveable { mutableStateOf<String?>(null) }
    val story = playing?.let { StoryShow.decode(it) }
    val playStory = { show: StoryShow -> playing = show.encode() }
    val endStory = { show: StoryShow ->
        playing = null
        if (!show.replay) {
            storyBook = storyBook.record(show)
            store.story = storyBook.encode()
        }
        // A closing played from an arena's last level goes on to the next level, as Next level would have.
        if (show.nextLevel && game.isSolved) game.nextLevel()
    }
    ColorSandTheme(chosen) {
        val palette = LocalPalette.current
        val arena = game.arena
        CompositionLocalProvider(LocalArena provides arena) {
            ArenaBackground(mapArena.takeIf { showLevels } ?: arena, palette, Modifier.fillMaxSize())
            if (!showLevels && keepsakeGame == null) Keepsakes(game, pours, feedback, onPlay = { keepsakeGame = it })
            BoxWithConstraints(Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.safeDrawing)) {
                val header = @Composable { Header(game, onColors = { picking = true }, onLevels = { showLevels = true }) }
                val board: @Composable (Modifier) -> Unit = { modifier ->
                    CompositionLocalProvider(LocalPawKind provides paw) { BoardView(game, modifier.tutorial(game, pours), pours) }
                }
                val landscape = isLandscapePhone(maxWidth, maxHeight)
                // The game, not drawn while the world map or a keepsake game is open over the scenery.
                Box(Modifier.fillMaxSize().drawWithContent { if (!showLevels && keepsakeGame == null) drawContent() }) {
                    if (landscape) {
                        // A short, wide screen: the controls stand at the side so the board gets the height.
                        Row(Modifier.fillMaxSize().padding(horizontal = 16.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                            Column(Modifier.weight(1f).fillMaxHeight(), horizontalAlignment = Alignment.CenterHorizontally) {
                                header()
                                Box(Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.BottomCenter) {
                                    board(Modifier.fillMaxSize())
                                    NoticeLine(game)
                                }
                            }
                            Spacer(Modifier.width(12.dp))
                            Controls(game, vertical = true)
                        }
                    } else {
                        Column(
                            Modifier.fillMaxSize().padding(16.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                        ) {
                            header()
                            board(Modifier.weight(1f).fillMaxWidth())
                            Box(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
                                // Sunny and Mo sit on the controls, behind the notice line.
                                StoryCameos(arena, cheering = game.isSolved && !pours.isRunning, modifier = Modifier.matchParentSize())
                                NoticeLine(game)
                            }
                            Controls(game)
                        }
                    }
                    // Arriving in an arena may begin its part of the story; the arena's banner waits for it.
                    ArenaIntro(
                        game,
                        paused = story != null,
                        onArrival = { arrival ->
                            StoryPlan.onArrival(arrival.level, storyBook, clearedBefore = game.isCleared(arrival.level - 1))?.let(playStory)
                        },
                    )
                    // Let the last grains land before the level-complete card comes up.
                    if (game.isSolved && !pours.isRunning) {
                        LevelComplete(
                            game,
                            onPlayKeepsake = { keepsakeGame = game.levelNumber },
                            // After an arena's last level, its closing plays before moving on.
                            onNext = {
                                val closing = StoryPlan.afterClear(game.levelNumber, storyBook)
                                if (closing != null) playStory(closing) else game.nextLevel()
                            },
                        )
                    }
                }
                if (picking) {
                    // A sheet over the daylight scenery, so it takes the HUD's light look.
                    ColorSandTheme(remember(palette) { hudPalette(palette) }) {
                        WithGameFont {
                            PalettePicker(
                                current = chosen,
                                custom = custom,
                                onPick = { chosen = it; store.palette = it.name },
                                onCustom = { scheme, save ->
                                    custom = scheme
                                    chosen = scheme.palette()
                                    if (save) store.customColors = scheme.encode()
                                },
                                onDismiss = { picking = false },
                                more = {
                                    PawPicker(paw, onPick = { paw = it; store.paw = it.name }, board = palette)
                                    FeedbackToggles(feedback)
                                },
                            )
                        }
                    }
                }
                if (showLevels) {
                    LevelSelector(
                        game,
                        onClose = { showLevels = false; mapArena = null },
                        onArenaInView = { mapArena = it },
                        story = storyBook,
                        onStory = { playStory(StoryPlan.replay(it, storyBook)) },
                    )
                }
            }
            keepsakeGame?.let { level -> MinigameOverlay(level, game, feedback, onClose = { keepsakeGame = null }) }
            story?.let { show -> StoryOverlay(show, onDone = { endStory(show) }) }
        }
    }
}

/**
 * Whether a [width] x [height] window is a phone on its side: wide, and too short to stack the header, the board
 * and the controls. Such a window gets the controls at the side.
 */
internal fun isLandscapePhone(width: Dp, height: Dp): Boolean = width > height * 1.3f && height < 560.dp
