// The story panels' scenery and props. A panel is painted in a box W x H units (4:3), most things standing on
// y = FLOOR. Colors go through the scheme's SceneGrade like the arena scenes.

internal const val W = 400f
internal const val H = 300f

/** Where characters usually stand in a panel. */
internal const val FLOOR = 262f

/** Where a panel is set. */
internal enum class Setting {
    SANDBOX, BEACH, SUNSET, LIVING_ROOM, UNDERWATER, DESERT, DESERT_NIGHT, BACKYARD, BACKYARD_NIGHT, BEDROOM, BEDROOM_MORNING, SPACE, MARS
}

/** Paints [setting] over the whole panel at clock [t]. */
internal fun DrawScope.backdrop(setting: Setting, g: SceneGrade, t: Float) = when (setting) {
    Setting.SANDBOX -> sandbox(g, t)
    Setting.BEACH -> beach(g, t)
    Setting.SUNSET -> sunset(g, t)
    Setting.LIVING_ROOM -> livingRoom(g, t)
    Setting.UNDERWATER -> underwater(g, t)
    Setting.DESERT -> desert(g, t)
    Setting.DESERT_NIGHT -> desertNight(g, t)
    Setting.BACKYARD -> backyard(g, t, night = false)
    Setting.BACKYARD_NIGHT -> backyard(g, t, night = true)
    Setting.BEDROOM -> bedroom(g, t, morning = false)
    Setting.BEDROOM_MORNING -> bedroom(g, t, morning = true)
    Setting.SPACE -> space(g, t)
    Setting.MARS -> mars(g, t)
}

/** The ground color characters stand on in [setting], for holes and dust. */
internal fun soilOf(setting: Setting): Color = when (setting) {
    Setting.SANDBOX -> Color(0xFFE8CF97)
    Setting.BEACH, Setting.SUNSET -> Color(0xFFF1D9A6)
    Setting.UNDERWATER -> Color(0xFFE4DCC2)
    Setting.DESERT, Setting.DESERT_NIGHT -> Color(0xFFEDB066)
    Setting.BACKYARD, Setting.BACKYARD_NIGHT -> Color(0xFFDDBF85)
    Setting.MARS -> Color(0xFFCB6A40)
    else -> Color(0xFFB98552)
}

private fun DrawScope.sky(g: SceneGrade, vararg stops: Pair<Float, Long>, bottom: Float = H) {
    drawRect(Brush.verticalGradient(*stops.map { it.first to g(it.second) }.toTypedArray(), startY = 0f, endY = bottom), size = Size(W, H))
}

private fun DrawScope.sun(g: SceneGrade, x: Float, y: Float, r: Float) {
    drawGlow(Offset(x, y), r * 3f, g(Color(0x88FFF1B8)))
    dot(g(0xFFFFE9A0), x, y, r)
    dot(g(0xFFFFF8DC), x, y, r * 0.75f)
}

private fun DrawScope.clouds(g: SceneGrade, t: Float, count: Int = 2, alpha: Float = 0.9f) {
    val r = SceneRandom(5)
    repeat(count) { i ->
        val width = r.next(48f, 72f)
        val path = cloudPath(width, 5, r)
        val x = (drift(t, 1 + i % 2, r.next()) * (W + width * 2)) - width
        val y = 34f + i * 26f + r.next(0f, 10f)
        translate(x, y) {
            drawPath(path, g(0xFFC9DDF0).copy(alpha = alpha))
            translate(-2f, -3f) { drawPath(path, g(0xFFFFFFFF).copy(alpha = alpha)) }
        }
    }
}

private fun DrawScope.stars(g: SceneGrade, t: Float, count: Int, bottom: Float, seed: Int = 3) {
    val r = SceneRandom(seed)
    repeat(count) { k ->
        val x = r.next(0f, W)
        val y = r.next(0f, bottom)
        val size = r.next(0.8f, 2.2f)
        val tw = 0.55f + 0.45f * swing(t, 40 + k % 5 * 7, r.next())
        if (k % 7 == 0) drawSparkle(Offset(x, y), size * 2.6f * tw, g(0xFFFFF6D8).copy(alpha = 0.9f))
        else dot(g(0xFFFFF6E8).copy(alpha = 0.5f + 0.5f * tw), x, y, size)
    }
}

/** Sand speckles over a band from [top] to [bottom]. */
private fun DrawScope.speckles(color: Color, top: Float, bottom: Float, seed: Int, count: Int = 40) {
    val r = SceneRandom(seed)
    repeat(count) { dot(color, r.next(0f, W), r.next(top, bottom), r.next(0.8f, 1.8f)) }
}

private fun DrawScope.sandbox(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF4FA3E0, 0.45f to 0xFF8CCBF0, 0.7f to 0xFFD6EEF2, bottom = 230f)
    sun(g, 52f, 44f, 22f)
    clouds(g, t)
    val far = Ridge(W, 205f, 26f, 1.2f, 0.15f)
    drawPath(far.fill(H), g(0xFF9ACFA4))
    val near = Ridge(W, 228f, 14f, 0.8f, 0.45f)
    drawPath(near.fill(H), g(0xFF72BC58))
    // A tree and the slide far off, so it reads as the playground.
    stick(g(0xFF8A5A3C), 352f, 216f, 352f, 180f, 6f)
    dot(g(0xFF4F9A4A), 352f, 170f, 22f)
    dot(g(0xFF66B25A), 348f, 166f, 17f)
    stick(g(0xFFD2553F), 30f, 210f, 44f, 168f, 3f)
    stick(g(0xFFD2553F), 84f, 210f, 70f, 168f, 3f)
    stick(g(0xFFD2553F), 40f, 168f, 74f, 168f, 3.5f)
    stick(g(0xFF8A5A3C), 57f, 168f, 57f + swing(t, 30) * 4f, 192f, 1f)
    // The sandbox: a wooden frame full of sand.
    box(g(0xFF9A6438), 6f, 222f, 394f, 236f, 4f)
    box(g(0xFFC08A52), 6f, 220f, 394f, 231f, 4f)
    drawRect(Brush.verticalGradient(0f to g(0xFFE2C487), 1f to g(0xFFF0DCA8), startY = 230f, endY = 300f), Offset(10f, 230f), Size(380f, 70f))
    speckles(g(0xFFC9A66A).copy(alpha = 0.6f), 236f, 296f, 11)
    box(g(0xFF9A6438), 0f, 290f, 400f, 300f)
    box(g(0xFFC08A52), 0f, 288f, 400f, 296f, 2f)
}

private fun DrawScope.beach(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF4DB3EA, 0.5f to 0xFFA8DDF4, 1f to 0xFFE6F6F6, bottom = 150f)
    sun(g, 340f, 46f, 20f)
    clouds(g, t, 2)
    drawRect(Brush.verticalGradient(0f to g(0xFF2D9FD0), 1f to g(0xFF5ACCD6), startY = 140f, endY = 206f), Offset(0f, 140f), Size(W, 70f))
    val shift = drift(t, 20) * 40f
    for (row in 0..2) {
        val y = 156f + row * 16f
        for (k in -1..10) {
            val x = k * 40f + shift + row * 13f
            stick(g(0xFFE6FAFF).copy(alpha = 0.5f), x, y, x + 14f, y, 2f)
        }
    }
    // Foam lapping on the sand.
    val lap = swing(t, 30) * 4f
    drawRect(g(0xFFE3C98F), Offset(0f, 202f + lap), Size(W, 16f))
    val foam = Path().apply {
        moveTo(0f, 204f + lap)
        for (k in 0..20) quadraticTo(k * 20f + 10f, 210f + lap, k * 20f + 20f, 204f + lap)
    }
    drawPath(foam, g(0xFFFFFFFF).copy(alpha = 0.85f), style = Stroke(4f, cap = StrokeCap.Round))
    drawRect(Brush.verticalGradient(0f to g(0xFFF0D7A0), 1f to g(0xFFF7E6BE), startY = 214f, endY = H), Offset(0f, 214f + lap * 0.3f), Size(W, 90f))
    speckles(g(0xFFD9B77E).copy(alpha = 0.6f), 222f, 298f, 21)
}

private fun DrawScope.sunset(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF6A5AB8, 0.35f to 0xFFE07AA0, 0.6f to 0xFFFFA36E, 0.75f to 0xFFFFD48A, bottom = 160f)
    stars(g, t, 8, 50f)
    clipRect(0f, 0f, W, 152f) {
        drawGlow(Offset(200f, 150f), 120f, g(Color(0x99FFE2A0)))
        dot(g(0xFFFFC56A), 200f, 152f, 40f)
        dot(g(0xFFFFE39A), 200f, 152f, 32f)
    }
    drawRect(Brush.verticalGradient(0f to g(0xFF8A5CA8), 1f to g(0xFF5A4C98), startY = 150f, endY = 212f), Offset(0f, 150f), Size(W, 64f))
    // The sun's golden path on the water.
    for (k in 0..5) {
        val y = 156f + k * 9f
        val half = 30f - k * 3f + swing(t, 40, k * 0.2f) * 4f
        stick(g(0xFFFFD27A).copy(alpha = 0.75f - k * 0.08f), 200f - half, y, 200f + half, y, 2.5f)
    }
    drawRect(Brush.verticalGradient(0f to g(0xFFD69A7A), 1f to g(0xFFEBB88E), startY = 210f, endY = H), Offset(0f, 210f), Size(W, 90f))
    speckles(g(0xFFB8805E).copy(alpha = 0.5f), 220f, 298f, 31)
}

/** The family aquarium on its cabinet, filling the middle of a cozy room; [livingRoom] draws the room around it. */
private fun DrawScope.livingRoom(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFFF6E6CC, 1f to 0xFFEBD3AF, bottom = 236f)
    // Soft wallpaper stripes and a picture frame.
    for (x in 0..9) box(g(0xFFF0DCBC).copy(alpha = 0.7f), x * 44f, 0f, x * 44f + 14f, 236f)
    box(g(0xFFB98552), 0f, 236f, W, H)
    for (k in 0..5) stick(g(0xFFA06F42), 0f, 248f + k * 10f, W, 248f + k * 10f, 1f)
    box(g(0xFFE7D1B0), 0f, 230f, W, 238f)
    aquarium(g, t, 60f, 40f, 340f, 196f)
    box(g(0xFF7A4E30), 50f, 196f, 350f, 238f, 4f)
    box(g(0xFF9A6640), 50f, 196f, 350f, 232f, 4f)
    box(g(0xFF7A4E30), 196f, 204f, 204f, 228f, 2f)
    dot(g(0xFFF2C14A), 186f, 216f, 2f)
    dot(g(0xFFF2C14A), 214f, 216f, 2f)
}

/** A glass tank from ([l], [t0]) to ([r], [b]) with water, gravel, weed, bubbles, the clownfish and the turtle. */
internal fun DrawScope.aquarium(g: SceneGrade, t: Float, l: Float, t0: Float, r: Float, b: Float) {
    box(g(0xFF55606E), l - 6f, t0 - 6f, r + 6f, t0 + 2f, 3f)
    drawRect(Brush.verticalGradient(0f to g(0xFF7AD3EE), 1f to g(0xFF2A84C2), startY = t0, endY = b), Offset(l, t0), Size(r - l, b - t0))
    clipRect(l, t0, r, b) {
        box(g(0xFFE4D3A2), l, b - 16f, r, b)
        speckles(g(0xFFB79E6A), b - 14f, b - 2f, 41, 30)
        for (k in 0..4) {
            val x = l + 20f + k * (r - l - 40f) / 4f
            kelp(g, t, x, b - 10f, 50f + (k % 3) * 18f, k * 0.17f)
        }
        val swimX = l + (r - l) * (0.2f + 0.6f * (0.5f + 0.5f * swing(t, 6)))
        translate(swimX - 30f, t0 + 20f) { scale(0.6f, 0.6f, Offset.Zero) { drawKeepsake(Arena.SEA_FLOOR, 1, t, g) } }
        translate(r - 120f - swing(t, 4) * 30f, b - 98f) { scale(0.9f, 0.9f, Offset.Zero) { drawKeepsake(Arena.SEA_FLOOR, 4, t, g) } }
        bubbles(g, t, l + 30f, b - 14f, b - t0)
        bubbles(g, t, r - 40f, b - 14f, b - t0, 0.5f)
        drawRect(Brush.linearGradient(0f to Color.White.copy(alpha = 0f), 0.5f to Color.White.copy(alpha = 0.22f), 1f to Color.White.copy(alpha = 0f), start = Offset(l + 40f, t0), end = Offset(l + 120f, b)), Offset(l, t0), Size(r - l, b - t0))
    }
    drawRect(Color.White.copy(alpha = 0.7f), Offset(l, t0), Size(r - l, b - t0), style = Stroke(2.5f))
}

/** A strand of kelp [height] tall swaying from its root at ([x], [y]). */
internal fun DrawScope.kelp(g: SceneGrade, t: Float, x: Float, y: Float, height: Float, phase: Float) {
    val steps = 6
    var px = x
    var py = y
    for (i in 1..steps) {
        val f = i / steps.toFloat()
        val nx = x + swing(t, 20, phase + f * 0.3f) * 8f * f
        val ny = y - height * f
        stick(g(0xFF3E9A5A), px, py, nx, ny, 6f - f * 3f)
        if (i % 2 == 0) oval(g(0xFF5CB86E), nx + 4f, ny + 3f, 5f, 2.5f)
        px = nx
        py = ny
    }
}

private fun DrawScope.bubbles(g: SceneGrade, t: Float, x: Float, y: Float, rise: Float, phase: Float = 0f) {
    for (k in 0..3) {
        val p = drift(t, 30, phase + k / 4f)
        val bx = x + swing(t, 50, k * 0.3f) * 4f
        drawCircle(g(0xFFE8F8FF).copy(alpha = 0.8f * (1f - p)), 2.5f + k * 0.8f, Offset(bx, y - rise * p), style = Stroke(1.2f))
    }
}

private fun DrawScope.underwater(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF63C4EC, 0.6f to 0xFF2F86C8, 1f to 0xFF205FA6)
    // Light rays from the surface.
    for (k in 0..3) {
        val x = 40f + k * 110f + swing(t, 8, k * 0.25f) * 10f
        val ray = polygon(x, 0f, x + 40f, 0f, x + 10f, 260f, x - 50f, 260f)
        drawPath(ray, Color.White.copy(alpha = 0.08f))
    }
    val floor = Ridge(W, 246f, 12f, 1f, 0.3f)
    drawPath(floor.fill(H), g(0xFFE4DCC2))
    speckles(g(0xFFBDB394), 244f, 298f, 51)
    kelp(g, t, 22f, 260f, 120f, 0f)
    kelp(g, t, 40f, 264f, 80f, 0.3f)
    kelp(g, t, 372f, 258f, 130f, 0.6f)
    kelp(g, t, 390f, 262f, 70f, 0.1f)
    // Coral.
    for ((cx, c) in listOf(80f to 0xFFFF8A80, 330f to 0xFFB98AE8)) {
        stick(g(c), cx, 250f, cx - 8f, 228f, 5f)
        stick(g(c), cx, 250f, cx + 6f, 222f, 5f)
        stick(g(c), cx + 2f, 238f, cx + 14f, 232f, 4f)
    }
    bubbles(g, t, 120f, 240f, 230f)
    bubbles(g, t, 300f, 236f, 220f, 0.4f)
}

private fun DrawScope.desert(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF5FB0E6, 0.55f to 0xFFA9D8EE, 1f to 0xFFFCE2B4, bottom = 200f)
    sun(g, 332f, 44f, 22f)
    clouds(g, t, 1, 0.7f)
    // Pyramids, far, far away.
    for ((x, s) in listOf(70f to 1f, 104f to 0.7f, 132f to 0.5f)) {
        drawPath(polygon(x - 30f * s, 192f, x, 192f - 34f * s, x + 30f * s, 192f), g(0xFFE6B880).copy(alpha = 0.9f))
        drawPath(polygon(x, 192f - 34f * s, x + 30f * s, 192f, x + 4f * s, 192f), g(0xFFC9935A).copy(alpha = 0.9f))
    }
    val far = Ridge(W, 200f, 16f, 1.1f, 0.2f)
    drawPath(far.fill(H), g(0xFFF0C27E))
    val near = Ridge(W, 236f, 18f, 0.7f, 0.6f)
    drawPath(near.fill(H), g(0xFFEDAE62))
    drawPath(near.line(), g(0xFFFFD9A0), style = Stroke(2f))
    speckles(g(0xFFD08A44).copy(alpha = 0.5f), 236f, 298f, 61)
}

private fun DrawScope.desertNight(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF151C48, 0.6f to 0xFF2E2E6A, 1f to 0xFF5A4A86, bottom = 220f)
    stars(g, t, 46, 190f)
    // A crescent moon.
    dot(g(0xFFFFF2C4), 330f, 50f, 18f)
    dot(g(0xFF1B2250), 338f, 44f, 16f)
    drawGlow(Offset(326f, 54f), 44f, g(Color(0x33FFF2C4)))
    val far = Ridge(W, 206f, 16f, 1.1f, 0.2f)
    drawPath(far.fill(H), g(0xFF6A4A6A))
    val near = Ridge(W, 240f, 16f, 0.7f, 0.6f)
    drawPath(near.fill(H), g(0xFF8A5A52))
    drawPath(near.line(), g(0xFFB98A7A).copy(alpha = 0.6f), style = Stroke(2f))
}

private fun DrawScope.backyard(g: SceneGrade, t: Float, night: Boolean) {
    if (night) {
        sky(g, 0f to 0xFF1E2858, 0.6f to 0xFF4A4386, 1f to 0xFFB07A9A, bottom = 200f)
        stars(g, t, 30, 150f, seed = 9)
    } else {
        sky(g, 0f to 0xFF56A8E2, 0.6f to 0xFF9ED4F0, 1f to 0xFFE2F2EE, bottom = 200f)
        sun(g, 340f, 40f, 18f)
        clouds(g, t, 2)
    }
    // A wooden fence and a house corner.
    val plank = if (night) g(0xFF6E5A6A) else g(0xFFD9A86A)
    val plankShade = if (night) g(0xFF56465A) else g(0xFFB98A50)
    for (k in 0..13) {
        val x = k * 30f
        box(plankShade, x + 2f, 150f, x + 28f, 232f, 3f)
        box(plank, x + 2f, 148f, x + 26f, 230f, 3f)
        drawPath(polygon(x + 2f, 150f, x + 14f, 140f, x + 26f, 150f), plank)
    }
    box(plankShade, 0f, 168f, W, 174f)
    box(plankShade, 0f, 206f, W, 212f)
    drawRect(Brush.verticalGradient(0f to if (night) g(0xFF3E6A50) else g(0xFF7CC55B), 1f to if (night) g(0xFF2E5040) else g(0xFF5DA746), startY = 226f, endY = H), Offset(0f, 226f), Size(W, 80f))
    for (k in 0..18) {
        val x = k * 22f + 6f
        stick(if (night) g(0xFF4E7A5E) else g(0xFF8ED46A), x, 234f, x - 3f, 226f, 2f)
        stick(if (night) g(0xFF4E7A5E) else g(0xFF8ED46A), x + 4f, 234f, x + 6f, 227f, 2f)
    }
    // The sand pile they play in.
    val sand = soilOf(Setting.BACKYARD)
    oval(darker(g(sand), if (night) 0.6f else 0.85f), 200f, 272f, 180f, 22f)
    oval(if (night) darker(g(sand), 0.7f) else g(sand), 200f, 268f, 176f, 19f)
}

private fun DrawScope.bedroom(g: SceneGrade, t: Float, morning: Boolean) {
    if (morning) sky(g, 0f to 0xFFFFE6C4, 1f to 0xFFF6D2A8, bottom = 230f) else sky(g, 0f to 0xFF2C2862, 1f to 0xFF3E3878, bottom = 230f)
    // The window, with the night or the morning outside.
    box(g(if (morning) 0xFFE9C79A else 0xFF24204E), 26f, 30f, 126f, 130f, 6f)
    clipRect(32f, 36f, 120f, 124f) {
        if (morning) {
            drawRect(Brush.verticalGradient(0f to g(0xFF8FD0F2), 1f to g(0xFFFCE8B8), startY = 36f, endY = 124f), Offset(32f, 36f), Size(88f, 88f))
            sun(g, 90f, 70f, 14f)
        } else {
            drawRect(g(0xFF101640), Offset(32f, 36f), Size(88f, 88f))
            translate(30f, 34f) { scale(0.24f, 0.4f, Offset.Zero) { stars(g, t, 16, 220f, seed = 13) } }
            dot(g(0xFFFFF2C4), 96f, 60f, 11f)
        }
    }
    stick(g(if (morning) 0xFFE9C79A else 0xFF24204E), 76f, 36f, 76f, 124f, 4f)
    stick(g(if (morning) 0xFFE9C79A else 0xFF24204E), 32f, 80f, 120f, 80f, 4f)
    box(g(if (morning) 0xFFC58F5A else 0xFF4A3A6E), 0f, 228f, W, H)
    for (k in 0..4) stick(g(if (morning) 0xFFAE7A48 else 0xFF3E3060), 0f, 240f + k * 12f, W, 240f + k * 12f, 1f)
    // The blanket fort: a quilt over two chairs, fairy lights along its edge.
    val chair = g(if (morning) 0xFF9A6640 else 0xFF5E4466)
    for (x in floatArrayOf(84f, 316f)) {
        stick(chair, x, 160f, x, 254f, 6f)
        stick(chair, x + if (x < 200f) -14f else 14f, 200f, x + if (x < 200f) -14f else 14f, 254f, 5f)
    }
    val quilt = Path().apply {
        moveTo(60f, 256f)
        quadraticTo(70f, 190f, 84f, 158f)
        quadraticTo(200f, 120f, 316f, 158f)
        quadraticTo(330f, 190f, 340f, 256f)
        close()
    }
    drawPath(quilt, g(if (morning) 0xFF5FA8D8 else 0xFF4A7AB8))
    clipRect(0f, 0f, W, H) {
        val dot = g(if (morning) 0xFFFFE9A0 else 0xFFE8D27A).copy(alpha = 0.8f)
        for (row in 0..5) for (col in 0..10) {
            val x = 70f + col * 26f + (row % 2) * 13f
            val y = 160f + row * 18f
            if (x < 80f + row * 2f || x > 320f - row * 2f) continue
            dot(dot, x, y, 2.6f)
        }
    }
    // The way in: a dark, cozy door in the quilt.
    val door = Path().apply {
        moveTo(140f, 256f)
        quadraticTo(150f, 190f, 200f, 182f)
        quadraticTo(250f, 190f, 260f, 256f)
        close()
    }
    drawPath(door, g(if (morning) 0xFF3A5A7A else 0xFF1A1E3E))
    for (k in 0..8) {
        val x = 86f + k * 28.5f
        val y = 158f - kotlin.math.sin(k / 8f * 3.1416f) * 34f + 4f
        val glow = 0.6f + 0.4f * swing(t, 40, k * 0.13f)
        if (!morning) drawGlow(Offset(x, y), 9f, g(Color(0xAAFFE08A)).copy(alpha = 0.6f * glow))
        dot(g(listOf(0xFFFFD86A, 0xFFFF8A9A, 0xFF8AD8FF)[k % 3]).copy(alpha = if (morning) 0.7f else glow), x, y, 2.6f)
    }
}

private fun DrawScope.space(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFF0C1034, 1f to 0xFF2A1E5E)
    stars(g, t, 70, H, seed = 17)
    // Home, far behind: a little blue and green planet, and the moon.
    dot(g(0xFF3E8AD8), 60f, 250f, 40f)
    oval(g(0xFF6CC46A), 48f, 240f, 16f, 10f)
    oval(g(0xFF6CC46A), 76f, 262f, 12f, 8f)
    oval(Color.White.copy(alpha = 0.3f), 44f, 226f, 12f, 4f)
    dot(g(0xFFD8D4CC), 130f, 200f, 9f)
    dot(g(0xFFB8B2A8), 128f, 202f, 2f)
    // Mars, ahead.
    dot(g(0xFFC9583A), 352f, 56f, 30f)
    dot(g(0xFFE07A50), 348f, 52f, 26f)
    oval(g(0xFFB04A30), 356f, 62f, 8f, 4f)
    // A shooting star now and then.
    val p = drift(t, 10)
    if (p < 0.3f) {
        val f = p / 0.3f
        val x = 380f - f * 300f
        val y = 20f + f * 80f
        stick(Color.White.copy(alpha = 0.7f * (1f - f)), x, y, x + 30f, y - 8f, 2f)
    }
}

private fun DrawScope.mars(g: SceneGrade, t: Float) {
    sky(g, 0f to 0xFFE88A6A, 0.6f to 0xFFF6B48A, 1f to 0xFFFFD6B0, bottom = 210f)
    // Two moons.
    dot(g(0xFFF4E6D6), 300f, 46f, 12f)
    dot(g(0xFFD6C4B2), 304f, 48f, 3f)
    dot(g(0xFFF4E6D6), 352f, 80f, 6f)
    val far = Ridge(W, 200f, 22f, 1.3f, 0.3f)
    drawPath(far.fill(H), g(0xFFD88060))
    val near = Ridge(W, 236f, 14f, 0.8f, 0.7f)
    drawPath(near.fill(H), g(0xFFC4623A))
    drawPath(near.line(), g(0xFFE89A70), style = Stroke(2f))
    for ((x, y, r) in listOf(Triple(70f, 270f, 22f), Triple(320f, 284f, 16f), Triple(200f, 292f, 10f))) {
        oval(g(0xFFA94E2E), x, y, r, r * 0.3f)
        oval(g(0xFFB65A34), x, y + 1.5f, r * 0.8f, r * 0.2f)
    }
    for ((x, r) in listOf(30f to 7f, 382f to 9f, 250f to 5f)) {
        oval(g(0xFF8E3E24), x, 258f, r, r * 0.7f)
        oval(g(0xFFB0563A), x - 1f, 256.5f, r * 0.8f, r * 0.5f)
    }
}

// Props.

/** [arena]'s keepsake for [stage], [size] units tall, standing at ([cx], [ground]). */
internal fun DrawScope.keepsake(arena: Arena, stage: Int, cx: Float, ground: Float, size: Float, g: SceneGrade, t: Float) {
    val s = size / 100f
    translate(cx - 50f * s, ground - 96f * s) { scale(s, s, Offset.Zero) { drawKeepsake(arena, stage, t, g) } }
}

/** A red sand bucket at ([cx], [ground]), [size] tall, with [treasures] peeking out of it (0 to 3). */
internal fun DrawScope.bucket(cx: Float, ground: Float, size: Float, g: SceneGrade, t: Float, treasures: Int = 0) {
    val s = size / 40f
    translate(cx, ground) {
        scale(s, s, Offset.Zero) {
            oval(Color.Black.copy(alpha = 0.18f), 0f, 0f, 16f, 2.5f)
            if (treasures >= 1) {
                dot(g(0xFFE8494E), -6f, -38f, 7f)
                oval(Color.White.copy(alpha = 0.5f), -8f, -41f, 2.5f, 1.4f)
            }
            if (treasures >= 2) {
                dot(g(0xFFFFD43F), 6f, -39f, 6f)
                oval(g(0xFFF07A28), 11f, -38f, 3f, 1.4f)
                dot(Color(0xFF26222B), 7f, -41f, 1f)
            }
            if (treasures >= 3) translate(0f, -40f) { rotate(15f, Offset.Zero) { scale(6f, 6f, Offset.Zero) { drawPath(starPath(0.45f), g(0xFFFF9A5A)) } } }
            val pail = polygon(-15f, -34f, 15f, -34f, 11f, 0f, -11f, 0f)
            drawPath(pail, g(0xFFC23338))
            drawPath(polygon(-14f, -33f, 12f, -33f, 9f, -2f, -10f, -2f), g(0xFFE8494E))
            box(g(0xFFFFD447), -15.5f, -36f, 15.5f, -31f, 2f)
            drawArc(g(0xFF5A6270), 180f, 180f, false, Offset(-14f, -50f), Size(28f, 30f), style = Stroke(1.6f))
            oval(Color.White.copy(alpha = 0.35f), -6f, -22f, 2.5f, 7f)
        }
    }
}

/** A wicker picnic basket at ([cx], [ground]), [size] wide, a baguette and a juice bottle poking out. */
internal fun DrawScope.picnicBasket(cx: Float, ground: Float, size: Float, g: SceneGrade) {
    val s = size / 50f
    translate(cx, ground) {
        scale(s, s, Offset.Zero) {
            oval(Color.Black.copy(alpha = 0.18f), 0f, 0f, 26f, 3f)
            stick(g(0xFFF2C88A), -8f, -26f, 6f, -40f, 6f)
            box(g(0xFF6EC2E8), 8f, -38f, 15f, -22f, 2.5f)
            box(g(0xFFFF8A80), 9f, -42f, 14f, -38f, 1f)
            drawArc(g(0xFF8A5A30), 180f, 180f, false, Offset(-18f, -46f), Size(36f, 40f), style = Stroke(3f))
            box(g(0xFF9A6438), -24f, -26f, 24f, 0f, 5f)
            box(g(0xFFC08A52), -24f, -26f, 24f, -3f, 5f)
            for (k in 0..3) stick(g(0xFF9A6438), -20f, -21f + k * 5f, 20f, -21f + k * 5f, 1.2f)
            // A gingham cloth over the edge.
            box(g(0xFFE8574A), -26f, -28f, 26f, -22f, 2f)
            for (k in 0..6) box(Color.White.copy(alpha = 0.6f), -24f + k * 7.5f, -28f, -21f + k * 7.5f, -22f)
        }
    }
}

/** A picnic blanket seen from the front, [w] wide, laid at ([cx], [y]). */
internal fun DrawScope.picnicBlanket(cx: Float, y: Float, w: Float, g: SceneGrade) {
    val blanket = polygon(cx - w / 2f, y + 18f, cx - w / 2f + 26f, y - 4f, cx + w / 2f - 26f, y - 4f, cx + w / 2f, y + 18f)
    drawPath(blanket, g(0xFFE8574A))
    clipRect(cx - w / 2f, y - 4f, cx + w / 2f, y + 18f) {
        for (k in 0..((w / 14f).toInt())) {
            val x = cx - w / 2f + k * 14f
            drawPath(polygon(x, y + 18f, x + 7f, y + 18f, x + 7f + 3f, y - 4f, x + 3f, y - 4f), Color.White.copy(alpha = 0.5f))
        }
    }
}

/** Drops of water flying up around ([cx], [y]) at [p] (0 to 1) of the splash. */
internal fun DrawScope.splash(cx: Float, y: Float, p: Float, g: SceneGrade, color: Long = 0xFFBEEFFF) {
    val c = g(color)
    for (k in 0..9) {
        val a = -3.1416f * (0.1f + 0.8f * k / 9f)
        val reach = 20f + 50f * p + (k % 3) * 8f
        val x = cx + kotlin.math.cos(a) * reach
        val yy = y + kotlin.math.sin(a) * reach * (1.1f - p * 0.5f) + p * p * 30f
        dot(c.copy(alpha = (1f - p * 0.6f)), x, yy, 4f - (k % 3))
    }
}

/** A few quick lines behind something moving left to right at ([x], [y]). */
internal fun DrawScope.speedLines(x: Float, y: Float, g: SceneGrade, t: Float) {
    for (k in 0..2) {
        val off = drift(t, 60, k / 3f) * 10f
        stick(g(0xFFFFFFFF).copy(alpha = 0.8f), x - 40f - off, y + k * 14f - 14f, x - 14f - off, y + k * 14f - 14f, 3f)
    }
}

/** Sleepy "z"s drifting up from ([x], [y]). */
internal fun DrawScope.zzz(x: Float, y: Float, g: SceneGrade, t: Float) {
    for (k in 0..2) {
        val p = drift(t, 24, k / 3f)
        val s = 5f + p * 6f
        val zx = x + p * 26f + swing(t, 30, k * 0.3f) * 3f
        val zy = y - p * 40f
        val z = Path().apply {
            moveTo(zx - s, zy - s)
            lineTo(zx + s, zy - s)
            lineTo(zx - s, zy + s)
            lineTo(zx + s, zy + s)
        }
        drawPath(z, g(0xFFFFFFFF).copy(alpha = 1f - p), style = Stroke(2.4f, cap = StrokeCap.Round))
    }
}

/** Clumps of [soil] flying up out of a hole at ([cx], [y]) at clock [t]. */
internal fun DrawScope.dirtSpray(cx: Float, y: Float, soil: Color, t: Float, strength: Float = 1f) {
    for (k in 0..7) {
        val p = drift(t, 50, k / 8f)
        val side = if (k % 2 == 0) -1f else 1f
        val x = cx + side * (6f + p * (30f + k * 3f)) * strength
        val yy = y - (60f * p - 70f * p * p) * strength - 4f
        dot(darker(soil, 0.9f + (k % 3) * 0.05f).copy(alpha = 1f - p * 0.5f), x, yy, 3.5f - (k % 3) * 0.7f)
    }
}

/** A tower of patted sand, [floors] buckets high, standing at ([cx], [ground]); the top one gets a flag when [done]. */
internal fun DrawScope.sandTower(cx: Float, ground: Float, floors: Int, g: SceneGrade, t: Float, done: Boolean) {
    val sand = g(0xFFE6C38A)
    val shade = g(0xFFC9A066)
    var y = ground
    var w = 70f
    for (k in 0 until floors) {
        val h = 30f
        box(shade, cx - w / 2f, y - h, cx + w / 2f, y, 6f)
        box(sand, cx - w / 2f, y - h, cx + w / 2f - 4f, y - 3f, 6f)
        for (b in 0..2) dot(shade, cx - w / 4f + b * w / 4f, y - h / 2f, 1.4f)
        y -= h
        w -= 10f
    }
    // Crenels on top.
    for (k in -1..1) box(sand, cx + k * w / 3f - 5f, y - 8f, cx + k * w / 3f + 5f, y + 1f, 2f)
    if (done) {
        stick(g(0xFF8A5A3C), cx, y - 2f, cx, y - 46f, 2.4f)
        val wave = swing(t, 60) * 3f
        drawPath(polygon(cx, y - 46f, cx + 26f, y - 40f + wave, cx, y - 32f), g(0xFFE8574A))
    }
}

/** A cardboard rocket at ([cx], [cy]) (its middle), crayon flames under it, [riders] drawn peeking out of its top. */
internal fun DrawScope.cardboardRocket(
    cx: Float,
    cy: Float,
    g: SceneGrade,
    t: Float,
    scale: Float = 1f,
    flames: Boolean = true,
    riders: DrawScope.() -> Unit,
) = translate(cx, cy) {
    scale(scale, scale, Offset.Zero) {
        // Crayon flames.
        val flick = 1f + 0.15f * swing(t, 240)
        if (flames) for ((c, len) in listOf(0xFFFF6A3D to 52f, 0xFFFFC93A to 36f)) {
            drawPath(polygon(-22f, 50f, 0f, 50f + len * flick, 22f, 50f), g(c))
        }
        riders()
        box(g(0xFFA06E3E), -40f, -20f, 40f, 52f, 4f)
        box(g(0xFFC48C54), -40f, -20f, 36f, 48f, 4f)
        // Flaps folded up into a nose cone.
        drawPath(polygon(-40f, -20f, -30f, -36f, -6f, -20f), g(0xFFB27A44))
        drawPath(polygon(40f, -20f, 30f, -36f, 6f, -20f), g(0xFF9A6438))
        // Drawn-on details: a round window, stars and a crayon stripe.
        dot(g(0xFFFFFFFF), 0f, 12f, 11f)
        dot(g(0xFF5AB4E8), 0f, 12f, 8.5f)
        oval(Color.White.copy(alpha = 0.6f), -3f, 9f, 3f, 2f)
        stick(g(0xFFE8574A), -36f, 36f, 32f, 36f, 3f)
        translate(-24f, -4f) { scale(5f, 5f, Offset.Zero) { drawPath(starPath(0.45f), g(0xFFFFD447)) } }
        translate(24f, 26f) { scale(4f, 4f, Offset.Zero) { drawPath(starPath(0.45f), g(0xFFFFD447)) } }
        // Fins.
        drawPath(polygon(-40f, 22f, -58f, 54f, -40f, 50f), g(0xFFE8574A))
        drawPath(polygon(40f, 22f, 58f, 54f, 40f, 50f), g(0xFFC23338))
    }
}

/** A thought bubble from ([fromX], [fromY]) up to a cloud around ([cx], [cy]), [content] drawn inside. */
internal fun DrawScope.thought(fromX: Float, fromY: Float, cx: Float, cy: Float, r: Float, content: DrawScope.() -> Unit) {
    val white = Color.White.copy(alpha = 0.92f)
    dot(white, fromX, fromY, 3f)
    dot(white, (fromX * 2 + cx) / 3f, (fromY * 2 + cy + r) / 3f, 5f)
    dot(white, (fromX + cx * 2) / 3f, (fromY + (cy + r) * 2) / 3f, 7f)
    for (k in 0..7) {
        val a = k / 8f * 6.283f
        dot(white, cx + kotlin.math.cos(a) * r * 0.75f, cy + kotlin.math.sin(a) * r * 0.55f, r * 0.42f)
    }
    oval(white, cx, cy, r, r * 0.72f)
    content()
}

/** A big full moon at ([cx], [cy]). */
internal fun DrawScope.moon(cx: Float, cy: Float, r: Float, g: SceneGrade) {
    drawGlow(Offset(cx, cy), r * 2.6f, g(Color(0x55FFF2C4)))
    dot(g(0xFFFFF4D2), cx, cy, r)
    dot(g(0xFFEDE0B8), cx - r * 0.3f, cy - r * 0.2f, r * 0.22f)
    dot(g(0xFFEDE0B8), cx + r * 0.35f, cy + r * 0.3f, r * 0.16f)
    dot(g(0xFFEDE0B8), cx + r * 0.1f, cy - r * 0.45f, r * 0.1f)
}

/** Glittering blue Martian ice at ([cx], [ground]). */
internal fun DrawScope.ice(cx: Float, ground: Float, g: SceneGrade, t: Float) {
    val light = g(0xFFDDF6FF)
    val mid = g(0xFF9EDCF5)
    drawPath(polygon(cx - 14f, ground, cx - 10f, ground - 26f, cx - 2f, ground), mid)
    drawPath(polygon(cx - 6f, ground, cx + 2f, ground - 36f, cx + 9f, ground), light)
    drawPath(polygon(cx + 5f, ground, cx + 13f, ground - 20f, cx + 17f, ground), mid)
    val tw = 0.5f + 0.5f * swing(t, 50)
    drawSparkle(Offset(cx + 2f, ground - 38f), 6f * tw + 2f, Color.White)
}

/** A little airplane crossing the sky at ([x], [y]). */
internal fun DrawScope.plane(x: Float, y: Float, g: SceneGrade) {
    oval(g(0xFFFFFFFF), x, y, 18f, 5f)
    drawPath(polygon(x - 2f, y, x + 6f, y - 14f, x + 10f, y), g(0xFFE8574A))
    drawPath(polygon(x - 16f, y, x - 18f, y - 9f, x - 11f, y), g(0xFFE8574A))
    for (k in 0..2) dot(g(0xFF5AB4E8), x - 6f + k * 6f, y - 1f, 1.5f)
    stick(Color.White.copy(alpha = 0.6f), x - 22f, y, x - 70f, y + 4f, 2f)
}

/** A paper-lantern glow at ([x], [y]). */
internal fun DrawScope.lantern(x: Float, y: Float, g: SceneGrade, t: Float) {
    val glow = 0.75f + 0.25f * swing(t, 70)
    drawGlow(Offset(x, y), 40f, g(Color(0x88FFD27A)).copy(alpha = 0.7f * glow))
    box(g(0xFF6B4A2E), x - 6f, y - 10f, x + 6f, y + 10f, 3f)
    oval(g(0xFFFFE6A0).copy(alpha = glow), x, y, 4f, 6f)
    stick(g(0xFF6B4A2E), x, y - 10f, x, y - 16f, 1.5f)
}
