package io.colorsand.ui.arena

import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.animateFloat
import androidx.compose.animation.core.infiniteRepeatable
import androidx.compose.animation.core.rememberInfiniteTransition
import androidx.compose.animation.core.tween
import androidx.compose.runtime.Composable
import androidx.compose.runtime.State
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.geometry.RoundRect
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.drawscope.DrawScope
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.floor
import kotlin.math.hypot
import kotlin.math.sin

// Shared pieces of the arena scenes: the clock, seamless motion, and shapes more than one scene draws.

internal const val TAU = (2 * PI).toFloat()

/** One loop of a scene's ambient motion. Everything moves in whole cycles per loop, so the loop never jumps. */
private const val LOOP_MS = 120_000

/** The scene's one clock: runs from 0 to 1 over a two-minute loop, forever. Read it only while drawing. */
@Composable
internal fun rememberSceneClock(): State<Float> =
    rememberInfiniteTransition(label = "scene").animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(LOOP_MS, easing = LinearEasing)),
        label = "clock",
    )

/** A sine over the loop at clock [t]: [cycles] whole swings per loop (about [cycles] / 120 per second). */
internal fun swing(t: Float, cycles: Int, phase: Float = 0f): Float = sin(TAU * (t * cycles + phase))

/** How far along a drift is at clock [t] when it crosses [laps] times per loop, from [start]: 0 until 1. */
internal fun drift(t: Float, laps: Int, start: Float = 0f): Float {
    val v = start + t * laps
    return v - floor(v)
}

/** A small repeatable random source, so scattered details land in the same place every time. */
internal class SceneRandom(seed: Int) {
    private var state = seed.toLong() * 0x5DEECE66DL + 11

    /** The next number in 0 until 1. */
    fun next(): Float {
        state = (state * 0x5DEECE66DL + 0xBL) and ((1L shl 48) - 1)
        return (state ushr 24).toFloat() / (1L shl 24).toFloat()
    }

    /** The next number in [from] until [to]. */
    fun next(from: Float, to: Float): Float = from + next() * (to - from)
}

/**
 * A rolling skyline: hills or dunes seen from the side, as a height for every x across [width].
 * [base] is the lowest line, [rise] the most a crest gets above it; [waves] and [phase] shape the roll.
 */
internal class Ridge(
    private val width: Float,
    private val base: Float,
    private val rise: Float,
    private val waves: Float,
    private val phase: Float,
) {
    /** The ridge's y at [x]. */
    fun y(x: Float): Float {
        val p = x / width
        val roll = 0.65f * sin(TAU * (p * waves + phase)) + 0.35f * sin(TAU * (p * waves * 2.3f + phase * 1.7f))
        return base - rise * (0.5f + 0.5f * roll)
    }

    /** The ridge filled down to [bottom]. */
    fun fill(bottom: Float): Path = Path().apply {
        moveTo(-1f, y(0f))
        line()
        lineTo(width + 1f, bottom)
        lineTo(-1f, bottom)
        close()
    }

    /** Only the ridge line, to stroke a rim of light along it. */
    fun line(): Path = Path().apply {
        moveTo(-1f, y(0f))
        line()
    }

    private fun Path.line() {
        val steps = 48
        for (i in 1..steps) {
            val x = width * i / steps
            lineTo(x, y(x))
        }
    }
}

/** A puffy cloud [width] wide, sitting on y = 0 and centered on x = 0: overlapping puffs with a flat base. */
internal fun cloudPath(width: Float, puffs: Int, random: SceneRandom): Path = Path().apply {
    val r = width / (puffs + 1)
    for (i in 0 until puffs) {
        val x = -width / 2 + r + i * (width - 2 * r) / (puffs - 1).coerceAtLeast(1)
        // Taller in the middle, lower at the ends.
        val middle = 1f - abs(i - (puffs - 1) / 2f) / puffs
        val radius = r * (0.9f + 0.7f * middle) * random.next(0.85f, 1.15f)
        addOval(Rect(Offset(x, -radius * 0.9f), radius))
    }
    addRoundRect(RoundRect(-width / 2 + r * 0.3f, -r * 0.9f, width / 2 - r * 0.3f, 0f, r * 0.45f, r * 0.45f))
}

/** A soft round glow of [color] around [center], fading out at [radius]. */
internal fun DrawScope.drawGlow(center: Offset, radius: Float, color: Color) {
    drawCircle(
        Brush.radialGradient(
            0f to color,
            0.35f to color.copy(alpha = color.alpha * 0.45f),
            1f to color.copy(alpha = 0f),
            center = center,
            radius = radius,
        ),
        radius,
        center,
    )
}

/** Darkens the corners a little so the eye settles on the middle. */
internal fun vignette(width: Float, height: Float, color: Color): Brush = Brush.radialGradient(
    0.55f to color.copy(alpha = 0f),
    1f to color,
    center = Offset(width / 2, height * 0.48f),
    radius = hypot(width, height) * 0.58f,
)
