/**
 * One illustrated panel of the story: its line of [text] and its picture, painted in the W x H panel box over
 * [setting]'s scenery. The [art] gets the scene grade, the scene clock t and the panel's entrance p, which runs
 * from 0 to 1 over the first second the panel shows (Mo popping up, a rocket lifting off).
 */
internal class Panel(val text: String, val setting: Setting, val art: DrawScope.(g: SceneGrade, t: Float, p: Float) -> Unit)

/** The panels [show] plays, in order. */
internal fun panelsOf(show: StoryShow): List<Panel> =
    if (show.beats.isEmpty()) listOf(nextDay) else show.beats.flatMap { panels(it) }

/** The title over each of [show]'s panels: a show can run from one arena's closing into the next one's opening. */
internal fun titlesOf(show: StoryShow): List<String> =
    if (show.beats.isEmpty()) listOf("Day ${show.day}") else show.beats.flatMap { beat -> panels(beat).map { "Sunny & Mo: " + placeName(beat.arena) } }

/** Where an arena's story happens, as it reads in a title. */
private fun placeName(arena: Arena): String = if (arena == Arena.MARS) arena.title else "the ${arena.title}"


/** The panels of one story beat: three or four each. */
internal fun panels(beat: StoryBeat): List<Panel> = when (beat.arena) {
    Arena.PLAYGROUND -> if (beat.beat == Beat.OPENING) playgroundOpening else playgroundClosing
    Arena.BEACH -> if (beat.beat == Beat.OPENING) beachOpening else beachClosing
    Arena.SEA_FLOOR -> if (beat.beat == Beat.OPENING) seaOpening else seaClosing
    Arena.DESERT -> if (beat.beat == Beat.OPENING) desertOpening else desertClosing
    Arena.BUILDING_SITE -> if (beat.beat == Beat.OPENING) siteOpening else siteClosing
    Arena.MARS -> if (beat.beat == Beat.OPENING) marsOpening else marsClosing
}

// Motion helpers: a happy hop, a back-out pop for things appearing.

private fun hop(t: Float, phase: Float = 0f, height: Float = 14f) = abs(swing(t, 70, phase)) * height

private fun pop(p: Float): Float {
    val x = p.coerceIn(0f, 1f) - 1f
    return 1f + 2.7f * x * x * x + 1.7f * x * x
}

private fun ease(p: Float): Float {
    val x = 1f - p.coerceIn(0f, 1f)
    return 1f - x * x * x
}

/** A little heart around ([x], [y]). */
private fun DrawScope.heart(x: Float, y: Float, s: Float, color: Color) {
    val path = Path().apply {
        moveTo(x, y + s * 0.9f)
        cubicTo(x - s * 1.6f, y - s * 0.2f, x - s * 0.7f, y - s * 1.4f, x, y - s * 0.4f)
        cubicTo(x + s * 0.7f, y - s * 1.4f, x + s * 1.6f, y - s * 0.2f, x, y + s * 0.9f)
        close()
    }
    drawPath(path, color)
}

/** Hearts floating up from ([x], [y]). */
private fun DrawScope.hearts(x: Float, y: Float, g: SceneGrade, t: Float) {
    for (k in 0..2) {
        val p = io.colorsand.ui.arena.drift(t, 20, k / 3f)
        heart(x + swing(t, 30, k * 0.3f) * 8f + (k - 1) * 14f, y - p * 50f, 5f + k, g(0xFFFF7A95).copy(alpha = 1f - p))
    }
}

/** A yellow "!" over someone's head at ([x], [y]). */
private fun DrawScope.surprise(x: Float, y: Float, g: SceneGrade) {
    stick(g(0xFFFFC93A), x, y - 22f, x, y - 6f, 5f)
    dot(g(0xFFFFC93A), x, y + 2f, 3f)
}

/** A suitcase with travel stickers, [w] wide, standing at ([cx], [ground]). */
private fun DrawScope.suitcase(cx: Float, ground: Float, w: Float, g: SceneGrade) {
    val h = w * 0.75f
    stick(g(0xFF5A3A24), cx - w * 0.18f, ground - h - 6f, cx + w * 0.18f, ground - h - 6f, 3f)
    stick(g(0xFF5A3A24), cx - w * 0.18f, ground - h - 6f, cx - w * 0.18f, ground - h, 3f)
    stick(g(0xFF5A3A24), cx + w * 0.18f, ground - h - 6f, cx + w * 0.18f, ground - h, 3f)
    box(g(0xFF9A4A2E), cx - w / 2f, ground - h, cx + w / 2f, ground, 6f)
    box(g(0xFFC9643A), cx - w / 2f, ground - h, cx + w / 2f - 3f, ground - 3f, 6f)
    dot(g(0xFFFFD447), cx - w * 0.2f, ground - h * 0.55f, w * 0.12f)
    box(g(0xFF6EC2E8), cx + w * 0.05f, ground - h * 0.7f, cx + w * 0.32f, ground - h * 0.4f, 2f)
}

