package io.colorsand.ui.minigame

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import io.colorsand.core.KeepsakeGame
import io.colorsand.core.Minigame
import io.colorsand.ui.GameController
import io.colorsand.ui.fx.Feedback

/** The keepsake games built so far. The keepsakes of the others stay decorative until theirs is. */
private val built = setOf(
    Minigame.TREASURE_DIG,
    Minigame.CATCH_THE_GRAINS,
    Minigame.MEMORY,
    Minigame.SAND_ART,
    Minigame.COLOR_MIXER,
    Minigame.HIDE_AND_SEEK,
    Minigame.SNOWBALL_TOSS,
    Minigame.ROCKET_PATH,
    Minigame.SAND_FLOW,
    Minigame.DIG_DEEPER,
    Minigame.STACK,
    Minigame.SORT,
    Minigame.BUBBLE_POP,
    Minigame.GEM_MATCH,
)

/** Whether this keepsake's game is built and can be played. */
val KeepsakeGame.isPlayable: Boolean get() = game in built

/**
 * Level [level]'s keepsake game, if it is built and can be opened now (see [GameController.canPlayKeepsake]):
 * what a tap on the keepsake or the level-complete card's button opens.
 */
fun GameController.playableKeepsake(level: Int): KeepsakeGame? =
    if (level < 1 || !canPlayKeepsake(level)) null else KeepsakeGame.forLevel(level).takeIf { it.isPlayable }

/** One round of [keepsake]'s game, which calls [onFinished] once it is played to the end. */
@Composable
internal fun MinigameContent(keepsake: KeepsakeGame, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier) {
    when (keepsake.game) {
        Minigame.TREASURE_DIG -> TreasureDigGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.CATCH_THE_GRAINS -> CatchTheGrainsGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.MEMORY -> KeepsakeMemoryGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.SAND_ART -> SandArtGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.COLOR_MIXER -> ColorMixerGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.HIDE_AND_SEEK -> HideAndSeekGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.SNOWBALL_TOSS -> SandTossGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.ROCKET_PATH -> RocketPathGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.SAND_FLOW -> SandFlowGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.DIG_DEEPER -> DigDeeperGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.STACK -> StackGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.SORT -> SortGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.BUBBLE_POP -> BubblePopGame(keepsake.arena, seed, feedback, onFinished, modifier)
        Minigame.GEM_MATCH -> GemMatchGame(keepsake.arena, seed, feedback, onFinished, modifier)
    }
}
