package io.colorsand.ui.minigame

import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** What the tower is built of: bucket-molded sand on the Beach, pallets of bricks on the Building Site. */
internal enum class StackKind { SAND, BRICKS }

/**
 * The look of Stack the castle in one arena: the [kind] of tower, the sky ([skyTop] to [skyBottom]), the [far] band
 * behind (the sea, the town) and its [farLight] edge, the ground ([groundLight], [ground], [groundShade]), the
 * pieces ([light], [block], [shade], [dark], with [mortar] between bricks), what holds the swinging piece ([holder],
 * [holderLight], [holderDark] on a [line]), the [wood] of the pallets and pulley (and its [woodDark] shade), the [flag] on top, and what the line under the game says.
 */
internal class StackLook(
    val arena: Arena,
    val kind: StackKind,
    val skyTop: Color,
    val skyBottom: Color,
    val far: Color,
    val farLight: Color,
    val groundLight: Color,
    val ground: Color,
    val groundShade: Color,
    val light: Color,
    val block: Color,
    val shade: Color,
    val dark: Color,
    val mortar: Color,
    val holder: Color,
    val holderLight: Color,
    val holderDark: Color,
    val line: Color,
    val wood: Color,
    val woodDark: Color,
    val flag: Color,
    val start: String,
    val perfect: String,
    val trimmed: String,
    val done: String,
) {
    /** What one piece is called in a sentence. */
    val piece: String get() = if (kind == StackKind.SAND) "sand block" else "pallet of bricks"

    companion object {
        /** [arena]'s look, its colors through [g]. Arenas without a Stack game get the Beach's. */
        fun of(arena: Arena, g: SceneGrade): StackLook = when (arena) {
            Arena.BUILDING_SITE -> StackLook(
                Arena.BUILDING_SITE, StackKind.BRICKS,
                g(0xFF8FC6EE), g(0xFFE4F1F8), g(0xFFAFBCCB), g(0xFFD6DEE7),
                g(0xFFD9CBB4), g(0xFFB9A88A), g(0xFF8E8676),
                g(0xFFE58A62), g(0xFFC9583A), g(0xFFA4442C), g(0xFF7A3020), g(0xFFE2D8C8),
                g(0xFFFFC21F), g(0xFFFFDE6A), g(0xFFD0921A), g(0xFF3B3F46),
                g(0xFFC98A4B), g(0xFF8E5A2E),
                g(0xFFFF8A1F),
                "Tap to drop the bricks on the tower!",
                "Perfect! Right on top.",
                "A few chips fell off. Keep building!",
                "Ten floors! The builder waves hello!",
            )
            else -> StackLook(
                Arena.BEACH, StackKind.SAND,
                g(0xFF7FCBF2), g(0xFFDDF3FC), g(0xFF2FA8D0), g(0xFFBFF0F5),
                g(0xFFFFF5DC), g(0xFFF3DFB2), g(0xFFD8BC86),
                g(0xFFFFE6B0), g(0xFFEBCB8C), g(0xFFCFA866), g(0xFF9A7446), g(0xFFB89260),
                g(0xFFE8494E), g(0xFFFF8A80), g(0xFFB0303A), g(0xFF8C6A48),
                g(0xFFC2AE92), g(0xFF8C7963),
                g(0xFFE8494E),
                "Tap to drop the sand on the castle!",
                "Perfect! Right on top.",
                "A little sand fell off. Keep stacking!",
                "Ten blocks tall! Up goes the flag!",
            )
        }
    }
}

/**
 * Where Stack the castle sits in a [width] x [height] canvas, in pixels. The round's 0 to 1 widths map onto a
 * [span] wide strip from [left]; pieces are [piece] tall and the foundation [base] tall. The ground is at [groundY]
 * before the camera rises. The swinging piece's top hangs [gap] over the tower's top, but never higher than
 * [hangTop]: once the tower reaches [topTarget], the camera rises instead.
 */
internal class StackLayout(val width: Float, val height: Float) {
    val span: Float = minOf(width, height * 0.66f)
    val left: Float = (width - span) / 2
    val piece: Float = span * 0.105f
    val base: Float = piece * 1.35f
    val groundY: Float = height * 0.91f
    val hangTop: Float = height * 0.17f

    val gap: Float = piece * 3.4f

    /** Where the tower's top should stand on screen once it is tall enough: the camera rises to keep it there. */
    val topTarget: Float = hangTop + piece + gap

    /** Where the swinging piece's top hangs over a tower whose top is at [towerTop] on screen. */
    fun hangOver(towerTop: Float): Float = maxOf(hangTop, towerTop - gap - piece)

    fun x(x: Float): Float = left + x * span

    /** The world height of the bottom of piece [index] (0 is the foundation). */
    fun bottomOf(index: Int): Float = if (index == 0) 0f else base + (index - 1) * piece

    fun heightOf(index: Int): Float = if (index == 0) base else piece

    /** How far the camera has to rise for a tower whose top is at world height [top]. */
    fun cameraFor(top: Float, target: Float = topTarget): Float = maxOf(0f, top - (groundY - target))

    /** The screen y of world height [h] with the camera risen by [camera], for scenery moving at [parallax]. */
    fun y(h: Float, camera: Float, parallax: Float = 1f): Float = groundY + camera * parallax - h
}
