/**
 * The Building Site: a sunny construction site. A clear blue sky with a city skyline far back, a yellow tower
 * crane whose hook sways with a bundle of steel beams, a half-built frame in scaffolding, piles of sand and
 * gravel, cones and a striped barricade with a blinking amber lamp, and a row of concrete barriers along the
 * gravel ground at the bottom. Dust drifts over the site.
 */
@Composable
internal fun BuildingSiteScene(grade: SceneGrade, modifier: Modifier = Modifier) {
    val clock = rememberSceneClock()
    Spacer(
        modifier.drawWithCache {
            val art = BuildingSiteArt(size, grade)
            onDrawBehind { art.draw(this, clock) }
        },
    )
}

/** Everything the Building Site draws, built once per size and grade; [draw] only moves it. */
private class BuildingSiteArt(size: Size, private val g: SceneGrade) {
    private val w = size.width
    private val h = size.height
    private val u = min(w, h * 0.6f)

    private val horizonY = h * 0.735f
    private val haze = Color(0xFFF2E8D6)
    private fun far(c: Long, amount: Float) = g(lerp(Color(c), haze, amount))

    private val sky = Brush.verticalGradient(
        0f to g(0xFF2C82D4), 0.3f to g(0xFF58AAE6), 0.55f to g(0xFF9DD0F0), 0.68f to g(0xFFD6EAEE), 0.735f to g(haze),
        startY = 0f, endY = h,
    )

    // A warm sun in the top-right corner.
    private val sunCenter = Offset(w * 0.92f, h * 0.045f)
    private val sunCore = g(0xFFFFF9E2)
    private val sunGlow = g(0xFFFFEBB0)

    private class Cloud(val path: Path, val y: Float, val width: Float, val start: Float, val laps: Int, val alpha: Float)

    private val clouds = SceneRandom(29).let { r ->
        listOf(
            Cloud(cloudPath(u * 0.2f, 4, r), h * 0.265f, u * 0.2f, 0.7f, 1, 0.55f),
            Cloud(cloudPath(u * 0.32f, 6, r), h * 0.145f, u * 0.32f, 0.2f, 2, 0.85f),
            Cloud(cloudPath(u * 0.26f, 5, r), h * 0.075f, u * 0.26f, 0.55f, 2, 0.8f),
        )
    }
    private val cloudWhite = g(0xFFFFFFFF)
    private val cloudShade = g(0xFFC8DCEE)

    // The city far back: two rows of towers, the farther paler, some in warmer stone, with a few lit windows.
    private class Skyline(val body: Path, val warm: Path, val windows: Path)

    private fun skyline(seed: Int, low: Float, high: Float): Skyline {
        val r = SceneRandom(seed)
        val body = Path()
        val warm = Path()
        val windows = Path()
        var x = -u * r.next(0f, 0.04f)
        while (x < w) {
            val bw = u * r.next(0.035f, 0.075f)
            // Now and then a tower stands out over the rest.
            val top = horizonY - u * r.next(low, high) * (if (r.next() < 0.15f) 1.6f else 1f)
            (if (r.next() < 0.35f) warm else body).addRect(Rect(x, top, x + bw, horizonY + 1f))
            when ((r.next() * 5).toInt()) {
                0 -> body.addRect(Rect(x + bw * 0.45f, top - u * 0.03f, x + bw * 0.55f, top)) // a mast
                1 -> body.addRect(Rect(x + bw * 0.15f, top - u * 0.012f, x + bw * 0.85f, top)) // a stepped top
                else -> Unit
            }
            val cell = u * 0.011f
            var wy = top + cell
            while (wy < horizonY - cell) {
                var wx = x + cell * 0.7f
                while (wx < x + bw - cell) {
                    if (r.next() < 0.3f) windows.addRect(Rect(wx, wy, wx + cell * 0.5f, wy + cell * 0.55f))
                    wx += cell
                }
                wy += cell * 1.3f
            }
            x += bw + u * r.next(0f, 0.03f)
        }
        return Skyline(body, warm, windows)
    }

    private val farCity = skyline(53, 0.06f, 0.15f)
    private val nearCity = skyline(59, 0.025f, 0.08f)
    private val farCityColor = far(0xFF8FA9C6, 0.5f)
    private val nearCityColor = far(0xFF7C95B4, 0.36f)
    private val farCityWarm = far(0xFFB3A3A6, 0.5f)
    private val nearCityWarm = far(0xFFA48E8C, 0.36f)
    private val windowColor = g(Color(0x40FFFFFF))
    private val farCrane = Path().apply {
        // Another tower crane far off over the city.
        val x = w * 0.56f
        val top = horizonY - u * 0.25f
        moveTo(x, horizonY); lineTo(x, top)
        moveTo(x - u * 0.05f, top + u * 0.012f); lineTo(x + u * 0.16f, top + u * 0.012f)
        moveTo(x - u * 0.05f, top + u * 0.012f); lineTo(x, top - u * 0.02f); lineTo(x + u * 0.16f, top + u * 0.012f)
        moveTo(x + u * 0.12f, top + u * 0.012f); lineTo(x + u * 0.12f, top + u * 0.07f)
    }
    private val horizonHaze = Brush.verticalGradient(
        0f to Color.Transparent, 0.7f to g(haze.copy(alpha = 0.6f)), 1f to g(haze.copy(alpha = 0.2f)),
        startY = horizonY - u * 0.07f, endY = horizonY + 1f,
    )

    // The site's ground: dusty earth with low mounds, toward a gravel yard in front.
    private val moundRidge = Ridge(w, horizonY + u * 0.008f, u * 0.018f, 2.3f, 0.2f)
    private val mounds = moundRidge.fill(h)
    private val moundColor = far(0xFFD9BE8E, 0.35f)
    private val ground = Brush.verticalGradient(
        0f to far(0xFFDCC294, 0.25f), 1f to g(0xFFC9A877), startY = horizonY, endY = h * 0.86f,
    )

    // The half-built frame on the right: two concrete floors, a steel skeleton above, scaffolding on its left.
    private val frameBase = h * 0.8f
    private val floor = u * 0.072f
    private val frameRight = w - u * 0.05f
    private val frameLeft = frameRight - max(u * 0.29f, w * 0.2f) // wider on wide screens
    private val bays = max(3, ((frameRight - frameLeft) / (u * 0.095f)).toInt())
    private val bay = (frameRight - frameLeft) / bays
    private val concrete = far(0xFFC9C6C0, 0.12f)
    private val concreteLit = far(0xFFE6E3DC, 0.1f)
    private val concreteShade = far(0xFF9E9A94, 0.12f)
    private val steel = far(0xFFC9553A, 0.15f)
    private val steelDark = far(0xFF8E3A2A, 0.15f)
    private val brick = far(0xFFC77A55, 0.15f)
    private val mortar = far(0xFFE8C9A8, 0.15f)
    private val rebar = far(0xFF6F5A4C, 0.15f)
    private val brickLines = Path().apply {
        val top = frameBase - floor
        val course = u * 0.009f
        var y = top + u * 0.012f + course
        var row = 0
        while (y < frameBase) {
            moveTo(frameLeft, y); lineTo(frameLeft + bay, y)
            var x = frameLeft + if (row % 2 == 0) u * 0.012f else u * 0.024f
            while (x < frameLeft + bay) {
                moveTo(x, y - course); lineTo(x, y)
                x += u * 0.024f
            }
            y += course
            row++
        }
    }
    private val scaffoldLeft = frameLeft - u * 0.075f
    private val scaffoldPole = far(0xFFB7C1CB, 0.1f)
    private val scaffoldBrace = far(0xFF8C98A6, 0.1f)
    private val plankColor = far(0xFFD9A35E, 0.1f)
    private val plankEdge = far(0xFFA8733A, 0.1f)
    private val netColor = g(Color(0x554FAF62))
    private val frameShadow = Color.Black.copy(alpha = 0.1f)

    // The tower crane on the left.
    private val mastX = u * 0.12f
    private val mastHalf = u * 0.02f
    private val jibY = h * 0.19f
    private val jibDepth = u * 0.026f
    private val jibTip = mastX + min(w - u * 0.12f, u * 0.88f)
    private val counterEnd = mastX - u * 0.2f
    private val apex = Offset(mastX, jibY - jibDepth - u * 0.085f)
    private val craneYellow = far(0xFFF6B72A, 0.1f)
    private val craneShade = far(0xFFCF8A16, 0.1f)
    private val cableColor = far(0xFF3E3A3A, 0.15f)
    private val lattice = Path().apply {
        // The mast's legs run on up through the jib to the A-frame; the bracing stops under the slewing ring.
        val top = jibY + u * 0.04f
        moveTo(mastX - mastHalf, frameBase); lineTo(mastX - mastHalf, jibY - jibDepth)
        moveTo(mastX + mastHalf, frameBase); lineTo(mastX + mastHalf, jibY - jibDepth)
        moveTo(mastX - mastHalf, top); lineTo(mastX + mastHalf, top)
        moveTo(mastX - mastHalf, top); lineTo(mastX + mastHalf, jibY)
        moveTo(mastX - mastHalf, jibY - jibDepth); lineTo(mastX + mastHalf, jibY - jibDepth)
        val step = mastHalf * 2.2f
        var y = frameBase
        var left = true
        moveTo(mastX - mastHalf, y)
        while (y - step > top) {
            y -= step
            lineTo(if (left) mastX + mastHalf else mastX - mastHalf, y)
            left = !left
        }
        // The jib: a truss tapering toward its tip, and the counter-jib behind the mast.
        moveTo(counterEnd, jibY); lineTo(jibTip, jibY)
        moveTo(counterEnd, jibY - jibDepth * 0.5f); lineTo(mastX, jibY - jibDepth)
        lineTo(jibTip, jibY - jibDepth * 0.35f)
        val jStep = jibDepth * 1.3f
        var x = mastX
        var up = true
        moveTo(x, jibY)
        while (x + jStep < jibTip) {
            x += jStep
            val f = (x - mastX) / (jibTip - mastX)
            lineTo(x, if (up) jibY - jibDepth * (1f - 0.65f * f) else jibY)
            up = !up
        }
        // The A-frame on top of the mast.
        moveTo(mastX - mastHalf, jibY - jibDepth); lineTo(apex.x, apex.y); lineTo(mastX + mastHalf, jibY - jibDepth)
    }
    private val pendants = Path().apply {
        moveTo(counterEnd + u * 0.02f, jibY - jibDepth * 0.5f); lineTo(apex.x, apex.y)
        lineTo(mastX + (jibTip - mastX) * 0.62f, jibY - jibDepth * 0.6f)
    }
    private val trolleyHome = mastX + (jibTip - mastX) * 0.68f
    private val drop = h * 0.045f
    private val beamLength = u * 0.15f

    // Mid-ground props: a sand pile, a gravel pile, cones and a striped barricade.
    private val sandPile = pile(w * 0.28f, h * 0.838f, u * 0.25f, u * 0.065f)
    private val sandLit = g(0xFFF0C77E)
    private val sandShade = g(0xFFC99A55)
    private val gravelPile = pile(w * 0.6f, h * 0.84f, u * 0.2f, u * 0.05f)
    private val gravelLit = g(0xFFB4B0AA)
    private val gravelShade = g(0xFF85817C)
    private class Stones(val color: Color, val size: Float, val points: List<Offset>)

    private val gravelStones = SceneRandom(61).let { r ->
        val cx = w * 0.6f
        val base = h * 0.84f
        List(3) { k ->
            val color = listOf(g(0xFF6B6763), g(0xFFD3D0CA), g(0xFF9A948C))[k]
            Stones(color, u * (0.006f - 0.001f * k), List(36) {
                val x = r.next(-1f, 1f)
                Offset(cx + x * u * 0.095f, base - u * 0.05f * (1f - x * x) * r.next(0.05f, 0.95f))
            })
        }
    }
    private fun pile(cx: Float, base: Float, width: Float, height: Float) = Path().apply {
        moveTo(cx - width / 2, base)
        cubicTo(cx - width * 0.3f, base - height * 0.2f, cx - width * 0.12f, base - height, cx + width * 0.02f, base - height)
        cubicTo(cx + width * 0.16f, base - height, cx + width * 0.32f, base - height * 0.25f, cx + width / 2, base)
        close()
    }
    private val shovelHandle = far(0xFF8A5A33, 0f)
    private val shovelBlade = g(0xFF6E7884)

    // The site office: a blue cabin with a window, a door and a sign.
    private val cabinX = w * 0.36f
    private val cabinBase = h * 0.818f
    private val cabinW = u * 0.17f
    private val cabinH = u * 0.075f
    private val cabinBlue = g(0xFF3F86C9)
    private val cabinDark = g(0xFF2C5F92)
    private val cabinRibs = Path().apply {
        var x = cabinX + u * 0.008f
        while (x < cabinX + cabinW) {
            moveTo(x, cabinBase - cabinH + u * 0.008f); lineTo(x, cabinBase - u * 0.004f)
            x += u * 0.008f
        }
    }
    private val glass = g(0xFFBFE4F7)

    private class Cone(val at: Offset, val size: Float)

    private val cones = listOf(
        Cone(Offset(w * 0.43f, h * 0.835f), u * 0.04f),
        Cone(Offset(w * 0.47f, h * 0.84f), u * 0.034f),
        Cone(Offset(w - u * 0.38f, h * 0.832f), u * 0.036f),
    )
    private val coneOrange = g(0xFFFF6B2C)
    private val coneDark = g(0xFFD9481A)
    private val coneWhite = g(0xFFF8F4EE)
    private val coneBase = g(0xFF3B3A3E)
    private val cone = Path().apply {
        moveTo(-0.28f, 0f); lineTo(-0.08f, -1f); lineTo(0.08f, -1f); lineTo(0.28f, 0f); close()
    }

    private val barricadeX = w * 0.12f
    private val barricadeY = h * 0.83f
    private val barricadeW = u * 0.17f
    private val barricadeBoard = Path().apply {
        addRoundRect(RoundRect(0f, 0f, barricadeW, u * 0.022f, CornerRadius(u * 0.004f)))
    }
    private val barricadeStripes = stripes(0f, 0f, barricadeW, u * 0.022f, u * 0.022f)
    private val red = g(0xFFE2412F)
    private val white = g(0xFFF7F3EC)
    private val legColor = g(0xFF5C5B60)
    private val amber = g(0xFFFFB31F)
    private val amberCore = g(0xFFFFF0B8)

    // The kerb: a row of concrete barriers with a reflective stripe, across the front, and the gravel yard below it.
    private val kerbTop = h * 0.855f
    private val kerb = u * 0.028f
    private val kerbFace = g(0xFFB9B5AE)
    private val kerbLit = g(0xFFE4E0D8)
    private val kerbStripe = g(0xFFF7C12C)
    private val kerbJoins = Path().apply {
        val segment = u * 0.24f
        var x = segment * 0.6f
        while (x < w) {
            addRect(Rect(x - u * 0.002f, kerbTop - kerb * 0.3f, x + u * 0.002f, kerbTop + kerb))
            x += segment
        }
    }
    private val yard = Brush.verticalGradient(
        0f to g(0xFFC4B9A6), 0.15f to g(0xFFD7CDB9), 1f to g(0xFFC9BCA5), startY = kerbTop + kerb, endY = h,
    )
    private val yardStones = SceneRandom(67).let { r ->
        val top = kerbTop + kerb * 1.4f
        listOf(g(Color(0x55635C52)), g(Color(0x66FFFFFF)), g(Color(0x40877C6E))).mapIndexed { k, c ->
            Stones(c, u * (0.007f - 0.0015f * k), List(70) { Offset(w * r.next(), r.next(top, h)) })
        }
    }
    private val tracks = Path().apply {
        // Two soft tyre ruts sweeping across the yard.
        for (k in 0..1) {
            val y0 = kerbTop + kerb * 2.4f + k * u * 0.045f
            moveTo(-u * 0.05f, y0)
            cubicTo(w * 0.35f, y0 - u * 0.01f, w * 0.65f, y0 + (h - kerbTop) * 0.25f, w + u * 0.05f, y0 + (h - kerbTop) * 0.45f)
        }
    }
    private val trackColor = g(Color(0x1A5A4A38))

    // Dust puffs drifting over the site.
    private class Puff(val y: Float, val radius: Float, val laps: Int, val start: Float)

    private val puffs = SceneRandom(71).let { r ->
        List(9) { Puff(h * r.next(0.74f, 0.9f), u * r.next(0.03f, 0.07f), 2 + (r.next() * 3).toInt(), r.next()) }
    }
    private val dust = Brush.radialGradient(
        0f to g(Color(0x66F4E6C8)), 0.5f to g(Color(0x30F4E6C8)), 1f to Color.Transparent, center = Offset.Zero, radius = 1f,
    )

    private val shade = vignette(w, h, g(Color(0x38283648)))

    /** Diagonal stripes filling the box from [left], [top] to [right], [bottom], each [stripe] wide. */
    private fun stripes(left: Float, top: Float, right: Float, bottom: Float, stripe: Float) = Path().apply {
        val tall = bottom - top
        var x = left - tall
        while (x < right) {
            moveTo(x, bottom); lineTo(x + stripe, bottom); lineTo(x + stripe + tall, top); lineTo(x + tall, top); close()
            x += stripe * 2
        }
    }

    fun draw(scope: DrawScope, clock: State<Float>) = with(scope) {
        val t = clock.value
        drawRect(sky)
        drawGlow(sunCenter, u * 0.8f, sunGlow.copy(alpha = 0.6f))
        drawGlow(sunCenter, u * 0.16f, sunCore)
        drawCircle(sunCore, u * 0.06f, sunCenter)

        for (c in clouds) {
            val x = -c.width + drift(t, c.laps, c.start) * (w + 2 * c.width)
            translate(x, c.y) {
                translate(0f, c.width * 0.05f) { drawPath(c.path, cloudShade, alpha = c.alpha * 0.8f) }
                drawPath(c.path, cloudWhite, alpha = c.alpha)
            }
        }

        drawPath(farCity.body, farCityColor)
        drawPath(farCity.warm, farCityWarm)
        drawPath(farCity.windows, windowColor)
        drawPath(farCrane, farCityColor, style = Stroke(u * 0.004f))
        drawPath(nearCity.body, nearCityColor)
        drawPath(nearCity.warm, nearCityWarm)
        drawPath(nearCity.windows, windowColor)
        drawRect(horizonHaze, Offset(0f, horizonY - u * 0.07f), Size(w, u * 0.07f + 1f))
        drawRect(ground, Offset(0f, horizonY), Size(w, h - horizonY))
        drawPath(mounds, moundColor)

        drawFrame()
        drawCrane(t)
        drawCabin()
        drawPiles()
        drawBarricade(t)
        for (c in cones) drawCone(c)
        drawYard()
        drawDust(t)
        drawRect(shade)
    }

    private fun DrawScope.drawFrame() {
        drawOval(frameShadow, Offset(scaffoldLeft - u * 0.02f, frameBase - u * 0.012f), Size(frameRight - scaffoldLeft + u * 0.06f, u * 0.03f))
        val col = u * 0.013f
        val slab = u * 0.012f
        // Ground floor: a bay of brick infill on the left, open bays to the right.
        drawRect(brick, Offset(frameLeft, frameBase - floor), Size(bay, floor))
        drawPath(brickLines, mortar, style = Stroke(u * 0.0018f))
        // Steel skeleton on floors three and four, behind the concrete slabs.
        val steelTop = frameBase - 4 * floor
        for (i in 0..bays) {
            val x = frameLeft + i * bay
            drawRect(steel, Offset(x - col * 0.35f, steelTop), Size(col * 0.7f, 2 * floor))
            drawRect(steelDark, Offset(x + col * 0.15f, steelTop), Size(col * 0.2f, 2 * floor))
        }
        for (k in 3..4) {
            val y = frameBase - k * floor
            drawRect(steel, Offset(frameLeft - col * 0.4f, y), Size(frameRight - frameLeft + col * 0.8f, slab * 0.7f))
            drawRect(steelDark, Offset(frameLeft - col * 0.4f, y + slab * 0.5f), Size(frameRight - frameLeft + col * 0.8f, slab * 0.2f))
        }
        // A cross brace in the middle bay.
        val bx = frameLeft + bay
        drawLine(steelDark, Offset(bx, frameBase - 2 * floor), Offset(bx + bay, steelTop + slab), u * 0.004f)
        drawLine(steelDark, Offset(bx + bay, frameBase - 2 * floor), Offset(bx, steelTop + slab), u * 0.004f)
        // Concrete columns and slabs on the lower two floors, with rebar sticking up from the upper ones.
        for (i in 0..bays) {
            val x = frameLeft + i * bay
            drawRect(concrete, Offset(x - col / 2, frameBase - 2 * floor), Size(col, 2 * floor))
            drawRect(concreteLit, Offset(x + col * 0.15f, frameBase - 2 * floor), Size(col * 0.35f, 2 * floor))
        }
        for (k in 1..2) {
            val y = frameBase - k * floor
            drawRect(concreteShade, Offset(frameLeft - col, y + slab * 0.6f), Size(frameRight - frameLeft + 2 * col, slab * 0.5f))
            drawRect(concrete, Offset(frameLeft - col, y - slab * 0.2f), Size(frameRight - frameLeft + 2 * col, slab * 0.8f))
            drawRect(concreteLit, Offset(frameLeft - col, y - slab * 0.2f), Size(frameRight - frameLeft + 2 * col, slab * 0.25f))
        }
        // Scaffolding: two poles, a plank at each floor, a diagonal brace and a green safety net over the top bays.
        val poles = listOf(scaffoldLeft, scaffoldLeft + u * 0.045f)
        val top = frameBase - 4 * floor - u * 0.02f
        drawRect(netColor, Offset(poles[0], top), Size(poles[1] - poles[0], 2 * floor))
        for (x in poles) drawLine(scaffoldPole, Offset(x, frameBase), Offset(x, top), u * 0.005f)
        for (k in 1..4) {
            val y = frameBase - k * floor + u * 0.012f
            drawLine(scaffoldBrace, Offset(poles[0] - u * 0.004f, y - u * 0.012f), Offset(frameLeft, y - u * 0.012f), u * 0.003f)
            drawRect(plankEdge, Offset(poles[0] - u * 0.006f, y - u * 0.004f), Size(frameLeft - poles[0] + u * 0.004f, u * 0.008f))
            drawRect(plankColor, Offset(poles[0] - u * 0.006f, y - u * 0.006f), Size(frameLeft - poles[0] + u * 0.004f, u * 0.004f))
        }
        drawLine(scaffoldBrace, Offset(poles[0], frameBase), Offset(poles[1], frameBase - 2 * floor), u * 0.003f)
        drawLine(scaffoldBrace, Offset(poles[1], frameBase - 2 * floor), Offset(poles[0], frameBase - 4 * floor), u * 0.003f)
        // Rebar ends poking out of the top concrete columns.
        for (i in 0..bays) {
            val x = frameLeft + i * bay
            for (d in listOf(-0.3f, 0.3f)) drawLine(rebar, Offset(x + col * d, frameBase - 2 * floor), Offset(x + col * d, frameBase - 2 * floor - u * 0.018f), u * 0.002f)
        }
    }

    private fun DrawScope.drawCrane(t: Float) {
        // The foundation block, then the steel.
        drawRect(concreteShade, Offset(mastX - mastHalf * 2.2f, frameBase - u * 0.02f), Size(mastHalf * 4.4f, u * 0.024f))
        drawRect(concrete, Offset(mastX - mastHalf * 2.2f, frameBase - u * 0.02f), Size(mastHalf * 4.4f, u * 0.008f))
        drawPath(lattice, craneShade, style = Stroke(u * 0.008f, cap = StrokeCap.Round, join = StrokeJoin.Round))
        drawPath(lattice, craneYellow, style = Stroke(u * 0.0052f, cap = StrokeCap.Round, join = StrokeJoin.Round))
        drawPath(pendants, cableColor, style = Stroke(u * 0.0022f))
        // Counterweights hanging at the back of the counter-jib.
        for (k in 0..2) {
            val x = counterEnd + u * 0.012f + k * u * 0.022f
            drawRect(concreteShade, Offset(x, jibY + u * 0.002f), Size(u * 0.02f, u * 0.042f))
            drawRect(concrete, Offset(x, jibY + u * 0.002f), Size(u * 0.014f, u * 0.042f))
        }
        // The cab below the jib, by the mast.
        val cab = Offset(mastX + mastHalf, jibY + u * 0.004f)
        drawRoundRect(craneShade, cab, Size(u * 0.05f, u * 0.042f), CornerRadius(u * 0.006f))
        drawRoundRect(craneYellow, cab, Size(u * 0.046f, u * 0.038f), CornerRadius(u * 0.006f))
        drawRoundRect(g(0xFF9FD3F2), cab + Offset(u * 0.016f, u * 0.006f), Size(u * 0.026f, u * 0.018f), CornerRadius(u * 0.003f))
        drawLine(Color.White.copy(alpha = 0.55f), cab + Offset(u * 0.02f, u * 0.02f), cab + Offset(u * 0.03f, u * 0.008f), u * 0.003f)
        drawBeacon(apex - Offset(0f, u * 0.006f), u * 0.009f, t, 0f)

        // The trolley rolls slowly along the jib; the hook and its load sway below it.
        val trolley = Offset(trolleyHome + u * 0.05f * swing(t, 3), jibY)
        drawRect(cableColor, Offset(trolley.x - u * 0.014f, jibY - u * 0.002f), Size(u * 0.028f, u * 0.01f))
        rotate(swing(t, 9, 0.1f) * 2.6f + swing(t, 23, 0.3f) * 0.6f, trolley) {
            val hook = Offset(trolley.x, trolley.y + drop)
            drawLine(cableColor, trolley + Offset(-u * 0.005f, 0f), hook + Offset(-u * 0.005f, 0f), u * 0.0022f)
            drawLine(cableColor, trolley + Offset(u * 0.005f, 0f), hook + Offset(u * 0.005f, 0f), u * 0.0022f)
            drawRoundRect(craneShade, hook - Offset(u * 0.011f, u * 0.004f), Size(u * 0.022f, u * 0.016f), CornerRadius(u * 0.003f))
            drawRoundRect(craneYellow, hook - Offset(u * 0.011f, u * 0.004f), Size(u * 0.018f, u * 0.012f), CornerRadius(u * 0.003f))
            val eye = hook + Offset(0f, u * 0.016f)
            drawArc(cableColor, 300f, 270f, false, eye - Offset(u * 0.006f, 0f), Size(u * 0.012f, u * 0.012f), style = Stroke(u * 0.003f))
            // Slings down to a bundle of three steel beams.
            val load = eye + Offset(0f, u * 0.04f)
            drawLine(cableColor, eye + Offset(0f, u * 0.006f), load + Offset(-beamLength * 0.32f, 0f), u * 0.0018f)
            drawLine(cableColor, eye + Offset(0f, u * 0.006f), load + Offset(beamLength * 0.32f, 0f), u * 0.0018f)
            val bh = u * 0.011f
            for (k in 0..2) {
                val y = load.y + k * bh
                val x = load.x - beamLength / 2 + (k - 1) * u * 0.004f
                drawRect(steelDark, Offset(x, y), Size(beamLength, bh))
                drawRect(steel, Offset(x, y), Size(beamLength, bh * 0.62f))
                drawRect(steelDark.copy(alpha = 0.6f), Offset(x + beamLength - bh * 0.6f, y), Size(bh * 0.6f, bh))
            }
        }
    }

    private fun DrawScope.drawCabin() {
        val top = cabinBase - cabinH
        drawOval(frameShadow, Offset(cabinX - u * 0.01f, cabinBase - u * 0.008f), Size(cabinW + u * 0.03f, u * 0.016f))
        drawRect(cabinDark, Offset(cabinX, top), Size(cabinW, cabinH))
        drawRect(cabinBlue, Offset(cabinX, top), Size(cabinW - u * 0.006f, cabinH))
        drawPath(cabinRibs, cabinDark.copy(alpha = 0.35f), style = Stroke(u * 0.002f))
        drawRect(white, Offset(cabinX - u * 0.003f, top - u * 0.006f), Size(cabinW + u * 0.006f, u * 0.009f))
        // A window, a door, and a yellow sign over the door.
        drawRect(white, Offset(cabinX + u * 0.018f, top + u * 0.018f), Size(u * 0.06f, u * 0.032f))
        drawRect(glass, Offset(cabinX + u * 0.021f, top + u * 0.021f), Size(u * 0.054f, u * 0.026f))
        drawLine(Color.White.copy(alpha = 0.7f), Offset(cabinX + u * 0.03f, top + u * 0.042f), Offset(cabinX + u * 0.042f, top + u * 0.024f), u * 0.003f)
        drawRect(cabinDark, Offset(cabinX + cabinW - u * 0.05f, top + u * 0.022f), Size(u * 0.026f, cabinH - u * 0.022f))
        drawRect(kerbStripe, Offset(cabinX + cabinW - u * 0.054f, top + u * 0.008f), Size(u * 0.034f, u * 0.01f))
        drawRect(Color.Black.copy(alpha = 0.2f), Offset(cabinX, cabinBase - u * 0.005f), Size(cabinW, u * 0.005f))
    }

    private fun DrawScope.drawPiles() {
        drawPath(sandPile, sandLit)
        clipPath(sandPile) { translate(u * 0.07f, u * 0.012f) { drawPath(sandPile, sandShade, alpha = 0.7f) } }
        // A shovel stuck in the sand.
        val tip = Offset(w * 0.28f - u * 0.04f, h * 0.838f - u * 0.04f)
        drawLine(shovelHandle, tip, tip + Offset(-u * 0.035f, -u * 0.06f), u * 0.006f, StrokeCap.Round)
        drawLine(shovelHandle, tip + Offset(-u * 0.042f, -u * 0.064f), tip + Offset(-u * 0.03f, -u * 0.07f), u * 0.006f, StrokeCap.Round)
        rotate(-30f, tip) { drawRoundRect(shovelBlade, tip - Offset(u * 0.011f, 0f), Size(u * 0.022f, u * 0.024f), CornerRadius(u * 0.006f)) }

        drawPath(gravelPile, gravelLit)
        clipPath(gravelPile) {
            translate(u * 0.06f, u * 0.01f) { drawPath(gravelPile, gravelShade, alpha = 0.7f) }
            for (s in gravelStones) drawPoints(s.points, PointMode.Points, s.color, s.size, StrokeCap.Round)
        }
    }

    private fun DrawScope.drawBarricade(t: Float) {
        val legs = listOf(barricadeX + u * 0.02f, barricadeX + barricadeW - u * 0.02f)
        for (x in legs) {
            drawLine(legColor, Offset(x - u * 0.014f, barricadeY), Offset(x, barricadeY - u * 0.05f), u * 0.005f, StrokeCap.Round)
            drawLine(legColor, Offset(x + u * 0.014f, barricadeY), Offset(x, barricadeY - u * 0.05f), u * 0.005f, StrokeCap.Round)
        }
        drawOval(Color.Black.copy(alpha = 0.1f), Offset(barricadeX - u * 0.01f, barricadeY - u * 0.006f), Size(barricadeW + u * 0.02f, u * 0.012f))
        translate(barricadeX, barricadeY - u * 0.052f) {
            drawPath(barricadeBoard, white)
            clipPath(barricadeBoard) { drawPath(barricadeStripes, red) }
            drawRect(Color.Black.copy(alpha = 0.15f), Offset(0f, u * 0.017f), Size(barricadeW, u * 0.005f))
        }
        drawLine(legColor, Offset(legs[1], barricadeY - u * 0.052f), Offset(legs[1], barricadeY - u * 0.064f), u * 0.004f)
        drawBeacon(Offset(legs[1], barricadeY - u * 0.07f), u * 0.009f, t, 0.5f)
    }

    /** An amber warning lamp at [at] that blinks about once a second; [phase] staggers lamps. */
    private fun DrawScope.drawBeacon(at: Offset, r: Float, t: Float, phase: Float) {
        val on = max(0f, swing(t, 70, phase))
        val glow = on * on
        drawRoundRect(legColor, at + Offset(-r, r * 0.3f), Size(r * 2, r * 0.8f), CornerRadius(r * 0.2f))
        if (glow > 0.02f) drawGlow(at, r * 6f, amber.copy(alpha = 0.55f * glow))
        drawCircle(lerp(g(0xFFC9861A), amber, glow), r, at)
        drawCircle(lerp(amber, amberCore, glow), r * 0.45f, at - Offset(r * 0.2f, r * 0.25f))
    }

    private fun DrawScope.drawCone(c: Cone) {
        val s = c.size
        drawOval(Color.Black.copy(alpha = 0.14f), Offset(c.at.x - s * 0.5f, c.at.y - s * 0.06f), Size(s, s * 0.14f))
        drawRect(coneBase, Offset(c.at.x - s * 0.36f, c.at.y - s * 0.08f), Size(s * 0.72f, s * 0.1f))
        translate(c.at.x, c.at.y - s * 0.07f) {
            scale(s, s * 0.95f, Offset.Zero) {
                drawPath(cone, coneOrange)
                clipPath(cone) {
                    drawRect(coneWhite, Offset(-1f, -0.66f), Size(2f, 0.16f))
                    drawRect(coneWhite, Offset(-1f, -0.34f), Size(2f, 0.14f))
                    drawRect(coneDark, Offset(0.05f, -1f), Size(1f, 1f), alpha = 0.45f)
                }
            }
        }
    }

    private fun DrawScope.drawYard() {
        drawRect(yard, Offset(0f, kerbTop + kerb), Size(w, h - kerbTop - kerb))
        drawPath(tracks, trackColor, style = Stroke(u * 0.022f))
        for (s in yardStones) drawPoints(s.points, PointMode.Points, s.color, s.size, StrokeCap.Round)
        // The kerb: a lit top over a front face with a yellow stripe, joins between barriers, its shadow on the yard.
        drawRect(kerbFace, Offset(0f, kerbTop), Size(w, kerb))
        drawRect(kerbStripe, Offset(0f, kerbTop + kerb * 0.4f), Size(w, kerb * 0.26f))
        drawRect(kerbLit, Offset(0f, kerbTop - kerb * 0.3f), Size(w, kerb * 0.36f))
        drawPath(kerbJoins, Color.Black.copy(alpha = 0.22f))
        drawRect(Color.Black.copy(alpha = 0.12f), Offset(0f, kerbTop + kerb), Size(w, kerb * 0.4f))
    }

    private fun DrawScope.drawDust(t: Float) {
        for (p in puffs) {
            val d = drift(t, p.laps, p.start)
            val x = -p.radius * 2 + d * (w + p.radius * 4)
            // Fade in and out over the crossing.
            val a = max(0f, swing(d, 1, -0.25f) * 0.5f + 0.5f)
            val y = p.y + u * 0.01f * swing(t, 11, p.start)
            translate(x, y) { scale(p.radius * 1.8f, p.radius, Offset.Zero) { drawCircle(dust, 1f, Offset.Zero, alpha = a) } }
        }
    }
}
