package io.colorsand.ui.minigame

import kotlin.random.Random

/**
 * A round of Hide and seek: [hiding] things (by index; 0 is the keepsake itself, the rest its friends) tucked into
 * a scene's hiding [spots], thing i at spot `hiding[i]`. Each look checks one spot, or none for a tap on open
 * scenery. There is no way to lose: after [HINT] empty looks in a row the game shows a hint (see [needsHint]), and
 * [next] finds the next thing outright for players who can't tap the scene. The state is immutable; [look] and
 * [next] return the next one.
 */
data class HideAndSeek(
    val spots: Int,
    val hiding: List<Int>,
    /** The things found so far, as indices into [hiding], in the order they were found. */
    val found: List<Int> = emptyList(),
    /** Empty looks since the last find. */
    val misses: Int = 0,
) {
    init {
        require(hiding.all { it in 0 until spots }) { "Every thing hides at one of the $spots spots: $hiding" }
        require(hiding.toSet().size == hiding.size) { "One thing to a spot: $hiding" }
    }

    val count: Int get() = hiding.size

    val isDone: Boolean get() = found.size == count

    /** Whether the player has looked in vain often enough to be shown where something is. */
    val needsHint: Boolean get() = !isDone && misses >= HINT

    /** The thing still hiding at [spot], or null when the spot is empty or its thing was found. */
    fun hiddenAt(spot: Int): Int? = hiding.indexOf(spot).takeIf { it >= 0 && it !in found }

    /** The things not found yet, in order. */
    fun stillHiding(): List<Int> = hiding.indices.filter { it !in found }

    /** This round after looking at [spot] (null: at no spot at all). Looks after the last find do nothing. */
    fun look(spot: Int?): HideAndSeek {
        if (isDone) return this
        val here = spot?.let(::hiddenAt) ?: return copy(misses = misses + 1)
        return copy(found = found + here, misses = 0)
    }

    /** This round with the next thing still hiding found: the keepsake first, then its friends in order. */
    fun next(): HideAndSeek = stillHiding().firstOrNull()?.let { look(hiding[it]) } ?: this

    /** The thing still hiding whose spot is the nearest by [distance], or null once everything is found. */
    fun nearestHidden(distance: (spot: Int) -> Float): Int? = stillHiding().minByOrNull { distance(hiding[it]) }

    companion object {
        /** Empty looks in a row before a hint. */
        const val HINT = 3

        /** A new round with [count] things hidden in different ones of [spots] spots, the same for the same [seed]. */
        fun start(seed: Int, spots: Int, count: Int = 5): HideAndSeek {
            require(count <= spots) { "$count things can't hide in $spots spots" }
            return HideAndSeek(spots, (0 until spots).shuffled(Random(seed)).take(count))
        }
    }
}
