// The drawing of Rocket path: the backdrop scrolling by in layers, the ground left behind at the start, the goal at
// the end, the rings (or reef gaps), sparkles and drifting things on the course, and the keepsake flying it. Course
// positions go through [PathLayout]; [t] is the round's time in seconds.

private const val TAU = (2 * PI).toFloat()
private val star = starPath(0.46f)

/** A little burst where a sparkle was collected, a ring flown through or something bumped, at [at] seconds. */
internal class PathPop(val x: Float, val d: Float, val at: Float, val big: Boolean)

/** How long a burst lasts, in seconds. */
internal const val PATH_POP_S = 0.6f

/** The backdrop, its colors shifting from the start toward the goal, with its scenery drifting by in layers. */
internal fun DrawScope.drawPathBackdrop(look: PathLook, layout: PathLayout, round: RocketPath, t: Float) {
    val w = layout.width
    val h = layout.height
    val u = layout.unit
    val p = round.progress
    drawRect(Brush.verticalGradient(listOf(lerp(look.lowTop, look.highTop, p), lerp(look.lowBottom, look.highBottom, p)), 0f, h), Offset.Zero, Size(w, h))
    val travel = round.travel
    when (look.scene) {
        PathScene.SKY -> {
            // Far clouds drift by slowly, near ones faster; streaks of breeze curl past.
            layer(layout, travel, 0.35f, 7, 1) { c, k, r -> skyCloud(c, (0.55f + 0.25f * r.next()) * u, 0.45f) }
            layer(layout, travel, 0.8f, 4, 2) { c, k, r -> skyCloud(c, (1f + 0.4f * r.next()) * u, 0.8f) }
            layer(layout, travel, 1.1f, 6, 3) { c, k, _ ->
                val sway = sin(t * 0.9f + k) * 3f * u
                val path = Path().apply {
                    moveTo(c.x - 9f * u + sway, c.y)
                    cubicTo(c.x - 3f * u + sway, c.y - 1.6f * u, c.x + 3f * u + sway, c.y + 1.6f * u, c.x + 8f * u + sway, c.y - 0.4f * u)
                    quadraticTo(c.x + 11f * u + sway, c.y - 2f * u, c.x + 9f * u + sway, c.y - 3.4f * u)
                }
                drawPath(path, Color.White.copy(alpha = 0.45f), style = Stroke(0.7f * u, cap = StrokeCap.Round))
            }
        }
        PathScene.REEF -> {
            // Sunbeams slanting down through the water.
            for (k in 0 until 4) {
                val x = w * (0.1f + 0.28f * k) + sin(t * 0.3f + k * 1.7f) * 4f * u
                val beam = Path().apply {
                    moveTo(x, 0f)
                    lineTo(x + 9f * u, 0f)
                    lineTo(x + 26f * u, h)
                    lineTo(x + 8f * u, h)
                    close()
                }
                drawPath(beam, Brush.verticalGradient(listOf(Color.White.copy(alpha = 0.13f), Color.White.copy(alpha = 0f)), 0f, h))
            }
            // Far reef walls at the sides, then kelp waving along the edges, then specks drifting in the water.
            layer(layout, travel, 0.45f, 6, 4) { c, k, r ->
                val x = if (k % 2 == 0) r.next(-0.05f, 0.08f) * w else r.next(0.92f, 1.05f) * w
                val color = lerp(look.lowBottom, look.highBottom, 0.3f).copy(alpha = 0.45f)
                drawOval(color, Offset(x - 12f * u, c.y - 16f * u), Size(24f * u, 32f * u))
            }
            layer(layout, travel, 1f, 6, 5) { c, k, r ->
                val x = if (k % 2 == 0) r.next(0f, 0.06f) * w else r.next(0.94f, 1f) * w
                kelp(Offset(x, c.y), 30f * u, t + k, u, lerp(Color(0xFF3F9A5A), look.lowBottom, 0.25f))
            }
            layer(layout, travel, 0.7f, 18, 6) { c, k, _ ->
                drawCircle(Color.White.copy(alpha = 0.25f), (0.3f + (k % 3) * 0.15f) * u, c + Offset(sin(t * 0.7f + k) * 1.5f * u, 0f))
            }
        }
        PathScene.SPACE -> {
            // Stars in three layers, the nearer ones brighter, twinkling; they fade in as the sky darkens.
            val dark = (0.25f + p * 0.75f)
            for ((layerIndex, f) in listOf(0.12f, 0.3f, 0.6f).withIndex()) {
                layer(layout, travel, f, 22, 7 + layerIndex) { c, k, _ ->
                    val tw = 0.6f + 0.4f * sin(t * (1.3f + layerIndex) + k * 2.1f)
                    drawCircle(Color.White.copy(alpha = dark * tw * (0.45f + 0.25f * layerIndex)), (0.25f + 0.18f * layerIndex) * u, c)
                }
            }
        }
    }
    drawStartGround(look, layout, round, t)
}

/**
 * Scenery repeating up the course in a band as tall as the screen and a bit: [count] pieces placed by [seed],
 * scrolling at [factor] times the course's speed, each drawn by [piece] at its center.
 */
private inline fun DrawScope.layer(
    layout: PathLayout,
    travel: Float,
    factor: Float,
    count: Int,
    seed: Int,
    piece: DrawScope.(Offset, Int, SceneRandom) -> Unit,
) {
    val w = layout.width
    val band = layout.height / w + 0.7f
    val r = SceneRandom(seed * 31 + 5)
    for (k in 0 until count) {
        val x = r.next()
        val base = r.next() * band
        val v = base - travel * factor
        val along = v - floor(v / band) * band
        val y = layout.height + 0.35f * w - along * w
        piece(Offset(x * w, y), k, r)
    }
}

/** The ground the keepsake set off from, sliding away below as the course begins. */
private fun DrawScope.drawStartGround(look: PathLook, layout: PathLayout, round: RocketPath, t: Float) {
    val top = layout.y(-0.15f)
    if (top > layout.height) return
    val w = layout.width
    val h = layout.height
    val u = layout.unit
    val ground = Path().apply {
        moveTo(0f, h + 1f)
        lineTo(0f, top + 6f * u)
        cubicTo(w * 0.3f, top - 3f * u, w * 0.65f, top + 4f * u, w, top - 2f * u)
        lineTo(w, h + 1f)
        close()
    }
    drawRect(look.groundDark, Offset(0f, top + 14f * u), Size(w, maxOf(0f, h - top)))
    drawPath(ground, Brush.verticalGradient(listOf(look.ground, look.groundDark), top - 3f * u, top + 30f * u))
    when (look.scene) {
        PathScene.SKY -> {
            // The lawn with a sandbox and a little tree.
            drawOval(Color(0xFFC99A55), Offset(w * 0.56f, top + 8f * u), Size(34f * u, 9f * u))
            drawOval(Color(0xFFF0CF8E), Offset(w * 0.565f, top + 8.2f * u), Size(32f * u, 7.6f * u))
            drawRect(Color(0xFF8E5A31), Offset(w * 0.12f - 1.4f * u, top - 8f * u), Size(2.8f * u, 14f * u))
            drawCircle(look.groundDark, 9f * u, Offset(w * 0.12f, top - 12f * u))
            drawCircle(look.ground, 7.5f * u, Offset(w * 0.12f - 1.5f * u, top - 13.5f * u))
            for (k in 0 until 8) drawCircle(Color.White, 0.7f * u, Offset(w * (0.08f + k * 0.12f), top + (12f + (k % 3) * 5f) * u))
        }
        PathScene.REEF -> {
            // Sand with corals and a sea star.
            for (k in 0 until 5) {
                val x = w * (0.08f + k * 0.22f)
                val c = listOf(Color(0xFFF27E7E), Color(0xFFFFB35C), Color(0xFFB98AE8))[k % 3]
                for (b in -1..1) drawLine(c, Offset(x, top + 4f * u), Offset(x + b * 3f * u, top - (5f + (k % 2) * 3f - abs1(b)) * u), 1.6f * u, StrokeCap.Round)
                drawCircle(c, 1.2f * u, Offset(x, top - (5f + (k % 2) * 3f) * u))
            }
            translate(w * 0.7f, top + 12f * u) { scale(3.2f * u, 3.2f * u, Offset.Zero) { drawPath(star, Color(0xFFFF8A5C)) } }
        }
        PathScene.SPACE -> {
            // A launch pad with its tower and a few rocks.
            val padX = w * 0.5f
            drawRect(Color(0xFF55606E), Offset(padX - 14f * u, top + 2f * u), Size(28f * u, 3f * u))
            drawRect(Color(0xFF8E97A4), Offset(padX - 14f * u, top + 1.2f * u), Size(28f * u, 1.2f * u))
            drawRect(Color(0xFF8E97A4), Offset(padX + 16f * u, top - 24f * u), Size(2f * u, 26f * u))
            for (k in 0 until 6) drawLine(Color(0xFF8E97A4), Offset(padX + 16f * u, top - (22f - k * 4f) * u), Offset(padX + 18f * u, top - (20f - k * 4f) * u), 0.5f * u)
            drawLine(Color(0xFF8E97A4), Offset(padX + 16f * u, top - 18f * u), Offset(padX + 8f * u, top - 18f * u), 1f * u)
            for (k in 0 until 4) drawOval(look.groundDark, Offset(w * (0.06f + k * 0.26f), top + (8f + k % 2 * 6f) * u), Size(6f * u, 3f * u))
            // A cloud of launch dust, settling.
            val dust = (round.time / 3f).coerceIn(0f, 1f)
            for (k in 0 until 6) {
                val a = PI.toFloat() * (k / 5f)
                drawCircle(lerp(look.ground, Color.White, 0.3f).copy(alpha = 0.5f * (1f - dust)), (4f + 4f * dust) * u, Offset(padX + cos(a) * (8f + 14f * dust) * u, top - sin(a) * 3f * u))
            }
        }
    }
}

private fun abs1(v: Int): Float = if (v == 0) 0f else 1f

/** The goal at the end of the course: a cloud with a smiling sun, a reef cave, or the two moons of Mars. */
internal fun DrawScope.drawPathGoal(look: PathLook, layout: PathLayout, round: RocketPath, t: Float) {
    val gd = RocketPath.LENGTH + RocketPath.GOAL_AHEAD
    if (!layout.shows(gd, 0.9f)) return
    val w = layout.width
    val u = layout.unit
    val c = layout.at(0.5f, gd)
    val glow = round.finale
    when (look.scene) {
        PathScene.SKY -> {
            val sun = c + Offset(10f * u, -22f * u)
            drawGlow(sun, 40f * u, Color(0xFFFFF1B0).copy(alpha = 0.8f))
            rotate(t * 8f, sun) {
                for (k in 0 until 12) {
                    val a = k * TAU / 12
                    drawLine(Color(0xFFFFD447), sun + Offset(cos(a) * 17f * u, sin(a) * 17f * u), sun + Offset(cos(a) * 22f * u, sin(a) * 22f * u), 2f * u, StrokeCap.Round)
                }
            }
            drawCircle(Color(0xFFFFC93A), 14.5f * u, sun)
            drawCircle(Color(0xFFFFE27A), 13f * u, sun - Offset(1f * u, 1f * u))
            drawCircle(Color(0xFF6B4A2E), 1.3f * u, sun + Offset(-4.5f * u, -2f * u))
            drawCircle(Color(0xFF6B4A2E), 1.3f * u, sun + Offset(4.5f * u, -2f * u))
            drawArc(Color(0xFF6B4A2E), 20f, 140f, false, sun + Offset(-5f * u, -2f * u), Size(10f * u, 8f * u), style = Stroke(1.1f * u, cap = StrokeCap.Round))
            drawCircle(Color(0xFFFF8A7A).copy(alpha = 0.5f), 2f * u, sun + Offset(-8f * u, 2f * u))
            drawCircle(Color(0xFFFF8A7A).copy(alpha = 0.5f), 2f * u, sun + Offset(8f * u, 2f * u))
            // The big soft cloud in front of the sun.
            val puffs = listOf(-30f to 6f, -18f to -4f, -4f to -9f, 12f to -6f, 26f to 0f, 36f to 8f, -38f to 10f)
            for ((dx, dy) in puffs) drawCircle(Color(0xFFC9DDF0), 13f * u, c + Offset(dx * u, dy * u + 2f * u))
            for ((dx, dy) in puffs) drawCircle(Color.White, 12.5f * u, c + Offset(dx * u, dy * u))
            drawOval(Color.White, Offset(c.x - 46f * u, c.y), Size(92f * u, 16f * u))
        }
        PathScene.REEF -> {
            // A heap of reef rock with a glowing cave mouth underneath, coral and anemones on top.
            val rock = lerp(look.lowBottom, Color(0xFF7A7396), 0.55f)
            val rockDark = lerp(rock, Color.Black, 0.25f)
            val rockLight = lerp(rock, Color.White, 0.2f)
            val boulders = listOf(Triple(-0.36f, 2f, 17f), Triple(-0.18f, -8f, 20f), Triple(0.02f, -12f, 22f), Triple(0.2f, -6f, 19f), Triple(0.37f, 3f, 16f), Triple(-0.48f, 10f, 12f), Triple(0.48f, 10f, 12f))
            for ((dx, dy, r) in boulders) drawCircle(rockDark, r * u, c + Offset(dx * w, dy * u + 1.5f * u))
            for ((dx, dy, r) in boulders) drawCircle(rock, r * u * 0.96f, c + Offset(dx * w - 0.6f * u, dy * u))
            for ((dx, dy, r) in boulders) drawOval(rockLight, Offset(c.x + dx * w - r * u * 0.6f, c.y + dy * u - r * u * 0.8f), Size(r * u * 0.9f, r * u * 0.45f))
            drawRect(rock, Offset(c.x - 0.48f * w, c.y), Size(0.96f * w, 14f * u))
            drawRect(rockDark, Offset(c.x - 0.48f * w, c.y + 14f * u), Size(0.96f * w, 2f * u))
            drawGlow(c + Offset(0f, 6f * u), 24f * u, look.ringLight.copy(alpha = 0.3f + 0.5f * glow))
            drawOval(Color(0xFF0A1E33), Offset(c.x - 14f * u, c.y - 6f * u), Size(28f * u, 22f * u))
            drawOval(Color(0xFF14324F), Offset(c.x - 11f * u, c.y - 2f * u), Size(22f * u, 16f * u))
            drawGlow(c + Offset(0f, 5f * u), 9f * u, Color(0xFFFFE9A8).copy(alpha = 0.35f + 0.5f * glow))
            for (k in 0 until 7) {
                val x = c.x + (k - 3f) * 0.13f * w
                val y = c.y - (if (k in 2..4) 30f else 22f) * u + (k % 2) * 3f * u
                val color = listOf(Color(0xFFF27E7E), Color(0xFFFFB35C), Color(0xFFB98AE8))[k % 3]
                for (b in -1..1) {
                    val sway = sin(t * 1.2f + k + b) * 1f * u
                    drawLine(color, Offset(x, y + 4f * u), Offset(x + b * 3.5f * u + sway, y - 6f * u), 1.6f * u, StrokeCap.Round)
                    drawCircle(lerp(color, Color.White, 0.25f), 1.1f * u, Offset(x + b * 3.5f * u + sway, y - 6f * u))
                }
            }
        }
        PathScene.SPACE -> {
            val phobos = layout.at(0.32f, gd + 0.12f)
            val deimos = layout.at(0.74f, gd + 0.34f)
            drawGlow(phobos, 34f * u, Color(0xFFFFE2C4).copy(alpha = 0.22f + 0.3f * glow))
            moon(phobos, 19f * u, Color(0xFFF0DCC8), Color(0xFFB89C86), 11)
            drawGlow(deimos, 20f * u, Color(0xFFFFE2C4).copy(alpha = 0.18f + 0.3f * glow))
            moon(deimos, 10f * u, Color(0xFFF5E6D6), Color(0xFFC2A994), 5)
        }
    }
}

/** A lumpy moon of radius [r] at [c] with a few craters, its far side in shade. */
private fun DrawScope.moon(c: Offset, r: Float, lit: Color, shade: Color, seed: Int) {
    val shape = Path().apply {
        val rr = SceneRandom(seed)
        for (k in 0..12) {
            val a = k * TAU / 12
            val rad = r * rr.next(0.96f, 1.03f)
            val p = c + Offset(cos(a) * rad, sin(a) * rad * 0.9f)
            if (k == 0) moveTo(p.x, p.y) else lineTo(p.x, p.y)
        }
        close()
    }
    drawCircle(Color.White.copy(alpha = 0.18f), r * 1.12f, c)
    drawPath(shape, shade)
    translate(-r * 0.12f, -r * 0.1f) { scale(0.9f, 0.9f, c) { drawPath(shape, lit) } }
    val rr = SceneRandom(seed + 1)
    for (k in 0 until 4) {
        val a = rr.next() * TAU
        val d = rr.next(0.1f, 0.6f) * r
        val cr = rr.next(0.1f, 0.22f) * r
        val p = c + Offset(cos(a) * d, sin(a) * d)
        drawCircle(shade, cr, p)
        drawCircle(lerp(shade, Color.Black, 0.15f), cr * 0.75f, p + Offset(cr * 0.15f, cr * 0.15f))
    }
}

/** The far half of every ring (or the reef gaps' rocks), behind the keepsake. */
internal fun DrawScope.drawGatesBehind(look: PathLook, layout: PathLayout, round: RocketPath, t: Float) {
    for (gate in round.gates) {
        if (!layout.shows(gate.d, 0.2f)) continue
        val c = layout.at(gate.x, gate.d)
        val flash = gate.passedAt?.let { ((round.time - it) / 0.8f).coerceIn(0f, 1f) }
        when (look.scene) {
            PathScene.REEF -> reefGap(look, layout, gate, c, t, flash)
            else -> ringHalf(look, layout, c, flash, back = true)
        }
    }
}

/** The near half of every ring, in front of the keepsake, so it flies through. */
internal fun DrawScope.drawGatesFront(look: PathLook, layout: PathLayout, round: RocketPath) {
    if (look.scene == PathScene.REEF) return
    for (gate in round.gates) {
        if (!layout.shows(gate.d, 0.2f)) continue
        val flash = gate.passedAt?.let { ((round.time - it) / 0.8f).coerceIn(0f, 1f) }
        ringHalf(look, layout, layout.at(gate.x, gate.d), flash, back = false)
    }
}

private fun DrawScope.ringHalf(look: PathLook, layout: PathLayout, c: Offset, flash: Float?, back: Boolean) {
    val u = layout.unit
    val rx = layout.len(RocketPath.GATE_HALF_WIDTH) * 1.05f
    val ry = rx * 0.36f
    val topLeft = Offset(c.x - rx, c.y - ry)
    val size = Size(2 * rx, 2 * ry)
    val start = if (back) 180f else 0f
    val done = flash != null
    val color = if (done) lerp(look.ring, Color(0xFFFFD447), 0.6f) else look.ring
    if (look.scene == PathScene.SPACE) {
        drawArc(look.ring.copy(alpha = 0.25f), start, 180f, false, topLeft, size, style = Stroke(4.5f * u))
    }
    if (flash != null && flash < 1f && !back) drawGlow(c, rx * 1.3f, Color(0xFFFFF1B0).copy(alpha = 0.7f * (1f - flash)))
    drawArc(lerp(color, Color.Black, 0.25f), start, 180f, false, topLeft.copy(y = topLeft.y + 0.5f * u), size, style = Stroke(2.4f * u, cap = StrokeCap.Round))
    drawArc(color, start, 180f, false, topLeft, size, style = Stroke(2.2f * u, cap = StrokeCap.Round))
    // Light bands on the hoop.
    for (k in 0 until 4) {
        drawArc(look.ringLight, start + 12f + k * 44f, 14f, false, topLeft, size, style = Stroke(1.1f * u, cap = StrokeCap.Round))
    }
}

/** Two coral-topped rocks with the gap to swim through between them. */
private fun DrawScope.reefGap(look: PathLook, layout: PathLayout, gate: PathGate, c: Offset, t: Float, flash: Float?) {
    val u = layout.unit
    val gap = layout.len(RocketPath.GATE_HALF_WIDTH)
    val rock = lerp(look.lowBottom, Color(0xFF7A7396), 0.55f)
    val rockLight = lerp(rock, Color.White, 0.22f)
    for (side in listOf(-1f, 1f)) {
        val rc = c + Offset(side * (gap + 7f * u), 0f)
        drawOval(lerp(rock, Color.Black, 0.25f), Offset(rc.x - 8f * u, rc.y - 5f * u), Size(16f * u, 11f * u))
        drawOval(rock, Offset(rc.x - 7.5f * u, rc.y - 6f * u), Size(15f * u, 10f * u))
        drawOval(rockLight, Offset(rc.x - 5.5f * u, rc.y - 5.6f * u), Size(9f * u, 4f * u))
        val coral = if ((gate.id + side.toInt()) % 2 == 0) look.ring else Color(0xFFB98AE8)
        for (b in -1..1) {
            val sway = sin(t * 1.4f + gate.id + b) * 0.8f * u
            val tip = rc + Offset(b * 3f * u + sway, -11f * u + abs1(b) * 2.5f * u)
            drawLine(coral, rc + Offset(b * 1.2f * u, -4f * u), tip, 1.5f * u, StrokeCap.Round)
            drawCircle(lerp(coral, Color.White, 0.3f), 1.1f * u, tip)
        }
    }
    // A faint ring of light across the gap, and a burst of bubbles once swum through.
    val lit = flash?.let { 1f - it } ?: 0f
    drawLine(look.ringLight.copy(alpha = 0.3f + 0.6f * lit), c - Offset(gap - 1f * u, 0f), c + Offset(gap - 1f * u, 0f), 0.6f * u, StrokeCap.Round)
    if (flash != null && flash < 1f) {
        for (k in 0 until 8) {
            val x = c.x + (k - 3.5f) * gap / 4f
            drawCircle(Color.White.copy(alpha = 0.8f * (1f - flash)), (0.8f + (k % 3) * 0.35f) * u, Offset(x, c.y - flash * (6f + (k % 3) * 4f) * u), style = Stroke(0.35f * u))
        }
    }
}

/** The sparkles still to collect: stars, bubbles or twinkles of stardust. */
internal fun DrawScope.drawPathSparkles(look: PathLook, layout: PathLayout, round: RocketPath, t: Float) {
    val u = layout.unit
    for (s in round.sparkles) {
        if (s.collectedAt != null || !layout.shows(s.d, 0.1f)) continue
        val c = layout.at(s.x, s.d)
        when (look.scene) {
            PathScene.SKY -> {
                drawGlow(c, 6f * u, look.sparkle.copy(alpha = 0.45f))
                translate(c.x, c.y) {
                    rotate(sin(t * 2f + s.id) * 14f, Offset.Zero) {
                        val r = 3.3f * u
                        scale(r, r, Offset.Zero) { drawPath(star, lerp(look.sparkle, Color(0xFFE7A91C), 0.4f)) }
                        scale(r * 0.82f, r * 0.82f, Offset.Zero) { drawPath(star, look.sparkle) }
                    }
                }
                drawCircle(Color.White.copy(alpha = 0.8f), 0.6f * u, c - Offset(0.9f * u, 1.1f * u))
            }
            PathScene.REEF -> {
                val wob = sin(t * 3f + s.id) * 0.25f * u
                val r = 2.6f * u + wob
                drawCircle(look.sparkle.copy(alpha = 0.18f), r, c)
                drawCircle(look.sparkle.copy(alpha = 0.9f), r, c, style = Stroke(0.5f * u))
                drawOval(Color.White.copy(alpha = 0.85f), Offset(c.x - r * 0.6f, c.y - r * 0.65f), Size(r * 0.6f, r * 0.4f))
            }
            PathScene.SPACE -> {
                val tw = 0.75f + 0.25f * sin(t * 4f + s.id * 1.3f)
                val color = if (s.id % 3 == 0) Color(0xFFFFB3D9) else look.sparkle
                drawGlow(c, 6f * u, color.copy(alpha = 0.5f * tw))
                drawSparkle(c, 3.2f * u * tw, color)
                drawCircle(Color.White, 0.7f * u, c)
            }
        }
    }
}

/** The things drifting on the course: balloons, jellyfish or little asteroids, tilting as they are pushed aside. */
internal fun DrawScope.drawPathObstacles(look: PathLook, layout: PathLayout, round: RocketPath, t: Float) {
    val u = layout.unit
    for (o in round.obstacles) {
        if (!layout.shows(o.d, 0.25f)) continue
        val c = layout.at(o.x, o.d)
        val r = layout.len(o.radius)
        val tilt = o.drift * 50f + o.offset * 25f
        when (look.scene) {
            PathScene.SKY -> {
                val colors = listOf(look.thing, Color(0xFF3E8EE0), Color(0xFF4DBA6A), Color(0xFFB98AE8))
                val color = colors[o.id % colors.size]
                val bob = sin(t * 1.4f + o.id) * 1f * u
                rotate(tilt, c) {
                    val b = c + Offset(0f, bob)
                    val string = Path().apply {
                        moveTo(b.x, b.y + r * 1.15f)
                        for (k in 1..6) lineTo(b.x + sin(t * 2f + k + o.id) * 1f * u, b.y + r * 1.15f + k * 2.5f * u)
                    }
                    drawPath(string, Color.White.copy(alpha = 0.7f), style = Stroke(0.35f * u))
                    drawPath(Path().apply {
                        moveTo(b.x, b.y + r * 1.0f)
                        lineTo(b.x - 1.2f * u, b.y + r * 1.15f + 0.8f * u)
                        lineTo(b.x + 1.2f * u, b.y + r * 1.15f + 0.8f * u)
                        close()
                    }, lerp(color, Color.Black, 0.25f))
                    drawOval(lerp(color, Color.Black, 0.22f), Offset(b.x - r * 0.88f, b.y - r * 1.05f), Size(r * 1.8f, r * 2.15f))
                    drawOval(color, Offset(b.x - r * 0.9f, b.y - r * 1.1f), Size(r * 1.7f, r * 2.05f))
                    drawOval(Color.White.copy(alpha = 0.5f), Offset(b.x - r * 0.55f, b.y - r * 0.8f), Size(r * 0.45f, r * 0.7f))
                }
            }
            PathScene.REEF -> {
                val pulse = 1f + 0.08f * sin(t * 2.4f + o.id)
                rotate(tilt, c) {
                    for (k in 0 until 4) {
                        val x0 = c.x + (k - 1.5f) * r * 0.42f
                        val path = Path().apply {
                            moveTo(x0, c.y)
                            for (s in 1..6) lineTo(x0 + sin(t * 2.5f + s * 0.9f + k) * 0.9f * u, c.y + s * r * 0.3f)
                        }
                        drawPath(path, look.thingDark.copy(alpha = 0.75f), style = Stroke(0.55f * u, cap = StrokeCap.Round))
                    }
                    val dome = Path().apply {
                        moveTo(c.x - r * pulse, c.y + r * 0.1f)
                        cubicTo(c.x - r * pulse, c.y - r * 1.25f, c.x + r * pulse, c.y - r * 1.25f, c.x + r * pulse, c.y + r * 0.1f)
                        for (k in 0..5) {
                            val x = c.x + r * pulse - (k + 0.5f) * 2f * r * pulse / 6f
                            quadraticTo(x + r * pulse / 6f, c.y + r * 0.35f, x - r * pulse / 6f, c.y + r * 0.1f)
                        }
                        close()
                    }
                    drawPath(dome, look.thing.copy(alpha = 0.8f))
                    drawOval(Color.White.copy(alpha = 0.4f), Offset(c.x - r * 0.55f, c.y - r * 0.75f), Size(r * 0.5f, r * 0.3f))
                    drawCircle(look.thingDark.copy(alpha = 0.5f), r * 0.25f, c - Offset(0f, r * 0.25f))
                }
            }
            PathScene.SPACE -> {
                val spin = o.id * 40f + t * 12f + o.offset * 300f
                rotate(spin, c) {
                    val rr = SceneRandom(o.id + 3)
                    val shape = Path().apply {
                        for (k in 0..9) {
                            val a = k * TAU / 10
                            val rad = r * rr.next(0.78f, 1.05f)
                            if (k == 0) moveTo(c.x + cos(a) * rad, c.y + sin(a) * rad) else lineTo(c.x + cos(a) * rad, c.y + sin(a) * rad)
                        }
                        close()
                    }
                    drawPath(shape, look.thingDark)
                    translate(-r * 0.1f, -r * 0.1f) { scale(0.88f, 0.88f, c) { drawPath(shape, look.thing) } }
                    drawCircle(look.thingDark, r * 0.22f, c + Offset(r * 0.25f, -r * 0.15f))
                    drawCircle(look.thingDark, r * 0.14f, c + Offset(-r * 0.35f, r * 0.3f))
                }
            }
        }
    }
}

/** Bursts where sparkles were collected, rings flown through and things bumped. */
internal fun DrawScope.drawPathPops(look: PathLook, layout: PathLayout, pops: List<PathPop>, t: Float) {
    val u = layout.unit
    for (pop in pops) {
        val age = ((t - pop.at) / PATH_POP_S).coerceIn(0f, 1f)
        val c = layout.at(pop.x, pop.d)
        val n = if (pop.big) 8 else 5
        for (k in 0 until n) {
            val a = k * TAU / n + pop.at
            val d = (2f + (if (pop.big) 12f else 7f) * age) * u
            drawSparkle(c + Offset(cos(a) * d, sin(a) * d), (1.6f * (1f - age) + 0.3f) * u, look.sparkle.copy(alpha = 1f - age))
        }
    }
}

/**
 * The keepsake flying the course, banking into its turns: the kite on its string, the turtle swimming up, or the
 * rocket on its flame. It shrinks a little as it reaches the goal. [sceneT] is the scene clock for its own motion.
 */
internal fun DrawScope.drawPathKeepsake(look: PathLook, layout: PathLayout, round: RocketPath, grade: SceneGrade, t: Float, sceneT: Float) {
    val u = layout.unit
    val c = layout.at(round.x, round.shipD)
    val size = layout.len(0.34f) * (1f - 0.3f * round.finale)
    val k = size / 100f
    val bank = (round.vx * 30f).coerceIn(-22f, 22f)
    when (look.scene) {
        PathScene.SKY -> {
            // The string runs down to someone flying it, far below.
            val string = Path().apply {
                moveTo(c.x - 1f * u, c.y + 2f * u)
                quadraticTo(c.x - 8f * u + sin(t) * 2f * u, (c.y + layout.height) / 2f, layout.width * 0.42f, layout.height + 2f)
            }
            drawPath(string, Color.White.copy(alpha = 0.8f), style = Stroke(0.4f * u))
            rotate(bank, c) {
                translate(c.x - 50f * k, c.y - 40f * k) { scale(k, k, Offset.Zero) { kiteAloft(sceneT, grade, 50f, 40f) } }
            }
        }
        PathScene.REEF -> {
            // A trail of little bubbles behind it.
            for (b in 0 until 4) {
                val age = ((t * 0.9f + b * 0.25f) % 1f)
                drawCircle(Color.White.copy(alpha = 0.6f * (1f - age)), (0.6f + 0.4f * b % 2) * u, c + Offset(sin(t * 3f + b) * 1.5f * u, (8f + age * 14f) * u), style = Stroke(0.3f * u))
            }
            rotate(-90f + bank, c) {
                translate(c.x - 50f * k, c.y - 62f * k) { scale(k, k, Offset.Zero) { seaTurtle(sceneT, grade, swimming = true) } }
            }
        }
        PathScene.SPACE -> {
            rotate(bank, c) {
                // The flame, flickering under the nozzle, and puffs trailing below.
                val nozzle = Offset(c.x, c.y + 40f * k)
                val flick = 1f + 0.18f * sin(t * 31f) + 0.1f * sin(t * 47f)
                for (p in 0 until 4) {
                    val age = (t * 1.4f + p * 0.25f) % 1f
                    drawCircle(Color.White.copy(alpha = 0.3f * (1f - age)), (2f + 4f * age) * u, nozzle + Offset(sin(p * 2.3f) * 3f * u * age, (6f + 26f * age) * u))
                }
                val flame = Path().apply {
                    moveTo(nozzle.x - 5f * k * 1.2f, nozzle.y)
                    quadraticTo(nozzle.x - 4f * k, nozzle.y + 18f * k * flick, nozzle.x, nozzle.y + 26f * k * flick)
                    quadraticTo(nozzle.x + 4f * k, nozzle.y + 18f * k * flick, nozzle.x + 5f * k * 1.2f, nozzle.y)
                    close()
                }
                drawGlow(nozzle + Offset(0f, 8f * k), 18f * k, Color(0xFFFFB347).copy(alpha = 0.6f))
                drawPath(flame, Color(0xFFFF7A2E))
                scale(0.55f, 0.6f, nozzle) { drawPath(flame, Color(0xFFFFE27A)) }
                translate(c.x - 50f * k, c.y - 45f * k) { scale(k, k, Offset.Zero) { rocket(sceneT, grade, flying = true) } }
            }
        }
    }
}

/** A thin track down the right edge showing how far up the course the keepsake is, with the goal at the top. */
internal fun DrawScope.drawPathProgress(look: PathLook, layout: PathLayout, round: RocketPath) {
    val u = layout.unit
    val x = layout.width - 3.5f * u
    val top = layout.height * 0.1f
    val bottom = layout.height * 0.9f
    drawLine(Color.White.copy(alpha = 0.35f), Offset(x, top), Offset(x, bottom), 1.4f * u, StrokeCap.Round)
    val y = bottom - (bottom - top) * round.progress
    drawLine(look.sparkle.copy(alpha = 0.9f), Offset(x, bottom), Offset(x, y), 1.4f * u, StrokeCap.Round)
    drawCircle(Color.White, 2f * u, Offset(x, top))
    drawCircle(look.sparkle, 1.3f * u, Offset(x, top))
    drawCircle(Color.White, 1.8f * u, Offset(x, y))
}

private fun DrawScope.skyCloud(c: Offset, u: Float, alpha: Float) {
    val white = Color.White.copy(alpha = alpha)
    drawOval(white, c - Offset(10f * u, 2.5f * u), Size(20f * u, 5f * u))
    drawCircle(white, 4f * u, c + Offset(-3f * u, -1.5f * u))
    drawCircle(white, 5f * u, c + Offset(2.5f * u, -2.5f * u))
}

private fun DrawScope.kelp(base: Offset, height: Float, t: Float, u: Float, color: Color) {
    val path = Path().apply {
        moveTo(base.x, base.y + height / 2)
        for (s in 1..8) {
            val y = base.y + height / 2 - height * s / 8f
            lineTo(base.x + sin(t * 1.1f + s * 0.6f) * 2.2f * u * s / 8f, y)
        }
    }
    drawPath(path, color, style = Stroke(1.6f * u, cap = StrokeCap.Round))
    for (s in 2..7 step 2) {
        val y = base.y + height / 2 - height * s / 8f
        val x = base.x + sin(t * 1.1f + s * 0.6f) * 2.2f * u * s / 8f
        drawOval(color, Offset(x, y - 1f * u), Size(4f * u, 2f * u))
        drawOval(color, Offset(x - 4f * u, y + 1.5f * u), Size(4f * u, 2f * u))
    }
}
