import kotlin.math.floor

/**
 * The look of Sand flow in one arena: the sand from its [light] top down to its [deep] bottom with [flecks], the
 * [tunnel] colors of carved channels, the [rock]s, the [water], the [sky] over a dune, the [rim] around the
 * cross-section, and what the status line says.
 */
internal class FlowLook(
    val arena: Arena,
    val light: Color,
    val sand: Color,
    val deep: Color,
    val strata: Color,
    val flecks: List<Color>,
    val tunnel: Color,
    val tunnelDeep: Color,
    val rock: Color,
    val rockLight: Color,
    val rockShade: Color,
    val water: Color,
    val waterLight: Color,
    val waterDeep: Color,
    val skyTop: Color,
    val skyBottom: Color,
    val rim: Color,
    val rimLight: Color,
    val rimDark: Color,
    val start: String,
    val flowing: String,
    val filling: String,
    val done: String,
    /** What the screen reader hears the game is. */
    val description: String,
) {
    val isDune: Boolean get() = arena == Arena.DESERT

    companion object {
        /** [arena]'s Sand flow, its colors through [g]: the oasis dune in the Desert, the duck's sandbox anywhere else. */
        fun of(arena: Arena, g: SceneGrade): FlowLook = when (arena) {
            Arena.DESERT -> FlowLook(
                arena,
                g(0xFFF7CB8A), g(0xFFE8A862), g(0xFFB9733D), g(0xFFC98A4E),
                listOf(g(0xFFFFE2B0), g(0xFFB0703C), g(0xFFD99A5A)),
                g(0xFF9A5A2C), g(0xFF6E3C1C),
                g(0xFFC0844A), g(0xFFE6B070), g(0xFF8A552C),
                g(0xFF3BB6D6), g(0xFFA8EEFF), g(0xFF1F86B0),
                g(0xFFFFF1D2), g(0xFFFFD9A0),
                g(0xFFB06E3A), g(0xFFD9955A), g(0xFF7E4823),
                "Drag to carve a stream in the dune",
                "Here comes the water…",
                "The oasis pool is filling!",
                "The oasis is green again!",
                "A dune to carve: a spring at the top, the oasis pool down in the hollow",
            )
            else -> FlowLook(
                arena,
                g(0xFFF4DCAA), g(0xFFE1B97C), g(0xFFB98A52), g(0xFFCDA068),
                listOf(g(0xFFB98E5A), g(0xFF9C9488), g(0xFFFFEBC2)),
                g(0xFF8C6238), g(0xFF5E3F22),
                g(0xFF9AA2AC), g(0xFFCDD3DA), g(0xFF656C76),
                g(0xFF46B0F0), g(0xFFB4E6FF), g(0xFF2A7FD0),
                g(0xFFFFFFFF).copy(alpha = 0f), g(0xFFFFFFFF).copy(alpha = 0f),
                g(0xFFC98A4B), g(0xFFE5AC6B), g(0xFF8E5A2E),
                "Drag to carve a stream in the sand",
                "Here comes the water…",
                "The duck's tub is filling!",
                "Splash! The duck is floating!",
                "A sandbox to carve: a pipe at the top, the duck's tub at the bottom",
            )
        }
    }
}

/**
 * Where a [columns] x [rows] Sand flow sits in a [width] x [height] area, in pixels: a band over the top for the
 * pipe or spring, then the cross-section, centered and as big as fits.
 */
internal class FlowLayout(width: Float, height: Float, val columns: Int, val rows: Int) {
    val cell: Float = minOf(width / (columns + 2 * RIM), height / (rows + TOP + RIM))
    val rim: Float = cell * RIM
    val origin: Offset = Offset((width - cell * columns) / 2, (height - cell * (rows + TOP + RIM)) / 2 + cell * TOP)

    val grid: Rect get() = Rect(origin, Size(cell * columns, cell * rows))

    fun center(index: Int): Offset = origin + Offset((index % columns + 0.5f) * cell, (index / columns + 0.5f) * cell)

    fun topLeft(x: Int, y: Int): Offset = origin + Offset(x * cell, y * cell)

    /** The cells a finger at [point] carves: every one its round tip touches. */
    fun brush(point: Offset): List<Int> {
        val r = cell * BRUSH
        val gx = (point.x - origin.x) / cell
        val gy = (point.y - origin.y) / cell
        val out = mutableListOf<Int>()
        for (y in floor(gy - BRUSH).toInt()..floor(gy + BRUSH).toInt()) {
            for (x in floor(gx - BRUSH).toInt()..floor(gx + BRUSH).toInt()) {
                if (x !in 0 until columns || y !in 0 until rows) continue
                val nx = (point.x).coerceIn(origin.x + x * cell, origin.x + (x + 1) * cell)
                val ny = (point.y).coerceIn(origin.y + y * cell, origin.y + (y + 1) * cell)
                val dx = point.x - nx
                val dy = point.y - ny
                if (dx * dx + dy * dy <= r * r) out += y * columns + x
            }
        }
        return out
    }

    private companion object {
        const val RIM = 0.32f

        /** The band over the cross-section for the pipe or spring, in cells. */
        const val TOP = 1.3f

        /** The finger's reach, in cells. */
        const val BRUSH = 0.3f
    }
}
