// The art of Color mixer: the vessel the scoops go into (the octopus's shell bowl, or the cement mixer's drum), the
// pots by it, the drops falling in, and the target swatch. The vessel is painted in a 100 x 90 box, pots and swatches
// in a 100 x 100 one, in the same soft two-tone style as the keepsakes.

/**
 * The look of a Color mixer in one arena: the [vessel] and its colors ([body], [light], [dark], [inside]), the
 * stripes or ribs on it ([trim]), the [frame] it stands on, the [ground] under it, and the pots' [pot] colors.
 * [scoop] is what a scoop is called there ("ink", "sand").
 */
internal class MixerLook(
    val vessel: MixerVessel,
    val body: Color,
    val light: Color,
    val dark: Color,
    val inside: Color,
    val trim: Color,
    val frame: Color,
    val frameLight: Color,
    val ground: Color,
    val groundLight: Color,
    val pot: Color,
    val potLight: Color,
    val potDark: Color,
    val scoop: String,
) {
    companion object {
        /** [arena]'s mixer, its colors through [g]. Arenas without a Color mixer get the Sea Floor's. */
        fun of(arena: Arena, g: SceneGrade): MixerLook = when (arena) {
            Arena.BUILDING_SITE -> MixerLook(
                MixerVessel.DRUM,
                g(0xFFFF8C2A), g(0xFFFFB066), g(0xFFC9601A), g(0xFF4A2A14),
                g(0xFF2F5FA8),
                g(0xFF55606E), g(0xFF8A95A3),
                g(0xFFB9A88E), g(0xFFD9CBB2),
                g(0xFFB4BCC6), g(0xFFE6EAEE), g(0xFF6E7884),
                "sand",
            )
            else -> MixerLook(
                MixerVessel.SHELL,
                g(0xFFFFC6B8), g(0xFFFFE6DC), g(0xFFE0907E), g(0xFFE7A79A),
                g(0xFFF2A592),
                g(0xFF3FAF8F), g(0xFF7FD8B6),
                g(0xFFE9D6A8), g(0xFFF6EACB),
                g(0xFFF4E7D3), g(0xFFFFF8EE), g(0xFFCBB495),
                "ink",
            )
        }
    }
}

/** What the scoops go into: a scallop shell held by the octopus, or a turning cement drum. */
internal enum class MixerVessel { SHELL, DRUM }

/** One scoop on its way into the vessel: its [color], which pot it came from ([from], 0 to 3), and how far it is (0 to 1). */
internal class MixerDrop(val color: Color, val from: Int, val progress: () -> Float)

/** The vessel's size in its own box units. */
internal const val VESSEL_W = 100f
internal const val VESSEL_H = 90f

/** The part of a drop's fall, 0 to 1, at which it lands and the ripple starts. */
internal const val DROP_LANDS = 0.55f

/**
 * Everything in the mixing area at this frame, fitted into [size]: the vessel and its stand, the mix [color] filled
 * to [fill] (0 empty to 1 full) and swirling by [stir], the [drops] falling in, the vessel tipping by [tip] (0 to 1)
 * as it is emptied, and the [burst] of a match (0 to 1). [turns] spins the drum, [t] is the clock (0 to 1).
 */
internal fun DrawScope.drawMixer(
    look: MixerLook,
    g: SceneGrade,
    color: Color,
    fill: Float,
    stir: Float,
    turns: Float,
    tip: Float,
    burst: Float,
    drops: List<MixerDrop>,
    t: Float,
) {
    val unit = minOf(size.width / VESSEL_W, size.height / VESSEL_H)
    translate((size.width - VESSEL_W * unit) / 2, (size.height - VESSEL_H * unit) / 2) {
        scale(unit, unit, Offset.Zero) {
            val mouth = when (look.vessel) {
                MixerVessel.SHELL -> drawShellBowl(look, g, color, fill, stir, tip, t)
                MixerVessel.DRUM -> drawDrum(look, g, color, fill, stir, turns, tip, t)
            }
            for (drop in drops) drawDrop(look, drop, mouth, fill)
            if (burst > 0f && burst < 1f) {
                drawGlow(mouth.center, 30f + 26f * burst, Color(0xFFFFF2B0).copy(alpha = 0.9f * (1f - burst)))
                // Drops of the finished mix leap up out of the vessel and fall back.
                for (k in 0 until 9) {
                    val a = PI.toFloat() * (0.12f + 0.76f * k / 8f)
                    val reach = 14f + 7f * ((k * 5) % 3)
                    val x = mouth.center.x - cos(a) * reach * burst * 1.6f
                    val y = mouth.center.y - sin(a) * reach * 2.2f * burst + 40f * burst * burst
                    val r = (2.6f - (k % 3) * 0.5f) * (1f - burst * 0.5f)
                    drawCircle(lerp(color, Color.Black, 0.18f), r, Offset(x, y + 0.4f))
                    drawCircle(color, r * 0.9f, Offset(x, y))
                    drawCircle(Color.White.copy(alpha = 0.6f), r * 0.3f, Offset(x - r * 0.3f, y - r * 0.3f))
                }
                sparkleBurst(mouth.center - Offset(0f, 8f), 34f, burst)
                if (look.vessel == MixerVessel.SHELL) {
                    for (k in 0 until 6) {
                        val x = mouth.center.x + (k - 2.5f) * 7f + sin(burst * 9f + k) * 2f
                        val y = mouth.center.y - burst * (30f + k * 5f)
                        drawCircle(Color.White.copy(alpha = 0.8f * (1f - burst)), 1.6f + (k % 3) * 0.7f, Offset(x, y), style = Stroke(0.6f))
                    }
                }
            }
        }
    }
}

/** The mix's top in the vessel: its [center] and half-widths [rx], [ry] when full. */
internal class Mouth(val center: Offset, val rx: Float, val ry: Float)

/** The octopus behind a scallop shell bowl on the sand, two arms over the rim, seaweed swaying either side. */
private fun DrawScope.drawShellBowl(look: MixerLook, g: SceneGrade, color: Color, fill: Float, stir: Float, tip: Float, t: Float): Mouth {
    // Seaweed either side, swaying.
    for ((x, h, phase) in listOf(Triple(9f, 40f, 0f), Triple(16f, 28f, 0.3f), Triple(88f, 36f, 0.6f), Triple(95f, 24f, 0.15f))) {
        val sway = sin((t * 30f + phase) * 2f * PI.toFloat()) * 2.5f
        val weed = Path().apply {
            moveTo(x - 1.6f, 84f)
            cubicTo(x - 4f + sway * 0.4f, 84f - h * 0.4f, x + 3f + sway, 84f - h * 0.7f, x + sway * 1.4f, 84f - h)
            cubicTo(x + 4f + sway, 84f - h * 0.7f, x + 0.5f + sway * 0.4f, 84f - h * 0.4f, x + 1.6f, 84f)
            close()
        }
        drawPath(weed, lerp(look.frame, Color.Black, 0.15f))
        translate(0.8f, 0f) { drawPath(weed, look.frame) }
    }
    // The sand the bowl sits on.
    drawOval(look.ground, Offset(8f, 79f), Size(84f, 11f))
    drawOval(look.groundLight, Offset(16f, 79.5f), Size(60f, 5f))
    drawOval(Color.Black.copy(alpha = 0.16f), Offset(18f, 79f), Size(64f, 7f))
    val pivot = Offset(50f, 80f)
    val center = Offset(50f, 50f)
    rotate(-18f * tip, pivot) {
        // The octopus behind the bowl, peeking over the rim.
        val s = 0.62f
        translate(50f - 50f * s, 31f - 46f * s) { scale(s, s, Offset.Zero) { drawKeepsake(Arena.SEA_FLOOR, 3, t, g) } }
        val rim = Rect(14f, 40f, 86f, 60f)
        // The pearly inside of the shell, shadowed under the far rim.
        drawOval(Brush.verticalGradient(listOf(lerp(look.inside, look.dark, 0.5f), look.inside, look.light), 40f, 60f), rim.topLeft, rim.size)
        drawOval(Color.White.copy(alpha = 0.3f), Offset(56f, 50f), Size(20f, 5f))
        drawContents(color, fill, stir, center.copy(y = center.y + 1f), 33f, 8.6f, t)
        // The shell's ribbed front.
        val front = Path().apply {
            moveTo(86f, 50f)
            arcTo(rim, 0f, 180f, false)
            cubicTo(15f, 70f, 30f, 83f, 50f, 83f)
            cubicTo(70f, 83f, 85f, 70f, 86f, 50f)
            close()
        }
        drawPath(front, Brush.verticalGradient(listOf(look.light, look.body, look.dark), 52f, 84f))
        clipPath(front) {
            for (k in -4..4) {
                val x = 50f + k * 8.4f
                drawLine(look.trim, Offset(50f + k * 2.2f, 86f), Offset(x, 56f), 2.6f, StrokeCap.Round)
            }
            drawOval(Color.White.copy(alpha = 0.35f), Offset(24f, 60f), Size(20f, 6f))
        }
        // The scalloped lip along the front of the rim.
        for (k in 0..12) {
            val a = PI.toFloat() * k / 12f
            val p = Offset(50f + 36f * cos(a), 50f + 10f * sin(a))
            drawCircle(look.light, 2.3f, p)
        }
        // Two arms curled over the rim.
        val purple = g(0xFF9B5DE5)
        val deep = g(0xFF7440C2)
        for (side in listOf(-1f, 1f)) {
            val wave = sin((t * 40f + if (side < 0) 0f else 0.5f) * 2f * PI.toFloat())
            for (k in 0..7) {
                val q = k / 7f
                val x = 50f + side * (31f + q * 9f + wave * q * 1.2f)
                val y = 42f + q * 16f - sin(q * PI.toFloat()) * 4f
                drawCircle(if (k % 2 == 0) deep else purple, 3.6f * (1f - q * 0.5f), Offset(x, y))
            }
            drawCircle(g(0xFFC9A3F5), 0.9f, Offset(50f + side * 33f, 42f))
        }
    }
    return Mouth(center, 33f, 8.6f)
}

/** The cement mixer: its frame and motor, and the striped drum, tilted toward us, turning by [turns]. */
private fun DrawScope.drawDrum(look: MixerLook, g: SceneGrade, color: Color, fill: Float, stir: Float, turns: Float, tip: Float, t: Float): Mouth {
    // Gravel and a little sand pile on the ground.
    drawOval(look.ground, Offset(4f, 80f), Size(92f, 10f))
    drawOval(look.groundLight, Offset(12f, 80.5f), Size(56f, 4f))
    for (k in 0 until 9) drawCircle(lerp(look.frame, look.ground, 0.5f), 0.9f + (k % 3) * 0.3f, Offset(10f + k * 9.5f, 85f + (k % 2) * 2f))
    drawOval(Color.Black.copy(alpha = 0.18f), Offset(18f, 79f), Size(64f, 7f))
    // Legs, the motor box and a wheel.
    drawLine(look.frame, Offset(40f, 62f), Offset(30f, 86f), 3.6f, StrokeCap.Round)
    drawLine(look.frame, Offset(62f, 62f), Offset(72f, 84f), 3.6f, StrokeCap.Round)
    drawRoundRect(lerp(look.frame, Color.Black, 0.2f), Offset(10f, 60f), Size(22f, 16f), CornerRadius(3f))
    drawRoundRect(g(0xFF3BA566), Offset(10f, 58f), Size(21f, 15f), CornerRadius(3f))
    drawRoundRect(Color.White.copy(alpha = 0.25f), Offset(12f, 59.5f), Size(14f, 2.5f), CornerRadius(1.2f))
    drawCircle(g(0xFF2E333B), 7f, Offset(72f, 84f))
    drawCircle(look.frameLight, 2.6f, Offset(72f, 84f))
    val pivot = Offset(50f, 52f)
    val tilt = -12f - 30f * tip
    rotate(tilt, pivot) {
        val body = Path().apply {
            moveTo(33f, 22f)
            cubicTo(26f, 32f, 19f, 40f, 19f, 52f)
            cubicTo(19f, 67f, 29f, 80f, 50f, 81f)
            cubicTo(71f, 80f, 81f, 67f, 81f, 52f)
            cubicTo(81f, 40f, 74f, 32f, 67f, 22f)
            arcTo(Rect(33f, 16.5f, 67f, 27.5f), 0f, 180f, false)
            close()
        }
        drawPath(body, look.body)
        clipPath(body) {
            // Bands wrapping round the drum, sliding along as it turns.
            val shift = ((turns + t * 30f) % 1f) * 20f
            for (k in -2..4) {
                val x = 10f + k * 20f + shift
                val band = Path().apply {
                    moveTo(x, 18f); lineTo(x + 8f, 18f); lineTo(x + 20f, 84f); lineTo(x + 12f, 84f); close()
                }
                drawPath(band, look.trim)
            }
            // Round shading, light from the upper left.
            drawRect(
                Brush.horizontalGradient(
                    0f to Color.Black.copy(alpha = 0.28f),
                    0.25f to Color.Transparent,
                    0.38f to Color.White.copy(alpha = 0.22f),
                    0.6f to Color.Transparent,
                    1f to Color.Black.copy(alpha = 0.32f),
                    startX = 19f,
                    endX = 81f,
                ),
                Offset(0f, 0f),
                Size(100f, 90f),
            )
            drawLine(look.dark, Offset(19f, 60f), Offset(81f, 60f), 2.4f)
        }
        // The mouth: a thick lip round the opening, the mix inside.
        drawOval(look.dark, Offset(31f, 15f), Size(38f, 13f))
        drawOval(look.light, Offset(32f, 15f), Size(36f, 11.5f))
        drawOval(look.inside, Offset(34.5f, 17f), Size(31f, 8.5f))
        drawContents(color, fill, stir, Offset(50f, 21.6f), 15f, 4f, t)
    }
    // Where the drop goes in, in the vessel's (unrotated) box.
    val a = tilt * PI.toFloat() / 180f
    val up = 21.6f - pivot.y
    return Mouth(Offset(pivot.x - up * sin(a), pivot.y + up * cos(a)), 15f, 4f)
}

/** The mix filled to [fill] in an opening of half-widths [rx], [ry] at [c], swirling while [stir] is up. */
private fun DrawScope.drawContents(color: Color, fill: Float, stir: Float, c: Offset, rx: Float, ry: Float, t: Float) {
    if (fill <= 0.01f) return
    val depth = 1f - fill
    val crx = rx * (1f - 0.28f * depth)
    val cry = ry * (1f - 0.28f * depth)
    val cc = c + Offset(0f, ry * 0.5f * depth)
    val top = Rect(cc.x - crx, cc.y - cry, cc.x + crx, cc.y + cry)
    drawOval(lerp(color, Color.Black, 0.22f), top.topLeft, top.size)
    drawOval(color, Offset(top.left + crx * 0.04f, top.top), Size(top.width * 0.96f, top.height * 0.9f))
    val clip = Path().apply { addOval(top) }
    clipPath(clip) {
        // A slow swirl, quicker just after a scoop.
        val spin = t * 2f * PI.toFloat() * 20f + stir * 6f
        for (k in 0 until 3) {
            val a = spin + k * 2.1f
            val p = Offset(cc.x + cos(a) * crx * 0.45f, cc.y + sin(a) * cry * 0.45f)
            drawOval(
                lerp(color, Color.White, 0.22f + 0.2f * stir).copy(alpha = 0.55f),
                p - Offset(crx * 0.32f, cry * 0.16f),
                Size(crx * 0.64f, cry * 0.32f),
            )
        }
        drawOval(Color.White.copy(alpha = 0.32f), Offset(cc.x - crx * 0.6f, cc.y - cry * 0.7f), Size(crx * 0.5f, cry * 0.42f))
    }
}

/** A drop of ink (or a clump of sand) falling into [mouth], then a ripple where it lands. */
private fun DrawScope.drawDrop(look: MixerLook, drop: MixerDrop, mouth: Mouth, fill: Float) {
    val p = drop.progress()
    val land = mouth.center + Offset((drop.from - 1.5f) * 4f, mouth.ry * 0.3f)
    if (p < DROP_LANDS) {
        val q = p / DROP_LANDS
        val start = Offset(50f + (drop.from - 1.5f) * 22f, 92f)
        // Up from the pots in an arc, then down into the mouth.
        val x = start.x + (land.x - start.x) * q
        val peak = minOf(land.y, start.y) - 22f
        val y = (1 - q) * (1 - q) * start.y + 2 * (1 - q) * q * peak + q * q * land.y
        val c = Offset(x, y)
        when (look.vessel) {
            MixerVessel.SHELL -> {
                drawCircle(lerp(drop.color, Color.Black, 0.2f), 3.4f, c + Offset(0f, 0.4f))
                drawCircle(drop.color, 3.2f, c)
                drawCircle(Color.White.copy(alpha = 0.6f), 1f, c - Offset(1f, 1.1f))
            }
            MixerVessel.DRUM -> {
                for (k in 0 until 6) {
                    val a = k * 1.05f + q * 3f
                    drawCircle(drop.color, 1.5f + (k % 2) * 0.5f, c + Offset(cos(a) * 2.2f, sin(a) * 1.8f))
                }
                drawCircle(lerp(drop.color, Color.White, 0.3f), 1.2f, c - Offset(0.6f, 0.8f))
            }
        }
    } else {
        val q = (p - DROP_LANDS) / (1f - DROP_LANDS)
        val rx = mouth.rx * (0.15f + 0.6f * q)
        val ry = mouth.ry * (0.15f + 0.6f * q)
        drawOval(drop.color.copy(alpha = 0.9f * (1f - q)), land - Offset(rx, ry), Size(2 * rx, 2 * ry), style = Stroke(1.2f))
        if (fill > 0f) for (k in 0 until 3) {
            val a = -PI.toFloat() * (0.25f + 0.25f * k)
            val r = 2f + 7f * q
            drawCircle(drop.color.copy(alpha = 1f - q), 0.9f, land + Offset(cos(a) * r, sin(a) * r * 0.8f - 4f * q * (1 - q)))
        }
    }
}

/** One pot of [ink], in a 100 x 100 box: an ink-filled shell cup, or a bucket of colored sand. [lift] raises it. */
internal fun DrawScope.drawPot(look: MixerLook, ink: Color, lift: Float) {
    translate(0f, -6f * lift) {
        drawOval(Color.Black.copy(alpha = 0.14f), Offset(22f, 86f), Size(56f, 8f))
        when (look.vessel) {
            MixerVessel.SHELL -> {
                val cup = Path().apply {
                    moveTo(16f, 46f)
                    cubicTo(16f, 74f, 32f, 90f, 50f, 90f)
                    cubicTo(68f, 90f, 84f, 74f, 84f, 46f)
                    close()
                }
                drawPath(cup, Brush.verticalGradient(listOf(look.potLight, look.pot, look.potDark), 46f, 90f))
                clipPath(cup) {
                    for (k in -3..3) drawLine(look.potDark.copy(alpha = 0.45f), Offset(50f + k * 3f, 92f), Offset(50f + k * 11f, 48f), 2.4f, StrokeCap.Round)
                }
                drawOval(look.potDark, Offset(15f, 37f), Size(70f, 18f))
                drawOval(lerp(ink, Color.Black, 0.18f), Offset(19f, 39f), Size(62f, 14f))
                drawOval(ink, Offset(20f, 39f), Size(60f, 12.5f))
                drawOval(Color.White.copy(alpha = 0.5f), Offset(30f, 41f), Size(18f, 4f))
                // A drip over the lip.
                drawRoundRect(ink, Offset(62f, 46f), Size(6f, 13f), CornerRadius(3f))
                drawCircle(ink, 3.6f, Offset(65f, 59f))
            }
            MixerVessel.DRUM -> {
                // The wire handle.
                drawArc(look.potDark, 180f, 180f, false, Offset(24f, 14f), Size(52f, 46f), style = Stroke(3f))
                val tin = Path().apply {
                    moveTo(20f, 38f); lineTo(80f, 38f); lineTo(74f, 88f); lineTo(26f, 88f); close()
                }
                drawPath(
                    tin,
                    Brush.horizontalGradient(listOf(look.potDark, look.potLight, look.pot, look.potDark), 20f, 80f),
                )
                drawRect(ink, Offset(20f, 56f), Size(60f, 16f))
                clipPath(tin) { drawRect(lerp(ink, Color.Black, 0.2f), Offset(0f, 70f), Size(100f, 2f)) }
                drawRect(Color.White.copy(alpha = 0.25f), Offset(30f, 57f), Size(10f, 14f))
                drawOval(look.potDark, Offset(18f, 32f), Size(64f, 13f))
                drawOval(lerp(ink, Color.Black, 0.15f), Offset(21f, 33.5f), Size(58f, 10f))
                // A heaped top of sand with grains in it.
                drawOval(ink, Offset(24f, 28f), Size(52f, 14f))
                for (k in 0 until 7) {
                    drawCircle(lerp(ink, if (k % 2 == 0) Color.White else Color.Black, 0.25f), 1.2f, Offset(30f + k * 6.5f, 34f + (k % 3) * 1.6f))
                }
            }
        }
    }
}

/** The target color as a swatch in a 100 x 100 box: a glossy pearl of ink, or a paint chip. */
internal fun DrawScope.drawSwatch(look: MixerLook, color: Color) {
    when (look.vessel) {
        MixerVessel.SHELL -> {
            drawCircle(Color.Black.copy(alpha = 0.16f), 40f, Offset(50f, 54f))
            drawCircle(lerp(color, Color.Black, 0.2f), 40f, Offset(50f, 51f))
            drawCircle(color, 38f, Offset(50f, 49f))
            drawOval(Color.White.copy(alpha = 0.45f), Offset(26f, 22f), Size(26f, 14f))
            drawCircle(Color.White.copy(alpha = 0.7f), 3f, Offset(70f, 66f))
        }
        MixerVessel.DRUM -> {
            val r = CornerRadius(8f)
            drawRoundRect(Color.Black.copy(alpha = 0.16f), Offset(14f, 12f), Size(74f, 84f), r)
            drawRoundRect(Color.White, Offset(12f, 8f), Size(76f, 84f), r)
            drawRoundRect(color, Offset(18f, 14f), Size(64f, 56f), CornerRadius(5f))
            drawRoundRect(Color.White.copy(alpha = 0.3f), Offset(22f, 18f), Size(28f, 6f), CornerRadius(3f))
            for (k in 0..2) drawRoundRect(Color(0xFFB8BEC6), Offset(20f, 76f + k * 5f), Size(if (k == 2) 34f else 60f, 2.4f), CornerRadius(1.2f))
        }
    }
}

/** A tick in a 100 x 100 box, for a mixed color. */
internal fun DrawScope.drawTick(color: Color) {
    val tick = Path().apply { moveTo(28f, 52f); lineTo(44f, 68f); lineTo(74f, 34f) }
    drawPath(tick, Color.Black.copy(alpha = 0.3f), style = Stroke(16f, cap = StrokeCap.Round))
    drawPath(tick, color, style = Stroke(10f, cap = StrokeCap.Round))
}

/** A soft twinkle, for the meter's goal. */
internal fun DrawScope.goalStar(c: Offset, r: Float, color: Color) = drawSparkle(c, r, color)
