/** How a layer's tiles are textured: sand grains, fine strata, pebbles, smooth streaks, or faceted stone. */
internal enum class DeepTexture { GRAINS, STRATA, PEBBLES, STREAKS, STONE }

/** One layer of the ground: its [name] as the status line says it, its colors, and its [texture]. */
internal class DeepLayer(val name: String, val light: Color, val base: Color, val dark: Color, val texture: DeepTexture)

/** Something to dig up: its [name] as it reads in a sentence and how it [draw]s in a 100 x 100 box. */
internal class DeepFind(val name: String, val draw: DrawScope.(SceneGrade) -> Unit)

/**
 * The look of Dig deeper in one arena: the [sky] over the surface, the [layers] going down, the [slab] color of the
 * hard old pipes or stone blocks, the [finds] in the ground, the [prize] in the chamber with its [chamber] walls and
 * [glow], and what the status line says.
 */
internal class DeepLook(
    val arena: Arena,
    val skyTop: Color,
    val skyBottom: Color,
    val layers: List<DeepLayer>,
    val slab: Color,
    val slabLight: Color,
    val slabDark: Color,
    val finds: List<DeepFind>,
    val prize: DeepFind,
    val chamber: Color,
    val chamberDark: Color,
    val glow: Color,
    val start: String,
    val found: String,
    val description: String,
) {
    val isSite: Boolean get() = arena == Arena.BUILDING_SITE

    companion object {
        /** [arena]'s dig: down to the time capsule on the Building Site, to the pyramid's chamber anywhere else. */
        fun of(arena: Arena, g: SceneGrade): DeepLook = when (arena) {
            Arena.BUILDING_SITE -> DeepLook(
                arena,
                g(0xFFBFE3F5), g(0xFFEAF5FA),
                listOf(
                    DeepLayer("Soft topsoil", g(0xFFA4734A), g(0xFF8B5E3C), g(0xFF5E3D24), DeepTexture.GRAINS),
                    DeepLayer("Crunchy gravel", g(0xFFC2BCB2), g(0xFFA29C92), g(0xFF746E66), DeepTexture.PEBBLES),
                    DeepLayer("Sticky clay and old pipes", g(0xFFCC8862), g(0xFFB0704C), g(0xFF7E4A30), DeepTexture.STREAKS),
                    DeepLayer("Hard bedrock: keep tapping!", g(0xFF9298A2), g(0xFF767C86), g(0xFF50555E), DeepTexture.STONE),
                ),
                g(0xFF7A8794), g(0xFFA9B4BF), g(0xFF4E5964),
                siteFinds,
                DeepFind("time capsule") { timeCapsule(it) },
                g(0xFF9AA0A8), g(0xFF5E646C), g(0xFFBFE8FF),
                "Tap below to dig down!",
                "You found the time capsule!",
                "A cross-section of the building site, with the excavator on top and a time capsule buried deep below",
            )
            else -> DeepLook(
                arena,
                g(0xFFFFD9A0), g(0xFFFFF0D4),
                listOf(
                    DeepLayer("Loose sand: easy digging", g(0xFFF9D395), g(0xFFEDB46C), g(0xFFC98A4E), DeepTexture.GRAINS),
                    DeepLayer("Packed sand", g(0xFFE6A562), g(0xFFCC8848), g(0xFF9E6130), DeepTexture.STRATA),
                    DeepLayer("Sticky clay: tap again!", g(0xFFD07E58), g(0xFFB4623E), g(0xFF84422A), DeepTexture.STREAKS),
                    DeepLayer("Old rock: keep tapping!", g(0xFFAA8C74), g(0xFF8C705C), g(0xFF5E4A3C), DeepTexture.STONE),
                ),
                g(0xFFD8B27A), g(0xFFF0D29E), g(0xFFA07C4C),
                desertFinds,
                DeepFind("golden scarab") { goldenScarab(it) },
                g(0xFFE8BE6A), g(0xFF9A6E2E), g(0xFFFFE08A),
                "Tap below the explorer to dig!",
                "You found the golden scarab!",
                "A cross-section of the desert under the pyramid, with a hidden chamber deep below",
            )
        }
    }
}

private val desertFinds = listOf(
    DeepFind("ruby") { gem(it(0xFFE84A5F), it(0xFFFF8A9A), it(0xFFA82838)) },
    DeepFind("pottery shard") { shard(it) },
    DeepFind("fossil shell") { ammonite(it(0xFFD8C6A8), it(0xFFA88E6C)) },
    DeepFind("emerald") { gem(it(0xFF2EBF7A), it(0xFF8AF0BE), it(0xFF1A8452)) },
    DeepFind("gold ring") { ring(it) },
    DeepFind("blue bead") { bead(it(0xFF2F9FD8), it(0xFF9ADCFF)) },
)

private val siteFinds = listOf(
    DeepFind("old coin") { coin(it) },
    DeepFind("glass marble") { marble(it) },
    DeepFind("toy car") { toyCar(it) },
    DeepFind("horseshoe") { horseshoe(it) },
    DeepFind("old bottle") { bottle(it) },
    DeepFind("rusty key") { key(it) },
)

private fun DrawScope.gem(base: Color, light: Color, dark: Color) {
    drawPath(polygon(30f, 36f, 70f, 36f, 84f, 50f, 50f, 86f, 16f, 50f), dark)
    drawPath(polygon(30f, 36f, 70f, 36f, 80f, 48f, 50f, 80f, 20f, 48f), base)
    drawPath(polygon(30f, 36f, 50f, 36f, 40f, 48f, 20f, 48f), light)
    drawPath(polygon(50f, 48f, 80f, 48f, 50f, 80f), dark.copy(alpha = 0.35f))
    drawSparkle(Offset(34f, 42f), 8f, Color.White.copy(alpha = 0.9f))
}

private fun DrawScope.shard(g: SceneGrade) {
    val clay = g(0xFFD27A4A)
    drawPath(polygon(22f, 30f, 70f, 22f, 84f, 58f, 60f, 82f, 28f, 72f), g(0xFF9C4E2A))
    drawPath(polygon(22f, 28f, 70f, 20f, 82f, 54f, 58f, 78f, 26f, 68f), clay)
    // A painted band and zigzag, as on old jars.
    stick(g(0xFF2E2A28), 26f, 42f, 78f, 36f, 4f)
    var x = 30f
    while (x < 72f) {
        stick(g(0xFF2E2A28), x, 50f, x + 6f, 58f, 2.5f)
        stick(g(0xFF2E2A28), x + 6f, 58f, x + 12f, 50f, 2.5f)
        x += 12f
    }
    oval(Color.White.copy(alpha = 0.3f), 40f, 30f, 10f, 3f)
}

private fun DrawScope.ammonite(base: Color, dark: Color) {
    dot(dark, 50f, 52f, 34f)
    dot(base, 50f, 50f, 32f)
    val spiral = Path().apply {
        var first = true
        var a = 0f
        while (a < 4.2f * PI.toFloat()) {
            val r = 3f + a * 2.1f
            val p = Offset(50f + cos(a) * r, 50f + sin(a) * r)
            if (first) moveTo(p.x, p.y) else lineTo(p.x, p.y)
            first = false
            a += 0.2f
        }
    }
    drawPath(spiral, dark, style = Stroke(3.5f))
    for (k in 0 until 10) {
        val a = k * 0.62f + 1.2f
        stick(dark.copy(alpha = 0.5f), 50f + cos(a) * 18f, 50f + sin(a) * 18f, 50f + cos(a) * 30f, 50f + sin(a) * 30f, 2f)
    }
    oval(Color.White.copy(alpha = 0.35f), 40f, 30f, 10f, 4f)
}

private fun DrawScope.ring(g: SceneGrade) {
    drawCircle(g(0xFFB8862A), 26f, Offset(50f, 56f), style = Stroke(12f))
    drawCircle(g(0xFFFFD45A), 25f, Offset(50f, 54f), style = Stroke(8f))
    // A little blue stone set on top.
    dot(g(0xFF1F6FA8), 50f, 30f, 10f)
    dot(g(0xFF3FA7E0), 50f, 29f, 8.5f)
    dot(g(0xFFA8E2FF), 47f, 26f, 3f)
    oval(Color.White.copy(alpha = 0.6f), 38f, 34f, 7f, 3f)
}

private fun DrawScope.bead(base: Color, light: Color) {
    dot(base.copy(alpha = 0.6f), 52f, 54f, 30f)
    dot(base, 50f, 50f, 28f)
    dot(light.copy(alpha = 0.7f), 40f, 40f, 10f)
    dot(Color.Black.copy(alpha = 0.3f), 50f, 50f, 6f)
    drawSparkle(Offset(36f, 36f), 7f, Color.White.copy(alpha = 0.9f))
}

private fun DrawScope.coin(g: SceneGrade) {
    dot(g(0xFF9A7A3C), 50f, 54f, 32f)
    dot(g(0xFFE0B456), 50f, 50f, 32f)
    dot(g(0xFFF4CE6E), 50f, 50f, 24f)
    drawPath(polygon(50f, 34f, 54f, 46f, 66f, 46f, 56f, 54f, 60f, 66f, 50f, 58f, 40f, 66f, 44f, 54f, 34f, 46f, 46f, 46f), g(0xFFC9973E))
    oval(Color.White.copy(alpha = 0.45f), 40f, 32f, 9f, 4f)
}

private fun DrawScope.marble(g: SceneGrade) {
    dot(g(0xFF2E6FB8), 50f, 52f, 30f)
    dot(g(0xFF6FC0F0).copy(alpha = 0.85f), 50f, 50f, 29f)
    rotate(30f, Offset(50f, 50f)) { oval(g(0xFFFF7A5A), 50f, 50f, 20f, 6f) }
    rotate(-40f, Offset(50f, 50f)) { oval(g(0xFFFFD04A), 50f, 54f, 14f, 4f) }
    dot(Color.White.copy(alpha = 0.75f), 39f, 38f, 7f)
}

private fun DrawScope.toyCar(g: SceneGrade) {
    box(g(0xFFB8392F), 14f, 46f, 86f, 70f, 10f)
    box(g(0xFFE8574A), 14f, 44f, 86f, 66f, 10f)
    box(g(0xFFE8574A), 30f, 28f, 70f, 50f, 9f)
    box(g(0xFFBFE6F8), 35f, 32f, 48f, 46f, 3f)
    box(g(0xFFBFE6F8), 52f, 32f, 65f, 46f, 3f)
    for (x in floatArrayOf(30f, 70f)) {
        dot(g(0xFF2E333B), x, 70f, 10f)
        dot(g(0xFFC9D0D8), x, 70f, 4f)
    }
    box(Color.White.copy(alpha = 0.35f), 20f, 48f, 50f, 52f, 2f)
}

private fun DrawScope.horseshoe(g: SceneGrade) {
    val iron = g(0xFF8A7A6E)
    val path = Path().apply { arcTo(androidx.compose.ui.geometry.Rect(22f, 20f, 78f, 76f), 160f, 220f, true) }
    drawPath(path, g(0xFF5E5048), style = Stroke(16f))
    drawPath(path, iron, style = Stroke(11f))
    for (a in listOf(170f, 210f, 250f, 290f, 330f, 370f)) {
        val r = a * PI.toFloat() / 180f
        dot(g(0xFF3E342E), 50f + cos(r) * 28f, 48f + sin(r) * 28f, 2.4f)
    }
    stick(Color.White.copy(alpha = 0.3f), 30f, 30f, 40f, 24f, 3f)
}

private fun DrawScope.bottle(g: SceneGrade) {
    val glass = g(0xFF5FB89A).copy(alpha = 0.9f)
    box(g(0xFF3E8A70), 32f, 40f, 70f, 88f, 12f)
    box(glass, 32f, 38f, 68f, 86f, 12f)
    box(glass, 43f, 16f, 57f, 42f, 4f)
    box(g(0xFF9A6A3E), 42f, 10f, 58f, 20f, 3f)
    box(g(0xFFF4E6C6), 36f, 54f, 64f, 70f, 2f)
    box(Color.White.copy(alpha = 0.45f), 37f, 44f, 42f, 80f, 2.5f)
}

private fun DrawScope.key(g: SceneGrade) {
    val rust = g(0xFFB0683A)
    val dark = g(0xFF7A4424)
    drawCircle(dark, 16f, Offset(30f, 50f), style = Stroke(10f))
    drawCircle(rust, 15f, Offset(30f, 48f), style = Stroke(7f))
    stick(dark, 44f, 52f, 86f, 52f, 9f)
    stick(rust, 44f, 50f, 86f, 50f, 6f)
    box(rust, 70f, 50f, 76f, 64f, 1.5f)
    box(rust, 80f, 50f, 86f, 60f, 1.5f)
    dot(g(0xFF8A5A3A), 60f, 50f, 2f)
}

/** The golden scarab in the chamber: a gleaming beetle with spread wing cases. */
internal fun DrawScope.goldenScarab(g: SceneGrade) {
    val gold = g(0xFFFFCB45)
    val shade = g(0xFFC98E1E)
    val light = g(0xFFFFF0A8)
    // Legs.
    for (side in floatArrayOf(-1f, 1f)) {
        for (k in 0 until 3) {
            val y = 48f + k * 12f
            stick(shade, 50f + side * 14f, y, 50f + side * 30f, y + (k - 1) * 8f, 4f)
        }
    }
    oval(shade, 50f, 22f, 12f, 9f)
    oval(gold, 50f, 21f, 10f, 7.5f)
    oval(shade, 50f, 36f, 18f, 10f)
    oval(gold, 50f, 35f, 16f, 8.5f)
    oval(shade, 50f, 62f, 22f, 26f)
    oval(gold, 50f, 60f, 20f, 24f)
    stick(shade, 50f, 38f, 50f, 84f, 2.5f)
    oval(light.copy(alpha = 0.8f), 42f, 52f, 5f, 10f)
    oval(light.copy(alpha = 0.6f), 46f, 32f, 5f, 2.5f)
    // A blue sun disc held up in front, as on old carvings.
    dot(g(0xFF2F7FC8), 50f, 9f, 6f)
    dot(g(0xFF8FD0FF), 48f, 7f, 2f)
}

/** The time capsule: a steel tube with bolted ends and a date plate. */
internal fun DrawScope.timeCapsule(g: SceneGrade) {
    val steel = g(0xFFB9C2CC)
    val shade = g(0xFF7A8490)
    box(shade, 14f, 34f, 86f, 74f, 18f)
    box(steel, 14f, 32f, 86f, 70f, 18f)
    box(g(0xFF8E98A4), 14f, 32f, 26f, 72f, 8f)
    box(g(0xFF8E98A4), 74f, 32f, 86f, 72f, 8f)
    for (y in floatArrayOf(38f, 51f, 64f)) {
        dot(g(0xFF5E6670), 20f, y, 2.2f)
        dot(g(0xFF5E6670), 80f, y, 2.2f)
    }
    box(g(0xFFFFD45A), 36f, 44f, 64f, 58f, 3f)
    stick(g(0xFFB8862A), 41f, 49f, 59f, 49f, 2f)
    stick(g(0xFFB8862A), 41f, 53f, 54f, 53f, 2f)
    box(Color.White.copy(alpha = 0.5f), 28f, 35f, 72f, 39f, 2f)
}

/** Draws [find] at [size] pixels, its box's top-left at [topLeft]. */
internal fun DrawScope.drawFind(find: DeepFind, g: SceneGrade, topLeft: Offset, size: Float) {
    val unit = size / 100f
    translate(topLeft.x, topLeft.y) { scale(unit, unit, Offset.Zero) { find.draw(this, g) } }
}
