package io.colorsand.ui.minigame

import androidx.compose.ui.graphics.Color
import io.colorsand.core.Arena
import io.colorsand.ui.arena.SceneGrade

/** The cut of a gem: each kind on a board has its own, so the kinds tell apart by shape as well as color. */
internal enum class GemShape { PEARL, GLASS, HEX, DROP, STAR, SHARD, METEOR, DIAMOND, TRIANGLE, OCTAGON }

/** How one kind of gem looks: its [shape] in a [light], [mid] and [dark] tone, and its [name] for screen readers. */
internal class GemStyle(val name: String, val shape: GemShape, val light: Color, val mid: Color, val dark: Color)

/**
 * How Sand gem match looks in one arena: the five kinds of gem, the board's frame ([frame], [frameDark] and its
 * [trim]) and checkered [tileA] / [tileB] well with [wellTop] to [wellBottom] light over it, the meter's sand
 * ([meterLight] to [meterDark]), and the lines it says. [stage] is the keepsake's, drawn by the meter.
 */
internal class GemLook(
    val arena: Arena,
    val stage: Int,
    val gems: List<GemStyle>,
    val frame: Color,
    val frameDark: Color,
    val trim: Color,
    val tileA: Color,
    val tileB: Color,
    val wellTop: Color,
    val wellBottom: Color,
    val meterLight: Color,
    val meterDark: Color,
    val meterName: String,
    val hello: String,
    val done: String,
    /** The Mars board's well shows a few dusk stars. */
    val stars: Boolean,
) {
    companion object {
        /** The treasure chest's gems from the Sea Floor, or the flag's Martian gems in the red dusk. */
        fun of(arena: Arena, g: SceneGrade): GemLook = when (arena) {
            Arena.MARS -> GemLook(
                arena = arena,
                stage = 1,
                gems = listOf(
                    GemStyle("red crystal", GemShape.SHARD, g(0xFFFFA3A3), g(0xFFE0303F), g(0xFF8E1426)),
                    GemStyle("meteor stone", GemShape.METEOR, g(0xFF9A8A86), g(0xFF5E4C4B), g(0xFF2F2629)),
                    GemStyle("violet crystal", GemShape.DIAMOND, g(0xFFE6C2FF), g(0xFFA45BEA), g(0xFF5E2AA0)),
                    GemStyle("ice crystal", GemShape.TRIANGLE, g(0xFFD2FCFF), g(0xFF5FD8E8), g(0xFF1E8FA8)),
                    GemStyle("dust topaz", GemShape.OCTAGON, g(0xFFFFE3A6), g(0xFFFFA63A), g(0xFFC2620E)),
                ),
                frame = g(0xFF8A3B28),
                frameDark = g(0xFF4A1D16),
                trim = g(0xFFD98A55),
                tileA = g(0xFF6E3752),
                tileB = g(0xFF5C2D48),
                wellTop = g(0xFF3A2552),
                wellBottom = g(0xFFB4503C),
                meterLight = g(0xFFFFB27A),
                meterDark = g(0xFFC4472C),
                meterName = "Martian dust",
                hello = "Line up three Martian gems!",
                done = "The flag flies over a heap of gems!",
                stars = true,
            )
            else -> GemLook(
                arena = arena,
                stage = 5,
                gems = listOf(
                    GemStyle("pearl", GemShape.PEARL, g(0xFFFFFFFF), g(0xFFF3E6EE), g(0xFFB9A4C2)),
                    GemStyle("sea glass", GemShape.GLASS, g(0xFFD4FAEA), g(0xFF6FD3B0), g(0xFF2A8F74)),
                    GemStyle("coral gem", GemShape.HEX, g(0xFFFFBDB3), g(0xFFFF5F5A), g(0xFFB52A3A)),
                    GemStyle("blue drop", GemShape.DROP, g(0xFFB4DEFF), g(0xFF3C8BEA), g(0xFF1C4A9E)),
                    GemStyle("gold star", GemShape.STAR, g(0xFFFFF4A8), g(0xFFFFC52E), g(0xFFD07F0E)),
                ),
                frame = g(0xFF8A5530),
                frameDark = g(0xFF5A3219),
                trim = g(0xFFF2C14A),
                tileA = g(0xFFF3E0B0),
                tileB = g(0xFFE7CE96),
                wellTop = g(0xFFFFF6DC),
                wellBottom = g(0xFFD9B878),
                meterLight = g(0xFFFFE9A0),
                meterDark = g(0xFFE0A23A),
                meterName = "Treasure sand",
                hello = "Swap two gems to line up three!",
                done = "The chest sparkles! All matched.",
                stars = false,
            )
        }
    }
}
