package io.colorsand.ui.minigame

import io.colorsand.core.Arena
import io.colorsand.core.SandColor
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.sin
import kotlin.random.Random

/**
 * How sand falls in one arena's Catch the grains: [fall] field heights a second straight down, blown sideways at
 * [drift] field widths a second (give or take [driftSpread], plus to the right), fluttering [sway] to each side
 * [swayRate] times a second. A spawn drops [burst] grains together every [every] seconds, in runs of one color out
 * of [colors] at a time, so the catch piles up in layers.
 */
data class GrainFall(
    val fall: Float,
    val drift: Float,
    val driftSpread: Float,
    val sway: Float,
    val swayRate: Float,
    val burst: Int,
    val every: Float,
    val colors: List<SandColor>,
) {
    companion object {
        /** [arena]'s fall: a breeze on the Beach, dune sand blown off a crest in the Desert, slow dust on Mars. */
        fun of(arena: Arena): GrainFall = when (arena) {
            Arena.DESERT -> GrainFall(
                fall = 0.25f, drift = -0.075f, driftSpread = 0.02f, sway = 0.012f, swayRate = 0.9f, burst = 2, every = 1.5f,
                colors = listOf(SandColor.ORANGE, SandColor.YELLOW, SandColor.RED, SandColor.BROWN, SandColor.PINK),
            )
            Arena.MARS -> GrainFall(
                fall = 0.14f, drift = 0f, driftSpread = 0.025f, sway = 0.045f, swayRate = 0.25f, burst = 1, every = 0.62f,
                colors = listOf(SandColor.RED, SandColor.ORANGE, SandColor.PURPLE, SandColor.PINK, SandColor.BROWN),
            )
            else -> GrainFall(
                fall = 0.23f, drift = 0.045f, driftSpread = 0.02f, sway = 0.03f, swayRate = 0.55f, burst = 1, every = 0.82f,
                colors = listOf(SandColor.CYAN, SandColor.YELLOW, SandColor.PINK, SandColor.BLUE, SandColor.WHITE, SandColor.ORANGE),
            )
        }
    }
}

/** One falling grain: born at [born] seconds above [x0], drifting at [vx], its flutter at [phase] (0 to 1). */
data class Grain(val id: Int, val color: SandColor, val x0: Float, val vx: Float, val phase: Float, val born: Float)

/** A grain that fell past the container into the sand at [x], [at] seconds. */
data class Landed(val x: Float, val color: SandColor, val at: Float)

/** What one [GrainCatch.step] did, for sounds and buzzes. */
enum class CatchEvent { CAUGHT, LANDED, FULL }

/**
 * A round of Catch the grains, in a field 1 wide and 1 high (y down): grains of colored sand fall as [fall] says,
 * and a container [bin] (its center, 0 to 1) slides along the bottom toward [target] to catch them. A grain is
 * caught as it reaches the container's mouth anywhere within [REACH] of its middle; the rest land in the sand, with
 * no penalty. Grains are aimed to come down near the container, and keep coming until [capacity] are caught.
 * [auto] slides the container under the next grain by itself, so a round can be finished without aiming.
 * [seed] makes the same round every time.
 */
class GrainCatch(val fall: GrainFall, seed: Int, val capacity: Int = CAPACITY) {
    private val random = Random(seed)

    /** Seconds since the round began. */
    var time: Float = 0f
        private set

    /** The container's middle, 0 to 1. */
    var bin: Float = 0.5f
        private set

    /** Where the container is sliding to; set by drags, taps and keys. */
    var target: Float = 0.5f
        set(value) { field = value.coerceIn(HALF_WIDTH, 1f - HALF_WIDTH) }

    /** Slides the container under the next grain by itself. */
    var auto: Boolean = false

    /** The grains in the air. */
    val grains: List<Grain> get() = falling

    /** The colors caught, bottom of the pile first. */
    val caught: List<SandColor> get() = pile

    /** Grains that fell into the sand lately, oldest first. */
    val landed: List<Landed> get() = sand

    /** The grains the last [step] caught, where they went in. */
    val justCaught: List<Landed> get() = fresh

    /** When the container filled up, or null. */
    var fullAt: Float? = null
        private set

    val isFull: Boolean get() = pile.size >= capacity

    /** How full the container is, 0 to 1. */
    val fill: Float get() = (pile.size.toFloat() / capacity).coerceAtMost(1f)

    /** The pile in layers: each run of one color, bottom first, with how many grains it holds. */
    val layers: List<Pair<SandColor, Int>>
        get() {
            val out = mutableListOf<Pair<SandColor, Int>>()
            for (c in pile) {
                if (out.isNotEmpty() && out.last().first == c) out[out.lastIndex] = c to out.last().second + 1 else out += c to 1
            }
            return out
        }

    private val falling = mutableListOf<Grain>()
    private val pile = mutableListOf<SandColor>()
    private val sand = mutableListOf<Landed>()
    private val fresh = mutableListOf<Landed>()
    private var nextId = 0
    private var nextSpawn = FIRST_SPAWN
    private var color = fall.colors[random.nextInt(fall.colors.size)]
    private var runLeft = RUN

    /** How high [grain] is at [at] seconds: 0 at the top of the field, 1 at the bottom. */
    fun y(grain: Grain, at: Float = time): Float = TOP + fall.fall * (at - grain.born)

    /** Where [grain] is across the field at [at] seconds. */
    fun x(grain: Grain, at: Float = time): Float {
        val age = at - grain.born
        return grain.x0 + grain.vx * age + fall.sway * sin(2 * PI.toFloat() * (fall.swayRate * age + grain.phase))
    }

    /** The second [grain] reaches the container's mouth. */
    fun reachesMouth(grain: Grain): Float = grain.born + (MOUTH - TOP) / fall.fall

    /** Moves the container one nudge to the left (-1) or right (+1), as a key press or a screen reader does. */
    fun nudge(direction: Int) {
        target = bin + direction * NUDGE
    }

    /**
     * Runs the round on by [dt] seconds (at most [MAX_FRAME], so a stall doesn't skip a stretch of the round), in
     * small steps so no grain passes through the container between frames; returns what happened.
     */
    fun step(dt: Float): List<CatchEvent> {
        val events = mutableListOf<CatchEvent>()
        fresh.clear()
        var left = dt.coerceIn(0f, MAX_FRAME)
        while (left > 0f) {
            val d = minOf(left, MAX_STEP)
            advance(d, events)
            left -= d
        }
        return events
    }

    private fun advance(d: Float, events: MutableList<CatchEvent>) {
        time += d
        if (auto && !isFull) aim()
        val gap = target - bin
        bin += gap.coerceIn(-SPEED * d, SPEED * d)
        if (!isFull) {
            while (time >= nextSpawn) {
                spawn(nextSpawn)
                nextSpawn += fall.every
            }
        }
        val it = falling.iterator()
        while (it.hasNext()) {
            val g = it.next()
            val y = y(g)
            if (!isFull && y >= MOUTH && y <= MOUTH + CATCH_DEPTH && abs(x(g) - bin) <= REACH) {
                it.remove()
                pile += g.color
                fresh += Landed(x(g), g.color, time)
                events += CatchEvent.CAUGHT
                if (isFull) {
                    fullAt = time
                    events += CatchEvent.FULL
                }
            } else if (y >= GROUND) {
                it.remove()
                sand += Landed(x(g), g.color, time)
                events += CatchEvent.LANDED
            }
        }
        sand.removeAll { time - it.at > SETTLE }
    }

    /** Points the container at the next grain to come down that it can still get under. */
    private fun aim() {
        val next = falling
            .filter { y(it) < MOUTH + CATCH_DEPTH * 0.5f }
            .minByOrNull { reachesMouth(it) } ?: return
        target = x(next, reachesMouth(next))
    }

    /** Drops the next spawn's grains at [at] seconds, aimed to come down where the container can reach in time. */
    private fun spawn(at: Float) {
        val fallTime = (MOUTH - TOP) / fall.fall
        // Somewhere across the field, pulled toward the container, so grains land within an easy slide of it.
        val anywhere = HALF_WIDTH + random.nextFloat() * (1f - 2 * HALF_WIDTH)
        val aim = (anywhere + (bin - anywhere) * PULL).coerceIn(HALF_WIDTH, 1f - HALF_WIDTH)
        repeat(fall.burst) { k ->
            val landing = (aim + (k - (fall.burst - 1) / 2f) * BURST_GAP).coerceIn(HALF_WIDTH * 0.6f, 1f - HALF_WIDTH * 0.6f)
            val vx = fall.drift + (random.nextFloat() * 2f - 1f) * fall.driftSpread
            val phase = random.nextFloat()
            val sway = fall.sway * sin(2 * PI.toFloat() * (fall.swayRate * fallTime + phase))
            val born = at + k * BURST_STAGGER
            falling += Grain(nextId++, nextColor(), landing - vx * fallTime - sway, vx, phase, born)
        }
    }

    /** The color of the next grain: the same color for a run of [RUN] grains, then another one. */
    private fun nextColor(): SandColor {
        if (runLeft == 0) {
            val others = fall.colors.filter { it != color }
            color = others[random.nextInt(others.size)]
            runLeft = RUN - 1 + random.nextInt(3)
        }
        runLeft--
        return color
    }

    companion object {
        /** Grains to fill a container. */
        const val CAPACITY = 40

        /** Half the container's width, in field widths. */
        const val HALF_WIDTH = 0.13f

        /** How far from the container's middle a grain still counts as caught: a little wider than the container. */
        const val REACH = HALF_WIDTH + 0.035f

        /** Where grains start, a little above the field. */
        const val TOP = -0.03f

        /** The container's mouth, where grains are caught. */
        const val MOUTH = 0.72f

        /** How far below the mouth a grain can still drop in, when the container slides under it late. */
        const val CATCH_DEPTH = 0.07f

        /** The sand the container stands on, where missed grains land. */
        const val GROUND = 0.93f

        /** How fast the container slides, in field widths a second. */
        const val SPEED = 1.5f

        /** One key press or screen reader nudge, in field widths. */
        const val NUDGE = 0.14f

        /** How strongly new grains are aimed toward the container, 0 to 1. */
        const val PULL = 0.3f

        /** Grains of one color in a row, give or take two. */
        const val RUN = 4

        /** How long a landed grain shows in the sand, in seconds. */
        const val SETTLE = 3f

        private const val FIRST_SPAWN = 0.4f
        private const val BURST_GAP = 0.06f
        private const val BURST_STAGGER = 0.22f

        /** The longest step, so no grain falls through the container in one. */
        private const val MAX_STEP = 0.02f

        /** The longest frame the round runs on by. */
        const val MAX_FRAME = 0.25f
    }
}
