/**
 * Plays [show] full screen over the game: one illustrated panel at a time with its line of text, sliding on to
 * the next with a tap on the picture, Next or the right arrow key (left goes back). Skip, Back and Escape end it
 * at once; either way [onDone] is called once. Keyboard focus stays inside, like a keepsake game's.
 */
@OptIn(ExperimentalComposeUiApi::class)
@Composable
fun StoryOverlay(show: StoryShow, onDone: () -> Unit) {
    var done by remember(show) { mutableStateOf(false) }
    val finish: () -> Unit = {
        if (!done) {
            done = true
            onDone()
        }
    }
    DismissOnBack(onBack = finish)
    val panels = remember(show) { panelsOf(show) }
    val titles = remember(show) { titlesOf(show) }
    // Survives the screen being rebuilt (an Android rotation), like the show itself does in App.
    var index by rememberSaveable(show) { mutableStateOf(0) }
    val advance: () -> Unit = { if (index < panels.lastIndex) index++ else finish() }
    val back: () -> Unit = { if (index > 0) index-- }
    val enter = remember(show) { Animatable(0f) }
    LaunchedEffect(show) { enter.animateTo(1f, spring(dampingRatio = 0.8f, stiffness = Spring.StiffnessLow)) }
    val focus = remember { FocusRequester() }
    LaunchedEffect(show) { runCatching { focus.requestFocus() } }
    Box(
        Modifier
            .fillMaxSize()
            .focusRequester(focus)
            // Keep keyboard focus inside the story: Tab never reaches the game underneath.
            .focusProperties { exit = { FocusRequester.Cancel } }
            .focusGroup()
            .onPreviewKeyEvent { event ->
                if (event.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false
                when (event.key) {
                    Key.Escape -> finish()
                    Key.DirectionRight -> advance()
                    Key.DirectionLeft -> back()
                    else -> return@onPreviewKeyEvent false
                }
                true
            }
            .focusable()
            // Swallow taps so nothing underneath reacts, without taking keyboard focus.
            .focusProperties { canFocus = false }
            .clickable(remember { MutableInteractionSource() }, indication = null) {}
            .graphicsLayer { alpha = enter.value.coerceIn(0f, 1f) }
            .background(Brush.verticalGradient(listOf(Color(0x8C1A1430), Color(0xB31A1430)))),
        contentAlignment = Alignment.Center,
    ) {
        WithHudLook {
            BoxWithConstraints(
                Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.safeDrawing).padding(16.dp),
                contentAlignment = Alignment.Center,
            ) {
                val last = index == panels.lastIndex
                val nextLabel = when {
                    !last -> "Next"
                    show.replay || show.beats.lastOrNull()?.beat == Beat.CLOSING -> "The end"
                    else -> "Let's play!"
                }
                val title = @Composable { StoryTitle(titles[index], index, panels.size, onSkip = finish) }
                val next = @Composable { modifier: Modifier -> PillButton(nextLabel, advance, ButtonStyle.go(LocalPalette.current), modifier) }
                val card = Modifier
                    .graphicsLayer { translationY = (1f - enter.value) * 40.dp.toPx() }
                    .frosted(LocalPalette.current, RoundedCornerShape(30.dp))
                    .padding(12.dp)
                // A short, wide screen (a phone on its side): the picture at the left, the words and Next beside it.
                val wide = maxWidth > maxHeight * 1.3f && maxHeight < 560.dp
                if (wide) {
                    val pictureHeight = min(maxHeight - 24.dp - 52.dp, 420.dp).coerceAtLeast(90.dp)
                    val pictureWidth = min(pictureHeight * (4f / 3f), maxWidth * 0.6f)
                    val side = min(maxWidth - 24.dp - pictureWidth - 12.dp, 300.dp)
                    Column(card.width(pictureWidth + side + 12.dp)) {
                        title()
                        Spacer(Modifier.height(8.dp))
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Slide(index) { shown -> PanelPicture(panels[shown], pictureModifier(pictureWidth, shown, advance)) }
                            Spacer(Modifier.width(12.dp))
                            Column(Modifier.width(side).height(pictureWidth * 0.75f), verticalArrangement = Arrangement.SpaceBetween) {
                                Slide(index, Modifier.weight(1f)) { shown -> PanelText(panels[shown].text, Modifier.fillMaxSize(), fontSize = 16) }
                                next(Modifier.fillMaxWidth())
                            }
                        }
                    }
                } else {
                    // The picture keeps 4:3 and leaves room for the title, the text and the button.
                    val pictureWidth = min(min(maxWidth - 24.dp, 560.dp), (maxHeight - 250.dp) * (4f / 3f)).coerceAtLeast(120.dp)
                    Column(card.width(pictureWidth + 24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                        title()
                        Spacer(Modifier.height(8.dp))
                        Slide(index) { shown ->
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                PanelPicture(panels[shown], pictureModifier(pictureWidth, shown, advance))
                                Spacer(Modifier.height(10.dp))
                                PanelText(panels[shown].text, Modifier.fillMaxWidth().heightIn(min = 48.dp))
                            }
                        }
                        Spacer(Modifier.height(12.dp))
                        next(Modifier)
                        Spacer(Modifier.height(4.dp))
                    }
                }
            }
        }
    }
}

/** Panel [index]'s content, sliding in from the side it comes from. */
@Composable
private fun Slide(index: Int, modifier: Modifier = Modifier, content: @Composable (Int) -> Unit) {
    AnimatedContent(
        index,
        modifier,
        transitionSpec = {
            val forward = targetState > initialState
            (slideInHorizontally(tween(420)) { if (forward) it / 3 else -it / 3 } + fadeIn(tween(420))) togetherWith
                (slideOutHorizontally(tween(320)) { if (forward) -it / 3 else it / 3 } + fadeOut(tween(260)))
        },
        label = "panel",
    ) { shown -> content(shown) }
}

/** A panel picture [width] wide at 4:3, rounded, that goes on to the next panel when tapped. */
private fun pictureModifier(width: Dp, shown: Int, advance: () -> Unit): Modifier = Modifier
    .size(width, width * 0.75f)
    .clip(RoundedCornerShape(20.dp))
    .pointerInput(shown) { detectTapGestures { advance() } }

/** A panel's line of text, the part a screen reader reads out as each panel comes. */
@Composable
private fun PanelText(text: String, modifier: Modifier, fontSize: Int = 18) {
    Text(
        text,
        color = LocalPalette.current.text,
        fontSize = fontSize.sp,
        lineHeight = (fontSize + 5).sp,
        fontWeight = FontWeight.Bold,
        textAlign = TextAlign.Center,
        minLines = 2,
        modifier = modifier
            .wrapContentHeight()
            .padding(horizontal = 6.dp)
            .semantics { liveRegion = LiveRegionMode.Polite },
    )
}

/** The story's title, the page it is on with a dot per panel, and Skip. */
@Composable
private fun StoryTitle(title: String, index: Int, count: Int, onSkip: () -> Unit) {
    val palette = LocalPalette.current
    Row(Modifier.fillMaxWidth().padding(start = 6.dp), verticalAlignment = Alignment.CenterVertically) {
        Column(Modifier.weight(1f)) {
            Text(
                title,
                color = palette.accent,
                fontSize = 18.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
                style = LocalTextStyle.current.withTitleShadow(palette),
                modifier = Modifier.semantics { heading() },
            )
            Row(
                Modifier.padding(top = 4.dp).clearAndSetSemantics { contentDescription = "Page ${index + 1} of $count" },
                horizontalArrangement = Arrangement.spacedBy(5.dp),
            ) {
                repeat(count) { k ->
                    Box(
                        Modifier
                            .size(if (k == index) 18.dp else 7.dp, 7.dp)
                            .background(if (k <= index) palette.accent else palette.dimText.copy(alpha = 0.3f), CircleShape),
                    )
                }
            }
        }
        if (count > 1) {
            GameButton(onSkip, ButtonStyle.accent(palette), Modifier.size(76.dp, 38.dp), lip = 3.dp) {
                Text("Skip", color = palette.onAccent, fontSize = 15.sp, fontWeight = FontWeight.ExtraBold, maxLines = 1)
            }
        }
    }
}

/** A panel's picture: its scenery and characters, scaled to fit, moving with the scene clock. */
@Composable
private fun PanelPicture(panel: Panel, modifier: Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val clock = rememberSceneClock()
    val entrance = remember(panel) { Animatable(0f) }
    LaunchedEffect(panel) { entrance.animateTo(1f, tween(ENTRANCE_MS, easing = LinearEasing)) }
    Canvas(modifier.clearAndSetSemantics { }) {
        val s = size.width / W
        clipRect {
            scale(s, s, Offset.Zero) {
                backdrop(panel.setting, grade, clock.value)
                panel.art(this, grade, clock.value, entrance.value)
            }
        }
    }
}

/** How long a panel's entrance (Mo popping up, a rocket lifting off) takes. */
private const val ENTRANCE_MS = 1100
